INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回路", "is_correct": true, "explanation": "正确。句中指闭合的控制电路或系统路径。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能是“闭合的”，句子的系统含义不成立。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能是“闭合的”，句子的系统含义不成立。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的身体部位，不能说“控制脸”，与句子的系统含义不符。"}], "explanations": {"回路": "正确。句中指闭合的控制电路或系统路径。", "声音": "语义：声音不能是“闭合的”，句子的系统含义不成立。", "时间": "语义：时间不能是“闭合的”，句子的系统含义不成立。", "脸": "体貌：脸是人的身体部位，不能说“控制脸”，与句子的系统含义不符。"}, "sentence_index": 6, "correct_answer": "回路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条回路把雨水引向河里。", "explanation": "这里应该用〈渠道〉。回路是闭合的路径，不能用来引导雨水流向河流。"}, {"text": "这条回路通往郊区。", "explanation": "这里应该用〈公路〉。回路是闭合的路径，不能指通往外地的道路。"}, {"text": "这条回路把热水送到楼上。", "explanation": "这里应该用〈水管〉。回路是闭合的路径，不能用来输送热水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只回路断开以后，系统就停止工作了。", "corrected_sentence": "这条回路断开以后，系统就停止工作了。", "error_description": "量词错误：“只”用于动物，“回路”应该用“条”或“个”，应说“这条回路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师接好了一把回路，系统就恢复正常。", "corrected_sentence": "工程师接好了一条回路，系统就恢复正常。", "error_description": "量词错误：“把”用于有柄的器具，回路应该用“条”或“个”，应说“一条回路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
