INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11596, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把肥料、农药等用到田地或植物上。", "primary_collocate": null, "pronunciation": "shī yòng", "ipa": "ʂʅ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "研究表明，长期施用自制堆肥的种植床，其微生物多样性指数较对照组提升逾40%，显著增强植物抗逆性。", "target_word": "施用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在春天给田里施用有机肥。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "施用太多化肥，土地会变硬。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种农药不能在雨天施用。", "target_word": "施用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每年两次给果树施用堆肥。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "施用堆肥以后，菜长得又大又绿。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农技员提醒大家，不要随便施用这种农药。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花园里要少施用化肥，多用堆肥。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎样给花盆施用肥料。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "施用的量太大，植物的根会坏。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "施用了", "label": "体标（了）"}, {"form": "施用过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "施用|把肥料、农药等用到田地或植物上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11596, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用 shī yòng：把肥料、农药等用到田地或植物上，即所听到的词。"}, {"text": "实用", "is_correct": false, "explanation": "实用 shí yòng 与 shī yòng 第一个音节的声调不同（第二声与第一声），意思是实际有用。"}, {"text": "试用", "is_correct": false, "explanation": "试用 shì yòng 与 shī yòng 第一个音节的声调不同（第四声与第一声），意思是先使用看效果。"}, {"text": "私用", "is_correct": false, "explanation": "私用 sī yòng 与 shī yòng 第一个音节的声母不同（s 与 sh），意思是为私人使用。"}], "explanations": {"施用": "施用 shī yòng：把肥料、农药等用到田地或植物上，即所听到的词。", "实用": "实用 shí yòng 与 shī yòng 第一个音节的声调不同（第二声与第一声），意思是实际有用。", "试用": "试用 shì yòng 与 shī yòng 第一个音节的声调不同（第四声与第一声），意思是先使用看效果。", "私用": "私用 sī yòng 与 shī yòng 第一个音节的声母不同（s 与 sh），意思是为私人使用。"}, "sentence_index": null, "correct_answer": "施用"}, "level_3": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用：把堆肥用到种植床上，与句意相合。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：焚烧会毁坏堆肥，与“提升微生物多样性、增强抗逆性”的结果相矛盾。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃堆肥不能带来句中所述的研究结果。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”的对象是土、矿等，不说“挖掘自制堆肥的种植床”。"}], "explanations": {"施用": "施用：把堆肥用到种植床上，与句意相合。", "焚烧": "语义：焚烧会毁坏堆肥，与“提升微生物多样性、增强抗逆性”的结果相矛盾。", "丢弃": "语义：丢弃堆肥不能带来句中所述的研究结果。", "挖掘": "搭配：“挖掘”的对象是土、矿等，不说“挖掘自制堆肥的种植床”。"}, "sentence_index": 0, "correct_answer": "施用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器不能在雨天施用。", "explanation": "这里应该用〈使用〉。施用多指把肥料、农药等用到田地或植物上，机器不能说施用。"}, {"text": "农民在春天给田里施用水。", "explanation": "这里应该用〈浇灌〉。施用多指肥料、农药等物质，给田地浇水要说浇灌。"}, {"text": "农民在地里施用种子。", "explanation": "这里应该用〈撒〉。施用多指把肥料、农药等用到田地里，播种的种子要说“撒”或“播种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用：把药物用到病人身上，与句意相合。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不说“种植这种农药”。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”用于种子和田地，不能用于药。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割是收获庄稼，与“药”及“不要随便”的语境不符。"}], "explanations": {"施用": "施用：把药物用到病人身上，与句意相合。", "种植": "搭配：“种植”的对象是植物，不说“种植这种农药”。", "播种": "搭配：“播种”用于种子和田地，不能用于药。", "收割": "语义：收割是收获庄稼，与“药”及“不要随便”的语境不符。"}, "sentence_index": 6, "correct_answer": "施用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上施用一杯牛奶。", "explanation": "这里应该用〈喝〉。施用指把肥料、农药等用到田地或植物上，喝牛奶不能说施用。"}, {"text": "妈妈用洗衣粉施用衣服。", "explanation": "这里应该用〈洗涤〉。施用多指肥料、农药等用到田地或植物上，洗衣服要说“洗涤”。"}, {"text": "工人施用机器。", "explanation": "这里应该用〈操作〉。施用只用于肥料、农药等，使用机器要说“操作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在春天把有机肥施用田里。", "corrected_sentence": "农民在春天把有机肥施用到田里。", "error_description": "介词缺失：“施用”后带处所时须加“到”或“于”，应说“施用到田里”，漏掉“到”即为错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年春天，农民在田里很施用化肥。", "corrected_sentence": "去年春天，农民在田里施用化肥。", "error_description": "错误：程度副词“很”不能修饰动词“施用”，应删去“很”，说“施用化肥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
