INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11597, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指自我控制、自我约束的能力或行为，能克制自己的欲望或冲动。", "primary_collocate": null, "pronunciation": "zì zhì", "ipa": "tsɨ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "面对长期的压力与诱惑，真正成熟的人往往能在情绪失控之前保持自制，把冲动转化为理性的选择。", "target_word": "自制", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "面对团队中接连出现的失误，他虽然愤怒，却始终自制，没有当众训斥任何人。", "target_word": "自制", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "自制并不等于压抑情绪，而是在冲动出现之后，仍能选择理性的回应方式。", "target_word": "自制", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他知道自己容易冲动，所以每次开会前都提醒自己要自制，不轻易发言。", "target_word": "自制", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "看到好吃的蛋糕，他还是不能自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生气的时候，他总能自制，不大声说话。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩游戏停不下来，需要学会自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再难过也能自制，没有哭出来。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对诱惑，一个人要学会自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一向自制，从不乱花钱。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自制力", "label": "复合"}, {"form": "自制了", "label": "体标"}], "register": "中性", "sense_fingerprint": "克制自己的欲望或冲动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自制", "is_correct": true, "explanation": "正确。“保持自制”指在情绪失控前克制自己，与“把冲动转化为理性的选择”的语境相符。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是不加克制，与“保持”后的克制语境相反。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“保持距离”指不靠近，与“把冲动转化为理性的选择”的语境不合。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“保持速度”指维持快慢，用于情绪时句子不通。"}], "explanations": {"自制": "正确。“保持自制”指在情绪失控前克制自己，与“把冲动转化为理性的选择”的语境相符。", "放纵": "语义：“放纵”是不加克制，与“保持”后的克制语境相反。", "距离": "搭配：“保持距离”指不靠近，与“把冲动转化为理性的选择”的语境不合。", "速度": "搭配：“保持速度”指维持快慢，用于情绪时句子不通。"}, "sentence_index": 0, "correct_answer": "自制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把湿衣服自制在阳光下晾干。", "explanation": "这里应该用〈晾〉。自制只指人约束自己，不能用于衣服，晾衣服要说晾。"}, {"text": "这个夏天很热，村口的池塘已经自制了。", "explanation": "这里应该用〈干涸〉。自制只指人约束自己，不能用来说池塘的变化。"}, {"text": "这个孩子很自制，把杯子自制碎了。", "explanation": "这里应该用〈摔〉。自制只指人约束自己，不能用来说杯子被弄碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自制", "is_correct": true, "explanation": "正确。“学会自制”指学会克制自己的欲望或冲动，与“停不下来”的语境相符。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是不加克制，与“需要学会”后的克制要求相反。"}, {"text": "上瘾", "is_correct": false, "explanation": "配价：“上瘾”是不及物动词，不能用“学会”后接动作宾语，句子不成立。"}, {"text": "叫喊", "is_correct": false, "explanation": "搭配：“学会叫喊”不是常见说法，与“玩游戏停不下来”的语境也不搭。"}], "explanations": {"自制": "正确。“学会自制”指学会克制自己的欲望或冲动，与“停不下来”的语境相符。", "放纵": "语义：“放纵”是不加克制，与“需要学会”后的克制要求相反。", "上瘾": "配价：“上瘾”是不及物动词，不能用“学会”后接动作宾语，句子不成立。", "叫喊": "搭配：“学会叫喊”不是常见说法，与“玩游戏停不下来”的语境也不搭。"}, "sentence_index": 6, "correct_answer": "自制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弯腰把地上的垃圾自制，准备拿去扔。", "explanation": "这里应该用〈捡〉。自制只指人约束自己，不能用于拾取垃圾，要说捡起来。"}, {"text": "他很快自制住了局面。", "explanation": "这里应该用〈控制〉。自制只指约束自己，不能用来指控制局面或别人。"}, {"text": "他一激动就自制，大声骂人。", "explanation": "这里应该用〈失控〉。自制表示克制住，不能与“大声骂人”这种失控行为搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很生气，但仍尽量自制对方，没有发火。", "corrected_sentence": "他很生气，但仍尽量自制，没有发火。", "error_description": "错误：“自制”指约束自己，不能以“对方”为宾语，应删去“对方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一生气就想骂人，却很快自制了住。", "corrected_sentence": "他一生气就想骂人，却很快自制住了。", "error_description": "错误：结果补语“住”与“了”的顺序颠倒。应说“自制住了”，不能说“自制了住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
