INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "床是供人躺下休息或睡觉的家具。", "primary_collocate": null, "pronunciation": "chuáng", "ipa": "tʂʰuɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这张床虽然很旧，但睡起来很舒服，我一直用到现在。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的床很大，睡起来很舒服。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在床上给孩子讲故事。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，一进门就躺在床上。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张床太小，两个人睡不下。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的床旁边有一盏小灯，晚上看书很方便。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一张新床，放在窗户旁边。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫喜欢睡在我的床上。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把床整理好，客人晚上要来。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床的下面放着一个旧箱子。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "床单", "label": "复合"}, {"form": "床垫", "label": "复合"}], "register": "中性", "sense_fingerprint": "床-供人躺下休息或睡觉的家具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1a78db7-dd1f-4ce9-a28b-f3b315ed5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "床", "is_correct": true, "explanation": "正确答案：床（chuáng），供人躺下休息或睡觉的家具。"}, {"text": "窗", "is_correct": false, "explanation": "chuāng（第一声）与 chuáng（第二声）声调不同，意思是窗户。"}, {"text": "船", "is_correct": false, "explanation": "chuán 与 chuáng 韵母不同（-an 与 -ang），意思是船。"}, {"text": "创", "is_correct": false, "explanation": "chuàng（第四声）与 chuáng（第二声）声调不同，意思是创造。"}, {"text": "闯", "is_correct": false, "explanation": "chuǎng（第三声）与 chuáng（第二声）声调不同，意思是冲撞、闯入。"}], "explanations": {"床": "正确答案：床（chuáng），供人躺下休息或睡觉的家具。", "窗": "chuāng（第一声）与 chuáng（第二声）声调不同，意思是窗户。", "船": "chuán 与 chuáng 韵母不同（-an 与 -ang），意思是船。", "创": "chuàng（第四声）与 chuáng（第二声）声调不同，意思是创造。", "闯": "chuǎng（第三声）与 chuáng（第二声）声调不同，意思是冲撞、闯入。"}, "sentence_index": null, "correct_answer": "床"}, "level_3": {"options": [{"text": "床", "is_correct": true, "explanation": "正确：床是供人睡觉的家具，“睡起来很舒服”与句意相符。"}, {"text": "柜", "is_correct": false, "explanation": "语义：柜子是用来放东西的，不能“睡起来很舒服”。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明用具，不能用来睡，“睡起来很舒服”说不通。"}, {"text": "桌", "is_correct": false, "explanation": "搭配：“桌”不能与“睡起来很舒服”搭配，桌子不能用来睡。"}], "explanations": {"床": "正确：床是供人睡觉的家具，“睡起来很舒服”与句意相符。", "柜": "语义：柜子是用来放东西的，不能“睡起来很舒服”。", "灯": "语义：灯是照明用具，不能用来睡，“睡起来很舒服”说不通。", "桌": "搭配：“桌”不能与“睡起来很舒服”搭配，桌子不能用来睡。"}, "sentence_index": 0, "correct_answer": "床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一把床，放在卧室里。", "explanation": "这里应该用〈张〉。床是平面的家具，量词用“张”；“把”多用于椅子、刀等有柄的东西，不用于床。"}, {"text": "妈妈给我缝了一床新被子，晚上很暖和。", "explanation": "此句中的“床”作被褥的量词，指成套的被子，是另一个义项；本词指供人睡觉的家具，这里不能这样用。"}, {"text": "这台车床的床很重，搬起来很费力。", "explanation": "此句中的“床”指车床的床身，是机器的承托部件，不是供人睡觉的家具，与本词义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11598, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "床", "is_correct": true, "explanation": "正确答案：床（chuáng），供人躺下休息或睡觉的家具。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 chuáng 只差介音 u，意思是长短的“长”。"}, {"text": "肠", "is_correct": false, "explanation": "cháng（第二声）与 chuáng 只差介音 u，意思是肠子。"}, {"text": "尝", "is_correct": false, "explanation": "cháng（第二声）与 chuáng 只差介音 u，意思是品尝。"}, {"text": "疮", "is_correct": false, "explanation": "chuāng（第一声）与 chuáng（第二声）只差声调，意思是皮肤上的疮。"}], "explanations": {"床": "正确答案：床（chuáng），供人躺下休息或睡觉的家具。", "长": "cháng（第二声）与 chuáng 只差介音 u，意思是长短的“长”。", "肠": "cháng（第二声）与 chuáng 只差介音 u，意思是肠子。", "尝": "cháng（第二声）与 chuáng 只差介音 u，意思是品尝。", "疮": "chuāng（第一声）与 chuáng（第二声）只差声调，意思是皮肤上的疮。"}, "sentence_index": null, "correct_answer": "床"}, "level_3": {"options": [{"text": "床", "is_correct": true, "explanation": "正确：床是可以购买、摆放在窗边的家具，句意通顺。"}, {"text": "脸", "is_correct": false, "explanation": "语义：脸是人身体的部位，不能买，也不能放在窗户旁边。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：嘴是人的器官，不是可以购买和摆放的物品。"}, {"text": "名单", "is_correct": false, "explanation": "搭配：“名单”一般是写出来或列出来的，不能说“买”。"}], "explanations": {"床": "正确：床是可以购买、摆放在窗边的家具，句意通顺。", "脸": "语义：脸是人身体的部位，不能买，也不能放在窗户旁边。", "嘴": "语义：嘴是人的器官，不是可以购买和摆放的物品。", "名单": "搭配：“名单”一般是写出来或列出来的，不能说“买”。"}, "sentence_index": 6, "correct_answer": "床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家新买了一条床，放在卧室里。", "explanation": "这里应该用〈张〉。“条”用于长条形的东西，床是平面家具，量词用“张”。"}, {"text": "他打开床透透气，屋里很闷。", "explanation": "这里应该用〈窗户〉。“打开”用于门窗等可开合的东西，床不能打开，这里应该用〈窗户〉。"}, {"text": "他拧开床洗了洗手。", "explanation": "这里应该用〈水龙头〉。“拧开”用于水龙头、瓶盖等，床不能拧开，这里应该用〈水龙头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈上周给我换了一只新床。", "corrected_sentence": "妈妈上周给我换了一张新床。", "error_description": "量词错误：床是平面家具，量词应用“张”，“只”用于动物或成对的东西。把“一只新床”改为“一张新床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天晚上把床睡觉。", "corrected_sentence": "我每天晚上睡在床上。", "error_description": "搭配错误：“睡觉”是不及物动词，不能用“把”字带“床”作宾语，应说“睡在床上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指数表示一个数自乘的次数，例如在2³中，3就是指数，表示2乘以自身3次。", "primary_collocate": null, "pronunciation": "zhǐ shù", "ipa": "ʈʂʅ˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "一个数要自乘多少次，这个次数叫做指数，例如7⁶里的6。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在2³里，3就是指数。", "target_word": "指数", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "指数告诉我们，一个数要乘多少次。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在10⁴中，指数是4，表示10乘4次。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个很小的指数。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数的指数是2，也就是平方。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "右上角的小数字就是指数。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指数越大，这个数变得越快。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把这个指数从3改成5。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算5⁴的时候，先看指数是几。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "指數", "label": "繁体"}, {"form": "指数函数", "label": "复合"}], "register": "书面", "sense_fingerprint": "数学中表示自乘次数的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确答案：指数 zhǐshù，指表示自乘次数的数字。"}, {"text": "质数", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是质数（素数）。"}, {"text": "指示", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是指示、指点。"}, {"text": "字数", "is_correct": false, "explanation": "zì（第四声）与 zhǐ（第三声）声母与声调都不同，意思是字的数目。"}, {"text": "植树", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）只差声调，意思是种树。"}], "explanations": {"指数": "正确答案：指数 zhǐshù，指表示自乘次数的数字。", "质数": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是质数（素数）。", "指示": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是指示、指点。", "字数": "zì（第四声）与 zhǐ（第三声）声母与声调都不同，意思是字的数目。", "植树": "zhí（第二声）与 zhǐ（第三声）只差声调，意思是种树。"}, "sentence_index": null, "correct_answer": "指数"}, "level_3": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确：指数即表示自乘次数的数，“这个次数叫做指数”与句意相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人或动物身体的高度，不能用来称呼表示自乘次数的数。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是数，不能用来称呼表示自乘次数的数。"}, {"text": "体温", "is_correct": false, "explanation": "体貌：体温是人或动物身体的温度，与数的自乘次数无关。"}], "explanations": {"指数": "正确：指数即表示自乘次数的数，“这个次数叫做指数”与句意相符。", "身高": "语义：身高是人或动物身体的高度，不能用来称呼表示自乘次数的数。", "颜色": "语义：颜色不是数，不能用来称呼表示自乘次数的数。", "体温": "体貌：体温是人或动物身体的温度，与数的自乘次数无关。"}, "sentence_index": 0, "correct_answer": "指数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在10⁴中，指数是10，表示10乘4次。", "explanation": "这里应该用〈底数〉。10是被乘的底数，指数应是4（乘的次数）；把指数说成10，就混淆了底数和指数。"}, {"text": "今天股市的指数涨了两个百分点。", "explanation": "这里的“指数”指股票市场的综合指标，与数学中表示自乘次数的意思不同。"}, {"text": "我的体重指数是22，属于正常。", "explanation": "这里的“指数”指体重指数，是由身高和体重算出的数值，与数学中表示自乘次数的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确答案：指数 zhǐshù，指表示自乘次数的数字。"}, {"text": "植树", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）只差声调，意思是种树。"}, {"text": "实数", "is_correct": false, "explanation": "shí（第二声）与 zhǐ（第三声）声母与声调不同，意思是实数。"}, {"text": "自述", "is_correct": false, "explanation": "zì（第四声）与 zhǐ（第三声）声母与声调不同，意思是自己叙述。"}, {"text": "只是", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同，意思是只是、仅仅。"}], "explanations": {"指数": "正确答案：指数 zhǐshù，指表示自乘次数的数字。", "植树": "zhí（第二声）与 zhǐ（第三声）只差声调，意思是种树。", "实数": "shí（第二声）与 zhǐ（第三声）声母与声调不同，意思是实数。", "自述": "zì（第四声）与 zhǐ（第三声）声母与声调不同，意思是自己叙述。", "只是": "shì（第四声）与 shù（第四声）韵母不同，意思是只是、仅仅。"}, "sentence_index": null, "correct_answer": "指数"}, "level_3": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确：“右上角的小数字”就是数学中表示自乘次数的指数，符合句意。"}, {"text": "小数点", "is_correct": false, "explanation": "语义：小数点是一个点，不是小数字，与“右上角的小数字”的说法不符。"}, {"text": "下标", "is_correct": false, "explanation": "语义：下标位于右下角，而句中说“右上角”，位置相互矛盾。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人或动物身体的重量，不能指数学中的数字符号。"}], "explanations": {"指数": "正确：“右上角的小数字”就是数学中表示自乘次数的指数，符合句意。", "小数点": "语义：小数点是一个点，不是小数字，与“右上角的小数字”的说法不符。", "下标": "语义：下标位于右下角，而句中说“右上角”，位置相互矛盾。", "体重": "体貌：“体重”是人或动物身体的重量，不能指数学中的数字符号。"}, "sentence_index": 6, "correct_answer": "指数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的物价指数比去年高了两个百分点。", "explanation": "这里的“指数”指物价指数，衡量价格总体水平的变化，与自乘次数的意思不同。"}, {"text": "我买了一只指数基金。", "explanation": "这里的“指数”是“指数基金”的意思，指跟踪某个市场指数的基金，与数学中的指数无关。"}, {"text": "5⁴的指数是625。", "explanation": "这里应该用〈幂〉。625是5的4次方的结果，即幂；指数是4，表示乘的次数，不能说指数是625。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在3⁵中，我们先确认指数几。", "corrected_sentence": "在3⁵中，我们先确认指数是几。", "error_description": "漏字：问指数的值时，“指数”后缺少动词“是”，应说“指数是几”；“指数几”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数的指数七，就要乘七次。", "corrected_sentence": "这个数的指数是七，就要乘七次。", "error_description": "成分残缺：“指数”后缺少动词“是”，应说“这个数的指数是七”，“指数”直接接数字不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
