INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11601, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在科学实验中，作为比较基准的组别，通常不接受处理或接受标准处理。", "primary_collocate": null, "pronunciation": "duì zhào zǔ", "ipa": "tweɪ˥˩ ʈʂɑʊ˥˩ tsu˨˩˦", "syllable_count": 3, "sentences": [{"text": "研究表明，长期施用自制堆肥的种植床，其微生物多样性指数较对照组提升逾40%，显著增强植物抗逆性。", "target_word": "对照组", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "对照组的小鼠没有吃这种药。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验组的植物长得高，对照组的植物长得矮。", "target_word": "对照组", "complexity_tier": "T3", "furigana": "duì zhào zǔ", "sentence_source": "generated"}, {"text": "研究人员把学生分成实验组和对照组。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对照组不接受任何处理。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两周后，对照组的植物没有变化。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有对照组，结果就不可靠。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项实验的对照组有三十个人。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对照组只喝水，不吃新药。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把对照组的数据画成了图表。", "target_word": "对照组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "對照組", "label": "繁体"}], "register": "科技", "sense_fingerprint": "对照组：科学实验中作为比较基准、不接受或只接受标准处理的组别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对照组", "is_correct": true, "explanation": "正确：对照组是作为比较基准的一组，“较……提升”的比较对象正是它。"}, {"text": "显微镜", "is_correct": false, "explanation": "语义：显微镜是观察工具，不是可以作为比较基准的样本组，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是实验中的比较对象，句中比较的是种植床的微生物指数。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“较……提升”的比较基准应是样本组，“学生”不能与种植床的指数相比。"}], "explanations": {"对照组": "正确：对照组是作为比较基准的一组，“较……提升”的比较对象正是它。", "显微镜": "语义：显微镜是观察工具，不是可以作为比较基准的样本组，句意不通。", "天气": "语义：天气不是实验中的比较对象，句中比较的是种植床的微生物指数。", "学生": "搭配：“较……提升”的比较基准应是样本组，“学生”不能与种植床的指数相比。"}, "sentence_index": 0, "correct_answer": "对照组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究人员只给对照组服用新药。", "explanation": "这里应该用〈实验组〉。对照组不接受研究中的处理，服用新药的是实验组。"}, {"text": "这两个人的性格形成了鲜明的对照组。", "explanation": "这里应该用〈反差〉。对照组指实验中用来比较的一组对象，两人性格之间的鲜明差别要说反差。"}, {"text": "在这场比赛中，中国队和日本队是彼此的对照组。", "explanation": "这里应该用〈对手〉。对照组是实验中用来比较的一组对象，互相竞争的两支球队要说对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对照组", "is_correct": true, "explanation": "正确：没有比较基准，实验结果就无法判断是否可靠。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是饮食，不是实验的比较基准，与结果的可靠性无关。"}, {"text": "天空", "is_correct": false, "explanation": "配价：“没有”后的对象应是实验条件，“天空”不能作为实验条件。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，与实验结果的可靠性无关，句意不通。"}], "explanations": {"对照组": "正确：没有比较基准，实验结果就无法判断是否可靠。", "早餐": "语义：早餐是饮食，不是实验的比较基准，与结果的可靠性无关。", "天空": "配价：“没有”后的对象应是实验条件，“天空”不能作为实验条件。", "小说": "语义：小说是文学作品，与实验结果的可靠性无关，句意不通。"}, "sentence_index": 6, "correct_answer": "对照组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究结束时，我们得出了对照组。", "explanation": "这里应该用〈结论〉。对照组是实验中的一组对象，不是研究得出的结果。"}, {"text": "这张对照组把两组数据列得很清楚。", "explanation": "这里应该用〈对照表〉。对照组指实验中的一组对象，不能指列数据的表格。"}, {"text": "这次聚会的对照组都是我的老同学。", "explanation": "这里应该用〈同学〉。对照组是实验中用来比较的一组对象，不能用来指一起聚会的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项研究设了两只对照组。", "corrected_sentence": "这项研究设了两个对照组。", "error_description": "量词错误：“对照组”应用量词〈个〉（或〈组〉）计数，“只”用于动物或单个小物件，应改为“两个对照组”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员把小鼠分对照组。", "corrected_sentence": "研究人员把小鼠分到对照组。", "error_description": "补语缺失：“分”后要用“到”引出去向，应说“分到对照组”，不能省去“到”说“分对照组”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
