INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "超过，指时间、数量或程度方面超出某个界限。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "研究表明，长期施用自制堆肥的种植床，其微生物多样性指数较对照组提升逾40%，显著增强植物抗逆性。", "target_word": "逾", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司成立逾二十年，客户遍布全国。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加今天会议的人数逾三百。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年逾六十，还每天坚持跑步。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古桥的历史逾八百年，至今仍能通行。", "target_word": "逾", "complexity_tier": "T3", "furigana": "Zhè zuò gǔ qiáo de lìshǐ yú bā bǎi nián, zhìjīn réng néng tōngxíng.", "sentence_source": "generated"}, {"text": "今年夏天，这个城市的气温逾三十八度。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，班里逾半数的同学得了满分。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体重逾九十公斤，医生让他少吃肉。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店每天的客人逾百人，常常要排队。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的长度逾五百公里，流过三个省。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逾期", "label": "复合"}, {"form": "逾越", "label": "复合"}], "register": "书面", "sense_fingerprint": "逾：书面语，时间、数量、程度超过某个界限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11602, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确答案：逾（yú），意思是超过，书面语。"}, {"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。"}, {"text": "无", "is_correct": false, "explanation": "wú（第二声）与 yú（第二声）韵母不同（u 与 ü），意思是没有。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉。"}, {"text": "与", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是和、跟。"}], "explanations": {"逾": "正确答案：逾（yú），意思是超过，书面语。", "雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。", "无": "wú（第二声）与 yú（第二声）韵母不同（u 与 ü），意思是没有。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉。", "与": "yǔ（第三声）与 yú（第二声）声调不同，意思是和、跟。"}, "sentence_index": null, "correct_answer": "逾"}, "level_3": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确：“逾”表示超过某个界限，“提升逾40%”即提升幅度超过40%。"}, {"text": "降", "is_correct": false, "explanation": "语义：“降”表示下降，与“提升”方向相反，“提升降40%”句意自相矛盾。"}, {"text": "减", "is_correct": false, "explanation": "语义：“减”表示减少，与“提升”方向相反，句意矛盾。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“下”不能直接带“40%”表示提升幅度，“提升下40%”不成话。"}], "explanations": {"逾": "正确：“逾”表示超过某个界限，“提升逾40%”即提升幅度超过40%。", "降": "语义：“降”表示下降，与“提升”方向相反，“提升降40%”句意自相矛盾。", "减": "语义：“减”表示减少，与“提升”方向相反，句意矛盾。", "下": "搭配：“下”不能直接带“40%”表示提升幅度，“提升下40%”不成话。"}, "sentence_index": 0, "correct_answer": "逾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在技术上逾了所有对手。", "explanation": "这里应该用〈超越〉。逾只用于时间、数量、程度超出某个界限，超过对手这类竞争关系要用超越。"}, {"text": "这个消息逾了我的想象。", "explanation": "这里应该用〈超出〉。逾多指时间、数量、程度的界限，想象这类抽象范围要用超出。"}, {"text": "他的成绩逾了不少。", "explanation": "这里应该用〈提高〉。逾表示超出界限，成绩变好是进步，应说提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11602, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "愈", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是病愈、更加。"}, {"text": "逾", "is_correct": true, "explanation": "正确答案：逾（yú），意思是超过，书面语。"}, {"text": "语", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇见。"}, {"text": "欲", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是想要。"}], "explanations": {"愈": "yù（第四声）与 yú（第二声）声调不同，意思是病愈、更加。", "逾": "正确答案：逾（yú），意思是超过，书面语。", "语": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇见。", "欲": "yù（第四声）与 yú（第二声）声调不同，意思是想要。"}, "sentence_index": null, "correct_answer": "逾"}, "level_3": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确：“逾半数”表示超过一半，与后文“得了满分”的语境相合。"}, {"text": "缺", "is_correct": false, "explanation": "语义：“缺”指缺少，缺席的同学不能得满分，与后文语境矛盾。"}, {"text": "退", "is_correct": false, "explanation": "搭配：“退”不能带“半数的同学”作宾语，“退”的对象多是学校、职位等。"}, {"text": "漏", "is_correct": false, "explanation": "搭配：“漏”指遗漏，不能说“班里漏半数的同学”来表示人数超过一半。"}], "explanations": {"逾": "正确：“逾半数”表示超过一半，与后文“得了满分”的语境相合。", "缺": "语义：“缺”指缺少，缺席的同学不能得满分，与后文语境矛盾。", "退": "搭配：“退”不能带“半数的同学”作宾语，“退”的对象多是学校、职位等。", "漏": "搭配：“漏”指遗漏，不能说“班里漏半数的同学”来表示人数超过一半。"}, "sentence_index": 6, "correct_answer": "逾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天上学都要逾马路。", "explanation": "此处“逾”取越过的意思，属另一义项。这一义项多见于“逾山越岭”“逾墙”之类书面或固定说法，日常过马路不说“逾”，本词此义也不用于马路这类场所。"}, {"text": "他悄悄逾了窗台，溜进了房间。", "explanation": "此处“逾”取越过的意思，属另一义项。本词此义用于超出时间、数量、程度的界限，不用于跨过窗台这类具体的物件。"}, {"text": "小狗一下子逾了篱笆，跑出了院子。", "explanation": "此处“逾”取越过的意思，属另一义项。本词此义不用于跨越篱笆这类具体的障碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的印数很逾五万册。", "corrected_sentence": "这本书的印数逾五万册。", "error_description": "错误：“逾”是动词，前面不能加程度副词“很”。正确：应说“印数逾五万册”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山的高度逾的三千米，山顶常年积雪。", "corrected_sentence": "这座山的高度逾三千米，山顶常年积雪。", "error_description": "错误：“逾”后多加了“的”。正确：“逾”是动词，后面直接接数量短语，不加“的”，应说“逾三千米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "生物体抵抗不良环境条件（如干旱、低温、盐碱等）的能力。", "primary_collocate": null, "pronunciation": "kàng nì xìng", "ipa": "kʰɑŋ˥˩ ni˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "研究表明，长期施用自制堆肥的种植床，其微生物多样性指数较对照组提升逾40%，显著增强植物抗逆性。", "target_word": "抗逆性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种玉米的抗逆性很强，干旱时也能长好。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民想选抗逆性好的新品种。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小麦经过培育，抗逆性提高了。", "target_word": "抗逆性", "complexity_tier": "T3", "furigana": "Xiǎomài jīngguò péiyù, kàngnìxìng tígāo le.", "sentence_source": "generated"}, {"text": "抗逆性强的树，冬天不容易冻死。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，仙人掌的抗逆性特别好。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究水稻的抗逆性。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐碱地里的草抗逆性很强，所以能活下来。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品种抗逆性差，遇到低温就会死。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多施有机肥可以增强花草的抗逆性。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗逆", "label": "复合"}], "register": "书面", "sense_fingerprint": "抗逆性：生物抵抗干旱、低温、盐碱等不良环境的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗逆性", "is_correct": true, "explanation": "正确：“增强植物抗逆性”指提高植物抵抗不良环境的能力，与句意相合。"}, {"text": "土壤", "is_correct": false, "explanation": "搭配：“增强”的对象应是能力或性状，“土壤”不能作为植物被增强的属性。"}, {"text": "病虫害", "is_correct": false, "explanation": "语义：“病虫害”是要防治的对象，与“显著增强植物”的褒义语境冲突。"}, {"text": "花粉", "is_correct": false, "explanation": "搭配：“花粉”是植物的组成部分，不是可以被增强的性状。"}], "explanations": {"抗逆性": "正确：“增强植物抗逆性”指提高植物抵抗不良环境的能力，与句意相合。", "土壤": "搭配：“增强”的对象应是能力或性状，“土壤”不能作为植物被增强的属性。", "病虫害": "语义：“病虫害”是要防治的对象，与“显著增强植物”的褒义语境冲突。", "花粉": "搭配：“花粉”是植物的组成部分，不是可以被增强的性状。"}, "sentence_index": 0, "correct_answer": "抗逆性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的抗逆性很强，能在高温下工作。", "explanation": "这里应该用〈耐热〉。抗逆性只用于生物体，电脑等器物的耐热能力不说抗逆性。"}, {"text": "害虫对农药产生了抗逆性。", "explanation": "这里应该用〈抗药性〉。抗逆性针对干旱、低温等环境条件，害虫对农药的抵抗要用抗药性。"}, {"text": "这座水泥墙的抗逆性很强，经得起风吹日晒。", "explanation": "这里应该用〈耐久〉。抗逆性只用于生物体，墙体的耐久性不说抗逆性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗逆性", "is_correct": true, "explanation": "正确：“研究水稻的抗逆性”指研究水稻抵抗不良环境的能力，与句意相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是人的情绪，水稻没有心情，“研究水稻的心情”句意不通。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：“哭声”属于人或动物的发声，植物不会哭，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”多用于人或动物，不搭配“水稻”。"}], "explanations": {"抗逆性": "正确：“研究水稻的抗逆性”指研究水稻抵抗不良环境的能力，与句意相合。", "心情": "语义：“心情”是人的情绪，水稻没有心情，“研究水稻的心情”句意不通。", "哭声": "语义：“哭声”属于人或动物的发声，植物不会哭，句意不通。", "脾气": "搭配：“脾气”多用于人或动物，不搭配“水稻”。"}, "sentence_index": 6, "correct_answer": "抗逆性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只抗逆性很强，干旱时也能存活。", "explanation": "这里应该用〈种〉。“只”用于动物等个体，抗逆性是抽象性质，应说“这种抗逆性”。"}, {"text": "这把抗逆性很强，能抗住盐碱。", "explanation": "这里应该用〈种〉。“把”用于带柄的器物，抗逆性是抽象性质，应说“这种抗逆性”。"}, {"text": "这颗抗逆性很强，耐得住低温。", "explanation": "这里应该用〈种〉。“颗”用于颗粒状的东西，抗逆性是抽象性质，应说“这种抗逆性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个麦种的抗逆性强很。", "corrected_sentence": "这个麦种的抗逆性很强。", "error_description": "错误：“很”放在了“强”后面，程度副词应放在形容词前面。正确：应说“抗逆性很强”，不说“抗逆性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种抗逆性们是这个品种的优点。", "corrected_sentence": "这种抗逆性是这个品种的优点。", "error_description": "错误：“们”只用于指人的复数，不能加在抽象性质“抗逆性”后面。正确：应说“这种抗逆性”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
