INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指某事物中包含、含有另一事物（多为抽象事物）。", "primary_collocate": null, "pronunciation": "yùn hán", "ipa": "yn˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这些实践重新肯定了身体在场、声音质感与即兴互动所蕴含的认知深度——它们无法被完全转译为文字或数据。", "target_word": "蕴含", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "尤为深远的是，这一日常实践蕴含行为生态学意义上的“认知转化效应”。", "target_word": "蕴含", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这句老话蕴含着很深的道理。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个传统节日都蕴含着人们的美好愿望。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画蕴含了画家对家乡的感情。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的茶文化蕴含丰富的历史知识。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话里蕴含着对孩子的爱。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的变化中，往往蕴含着很大的机会。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事蕴含的意思，孩子们慢慢才懂。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗蕴含着作者对生活的思考。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴含着", "label": "体标"}, {"form": "蕴含了", "label": "体标"}], "register": "书面", "sense_fingerprint": "蕴含:事物中包含抽象的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a818043-95f1-4634-87a5-2d86d4a18143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺乏", "is_correct": false, "explanation": "语义：“缺乏”表示没有，与“重新肯定了……深度”的语境矛盾。"}, {"text": "蕴含", "is_correct": true, "explanation": "蕴含指事物中含有抽象的内容，与“认知深度”搭配，填入后语义通顺。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”接能量、时间或资源，不接“认知深度”这类抽象内容。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：“排斥”表示拒绝，与“肯定”的语境相反。"}], "explanations": {"缺乏": "语义：“缺乏”表示没有，与“重新肯定了……深度”的语境矛盾。", "蕴含": "蕴含指事物中含有抽象的内容，与“认知深度”搭配，填入后语义通顺。", "消耗": "搭配：“消耗”接能量、时间或资源，不接“认知深度”这类抽象内容。", "排斥": "语义：“排斥”表示拒绝，与“肯定”的语境相反。"}, "sentence_index": 0, "correct_answer": "蕴含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子里蕴含着三本书。", "explanation": "这里应该用〈装〉。蕴含指事物内部隐含的抽象内容，不用于具体的书本等实物。"}, {"text": "这个班里蕴含着三十个学生。", "explanation": "这里应该用〈包括〉。蕴含强调内在含有的抽象内容，不用于清点具体的人。"}, {"text": "桌子上蕴含着一只猫。", "explanation": "这里应该用〈趴〉。蕴含不用于说某个具体动物处于某个位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“对孩子的爱”的语境相反。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”常接事情或不满的内容，不接“对孩子的爱”这类感情。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表达厌恶，与“对孩子的爱”的语境矛盾。"}, {"text": "蕴含", "is_correct": true, "explanation": "蕴含指话中隐含的内容，与“对孩子的爱”搭配，填入后语义通顺。"}], "explanations": {"反对": "语义：“反对”表示不同意，与“对孩子的爱”的语境相反。", "抱怨": "搭配：“抱怨”常接事情或不满的内容，不接“对孩子的爱”这类感情。", "讨厌": "语义：“讨厌”表达厌恶，与“对孩子的爱”的语境矛盾。", "蕴含": "蕴含指话中隐含的内容，与“对孩子的爱”搭配，填入后语义通顺。"}, "sentence_index": 6, "correct_answer": "蕴含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他蕴含了这场比赛。", "explanation": "这里应该用〈参加〉。蕴含指事物内部隐含的内容，不能用人作主语表示参与某项活动。"}, {"text": "昨天这里蕴含了一场大火。", "explanation": "这里应该用〈发生〉。蕴含指隐含的内容，不能用来说已经发生的事件。"}, {"text": "他蕴含了很多朋友。", "explanation": "这里应该用〈认识〉。蕴含的主语是事物，不能说人身上蕴含着具体的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影蕴含了着深刻的哲理。", "corrected_sentence": "这部电影蕴含着深刻的哲理。", "error_description": "错误：“蕴含”后同时用了“了”和“着”，体标重复。正确应只用“着”表示持续的状态：“这部电影蕴含着深刻的哲理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小镇很蕴含着独特的魅力。", "corrected_sentence": "这座小镇蕴含着独特的魅力。", "error_description": "错误：“蕴含”前多加了副词“很”。“蕴含”不能受“很”修饰；正确为“这座小镇蕴含着独特的魅力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
