INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11607, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生态学是研究生物与环境之间相互关系的科学。", "primary_collocate": null, "pronunciation": "shēng tài xué", "ipa": "ʂɤŋ˥˥ tʰaɪ˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "从生态学视角审视，该项目尤为重视物种配置的科学性。", "target_word": "生态学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一研究路径借鉴了生态学的分析框架，揭示了个体行为与环境反馈之间的动态关联，意义尤为深远。", "target_word": "生态学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "她大学读的是生态学。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学研究生物和环境的关系。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学老师带我们去森林看鸟。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了生态学以后，他更爱护河流了。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学告诉我们，每种动物都很重要。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本生态学课本有很多彩色图片。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用生态学的知识保护湿地。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对生态学很感兴趣。", "target_word": "生态学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行为生态学", "label": "复合"}, {"form": "生态学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "生态学|研究生物与环境相互关系的科学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730e64f6-c995-4cfd-ab89-a28de46c42ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11607, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态学", "is_correct": true, "explanation": "正确：“生态学”研究生物与环境的关系，与句中的“物种配置”“科学性”相合。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法研究语言的组织规则，与物种配置的科学性无关，句意不合。"}, {"text": "会计", "is_correct": false, "explanation": "语义：会计核算经济活动的收支与成本，与物种配置的科学性无关，句意不合。"}, {"text": "厨艺", "is_correct": false, "explanation": "搭配：“视角”多接学科或理论，“厨艺”是技能，不说“从厨艺视角审视”。"}], "explanations": {"生态学": "正确：“生态学”研究生物与环境的关系，与句中的“物种配置”“科学性”相合。", "语法": "语义：语法研究语言的组织规则，与物种配置的科学性无关，句意不合。", "会计": "语义：会计核算经济活动的收支与成本，与物种配置的科学性无关，句意不合。", "厨艺": "搭配：“视角”多接学科或理论，“厨艺”是技能，不说“从厨艺视角审视”。"}, "sentence_index": 0, "correct_answer": "生态学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林的生态学很好。", "explanation": "这里应该用〈生态〉。“生态”指生物与环境的状况，描述森林的状况要说“生态”；“生态学”是研究这一关系的学科，不能用来说状况。"}, {"text": "我们班新开了一台生态学，每周一次。", "explanation": "量词〈台〉用于机器设备，不用于学科，这里应该用〈门〉。"}, {"text": "池塘里的生态学很多，鱼和虾都很健康。", "explanation": "这里应该用〈生物〉。“生物”指有生命的个体，池塘里的鱼虾要说“生物”；“生态学”是学科名称，不能指具体的生命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11607, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态学", "is_correct": true, "explanation": "正确：“生态学”研究生物与环境的关系，能说明每种动物为何重要，与句意相合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学研究数量与空间关系，与动物的重要性无关，句子语义不合。"}, {"text": "化学", "is_correct": false, "explanation": "语义：化学研究物质的组成与变化，无法说明每种动物为何重要。"}, {"text": "经济", "is_correct": false, "explanation": "搭配：“告诉我们”的主语多为学科、书籍或事实，“经济”作主语不合搭配。"}], "explanations": {"生态学": "正确：“生态学”研究生物与环境的关系，能说明每种动物为何重要，与句意相合。", "数学": "语义：数学研究数量与空间关系，与动物的重要性无关，句子语义不合。", "化学": "语义：化学研究物质的组成与变化，无法说明每种动物为何重要。", "经济": "搭配：“告诉我们”的主语多为学科、书籍或事实，“经济”作主语不合搭配。"}, "sentence_index": 6, "correct_answer": "生态学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我修了一只生态学，很有收获。", "explanation": "量词〈只〉用于动物，不用于学科，这里应该用〈门〉。"}, {"text": "这条河的生态学很脆弱，要好好保护。", "explanation": "这里应该用〈生态〉。“生态”指生物与环境的状况，河流的状况要说“生态”；“生态学”是学科名称，不能用来描述状况。"}, {"text": "我买了一辆生态学，价格很贵。", "explanation": "量词〈辆〉用于车辆，不用于学科，这里应该用〈门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他选了一本生态学，每周上两次课。", "corrected_sentence": "他选了一门生态学，每周上两次课。", "error_description": "量词错误：学科应用量词“门”，“本”用于书籍，不能修饰“生态学”。正确说法是“一门生态学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一位生态学的家，常在湿地工作。", "corrected_sentence": "他是一位生态学家，常在湿地工作。", "error_description": "复合词错误：“生态学家”是一个词，指研究生态学的人，中间不能加“的”。正确说法是“生态学家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
