INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11609, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11609, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲身经历，指自己亲自做过或遇到过某事。", "primary_collocate": null, "pronunciation": "qīn lì", "ipa": "tɕʰin˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "当个体亲历香蕉皮蜕变为沃土的完整周期，其对“废物”概念的认知边界将发生根本位移——废弃物不再是线性消费的终点，而是循环代谢的中介。", "target_word": "亲历", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这场大雨我亲历了，路上的水很深。", "target_word": "亲历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷亲历过那次大地震，现在还常常想起。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有亲历过战争的人，才懂得和平多么珍贵。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲历了公司从小到大的全过程。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有亲历那件事，只是听朋友说的。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者亲历了比赛的每一个精彩时刻。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，亲历一次，比看十本书更有用。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人亲历了国家的许多变化。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己亲历的故事写成了一本书。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲历了", "label": "体标"}, {"form": "亲历过", "label": "体标"}], "register": "书面", "sense_fingerprint": "亲自做过或遇到过某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲历", "is_correct": true, "explanation": "正确：亲历指亲身经历，“当个体……”正是说个体亲身经历香蕉皮转化为沃土的全过程。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的宾语应是商品，不能说购买一个周期。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”与“蜕变为沃土”的转化方向相反，句意不通。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”与“亲身经历”的意思相反，若个体忽略这一周期，句中认知边界的转变便无从谈起。"}], "explanations": {"亲历": "正确：亲历指亲身经历，“当个体……”正是说个体亲身经历香蕉皮转化为沃土的全过程。", "购买": "搭配：“购买”的宾语应是商品，不能说购买一个周期。", "扔掉": "语义：“扔掉”与“蜕变为沃土”的转化方向相反，句意不通。", "忽略": "语义：“忽略”与“亲身经历”的意思相反，若个体忽略这一周期，句中认知边界的转变便无从谈起。"}, "sentence_index": 0, "correct_answer": "亲历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大学里亲历了一位好朋友。", "explanation": "这里应该用〈结识〉。亲历的宾语是亲身经历的事件，不能是人；认识新朋友要用结识。"}, {"text": "我昨天亲历了这本书。", "explanation": "这里应该用〈读〉。亲历的宾语必须是亲身经历的事件，书是用来阅读的，不能说亲历。"}, {"text": "他亲历了一大碗热面。", "explanation": "这里应该用〈享受〉。亲历的宾语必须是事件，一大碗热面是用来享受的，不能说亲历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲历", "is_correct": true, "explanation": "正确：亲历指亲身经历，记者在现场经历了比赛的精彩时刻，符合句意。"}, {"text": "担任", "is_correct": false, "explanation": "搭配：“担任”后接职务或角色，不能接“时刻”。"}, {"text": "戒掉", "is_correct": false, "explanation": "语义：“戒掉”的对象是习惯或瘾，与记者报道比赛的语境无关。"}, {"text": "捣鼓", "is_correct": false, "explanation": "语域：“捣鼓”是口语，与这段新闻式叙述的语体不合。"}], "explanations": {"亲历": "正确：亲历指亲身经历，记者在现场经历了比赛的精彩时刻，符合句意。", "担任": "搭配：“担任”后接职务或角色，不能接“时刻”。", "戒掉": "语义：“戒掉”的对象是习惯或瘾，与记者报道比赛的语境无关。", "捣鼓": "语域：“捣鼓”是口语，与这段新闻式叙述的语体不合。"}, "sentence_index": 6, "correct_answer": "亲历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们亲历了故宫。", "explanation": "这里应该用〈游览〉。亲历的宾语必须是亲身经历的事件，故宫是地点，参观景点要用游览。"}, {"text": "我们去云南亲历了一顿火锅。", "explanation": "这里应该用〈吃〉。亲历的宾语必须是亲身经历的事件，火锅是用来品尝的食物，应说“吃火锅”。"}, {"text": "我在家里亲历了一场音乐会。", "explanation": "这里应该用〈观看〉。亲历指亲身在场经历，在家通过屏幕看演出要用观看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我亲历了过那场暴雨。", "corrected_sentence": "我亲历过那场暴雨。", "error_description": "“了”和“过”不能同时用在动词“亲历”后。表示亲身经历过，只用“过”，应说“我亲历过那场暴雨。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的同学都亲历了过那次远足。", "corrected_sentence": "我们班的同学都亲历过那次远足。", "error_description": "“了”和“过”不能同时用在动词“亲历”后面。表示经历过只用“过”，应说“都亲历过那次远足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
