INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11611, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肥沃的土壤。", "primary_collocate": null, "pronunciation": "wò tǔ", "ipa": "wo˥˩ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "当个体亲历香蕉皮蜕变为沃土的完整周期，其对“废物”概念的认知边界将发生根本位移——废弃物不再是线性消费的终点，而是循环代谢的中介。", "target_word": "沃土", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片沃土种什么都长得很好。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在沃土上种下了小麦。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一大片黑色的沃土。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的沃土里，种子很快就发芽了。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是一片沃土，水多，土也软。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把花种在沃土里，每天浇水。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农说，只有沃土才能养出好庄稼。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江南的沃土养活了很多人。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地原来是沙地，现在变成了沃土。", "target_word": "沃土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片沃土", "label": "量词"}], "register": "书面", "sense_fingerprint": "肥沃的土壤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沃土", "is_correct": true, "explanation": "正确：沃土是肥沃的土壤，香蕉皮最终蜕变成的正是这种土。"}, {"text": "废料", "is_correct": false, "explanation": "语义：“废料”正是文中要打破的“废物”概念，蜕变的结果不能是废料。"}, {"text": "电池", "is_correct": false, "explanation": "语义：香蕉皮不会蜕变成电池，这与“循环代谢”的语境不符。"}, {"text": "塑料", "is_correct": false, "explanation": "搭配：塑料不能参与生物的循环代谢，不能与“完整周期”搭配。"}], "explanations": {"沃土": "正确：沃土是肥沃的土壤，香蕉皮最终蜕变成的正是这种土。", "废料": "语义：“废料”正是文中要打破的“废物”概念，蜕变的结果不能是废料。", "电池": "语义：香蕉皮不会蜕变成电池，这与“循环代谢”的语境不符。", "塑料": "搭配：塑料不能参与生物的循环代谢，不能与“完整周期”搭配。"}, "sentence_index": 0, "correct_answer": "沃土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只沃土。", "explanation": "这里应该用〈片〉。“只”用于动物等，沃土是大片土地，应说“一片沃土”。"}, {"text": "他用沃土煮了一锅汤。", "explanation": "这里应该用〈水〉。沃土是土壤，不能用来煮汤，煮汤要用水。"}, {"text": "他在院子里堆了一本沃土。", "explanation": "这里应该用〈片〉。“本”用于书册，不能用来计量沃土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沃土", "is_correct": true, "explanation": "正确：沃土是肥沃的土，适合用来种花，符合“种在……里，每天浇水”的语境。"}, {"text": "水泥地", "is_correct": false, "explanation": "语义：水泥地无法让花扎根、吸收养分，与“种”“浇水”的语境相冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：花无法在冰箱里生长，这句话不成立。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“种在……里”要求有土壤等能让植物生长的介质，石头不能用来种花。"}], "explanations": {"沃土": "正确：沃土是肥沃的土，适合用来种花，符合“种在……里，每天浇水”的语境。", "水泥地": "语义：水泥地无法让花扎根、吸收养分，与“种”“浇水”的语境相冲突。", "冰箱": "语义：花无法在冰箱里生长，这句话不成立。", "石头": "搭配：“种在……里”要求有土壤等能让植物生长的介质，石头不能用来种花。"}, "sentence_index": 6, "correct_answer": "沃土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂用沃土造了一座桥。", "explanation": "这里应该用〈钢铁〉。沃土是肥沃的土壤，不能用来造桥；造桥要用钢铁。"}, {"text": "这家工厂烧了很多沃土。", "explanation": "这里应该用〈煤〉。工厂烧的是燃料，沃土不能燃烧。"}, {"text": "他喝了一口沃土。", "explanation": "这里应该用〈水〉。沃土是土壤，不能喝；能喝的应是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把这颗沃土翻了一遍，准备种小麦。", "corrected_sentence": "农民把这片沃土翻了一遍，准备种小麦。", "error_description": "量词“颗”用于颗粒状的小东西，“沃土”是大片土地，应该用“片”，说“这片沃土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片地的沃土了特别厚，玉米长得很好。", "corrected_sentence": "这片地的沃土特别厚，玉米长得很好。", "error_description": "“了”是动态助词，只能用在动词后，不能用在名词“沃土”后。应去掉“了”，说“这片地的沃土特别厚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
