INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或现象出现、产生。", "primary_collocate": null, "pronunciation": "fā shēng", "ipa": "fa˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "昨天晚上，我家附近发生了一场火灾。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里很少发生地震。", "target_word": "发生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道刚才发生了什么事吗？", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上发生了交通事故，车开得很慢。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，城市发生了很大的变化。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病多在冬天发生。", "target_word": "发生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说那件事从来没有发生过。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时发生了一个小问题。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热时，容易发生火灾。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨之后，山里发生了泥石流。", "target_word": "发生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发生了", "label": "体标"}, {"form": "发生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事物或现象出现、产生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发生", "is_correct": true, "explanation": "“发生”指事情出现，与“一场火灾”搭配，句意通顺。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”用于活动、仪式，不能说“举行了一场火灾”。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后接行动或活动，“火灾”不是可以进行的事。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”需要有人或团体作参与者，“我家附近”不能参加一场火灾。"}], "explanations": {"发生": "“发生”指事情出现，与“一场火灾”搭配，句意通顺。", "举行": "搭配：“举行”用于活动、仪式，不能说“举行了一场火灾”。", "进行": "搭配：“进行”后接行动或活动，“火灾”不是可以进行的事。", "参加": "配价：“参加”需要有人或团体作参与者，“我家附近”不能参加一场火灾。"}, "sentence_index": 0, "correct_answer": "发生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科学家发生了一种新药。", "explanation": "这里应该用〈发明〉。发生指事情或现象出现，不用于创造出新东西；创造新药要用发明。"}, {"text": "这个城市的经济发生得很快。", "explanation": "这里应该用〈发展〉。经济的壮大、进步要用发展，发生指事件、现象的出现，不能用于经济。"}, {"text": "他发生了一篇论文。", "explanation": "这里应该用〈发表〉。论文公开刊登要用发表，发生不能指人写出或刊登作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发生", "is_correct": true, "explanation": "“发生”指事情出现，与“那件事”搭配，句意通顺。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所或展品，“那件事”不能被参观。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”的对象是人或地方，“那件事”不能被访问。"}, {"text": "出差", "is_correct": false, "explanation": "配价：“出差”的主体必须是人，“那件事”不能出差。"}], "explanations": {"发生": "“发生”指事情出现，与“那件事”搭配，句意通顺。", "参观": "语义：“参观”的对象是场所或展品，“那件事”不能被参观。", "访问": "语义：“访问”的对象是人或地方，“那件事”不能被访问。", "出差": "配价：“出差”的主体必须是人，“那件事”不能出差。"}, "sentence_index": 6, "correct_answer": "发生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在北京发生。", "explanation": "这里应该用〈出生〉。发生指事情出现，人在某地来到世上要用出生。"}, {"text": "他发生了一支蜡烛。", "explanation": "这里应该用〈点燃〉。发生指事情出现，不能指人点燃东西，点燃蜡烛要用点燃。"}, {"text": "他发生了一家公司。", "explanation": "这里应该用〈创办〉。发生指事情出现，不能用来指人创建公司，应说“创办”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次意外发生工厂里。", "corrected_sentence": "这次意外发生在工厂里。", "error_description": "“发生”后面接地点时漏了介词“在”。应说“发生在工厂里”，不说“发生工厂里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个错误从来没有发生了。", "corrected_sentence": "那个错误从来没有发生过。", "error_description": "“从来没有”与“发生”搭配时，“发生”后要用“过”，不用“了”。应说“从来没有发生过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
