INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11613, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的最主要、起决定性作用的部分。", "primary_collocate": null, "pronunciation": "gēn běn", "ipa": "kən˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "教育是一个国家发展的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要解决问题，先要找到问题的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚实是做人的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业是这个地方的根本，大家都靠它生活。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体健康是学习和工作的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店以质量为根本，所以客人很多。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不改变习惯，就不能抓住问题的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水是生命的根本，我们要节约用水。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话说到了这件事的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，打好基础才是学好语言的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根本性", "label": "复合"}], "register": "中性", "sense_fingerprint": "根本：名词，事物最主要、起决定作用的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "正确：“根本”指事物最主要、起决定作用的部分，与“国家发展”的语境相符。"}, {"text": "零食", "is_correct": false, "explanation": "语义：“零食”是吃的小食品，不能作为国家发展的决定性部分。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“发展的”后面不接“体重”，两者不构成合理的修饰关系。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的外观特征，不能说成国家发展的决定性因素。"}], "explanations": {"根本": "正确：“根本”指事物最主要、起决定作用的部分，与“国家发展”的语境相符。", "零食": "语义：“零食”是吃的小食品，不能作为国家发展的决定性部分。", "体重": "搭配：“发展的”后面不接“体重”，两者不构成合理的修饰关系。", "颜色": "语义：“颜色”是事物的外观特征，不能说成国家发展的决定性因素。"}, "sentence_index": 0, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一个新的根本。", "explanation": "这里应该用〈背包〉。“根本”指抽象事物最主要的部分，不是可以购买的具体物品。"}, {"text": "这个城市的根本在东边。", "explanation": "这里应该用〈中心〉。“根本”指抽象事物最主要的部分，不指地理上的中心位置。"}, {"text": "我终于找到了问题的一只根本。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对、单个的东西，抽象名词“根本”应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "正确：“抓住问题的根本”指抓住问题最主要的所在，与“改变习惯”的语境吻合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是问题的组成部分，“抓住问题的天气”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“抓住”可以接“机会”或“要点”，不能搭配“工资”来指问题的核心。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是出门时带的物品，与问题的本质毫无关系。"}], "explanations": {"根本": "正确：“抓住问题的根本”指抓住问题最主要的所在，与“改变习惯”的语境吻合。", "天气": "语义：“天气”不是问题的组成部分，“抓住问题的天气”说不通。", "工资": "搭配：“抓住”可以接“机会”或“要点”，不能搭配“工资”来指问题的核心。", "行李": "语义：“行李”是出门时带的物品，与问题的本质毫无关系。"}, "sentence_index": 6, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的根本很鲜艳。", "explanation": "这里应该用〈颜色〉。“根本”指抽象事物的基础或最重要部分，不指物体的颜色，形容颜色不能用“根本”。"}, {"text": "这棵树的根本很深，所以很稳。", "explanation": "这里应该用〈根〉。“根本”指事物最主要的部分，不指植物的根。"}, {"text": "他的书包里装满了根本。", "explanation": "这里应该用〈书〉。“根本”指抽象事物最主要的部分，不是可以装进书包的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的研究触及了这个现象根本。", "corrected_sentence": "他的研究触及了这个现象的根本。", "error_description": "错误形式“这个现象根本”，正确形式“这个现象的根本”。“根本”作名词，前面的定语“这个现象”后须用“的”连接，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革的一条根本是提高效率。", "corrected_sentence": "这次改革的根本是提高效率。", "error_description": "错误形式“一条根本”，正确形式“根本”。“条”用于细长的东西，抽象名词“根本”前不用“条”，直接用“的”连接即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
