INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11614, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体位置的改变，由起点指向终点的有向线段，只取决于初、末位置。", "primary_collocate": null, "pronunciation": "wèi yí", "ipa": "wei˥˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "一只蚂蚁沿直线爬行，最后它的位移是两米。", "target_word": "位移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，这座桥的桥墩发生了位移。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小车从车站出发开到学校，这一过程中它发生了位移。", "target_word": "位移", "complexity_tier": "T3", "furigana": "xiǎo chē cóng chēzhàn chūfā kāi dào xuéxiào, zhè yí guòchéng zhōng tā fāshēng le wèi yí.", "sentence_source": "generated"}, {"text": "小车五秒内的位移是十米。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画出小球的位移。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "位移既有大小，也有方向。", "target_word": "位移", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他算错了小球的位移，答案不对。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山坡上的岩石慢慢发生位移，很危险。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路程和位移不一样，路程是走过的长度。", "target_word": "位移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头一年的位移只有两厘米。", "target_word": "位移", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "位移|由起点指向终点的有向位置变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位移", "is_correct": true, "explanation": "正确：“位移”指从起点指向终点的位置变化，与“它的……是两米”的语境相符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是温度，不是长度，“它的体温是两米”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是报酬，不是长度，“它的工资是两米”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不表示长度，“它的颜色是两米”说不通。"}], "explanations": {"位移": "正确：“位移”指从起点指向终点的位置变化，与“它的……是两米”的语境相符。", "体温": "搭配：“体温”是温度，不是长度，“它的体温是两米”说不通。", "工资": "搭配：“工资”是报酬，不是长度，“它的工资是两米”说不通。", "颜色": "语义：“颜色”不表示长度，“它的颜色是两米”说不通。"}, "sentence_index": 0, "correct_answer": "位移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我找到了那本书的位移。", "explanation": "这里应该用〈位置〉。“位移”指物体从一处到另一处的变化过程，不指某一时刻所在的地点。"}, {"text": "我的新位移在学校附近。", "explanation": "这里应该用〈地址〉。“位移”指位置变化的过程，不指住址。"}, {"text": "这次会议的时间需要位移，改到下周三。", "explanation": "这里应该用〈调整〉。“位移”指物体在空间中的位置变化，安排时间的改动要用“调整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位移", "is_correct": true, "explanation": "正确：“算错了小球的位移”指计算小球位置变化的结果，与“答案不对”相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的袋子，小球没有书包，也就谈不上算错。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的时间长度，与小球的运动无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算错”不与“颜色”搭配，计算的对象应是数量或运动状态。"}], "explanations": {"位移": "正确：“算错了小球的位移”指计算小球位置变化的结果，与“答案不对”相符。", "书包": "语义：“书包”是装东西的袋子，小球没有书包，也就谈不上算错。", "年龄": "语义：“年龄”指存在的时间长度，与小球的运动无关。", "颜色": "搭配：“算错”不与“颜色”搭配，计算的对象应是数量或运动状态。"}, "sentence_index": 6, "correct_answer": "位移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在桥上看到了一条位移。", "explanation": "这里应该用〈次〉。“条”用于细长的东西，表示一次位置变化时应用“次”。"}, {"text": "他绕操场跑了一圈，位移是四百米。", "explanation": "这里应该用〈路程〉。绕一圈回到原地，位移为零，只有走过的路程是四百米。"}, {"text": "这个学生的位移很重，他背着书包走了很久。", "explanation": "这里应该用〈重量〉。“位移”是位置的变化，有大小和方向，不能说“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只箱子从门口搬到了屋里，它做了位移。", "corrected_sentence": "这只箱子从门口搬到了屋里，它发生了位移。", "error_description": "错误形式“它做了位移”，正确形式“它发生了位移”。“位移”指位置的变化，应与“发生”搭配，“做”不能与“位移”构成动宾关系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗从院子跑到门口，它位移是十米。", "corrected_sentence": "小狗从院子跑到门口，它的位移是十米。", "error_description": "错误形式“它位移是十米”，正确形式“它的位移是十米”。“的”连接代词与名词，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起点", "is_correct": true, "explanation": "起点与终点是反义词，分别指过程开始和结束的位置。"}, {"text": "时间", "is_correct": false, "explanation": "不是反义词：“时间”与“终点”没有相对关系。"}, {"text": "中心", "is_correct": false, "explanation": "不是反义词：“中心”指中央位置，与“终点”不构成反义。"}, {"text": "方向", "is_correct": false, "explanation": "不是反义词：“方向”指朝向，与“终点”没有相对关系。"}], "correct_answer": "起点", "explanations": {"起点": "起点与终点是反义词，分别指过程开始和结束的位置。", "时间": "不是反义词：“时间”与“终点”没有相对关系。", "中心": "不是反义词：“中心”指中央位置，与“终点”不构成反义。", "方向": "不是反义词：“方向”指朝向，与“终点”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起点", "is_correct": true, "explanation": "起点与终点是反义词，分别指过程开始和结束的位置。"}, {"text": "方法", "is_correct": false, "explanation": "不是反义词：“方法”指做事的途径，与“终点”无关。"}, {"text": "效果", "is_correct": false, "explanation": "不是反义词：“效果”指结果的好坏，与“终点”无关。"}, {"text": "环境", "is_correct": false, "explanation": "不是反义词：“环境”指周围的情况，与“终点”无关。"}], "correct_answer": "起点", "explanations": {"起点": "起点与终点是反义词，分别指过程开始和结束的位置。", "方法": "不是反义词：“方法”指做事的途径，与“终点”无关。", "效果": "不是反义词：“效果”指结果的好坏，与“终点”无关。", "环境": "不是反义词：“环境”指周围的情况，与“终点”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "终点指路程、比赛或过程结束的位置。", "primary_collocate": null, "pronunciation": "zhōng diǎn", "ipa": "ʈʂʊŋ⁵⁵ tiɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "当个体亲历香蕉皮蜕变为沃土的完整周期，其对“废物”概念的认知边界将发生根本位移——废弃物不再是线性消费的终点，而是循环代谢的中介。", "target_word": "终点", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "马拉松的终点就在体育场门口。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于跑到了比赛的终点。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的终点是一个小海港。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习没有终点，我们要一直努力。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一个冲过了终点，大家都鼓掌。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的终点是西藏的拉萨。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离终点只剩一百米，她开始加速。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的终点是大海。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生不是比赛，也没有统一的终点。", "target_word": "终点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个终点", "label": "量词"}, {"form": "终点站", "label": "复合"}], "register": "中性", "sense_fingerprint": "路程、比赛或过程结束的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "终点", "is_correct": true, "explanation": "终点：路程、比赛或过程结束的位置，与听到的读音一致。"}, {"text": "重点", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是重要的地方。"}, {"text": "正点", "is_correct": false, "explanation": "zhèng（第四声）与 zhōng（第一声）韵母和声调都不同，意思是准时。"}, {"text": "争点", "is_correct": false, "explanation": "zhēng（第一声）与 zhōng（第一声）韵母不同（eng/ong），意思是争论的焦点。"}], "explanations": {"终点": "终点：路程、比赛或过程结束的位置，与听到的读音一致。", "重点": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是重要的地方。", "正点": "zhèng（第四声）与 zhōng（第一声）韵母和声调都不同，意思是准时。", "争点": "zhēng（第一声）与 zhōng（第一声）韵母不同（eng/ong），意思是争论的焦点。"}, "sentence_index": null, "correct_answer": "终点"}, "level_3": {"options": [{"text": "终点", "is_correct": true, "explanation": "“终点”指过程结束的位置，符合“线性消费的终点”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“线性消费”的对象是物品，“天气”不能被消费。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：“邻居”是人，不能作为“线性消费”的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“消费”后接物品，不能说“消费的颜色”。"}], "explanations": {"终点": "“终点”指过程结束的位置，符合“线性消费的终点”的语境。", "天气": "语义：“线性消费”的对象是物品，“天气”不能被消费。", "邻居": "语义：“邻居”是人，不能作为“线性消费”的对象。", "颜色": "搭配：“消费”后接物品，不能说“消费的颜色”。"}, "sentence_index": 0, "correct_answer": "终点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划的终点是三千元。", "explanation": "这里应该用〈预算〉。终点指过程结束的位置，不能表示金额，计划的金额要用预算。"}, {"text": "我们从终点离开博物馆。", "explanation": "这里应该用〈出口〉。终点指路程或过程结束的位置，离开场所要从出口走。"}, {"text": "他从终点重新开始。", "explanation": "这里应该用〈出发点〉。终点是过程结束的地方，重新开始要从出发点起步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终点", "is_correct": true, "explanation": "“终点”指过程结束的位置，指旅行的终点，句意通顺。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是东西，不能是地点。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”是人，“西藏的拉萨”是地方，不能对应。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”是可以买的东西，不能说“门票是拉萨”。"}], "explanations": {"终点": "“终点”指过程结束的位置，指旅行的终点，句意通顺。", "行李": "语义：“行李”是东西，不能是地点。", "司机": "语义：“司机”是人，“西藏的拉萨”是地方，不能对应。", "门票": "搭配：“门票”是可以买的东西，不能说“门票是拉萨”。"}, "sentence_index": 6, "correct_answer": "终点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的终点是当医生。", "explanation": "这里应该用〈理想〉。终点指过程结束的位置，不能指想要实现的目标。"}, {"text": "这部电影的终点很感人。", "explanation": "这里应该用〈结局〉。电影的结尾要说结局，终点指路程或过程结束的位置。"}, {"text": "他去终点买了一本书。", "explanation": "这里应该用〈书店〉。终点指路程或过程结束的位置，买书要去书店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次长跑有一只终点。", "corrected_sentence": "这次长跑有一个终点。", "error_description": "“终点”的量词应用“个”，“只”多用于动物，不能说“一只终点”。应说“有一个终点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于跑终点了。", "corrected_sentence": "他终于跑到终点了。", "error_description": "“跑”后面要用补语“到”表示到达，应说“跑到终点”，不说“跑终点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
