INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11616, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指身体与心理、环境紧密联系，不可分割的状态或属性。", "primary_collocate": null, "pronunciation": "jù shēn", "ipa": "tɕy˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "此种具身认知要求身体亲身参与，进而催化更广泛的可持续生活方式选择，形成从减废到低碳出行、从有机消费到能源节约的行为链式反应。", "target_word": "具身", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "学者认为，人的学习是具身的。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种学习方式是具身的，身体也在参与。", "target_word": "具身", "complexity_tier": "T3", "furigana": "zhè zhǒng xué xí fāng shì shì jù shēn de, shēn tǐ yě zài cān yù.", "sentence_source": "generated"}, {"text": "学者说，思考不只在脑中，也是具身的。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车时的感觉是具身的，书上学不到。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "具身的体验让孩子更懂自然。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想设计更具身的课堂。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为语言理解是具身的，离不开身体。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈带来的是一种具身的记忆。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究说明，情绪是具身的，不只是想法。", "target_word": "具身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "具身认知", "label": "复合"}, {"form": "具身体验", "label": "复合"}], "register": "书面", "sense_fingerprint": "具身|形容词|身体心理环境不可分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbc18688-d601-46ef-99b3-ee748b978efe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "具身", "is_correct": true, "explanation": "正确。“此种具身认知”指身体、心理与环境紧密相连的认知，与句中“要求身体亲身参与”相符。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：句中强调身体亲身参与，“抽象认知”与之相反。"}, {"text": "理性", "is_correct": false, "explanation": "语义：这段讲的是身体与环境的互动，“理性”只强调思维，与句意不符。"}, {"text": "客观", "is_correct": false, "explanation": "语义：句中要求身体亲身参与，“客观认知”与之相反，不能用来描述这一过程。"}], "explanations": {"具身": "正确。“此种具身认知”指身体、心理与环境紧密相连的认知，与句中“要求身体亲身参与”相符。", "抽象": "语义：句中强调身体亲身参与，“抽象认知”与之相反。", "理性": "语义：这段讲的是身体与环境的互动，“理性”只强调思维，与句意不符。", "客观": "语义：句中要求身体亲身参与，“客观认知”与之相反，不能用来描述这一过程。"}, "sentence_index": 0, "correct_answer": "具身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们需要一份更具身的行动计划。", "explanation": "这里应该用〈具体〉。具身说的是身体与心理、环境紧密相连，不能用来形容计划；行动计划要用“具体”。"}, {"text": "这次考试的具身难度比我想象的低。", "explanation": "这里应该用〈实际〉。具身指身体与环境相连的属性，不能修饰难度；“实际难度”指真实的难度。"}, {"text": "这件事关系到我们的具身利益。", "explanation": "这里应该用〈切身〉。“切身利益”指与自己直接相关的利益，具身不能用来修饰利益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具身", "is_correct": true, "explanation": "正确。“具身的课堂”指学生的身体参与、在行动中学习，与老师设计课堂的目的相符。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：老师想设计的是让学生更投入的课堂，“呆板”与这一目的相反。"}, {"text": "单调", "is_correct": false, "explanation": "语义：“单调”指缺乏变化，与老师想要设计的生动课堂相矛盾。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：“尖锐”多用于问题、言辞或批评，不说“尖锐的课堂”。"}], "explanations": {"具身": "正确。“具身的课堂”指学生的身体参与、在行动中学习，与老师设计课堂的目的相符。", "呆板": "语义：老师想设计的是让学生更投入的课堂，“呆板”与这一目的相反。", "单调": "语义：“单调”指缺乏变化，与老师想要设计的生动课堂相矛盾。", "尖锐": "搭配：“尖锐”多用于问题、言辞或批评，不说“尖锐的课堂”。"}, "sentence_index": 6, "correct_answer": "具身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同的条款很具身，逐条都写得清楚。", "explanation": "这里应该用〈正式〉。具身指身体与心理、环境紧密相连，合同条款不具备这一属性；形容条款应用“正式”。"}, {"text": "这家公司的利润很具身，逐年都在增长。", "explanation": "这里误把具身当成了“可观、丰厚”的意思。具身指身体与心理、环境紧密联系，利润是经营数字，与身体和环境无关；形容利润应说“可观”。"}, {"text": "这套规则很具身，所有人都能看懂。", "explanation": "这里误把具身当成了“简明”的意思。具身指身体与心理、环境紧密联系，规则是人为制定的，与身体和环境无关；形容规则易懂应说“简明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种感觉是具身，手也跟着动了。", "corrected_sentence": "这种感觉是具身的，手也跟着动了。", "error_description": "错误：“具身”作谓语时漏掉了“的”。应说“是具身的”；“是具身”听起来不自然，不符合规范。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的动作是具身的的，每一下都带着感觉。", "corrected_sentence": "她的动作是具身的，每一下都带着感觉。", "error_description": "错误：“的”重复了一次，多写了一个“的”。应说“是具身的”，只用一个“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
