INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11617, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻加快事物发展或变化的过程。", "primary_collocate": null, "pronunciation": "cuī huà", "ipa": "tsʰweɪ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "此种具身认知（embodied cognition）进而催化更广泛的可持续生活方式选择，形成从减废到低碳出行、从有机消费到能源节约的行为链式反应。", "target_word": "催化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在知识经济的推动下，跨学科合作不断催化新的研究范式，使传统学科之间的边界日益模糊。", "target_word": "催化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "新政策催化了市场的变化。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛催化了他的成长。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络催化了新闻的传播。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励催化了她的转变。", "target_word": "催化", "complexity_tier": "T3", "furigana": "lǎo shī de gǔ lì cuī huà le tā de zhuǎn biàn 。", "sentence_source": "generated"}, {"text": "价格下降会催化消费的增长。", "target_word": "催化", "complexity_tier": "T3", "furigana": "jià gé xià jiàng huì cuī huà xiāo fèi de zēng zhǎng 。", "sentence_source": "generated"}, {"text": "战争催化了科技的进步。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事催化了两家公司的合作。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社交软件催化了年轻人的交流方式变化。", "target_word": "催化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "催化了", "label": "体标"}, {"form": "催化剂", "label": "复合"}, {"form": "催化作用", "label": "复合"}], "register": "书面", "sense_fingerprint": "比喻义：推动事物更快发展或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11617, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "催化", "is_correct": true, "explanation": "正确。“催化”指推动事物发展或变化，与后文“形成……行为链式反应”的语义一致。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“进而阻碍更广泛的选择”与后文“形成……行为链式反应”的推进关系相矛盾。"}, {"text": "抑制", "is_correct": false, "explanation": "语义：“抑制”与“推动”相反，“进而抑制更广泛的选择”与后文的链式反应相矛盾。"}, {"text": "扼杀", "is_correct": false, "explanation": "语义：“扼杀”表示消灭，与“进而”引出的积极连锁反应相冲突。"}], "explanations": {"催化": "正确。“催化”指推动事物发展或变化，与后文“形成……行为链式反应”的语义一致。", "阻碍": "语义：“进而阻碍更广泛的选择”与后文“形成……行为链式反应”的推进关系相矛盾。", "抑制": "语义：“抑制”与“推动”相反，“进而抑制更广泛的选择”与后文的链式反应相矛盾。", "扼杀": "语义：“扼杀”表示消灭，与“进而”引出的积极连锁反应相冲突。"}, "sentence_index": 0, "correct_answer": "催化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重催化了三公斤。", "explanation": "这里应该用〈增加〉。催化指推动事物发展或变化，不用于体重等数量的增减。"}, {"text": "大风催化了那棵树。", "explanation": "这里应该用〈吹倒〉。催化表示推动事物发展或变化，不用于吹倒树木这类物理动作。"}, {"text": "医生催化了他的体温。", "explanation": "这里应该用〈测量〉。催化表示推动事物发展或变化，不用于测量体温这类检查动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "催化", "is_correct": true, "explanation": "正确。“催化”表示推动增长过程，与“价格下降会……消费的增长”的语义一致。"}, {"text": "衰退", "is_correct": false, "explanation": "配价：“衰退”是不及物动词，不能带“消费的增长”作宾语。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“价格下降会阻止消费的增长”与常见的因果方向相反，句意矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的宾语应是请求、邀请等，不能说“拒绝消费的增长”。"}], "explanations": {"催化": "正确。“催化”表示推动增长过程，与“价格下降会……消费的增长”的语义一致。", "衰退": "配价：“衰退”是不及物动词，不能带“消费的增长”作宾语。", "阻止": "语义：“价格下降会阻止消费的增长”与常见的因果方向相反，句意矛盾。", "拒绝": "搭配：“拒绝”的宾语应是请求、邀请等，不能说“拒绝消费的增长”。"}, "sentence_index": 6, "correct_answer": "催化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他催化了一杯咖啡。", "explanation": "这里应该用〈喝〉。催化表示推动事物发展或变化，不用于饮用这类动作。"}, {"text": "他催化了那份邀请。", "explanation": "这里应该用〈拒绝〉。催化表示推动事物发展或变化，不用于拒绝邀请这类回应。"}, {"text": "他催化了衣服。", "explanation": "这里应该用〈清洗〉。催化表示推动事物发展或变化，不能用于具体的衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次合作催化了了两国的交流。", "corrected_sentence": "这次合作催化了两国的交流。", "error_description": "“催化”后重复使用了“了”。正确形式是“催化了两国的交流”，只用一个“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个决定没催化了公司的改革。", "corrected_sentence": "这个决定没催化公司的改革。", "error_description": "错误：“没催化了”；正确：“没催化”。用“没”否定已发生的动作时，动词后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
