INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从住所出发到外面去，常指外出旅行或办事。", "primary_collocate": null, "pronunciation": "chū xíng", "ipa": "ʈʂʰu˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "人们的日常选择进而催化更广泛的可持续生活方式，形成从减废到低碳出行、从有机消费到能源节约的行为链式反应。", "target_word": "出行", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这种出行方式不仅节能，还能让人保持健康。", "target_word": "出行", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "下雨天出行，请带一把伞。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节假日出行的人很多，路上很堵。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年纪大了，出行不太方便。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出行前，我先看了天气预报。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家人计划下周出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有大雪，请大家注意出行安全。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们这次出行带了很多吃的。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她腿受伤了，出行要靠轮椅。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出行了", "label": "体标（了）"}, {"form": "出行过", "label": "体标（过）"}, {"form": "出行方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：从住所出发到外面去，外出旅行或办事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出行", "is_correct": true, "explanation": "正确答案：“低碳出行”指低碳的出门移动方式，与“能源节约”的生活选择相合。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：“睡眠”不属于可以“低碳”选择的生活行为，语义不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，与这段书面论述的语域不符。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：“草稿”与低碳生活方式无关，语义不通。"}], "explanations": {"出行": "正确答案：“低碳出行”指低碳的出门移动方式，与“能源节约”的生活选择相合。", "睡眠": "语义：“睡眠”不属于可以“低碳”选择的生活行为，语义不通。", "玩意儿": "语域：“玩意儿”是口语词，与这段书面论述的语域不符。", "草稿": "语义：“草稿”与低碳生活方式无关，语义不通。"}, "sentence_index": 0, "correct_answer": "出行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他周末经常出行写作业。", "explanation": "这里应该用〈在家〉。出行指从住所出发到外面去，不能用于在家里写作业。"}, {"text": "爷爷每天早上在公园出行。", "explanation": "这里应该用〈散步〉。出行指出门到远处办事或旅行，不用于在公园里走动。"}, {"text": "周末我常常在商场里出行。", "explanation": "这里应该用〈逛〉。逛指随意走动观看，出行指出门到远处办事或旅行，不用于在商场里走动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出行", "is_correct": true, "explanation": "正确答案：“计划下周出行”指计划下周外出旅行，与“一家人”相合。"}, {"text": "出声", "is_correct": false, "explanation": "语义：“出声”指发出声音，与计划下周的安排不符。"}, {"text": "出血", "is_correct": false, "explanation": "语义：“出血”指流血，与计划下周的安排不符。"}, {"text": "出汗", "is_correct": false, "explanation": "语义：“出汗”指身体排出汗液，与“计划下周”的安排不符，语义不通。"}], "explanations": {"出行": "正确答案：“计划下周出行”指计划下周外出旅行，与“一家人”相合。", "出声": "语义：“出声”指发出声音，与计划下周的安排不符。", "出血": "语义：“出血”指流血，与计划下周的安排不符。", "出汗": "语义：“出汗”指身体排出汗液，与“计划下周”的安排不符，语义不通。"}, "sentence_index": 6, "correct_answer": "出行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打算明年出行留学。", "explanation": "这里应该用〈出国〉。出行指出门办事或旅行，长期出国学习不能用“出行”。"}, {"text": "他出行在一个农村家庭。", "explanation": "这里应该用〈出生〉。出行是离家外出的动作，不能表示出生的地点。"}, {"text": "他一夜之间出行了。", "explanation": "这里应该用〈出名〉。出名指名声传开，出行指出门办事或旅行，不能用于形容名声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天一早我们出行过。", "corrected_sentence": "明天一早我们出行。", "error_description": "错误：“过”表示已经发生的经历，不能用于“明天一早”这样的将来时间。正确：“明天一早我们出行。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们和朋友一起出行的很开心。", "corrected_sentence": "我们和朋友一起出行得很开心。", "error_description": "错误：程度补语前应用“得”，不用“的”。正确：“我们和朋友一起出行得很开心。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“节约”构成反义，指无益地耗费资源。"}, {"text": "桥梁", "is_correct": false, "explanation": "桥梁是建筑物，与“节约”既不是反义也不是近义。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然地理事物，与“节约”没有反义关系。"}, {"text": "公园", "is_correct": false, "explanation": "公园是供游览的场所，与“节约”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“节约”构成反义，指无益地耗费资源。", "桥梁": "桥梁是建筑物，与“节约”既不是反义也不是近义。", "河流": "河流是自然地理事物，与“节约”没有反义关系。", "公园": "公园是供游览的场所，与“节约”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“节约”构成反义，指无益地耗费资源。"}, {"text": "文件", "is_correct": false, "explanation": "文件是书面材料，与“节约”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑构件，与“节约”没有反义关系。"}, {"text": "报纸", "is_correct": false, "explanation": "报纸是出版物，与“节约”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“节约”构成反义，指无益地耗费资源。", "文件": "文件是书面材料，与“节约”没有反义关系。", "窗户": "窗户是建筑构件，与“节约”没有反义关系。", "报纸": "报纸是出版物，与“节约”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "不浪费资源，有意控制使用量。", "primary_collocate": null, "pronunciation": "jié yuē", "ipa": "tɕjɛ˧˥ ɥɛ˥", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "节约", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此种具身认知（embodied cognition）进而催化更广泛的可持续生活方式选择，形成从减废到低碳出行、从有机消费到能源节约的行为链式反应。", "target_word": "节约", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "节约水电是每个家庭的责任。", "target_word": "节约", "complexity_tier": "T3", "furigana": "jiéyuē shuǐdiàn shì měi ge jiātíng de zérèn.", "sentence_source": "generated"}, {"text": "公司推行能源节约，每月省了不少钱。", "target_word": "节约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要培养学生的节约意识。", "target_word": "节约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节约对环境保护很重要。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这项政策的目的是资源节约。", "target_word": "节约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市节约用水的成果很明显。", "target_word": "节约", "complexity_tier": "T3", "furigana": "zhè ge chéngshì jiéyuē yòngshuǐ de chéngguǒ hěn míngxiǎn.", "sentence_source": "generated"}, {"text": "节约粮食要从小事做起。", "target_word": "节约", "complexity_tier": "T3", "furigana": "jiéyuē liángshi yào cóng xiǎoshì zuò qǐ.", "sentence_source": "generated"}, {"text": "厂里的原材料节约做得不错。", "target_word": "节约", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "节约型", "label": "复合"}], "register": "中性", "sense_fingerprint": "节约：不浪费资源，有意控制使用量（作动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节约", "is_correct": true, "explanation": "节约：指有意控制能源使用量、减少浪费，此处作效益项之一。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：消耗指资源被用掉，是负面的损耗，不能与“健康改善”并列作效益。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染是有害的作用，与“外部性效益”的语境相反。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不与“健康改善”并列作效益，两者不是同类的效益项。"}], "explanations": {"节约": "节约：指有意控制能源使用量、减少浪费，此处作效益项之一。", "消耗": "语义：消耗指资源被用掉，是负面的损耗，不能与“健康改善”并列作效益。", "污染": "语义：污染是有害的作用，与“外部性效益”的语境相反。", "价格": "搭配：“价格”不与“健康改善”并列作效益，两者不是同类的效益项。"}, "sentence_index": 0, "correct_answer": "节约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店卖各种节约灯。", "explanation": "这里应该用〈节能〉。“节约”是抽象的行为或意识，不作“灯”的定语，说“节能灯”才对。"}, {"text": "桌上放着一个节约。", "explanation": "这里的“节约”是抽象概念，指做法或意识，不能当作可以放在桌上的具体物品。"}, {"text": "这个新方法节约了工作效率。", "explanation": "这里应该用〈提高〉。“节约”指节省资源、控制使用量，不用于“效率”，效率要说“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节约", "is_correct": true, "explanation": "节约：指减少浪费、有意控制资源使用，与“政策的目的”相符。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是具体物质，不能作为政策的目的。"}, {"text": "车辆", "is_correct": false, "explanation": "搭配：“资源”后不接“车辆”，不构成词组。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：建筑指建造物，与“政策的目的”这种抽象指向不合。"}], "explanations": {"节约": "节约：指减少浪费、有意控制资源使用，与“政策的目的”相符。", "煤炭": "语义：煤炭是具体物质，不能作为政策的目的。", "车辆": "搭配：“资源”后不接“车辆”，不构成词组。", "建筑": "语义：建筑指建造物，与“政策的目的”这种抽象指向不合。"}, "sentence_index": 6, "correct_answer": "节约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我手里握着一把节约。", "explanation": "这里的“节约”是抽象的做法或意识，不能握在手里，换用量词“个”也无法解决问题。"}, {"text": "他把节约装进了箱子里。", "explanation": "这里的“节约”是抽象概念，指做法或意识，不能装进箱子，不是具体的东西。"}, {"text": "这座楼装了不少节约龙头。", "explanation": "这里应该用〈节水〉。“节约”不能直接修饰“龙头”，应说“节水龙头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家每个月都注意节约了用水。", "corrected_sentence": "我们家每个月都注意节约用水。", "error_description": "体标错误：“每个月都”表示习惯性动作，句中不用“了”，应说“节约用水”。错误形式：节约了用水；正确形式：节约用水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把节约下去的钱捐给了学校。", "corrected_sentence": "他把节约下来的钱捐给了学校。", "error_description": "补语错误：“节约下来”表示把钱省存下来，“节约下去”指持续节约，不能修饰“钱”。错误形式：节约下去的钱；正确形式：节约下来的钱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
