INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11621, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个事件发生后，会引发一系列连续的事件，就像链条一样一环扣一环。", "primary_collocate": null, "pronunciation": "liàn shì fǎn yìng", "ipa": "ljɛn⁵¹ ʂʐ̩⁵¹ fan²¹⁴ iŋ⁵¹", "syllable_count": 4, "sentences": [{"text": "此种具身认知（embodied cognition）进而催化更广泛的可持续生活方式选择，形成从减废到低碳出行、从有机消费到能源节约的行为链式反应。", "target_word": "链式反应", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一个小错误引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场链式反应让很多人丢了工作。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一说话，就引发了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格上涨可能带来链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电后，城市里出现了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故很快变成了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都笑了，笑声引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家银行出问题，会引起链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一句话，在班里引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场链式反应", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个事件引发一系列连续事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链式反应", "is_correct": true, "explanation": "正确。“行为链式反应”指一种行为接连引发一系列改变，与句中从减废到低碳出行的连续过程相符。"}, {"text": "化学反应", "is_correct": false, "explanation": "语义：“化学反应”指物质之间的化学变化，句中讲的是人的生活行为选择，不能用来形容这些行为。"}, {"text": "连环画", "is_correct": false, "explanation": "语义：“连环画”是一种图画故事书，与“形成…的行为”所描述的生活方式变化无关，句意不通。"}, {"text": "天气预报", "is_correct": false, "explanation": "搭配：“形成…的”后接的是习惯或趋势，“天气预报”是播报性的信息，不能作为形成的结果。"}], "explanations": {"链式反应": "正确。“行为链式反应”指一种行为接连引发一系列改变，与句中从减废到低碳出行的连续过程相符。", "化学反应": "语义：“化学反应”指物质之间的化学变化，句中讲的是人的生活行为选择，不能用来形容这些行为。", "连环画": "语义：“连环画”是一种图画故事书，与“形成…的行为”所描述的生活方式变化无关，句意不通。", "天气预报": "搭配：“形成…的”后接的是习惯或趋势，“天气预报”是播报性的信息，不能作为形成的结果。"}, "sentence_index": 0, "correct_answer": "链式反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我的问候没有链式反应，只点了点头。", "explanation": "这里应该用〈回应〉。链式反应指一件事引起一连串相继发生的事件，对问候的单次应答要用“回应”。"}, {"text": "这幅画的链式反应很漂亮。", "explanation": "这里应该用〈构图〉。链式反应指一连串事件相继发生，不能用来评价画面的布局，应说“构图”。"}, {"text": "他给我的链式反应很好。", "explanation": "这里应该用〈印象〉。链式反应指一连串事件相继发生，不能用来评价别人给我留下的感受，应说“印象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链式反应", "is_correct": true, "explanation": "正确。“变成了链式反应”指事故接连引发一系列后果，与“很快”所描述的快速扩散相符。"}, {"text": "交通信号", "is_correct": false, "explanation": "语义：事故会扩散成一系列后果，不会变成一种指挥车辆的信号，句意不通。"}, {"text": "调味品", "is_correct": false, "explanation": "语义：“调味品”是食品类物品，事故不能变成调味品。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，只能描述人，不能指事故。"}], "explanations": {"链式反应": "正确。“变成了链式反应”指事故接连引发一系列后果，与“很快”所描述的快速扩散相符。", "交通信号": "语义：事故会扩散成一系列后果，不会变成一种指挥车辆的信号，句意不通。", "调味品": "语义：“调味品”是食品类物品，事故不能变成调味品。", "身材": "体貌：“身材”指人的体型，只能描述人，不能指事故。"}, "sentence_index": 6, "correct_answer": "链式反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事对他的链式反应很大。", "explanation": "这里应该用〈影响〉。链式反应指一连串事件相继发生的过程，不能用来表示作用的强弱。"}, {"text": "这种药的链式反应很明显。", "explanation": "这里应该用〈作用〉。链式反应不表示药物效力的显现，描述药物效果要用“作用”。"}, {"text": "我对这次旅行的链式反应很满意。", "explanation": "这里应该用〈感受〉。链式反应指一连串事件相继发生，不能用来表示对旅行的主观感受，应说“感受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故引发了一颗链式反应。", "corrected_sentence": "这次事故引发了一场链式反应。", "error_description": "量词错误：“链式反应”是一连串事件的过程，应搭配量词“场”；“颗”用于小而圆的东西，不能用于事件，应改为“一场链式反应”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次断电引起了一座链式反应。", "corrected_sentence": "这次断电引起了一场链式反应。", "error_description": "量词错误：“座”用于山、桥等大型固定的建筑或物体，不能用于过程，应改为“一场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
