INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11623, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容具有仪式特点或性质的，通常指行为、活动等带有庄重、规范的形式感。", "primary_collocate": null, "pronunciation": "yí shì xìng", "ipa": "i˧˥ ʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "口头传统并非简单的信息传递，而是一种动态的、仪式性的交流实践，它将民间传说、道德训诫与集体记忆编织进代际传承的经纬之中。", "target_word": "仪式性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "因此，家庭堆肥不仅是技术操作，更是生态主体性建构的仪式性实践，在微观生活政治中重塑人与自然的伦理契约。", "target_word": "仪式性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个节日的活动很有仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婚礼的仪式性很强，每一步都有规定。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的见面带有很强的仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开学典礼更多是仪式性的活动，没有实际内容。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议只是仪式性的，决定早就做好了。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶道的仪式性让客人觉得很庄重。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种仪式性的动作，代表对祖先的尊敬。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得生日聚会太有仪式性，不够轻松。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "仪式感", "label": "复合"}, {"form": "儀式性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "仪式性：活动或行为具有仪式的特点，庄重、规范、重形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仪式性", "is_correct": true, "explanation": "正确：“仪式性”形容交流实践带有仪式特点，与前面的“动态的”并列，语义通顺。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“静止”多形容事物的状态，不宜修饰“交流实践”；且与前面的“动态的”正好相反。"}, {"text": "私密", "is_correct": false, "explanation": "语义：“私密”指个人且不公开，与“民间传说”“集体记忆”所体现的公共性相矛盾。"}, {"text": "书面", "is_correct": false, "explanation": "语义：“书面”指以文字形式呈现，与句首的“口头传统”相矛盾。"}], "explanations": {"仪式性": "正确：“仪式性”形容交流实践带有仪式特点，与前面的“动态的”并列，语义通顺。", "静止": "搭配：“静止”多形容事物的状态，不宜修饰“交流实践”；且与前面的“动态的”正好相反。", "私密": "语义：“私密”指个人且不公开，与“民间传说”“集体记忆”所体现的公共性相矛盾。", "书面": "语义：“书面”指以文字形式呈现，与句首的“口头传统”相矛盾。"}, "sentence_index": 0, "correct_answer": "仪式性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很仪式性，连笑都很有规矩。", "explanation": "这里应该用〈拘谨〉。“仪式性”形容活动、行为的仪式特点，不用来形容人的性格。"}, {"text": "这个小孩仪式性地吃掉了一整袋饼干。", "explanation": "这里应该用〈随便〉。“仪式性”指郑重讲究形式，不用来形容随便吃零食这类随意的动作。"}, {"text": "他做饭很仪式性，三分钟就做好了。", "explanation": "这里应该用〈快〉。“仪式性”指郑重讲究的仪式特点，与三分钟就做好的快速相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仪式性", "is_correct": true, "explanation": "正确：“只是仪式性的”说明会议只有形式，“只是”与“仪式性”搭配通顺。"}, {"text": "随机", "is_correct": false, "explanation": "语义：“随机”指没有预先决定，与“决定早就做好了”相矛盾。"}, {"text": "显著", "is_correct": false, "explanation": "搭配：“显著”多用于效果、差异，不用来形容会议的性质。"}, {"text": "实质性", "is_correct": false, "explanation": "语义：“实质性”指有实际内容，与“决定早就做好了”相矛盾。"}], "explanations": {"仪式性": "正确：“只是仪式性的”说明会议只有形式，“只是”与“仪式性”搭配通顺。", "随机": "语义：“随机”指没有预先决定，与“决定早就做好了”相矛盾。", "显著": "搭配：“显著”多用于效果、差异，不用来形容会议的性质。", "实质性": "语义：“实质性”指有实际内容，与“决定早就做好了”相矛盾。"}, "sentence_index": 6, "correct_answer": "仪式性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仪式性地把纸扔进了垃圾桶。", "explanation": "这里应该用〈随手〉。“仪式性”指郑重讲究形式，不用来形容随手扔纸这类随意的动作。"}, {"text": "他仪式性地把钥匙藏进了抽屉。", "explanation": "这里应该用〈偷偷〉。“仪式性”强调郑重的仪式特点，不用来形容偷偷藏东西这类隐秘的动作。"}, {"text": "这个孩子仪式性地踩了一脚水坑。", "explanation": "这里应该用〈兴奋〉。“仪式性”指郑重讲究的仪式特点，不用来形容孩子玩耍时的兴奋情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场开幕式的仪式性很很强，大家都穿着正装。", "corrected_sentence": "这场开幕式的仪式性很强，大家都穿着正装。", "error_description": "错误：“很很强”，程度副词“很”重复使用。正确：“仪式性很强”，“很”只用一次，修饰形容词“强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这顿饭的仪式性感很强，大家都很认真。", "corrected_sentence": "这顿饭的仪式性很强，大家都很认真。", "error_description": "错误：“仪式性感”，“仪式性”后不能加“感”；“仪式感”是名词，与形容词“仪式性”混用是常见错误。正确：“仪式性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
