INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11625, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类与自然的关系，强调和谐共处。", "primary_collocate": null, "pronunciation": "rén yǔ zì rán", "ipa": "ɻən˧˥ y˨˩˦ tsɨ˥˩ ɻan˧˥", "syllable_count": 4, "sentences": [{"text": "因此，家庭堆肥不仅是技术操作，更是生态主体性建构的仪式性实践，在微观生活政治中重塑人与自然的伦理契约。", "target_word": "人与自然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些传统的水资源保护实践，体现了人与自然和谐相处的智慧。", "target_word": "人与自然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位作家常写人与自然的关系。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会让人与自然和谐相处。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次展览的主题是人与自然。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了人与自然的故事。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，人与自然应该互相尊重。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片讲的是人与自然。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护森林，就是保护人与自然的关系。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在山里学习人与自然的知识。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人与自然|名词|人类与自然的和谐关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbc18688-d601-46ef-99b3-ee748b978efe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人与自然", "is_correct": true, "explanation": "正确。这里指人类与大自然之间的伦理关系，与前文“生态主体性”“家庭堆肥”的语境相符。"}, {"text": "人与机器", "is_correct": false, "explanation": "语义：前文讲的是生态与自然，与机器无关，“人与机器”不符合这段论述的主题。"}, {"text": "人与神", "is_correct": false, "explanation": "语义：“神”带有宗教色彩，与这段讲生态实践的学术语境不符。"}, {"text": "人与金钱", "is_correct": false, "explanation": "搭配：“伦理契约”不与“金钱”搭配，“人与金钱的伦理契约”不成立。"}], "explanations": {"人与自然": "正确。这里指人类与大自然之间的伦理关系，与前文“生态主体性”“家庭堆肥”的语境相符。", "人与机器": "语义：前文讲的是生态与自然，与机器无关，“人与机器”不符合这段论述的主题。", "人与神": "语义：“神”带有宗教色彩，与这段讲生态实践的学术语境不符。", "人与金钱": "搭配：“伦理契约”不与“金钱”搭配，“人与金钱的伦理契约”不成立。"}, "sentence_index": 0, "correct_answer": "人与自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家人之间要多沟通，才能让人与自然和谐相处。", "explanation": "这里应该用〈人与人〉。人与自然指人类与大自然的关系，家人之间的相处应说“人与人”。"}, {"text": "食堂里的人与自然很和谐。", "explanation": "这里误把〈人与自然〉当成了“氛围”的意思。人与自然指人类与大自然的关系，食堂的氛围应说“氛围”。"}, {"text": "这家商店的人与自然很热闹。", "explanation": "这里误把〈人与自然〉当成了“人流”的意思。人与自然指人类与大自然的关系，形容商店热闹应说“人流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人与自然", "is_correct": true, "explanation": "正确。“人与自然应该互相尊重”符合人与大自然相处的观念，与“爷爷说”的语气相符。"}, {"text": "收入与支出", "is_correct": false, "explanation": "搭配：“互相尊重”不用于收入与支出这样的财务关系。"}, {"text": "公路与铁路", "is_correct": false, "explanation": "语义：公路与铁路是交通设施，句子讲的是需要相互尊重的相处关系，与之不符。"}, {"text": "门与窗", "is_correct": false, "explanation": "语义：门和窗是物件，不存在“互相尊重”的相处意义。"}], "explanations": {"人与自然": "正确。“人与自然应该互相尊重”符合人与大自然相处的观念，与“爷爷说”的语气相符。", "收入与支出": "搭配：“互相尊重”不用于收入与支出这样的财务关系。", "公路与铁路": "语义：公路与铁路是交通设施，句子讲的是需要相互尊重的相处关系，与之不符。", "门与窗": "语义：门和窗是物件，不存在“互相尊重”的相处意义。"}, "sentence_index": 6, "correct_answer": "人与自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里同学之间的人与自然关系很和谐。", "explanation": "这里应该用〈人际〉。人与自然指人类与大自然的关系，同学之间的相处应说“人际关系”。"}, {"text": "这次会议的人与自然很多，大家都很忙。", "explanation": "这里误把〈人与自然〉当成了“人数”的意思。人与自然指人类与大自然的关系，不能用来指会议的人数；说人多应用“人数”。"}, {"text": "这场比赛的人与自然很激烈。", "explanation": "这里误把〈人与自然〉当成了“竞争”的意思。人与自然指人类与大自然的关系，形容比赛激烈应说“竞争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书探讨的是人与自然地关系。", "corrected_sentence": "这本书探讨的是人与自然的关系。", "error_description": "错误：修饰名词“关系”应用“的”，这里误用了“地”。应说“人与自然的关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师讲解了人与自然们的关系。", "corrected_sentence": "这位老师讲解了人与自然的关系。", "error_description": "错误：“们”加在“自然”后面表示复数，但“自然”是不可数的概念。应说“人与自然的关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11629, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
