INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11629, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陆地上有轮子的交通工具，用于载人或运输物品。", "primary_collocate": null, "pronunciation": "chē", "ipa": "ʈʂʰɤ˥", "syllable_count": 1, "sentences": [{"text": "很多人坐车上班。", "target_word": "车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样，路上的车就少了。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "开车会排出废气，污染空气。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车可以坐很多人。", "target_word": "车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人选择公共交通工具，而不是每个人都开车，这对环境有很多好处。", "target_word": "车", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "开车的人少了，空气中的污染也就减少了。", "target_word": "车", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "路上的车排放的废气会让空气变坏，对健康不好。", "target_word": "车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "而一辆车可以同时运送很多人，比每人都开车更环保。", "target_word": "车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐公共交通工具时，每个人的碳足迹通常比开车小很多。", "target_word": "车", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "如果更多人选择坐地铁或公交，路上的车就会减少，堵车情况也会变好。", "target_word": "车", "complexity_tier": "T4", "sentence_source": "mined"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "汽车", "label": "复合"}, {"form": "公交车", "label": "复合"}, {"form": "車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：陆地上有轮子、载人或运货的交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11629, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车", "is_correct": true, "explanation": "车（chē，第一声）指陆地上有轮子的交通工具，是正确答案。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chē（第一声）声调不同，意思是茶。"}, {"text": "撤", "is_correct": false, "explanation": "chè（第四声）与 chē 声调不同，意思是撤退、撤销。"}, {"text": "遮", "is_correct": false, "explanation": "zhē 与 chē 声母不同：zh 与 ch，意思是遮挡。"}, {"text": "扯", "is_correct": false, "explanation": "chě（第三声）与 chē 声调不同，意思是拉、扯。"}], "explanations": {"车": "车（chē，第一声）指陆地上有轮子的交通工具，是正确答案。", "茶": "chá（第二声）与 chē（第一声）声调不同，意思是茶。", "撤": "chè（第四声）与 chē 声调不同，意思是撤退、撤销。", "遮": "zhē 与 chē 声母不同：zh 与 ch，意思是遮挡。", "扯": "chě（第三声）与 chē 声调不同，意思是拉、扯。"}, "sentence_index": null, "correct_answer": "车"}, "level_3": {"options": [{"text": "车", "is_correct": true, "explanation": "车：“坐车上班”指乘坐车辆上班，空位应填“车”。"}, {"text": "站", "is_correct": false, "explanation": "语义：乘坐的是车，不是站点，“坐站上班”说不通。"}, {"text": "票", "is_correct": false, "explanation": "搭配：“坐票”指有座位的车票，不是乘坐的交通工具，“坐票上班”不成立。"}, {"text": "路", "is_correct": false, "explanation": "搭配：“坐路上班”不成立，“路”不能作为乘坐的交通工具。"}], "explanations": {"车": "车：“坐车上班”指乘坐车辆上班，空位应填“车”。", "站": "语义：乘坐的是车，不是站点，“坐站上班”说不通。", "票": "搭配：“坐票”指有座位的车票，不是乘坐的交通工具，“坐票上班”不成立。", "路": "搭配：“坐路上班”不成立，“路”不能作为乘坐的交通工具。"}, "sentence_index": 0, "correct_answer": "车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一朵车，很便宜。", "explanation": "这里应该用〈辆〉。车的量词是“辆”，“朵”用于花朵，不用于车。"}, {"text": "我每天都用车写作业。", "explanation": "这里应该用〈笔〉。车指交通工具，不能用来写字。"}, {"text": "我们沿着车走去学校。", "explanation": "这里应该用〈马路〉。车是交通工具，人不能沿着车走路，应说“沿着马路走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车", "is_correct": true, "explanation": "车：“路上的车”指道路上行驶的交通工具，空位应填“车”。"}, {"text": "水", "is_correct": false, "explanation": "语义：“水”不能排放废气，“路上的水排放的废气”说不通。"}, {"text": "笛", "is_correct": false, "explanation": "语义：“笛”是乐器，不会排放废气，“路上的笛排放的废气”说不通。"}, {"text": "缸", "is_correct": false, "explanation": "语义：“缸”是容器，不会排放废气，“路上的缸排放的废气”说不通。"}], "explanations": {"车": "车：“路上的车”指道路上行驶的交通工具，空位应填“车”。", "水": "语义：“水”不能排放废气，“路上的水排放的废气”说不通。", "笛": "语义：“笛”是乐器，不会排放废气，“路上的笛排放的废气”说不通。", "缸": "语义：“缸”是容器，不会排放废气，“路上的缸排放的废气”说不通。"}, "sentence_index": 6, "correct_answer": "车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门前有一棵车，很大。", "explanation": "这里应该用〈辆〉。“棵”用于树木，车的量词是“辆”。"}, {"text": "他每天早上用车刷牙。", "explanation": "这里应该用〈牙刷〉。车指交通工具，不能用来刷牙。"}, {"text": "我家门口停着一把车，很干净。", "explanation": "这里应该用〈辆〉。车的量词是“辆”，“把”用于有柄的器具，不用于车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区门口停了一只车。", "corrected_sentence": "我们小区门口停了一辆车。", "error_description": "错误形式：“一只车”；正确形式：“一辆车”。车的量词是“辆”，“只”用于动物或成对的东西，不用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路口的红绿灯变了，车们都停下来了。", "corrected_sentence": "路口的红绿灯变了，车都停下来了。", "error_description": "错误形式：“车们”；正确形式：“车”。“们”一般只加在指人的名词后面，表示物的“车”不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
