INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11631, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使物体从封闭的地方出来。", "primary_collocate": null, "pronunciation": "fàng chū", "ipa": "faŋ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "开车会放出脏东西，让空气污染。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "工厂放出的烟太多，天空都变灰了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子打开笼子，把小鸟放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花晚上会放出很香的气味。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水器会放出热气，浴室里很暖和。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天早上把鸡放出，晚上再关起来。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开门，我把小狗放出去玩了一会儿。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯一到晚上就会放出光。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，里面的冷气全放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把瓶子里的气放出了一点。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放出了", "label": "体标"}, {"form": "放出来", "label": "复合"}, {"form": "放出去", "label": "复合"}], "register": "中性", "sense_fingerprint": "使物体、气体或光从封闭的地方出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正确：放出指使物体、气体从封闭的地方出来，与“排出脏东西”的语义相符。"}, {"text": "清理", "is_correct": false, "explanation": "语义：清理会减少污染，与后半句“让空气污染”的语义矛盾。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”的对象一般是衣物、布料，不能说缝补“脏东西”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是让坏的东西恢复正常，不是车排出东西的动作，与语境不符。"}], "explanations": {"放出": "正确：放出指使物体、气体从封闭的地方出来，与“排出脏东西”的语义相符。", "清理": "语义：清理会减少污染，与后半句“让空气污染”的语义矛盾。", "缝补": "搭配：“缝补”的对象一般是衣物、布料，不能说缝补“脏东西”。", "修理": "语义：修理是让坏的东西恢复正常，不是车排出东西的动作，与语境不符。"}, "sentence_index": 0, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把行李放出了，坐了下来。", "explanation": "这里应该用〈放下〉。放出指使物体从封闭的地方出来，不表示把东西放置下来；说“放下行李”才自然。"}, {"text": "他放出了这次比赛，很可惜。", "explanation": "这里应该用〈放弃〉。放出指物质从封闭处出来，不能用于比赛；表示不再做某事应用〈放弃〉。"}, {"text": "他把书放出了桌子上。", "explanation": "这里应该用〈放在〉。放出指使物体从封闭的地方出来，不表示把东西摆到某处；说“放在桌子上”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正确：放出去指把小狗从屋里放出，与“打开门”“去玩”的语境相符。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”与“打开门”的语境矛盾，“关去玩”说不通。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁”是把东西封起来，与“打开门”“去玩”冲突，不能用来说放小狗出去玩。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象一般是吃的东西或动物进食，不能说“喂去玩”。"}], "explanations": {"放出": "正确：放出去指把小狗从屋里放出，与“打开门”“去玩”的语境相符。", "关": "语义：“关”与“打开门”的语境矛盾，“关去玩”说不通。", "锁": "语义：“锁”是把东西封起来，与“打开门”“去玩”冲突，不能用来说放小狗出去玩。", "喂": "搭配：“喂”的对象一般是吃的东西或动物进食，不能说“喂去玩”。"}, "sentence_index": 6, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把东西放出了箱子里。", "explanation": "这里应该用〈放进〉。放出表示从封闭的地方出来，与“放进”方向相反，且“放出……箱子里”自相矛盾。"}, {"text": "他放出了一个笑容，大家都很开心。", "explanation": "这里应该用〈露出〉。放出指使物体从封闭处出来，不用于表情；表示脸上显出笑容应用〈露出〉。"}, {"text": "他终于放出了心情，觉得很轻松。", "explanation": "这里应该用〈放松〉。放出指物体从封闭处出来，不用于心情；表示心情松弛应用〈放松〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂放出了一只烟，天空变灰了。", "corrected_sentence": "工厂放出了一股烟，天空变灰了。", "error_description": "错误：“烟”的量词应用“股”，“只”用于动物或小件物品，不能修饰“烟”；应说“一股烟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器会很放出一些热气。", "corrected_sentence": "这台机器会放出一些热气。", "error_description": "错误：程度副词“很”不能修饰动词“放出”，应去掉“很”，说“会放出一些热气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
