INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指不干净、污秽的物品或垃圾。", "primary_collocate": null, "pronunciation": "zāng dōng xi", "ipa": "tsaŋ˥ tʊŋ˥ ɕi", "syllable_count": 3, "sentences": [{"text": "开车会放出脏东西，让空气污染。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "地上有很多脏东西，快去打扫一下。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭以前先洗手，别把脏东西吃进去。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把脏东西带回了家。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的脏东西越来越多，鱼都不见了。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛里进了脏东西，他一直流眼泪。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把垃圾桶里的脏东西倒掉。", "target_word": "脏东西", "complexity_tier": "T3", "furigana": "qǐng bǎ lā jī tǒng lǐ de zāng dōng xi dǎo diào.", "sentence_source": "generated"}, {"text": "小狗在外面玩，身上沾了不少脏东西。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别捡路边的脏东西，上面有很多细菌。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气中的脏东西太多，我们要戴口罩。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不干净的东西，如灰尘、垃圾、污物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脏东西", "is_correct": true, "explanation": "正确：“脏东西”指不干净的污物，开车排放的污物可以说放出脏东西。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物是活的动物，不是车辆排放的污物，与“放出”的语境不合。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“放出”用于排放废气、气味等，不能说放出玩具。"}, {"text": "花粉", "is_correct": false, "explanation": "语义：花粉来自植物，开车排放的是废气，花粉与句意不符。"}], "explanations": {"脏东西": "正确：“脏东西”指不干净的污物，开车排放的污物可以说放出脏东西。", "宠物": "语义：宠物是活的动物，不是车辆排放的污物，与“放出”的语境不合。", "玩具": "搭配：“放出”用于排放废气、气味等，不能说放出玩具。", "花粉": "语义：花粉来自植物，开车排放的是废气，花粉与句意不符。"}, "sentence_index": 0, "correct_answer": "脏东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把刚买的新碗当成脏东西，洗了三遍才用。", "explanation": "这里应该用〈餐具〉。脏东西指不干净的物品，刚买的新碗并不脏，不能说成脏东西。"}, {"text": "这盘刚洗好的草莓很干净，是一堆脏东西。", "explanation": "这里应该用〈水果〉。脏东西指不干净的东西，刚洗好的草莓是干净的食物，不能说成脏东西。"}, {"text": "这束花是脏东西，我很喜欢。", "explanation": "这里应该用〈鲜花〉。脏东西指不干净的东西，鲜花不是脏东西，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脏东西", "is_correct": true, "explanation": "正确：“倒掉”的是垃圾桶里的废弃污物，与“脏东西”相合。"}, {"text": "宝贝", "is_correct": false, "explanation": "语义：垃圾桶里装的是废弃物，宝贝是珍贵的，不会被倒掉，与句意矛盾。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“倒掉”用于液体或废弃物，不能说倒掉钥匙。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币有价值，人们不会把它当作脏东西倒掉，与句意不合。"}], "explanations": {"脏东西": "正确：“倒掉”的是垃圾桶里的废弃污物，与“脏东西”相合。", "宝贝": "语义：垃圾桶里装的是废弃物，宝贝是珍贵的，不会被倒掉，与句意矛盾。", "钥匙": "搭配：“倒掉”用于液体或废弃物，不能说倒掉钥匙。", "硬币": "语义：硬币有价值，人们不会把它当作脏东西倒掉，与句意不合。"}, "sentence_index": 6, "correct_answer": "脏东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刚出炉的蛋糕放在桌上，我把它当成了脏东西。", "explanation": "这里应该用〈美食〉。脏东西指不干净的东西，刚出炉的蛋糕是干净的食物，不能当成脏东西。"}, {"text": "他在路上捡到了脏东西，那可是一件珍贵的文物。", "explanation": "这里应该用〈文物〉。脏东西指不干净的东西，珍贵的文物不能说成脏东西。"}, {"text": "院子里的脏东西开得很漂亮。", "explanation": "这里应该用〈花〉。脏东西指不干净的东西，开得漂亮的是花，不能用脏东西来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "垃圾桶里装着一堆脏东西们。", "corrected_sentence": "垃圾桶里装着一堆脏东西。", "error_description": "错误：“脏东西们”；正确：“脏东西”。“们”只用于指人的名词，“脏东西”指物品或垃圾，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地板角落里有一根脏东西，快去清理。", "corrected_sentence": "地板角落里有一堆脏东西，快去清理。", "error_description": "错误：“一根脏东西”；正确：“一堆脏东西”。“根”只用于细长条状的东西，“脏东西”应用“一堆”来量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
