INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11633, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "空气污染是指空气中含有有害物质，对人体健康和环境造成不良影响的现象。", "primary_collocate": null, "pronunciation": "kōng qì wū rǎn", "ipa": "kʰʊŋ˥ tɕʰi˥˩ u˥ ɻan˨˩˦", "syllable_count": 4, "sentences": [{"text": "开车会放出脏东西，造成空气污染。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天空气污染很严重，我们戴了口罩。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂太多会造成空气污染。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气污染对孩子的身体不好。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了减少空气污染，很多人坐地铁上班。", "target_word": "空气污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气污染严重的时候，不要出去跑步。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里的空气污染让老人经常咳嗽。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多种树有助于治理空气污染。", "target_word": "空气污染", "complexity_tier": "T3", "furigana": "duō zhòng shù yǒu zhù yú zhì lǐ kōng qì wū rǎn.", "sentence_source": "generated"}, {"text": "冬天烧煤取暖会带来空气污染。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻说，这个城市的空气污染比去年少了。", "target_word": "空气污染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "空气污染指数", "label": "复合"}], "register": "中性", "sense_fingerprint": "空气污染：空气中有有害物质，影响健康和环境的现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气污染", "is_correct": true, "explanation": "正确：放出脏东西会造成空气污染，与句意相合。"}, {"text": "空气清新", "is_correct": false, "explanation": "语义：清理会减少污染，与后半句“造成空气污染”的语义矛盾。"}, {"text": "交通堵塞", "is_correct": false, "explanation": "搭配：“造成”后接的结果应与排放脏东西有因果关系，“交通堵塞”不是它的结果。"}, {"text": "树木茂盛", "is_correct": false, "explanation": "语义：排放脏东西不会让树木茂盛，与句意矛盾。"}], "explanations": {"空气污染": "正确：放出脏东西会造成空气污染，与句意相合。", "空气清新": "语义：清理会减少污染，与后半句“造成空气污染”的语义矛盾。", "交通堵塞": "搭配：“造成”后接的结果应与排放脏东西有因果关系，“交通堵塞”不是它的结果。", "树木茂盛": "语义：排放脏东西不会让树木茂盛，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "空气污染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行带来的是一场空气污染，大家都玩得很开心。", "explanation": "这里应该用〈游玩〉。空气污染指有害的现象，不能用来说成让人开心的活动。"}, {"text": "厨房里飘出阵阵空气污染，大家都饿了。", "explanation": "这里应该用〈香味〉。空气污染指有害的现象，不能用来形容飘出的香气。"}, {"text": "他每天早上吃一碗粥，说空气污染的味道很香。", "explanation": "这里应该用〈食物〉。空气污染指有害的现象，不能当作食物或香味来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气污染", "is_correct": true, "explanation": "正确：城市里的空气污染会让老人经常咳嗽，与句意相合。"}, {"text": "新鲜空气", "is_correct": false, "explanation": "语义：新鲜空气不会让人咳嗽，与句中“让老人经常咳嗽”矛盾。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光与空气质量无关，不会让老人经常咳嗽。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“让”的主语应是引起咳嗽的因素，“图书馆”不是这样的因素。"}], "explanations": {"空气污染": "正确：城市里的空气污染会让老人经常咳嗽，与句意相合。", "新鲜空气": "语义：新鲜空气不会让人咳嗽，与句中“让老人经常咳嗽”矛盾。", "阳光": "语义：阳光与空气质量无关，不会让老人经常咳嗽。", "图书馆": "搭配：“让”的主语应是引起咳嗽的因素，“图书馆”不是这样的因素。"}, "sentence_index": 6, "correct_answer": "空气污染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工地的空气污染太吵了，晚上根本睡不着。", "explanation": "这里应该用〈噪音〉。空气污染指有害物质造成的现象，不能用来形容声音吵。"}, {"text": "今天的空气污染特别好，我们出去晒太阳吧。", "explanation": "这里应该用〈天气〉。空气污染指有害的现象，不能用来说天气好。"}, {"text": "屋里的空气污染很清新，闻起来像刚下过雨。", "explanation": "这里应该用〈新鲜空气〉。空气污染指有害的现象，不能用来形容清新的气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故造成了一只严重的空气污染。", "corrected_sentence": "这次事故造成了一场严重的空气污染。", "error_description": "量词错误：“空气污染”应用量词“场”，“只”用于动物等，不能用于此，应说“一场严重的空气污染”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人戴口罩，是为了防止空气污染了。", "corrected_sentence": "很多人戴口罩，是为了防止空气污染。", "error_description": "错误：“防止空气污染了”；正确：“防止空气污染”。“防止”后面的宾语是要避免的情况，不能带“了”表示已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
