INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指公共汽车行驶或规划的固定路线，通常有编号和站点。", "primary_collocate": null, "pronunciation": "gōng jiāo xiàn lù", "ipa": "kʊŋ˥ tɕjɑʊ˥ ɕjɛn˥˩ lu˥˩", "syllable_count": 4, "sentences": [{"text": "城市规划让公交线路方便。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这条公交线路经过我们学校。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天坐这条公交线路去上班。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的公交线路下个月开通。", "target_word": "公交线路", "complexity_tier": "T3", "furigana": "xīn de gōngjiāo xiànlù xià gè yuè kāitōng", "sentence_source": "generated"}, {"text": "这个城市有一百多条公交线路。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站牌上写着这条公交线路的每一站。", "target_word": "公交线路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交线路太少，老人出门不方便。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司旁边新开了一条公交线路。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先查一下公交线路，再决定怎么走。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交线路改了，今天我坐错了车。", "target_word": "公交线路", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条公交线路", "label": "量词"}, {"form": "公交线路图", "label": "复合"}], "register": "中性", "sense_fingerprint": "公交线路：公共汽车固定的行驶或规划路线，有编号和站点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公交线路", "is_correct": true, "explanation": "公交线路：公共汽车的固定路线，城市规划可以让它更方便。"}, {"text": "手机号码", "is_correct": false, "explanation": "语义：城市规划不影响手机号码，句意不通。"}, {"text": "身份证", "is_correct": false, "explanation": "语义：城市规划不会让身份证更方便，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“方便”说出行、办事，不用于价格，价格应说“便宜”。"}], "explanations": {"公交线路": "公交线路：公共汽车的固定路线，城市规划可以让它更方便。", "手机号码": "语义：城市规划不影响手机号码，句意不通。", "身份证": "语义：城市规划不会让身份证更方便，句意不通。", "价格": "搭配：“方便”说出行、办事，不用于价格，价格应说“便宜”。"}, "sentence_index": 0, "correct_answer": "公交线路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位司机把公交线路开到了终点站。", "explanation": "这里应该用〈公交车〉。“开”的是车，“公交线路”指路线，不能驾驶。"}, {"text": "他把公交线路装进了书包，带去学校。", "explanation": "这里应该用〈线路图〉。“装进书包”的是图纸，“公交线路”指路线，不能装进包里。"}, {"text": "我在公交线路等车，等了很久。", "explanation": "这里应该用〈公交站〉。等车要在站点，“公交线路”指路线，不能在线路上等车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公交线路", "is_correct": true, "explanation": "公交线路：公共汽车的固定路线，线路太少会让老人出门不便。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍多少与老人出门无关，句意不通。"}, {"text": "红包", "is_correct": false, "explanation": "语义：红包与老人出门没有关系，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“太少”不用于价格，价格应说“太高”或“太低”。"}], "explanations": {"公交线路": "公交线路：公共汽车的固定路线，线路太少会让老人出门不便。", "书籍": "语义：书籍多少与老人出门无关，句意不通。", "红包": "语义：红包与老人出门没有关系，句意不通。", "价格": "搭配：“太少”不用于价格，价格应说“太高”或“太低”。"}, "sentence_index": 6, "correct_answer": "公交线路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在售票处买了公交线路，花了两块钱。", "explanation": "这里应该用〈车票〉。“买”的是票，“公交线路”指路线，不能购买。"}, {"text": "我下车以后向公交线路问路。", "explanation": "这里应该用〈司机〉。“问路”要问人，“公交线路”不是人，不能询问。"}, {"text": "这条公交线路短路了，家里停电了。", "explanation": "这里应该用〈电路〉。“短路”是电路的故障，“公交线路”指公共汽车的路线，不能短路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城市东边新开了一辆公交线路，方便上班族。", "corrected_sentence": "城市东边新开了一条公交线路，方便上班族。", "error_description": "量词错误：“线路”应用“条”，“辆”用于车辆，不能修饰线路，应说“一条公交线路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这条公交线路查了一下。", "corrected_sentence": "我把这条公交线路查了一下。", "error_description": "把字句遗漏：要表示对“这条公交线路”进行处置，应在前面加“把”，说“我把这条公交线路查了一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
