INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11642, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过脚的运动使身体向前移动。", "primary_collocate": null, "pronunciation": "zǒu lù", "ipa": "tsou˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "走路或骑自行车去工作也是好办法。", "target_word": "走路", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我家离学校很近，走路五分钟就到。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶每天晚饭后都去公园走路。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩一岁就会走路了。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的腿受伤了，现在走路很慢。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天天气好，我们走路去超市吧。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走路的时候不要看手机。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走路很快，我跟不上她。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说每天走路对身体好。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想坐车，想走路回家。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用脚步行、不乘车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走路", "is_correct": true, "explanation": "正确：“走路”指用脚步行，与“骑自行车”并列，构成“走路或骑自行车”的说法。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是在水中运动，不能表示去工作的方式。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“去工作”矛盾，不能作为出行方式。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”不能与“去工作”的出行方式并列，句子不通。"}], "explanations": {"走路": "正确：“走路”指用脚步行，与“骑自行车”并列，构成“走路或骑自行车”的说法。", "游泳": "语义：“游泳”是在水中运动，不能表示去工作的方式。", "睡觉": "语义：“睡觉”与“去工作”矛盾，不能作为出行方式。", "唱歌": "搭配：“唱歌”不能与“去工作”的出行方式并列，句子不通。"}, "sentence_index": 0, "correct_answer": "走路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车每天走路去上班。", "explanation": "这里应该用〈开〉。走路只指人或动物用腿移动，汽车没有腿，不能说走路。"}, {"text": "我们的飞机走路去了北京。", "explanation": "这里应该用〈飞〉。飞机不能用腿行走，走路只用于有腿的人或动物。"}, {"text": "这台洗衣机走路到了阳台。", "explanation": "这里应该用〈挪〉。洗衣机没有腿，不能自己走路，只能说挪到阳台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走路", "is_correct": true, "explanation": "正确：“走路的时候”指行走时，与“不要看手机”的注意事项相符。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“衣服”是名词，“衣服的时候不要看手机”不通。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”表示跌倒，不是一种活动，句子说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”是名词，不能作动作，“眼睛的时候不要看手机”不通。"}], "explanations": {"走路": "正确：“走路的时候”指行走时，与“不要看手机”的注意事项相符。", "衣服": "语义：“衣服”是名词，“衣服的时候不要看手机”不通。", "摔": "语义：“摔”表示跌倒，不是一种活动，句子说不通。", "眼睛": "语义：“眼睛”是名词，不能作动作，“眼睛的时候不要看手机”不通。"}, "sentence_index": 6, "correct_answer": "走路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树每天走路去河边。", "explanation": "这里应该用〈生长〉。树没有腿，不能走路，植物只能说生长或长大。"}, {"text": "这把椅子走路搬回了家。", "explanation": "这里应该用〈搬〉。椅子没有腿，不能自己走路，只能被搬回家。"}, {"text": "这条鱼想走路回海里。", "explanation": "这里应该用〈游〉。鱼没有腿，走路只用于用腿行走的生物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他走路得很快。", "corrected_sentence": "他走路走得很快。", "error_description": "错误在于补语结构。“走得很快”是动词带补语，“得”前要重复动词“走”，不能只说“走路得很快”；正确形式：“他走路走得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走路着很慢。", "corrected_sentence": "他走路很慢。", "error_description": "错误在于多加了“着”。“走路”是一个动宾式的词，后面不能直接加“着”，应说“他走路很慢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
