INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11643, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指两腿分开跨坐，通常用于乘坐马、自行车、摩托车等。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "走路或骑自行车去工作也是好办法。", "target_word": "骑", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "周末我常常骑马去草地上玩。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑摩托车去上班。", "target_word": "骑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明会骑自行车了。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天骑自行车去学校，不坐公交车了。", "target_word": "骑", "complexity_tier": "T3", "furigana": "qí", "sentence_source": "generated"}, {"text": "骑自行车的时候要戴头盔。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐骑着马在草地上慢慢走。", "target_word": "骑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你骑过马吗？", "target_word": "骑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸教我骑车，我骑得很慢。", "target_word": "骑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自行车骑到了公园门口。", "target_word": "骑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骑了", "label": "体标（了）"}, {"form": "骑过", "label": "体标（过）"}, {"form": "骑着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "跨坐在马或车上并驾驭前行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11643, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「骑」读 qí，指两腿分开跨坐在自行车上行进。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是气体、气息。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是期限、日期。"}], "explanations": {"骑": "正确：「骑」读 qí，指两腿分开跨坐在自行车上行进。", "起": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。", "气": "qì（第四声）与 qí（第二声）声调不同，意思是气体、气息。", "七": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。", "期": "qī（第一声）与 qí（第二声）声调不同，意思是期限、日期。"}, "sentence_index": null, "correct_answer": "骑"}, "level_3": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「骑自行车」是骑车的说法，与「走路」并列。"}, {"text": "开", "is_correct": false, "explanation": "搭配：「开」用于汽车等，不能说开自行车。"}, {"text": "修", "is_correct": false, "explanation": "语义：「修」是维修，不能表示去工作的方式。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」是清洗，与去工作的交通方式无关。"}], "explanations": {"骑": "正确：「骑自行车」是骑车的说法，与「走路」并列。", "开": "搭配：「开」用于汽车等，不能说开自行车。", "修": "语义：「修」是维修，不能表示去工作的方式。", "洗": "语义：「洗」是清洗，与去工作的交通方式无关。"}, "sentence_index": 0, "correct_answer": "骑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天骑公交车去学校。", "explanation": "这里应该用〈坐〉。骑指两腿分开跨坐，公交车是坐的，不能骑。"}, {"text": "我每天骑电梯去办公室。", "explanation": "这里应该用〈乘〉。电梯是乘坐的，骑只用于跨坐在马或车上。"}, {"text": "我每天骑船去上班。", "explanation": "这里应该用〈坐〉或〈划〉。船不能被骑，骑只用于跨坐在马或车上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11643, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「骑」读 qí，指跨坐在马或车上前行。"}, {"text": "启", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启、启发。"}, {"text": "汽", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是蒸汽、汽车的汽。"}, {"text": "欺", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。"}, {"text": "漆", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是油漆。"}], "explanations": {"骑": "正确：「骑」读 qí，指跨坐在马或车上前行。", "启": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启、启发。", "汽": "qì（第四声）与 qí（第二声）声调不同，意思是蒸汽、汽车的汽。", "欺": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。", "漆": "qī（第一声）与 qí（第二声）声调不同，意思是油漆。"}, "sentence_index": null, "correct_answer": "骑"}, "level_3": {"options": [{"text": "骑", "is_correct": true, "explanation": "正确：「姐姐骑着马」指跨坐马背上，与「草地上慢慢走」相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，“吃着马在草地上慢慢走”不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”表示饮用，“喝着马”不通，句子不成立。"}, {"text": "追", "is_correct": false, "explanation": "语义：「追」表示快速赶上，与「慢慢走」的描写矛盾。"}], "explanations": {"骑": "正确：「姐姐骑着马」指跨坐马背上，与「草地上慢慢走」相符。", "吃": "语义：“吃”表示进食，“吃着马在草地上慢慢走”不通。", "喝": "语义：“喝”表示饮用，“喝着马”不通，句子不成立。", "追": "语义：「追」表示快速赶上，与「慢慢走」的描写矛盾。"}, "sentence_index": 6, "correct_answer": "骑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把花骑到了桌子上。", "explanation": "这里应该用〈放〉。骑只用于人或动物跨坐，花不能被骑。"}, {"text": "这片树叶骑到了窗台上。", "explanation": "这里应该用〈落〉或〈飘〉。树叶没有腿，不能跨坐，骑只用于人或动物跨坐在马或车上。"}, {"text": "妈妈骑了一个苹果。", "explanation": "这里应该用〈拿〉或〈吃〉。苹果不能被骑，骑只用于人或动物跨坐在马或车上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑很快。", "corrected_sentence": "他骑得很快。", "error_description": "错误在于补语前缺少「得」。「骑」后带程度补语要说「骑得很快」，「骑很快」不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑马了去草地上玩。", "corrected_sentence": "他骑了马去草地上玩。", "error_description": "错误在于体标「了」位置不对。「了」应紧跟动词「骑」，说「骑了马」，不能放在宾语后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
