INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自行车是一种常见的交通工具，通常有两个轮子，通过脚踏板驱动链条带动后轮前进。", "primary_collocate": null, "pronunciation": "zì xíng chē", "ipa": "tsz̩˥˩ ɕiŋ˧˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "走路或骑自行车去工作也是好办法。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我每天骑自行车上学，不用坐公交车。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自行车坏了，需要修一下。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车是爸爸送给我的生日礼物。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们骑着自行车去公园玩。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车的轮子没气了，我去打气。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自行车停在楼下了。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在城市里骑自行车比开车方便。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候学过骑自行车。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把自行车放在门口的车棚里。", "target_word": "自行车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "电动自行车", "label": "复合"}, {"form": "自行车道", "label": "复合"}, {"form": "自行車", "label": "繁体"}], "register": "通用", "sense_fingerprint": "靠脚踏板驱动的两轮交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b79c64-687c-41da-88a3-fa2136641a60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自行车", "is_correct": true, "explanation": "正确。“骑自行车”是常用说法，与“走路”并列为出行方式。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：“骑”不能用于公交车，应说“坐公交车”。"}, {"text": "出租车", "is_correct": false, "explanation": "搭配：“骑”不能用于出租车，应说“坐出租车”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是轨道交通，人不能“骑”，与前面“走路”的人力出行不合。"}], "explanations": {"自行车": "正确。“骑自行车”是常用说法，与“走路”并列为出行方式。", "公交车": "搭配：“骑”不能用于公交车，应说“坐公交车”。", "出租车": "搭配：“骑”不能用于出租车，应说“坐出租车”。", "地铁": "语义：地铁是轨道交通，人不能“骑”，与前面“走路”的人力出行不合。"}, "sentence_index": 0, "correct_answer": "自行车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天给自行车加油，骑去学校。", "explanation": "这里应该用〈摩托车〉。加油是给摩托车等机动车做的事，自行车靠人蹬，不需要加油。"}, {"text": "他每天开自行车去上班。", "explanation": "这里应该用〈骑〉。自行车靠脚蹬，要用“骑”，“开”用于汽车等机动车。"}, {"text": "她每天给自行车梳头。", "explanation": "这里应该用〈擦〉，即“擦自行车”。“梳头”只用于人，清洁自行车要用“擦”或“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自行车", "is_correct": true, "explanation": "正确。“停”的对象是自行车这类交通工具，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“停”用于车辆，书包应说“放”，不能说“停”。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“停”不能用于衣服，衣服不会“停在楼下”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能自己移动或“停在楼下”，与句意不合。"}], "explanations": {"自行车": "正确。“停”的对象是自行车这类交通工具，符合句意。", "书包": "搭配：“停”用于车辆，书包应说“放”，不能说“停”。", "衣服": "搭配：“停”不能用于衣服，衣服不会“停在楼下”。", "冰箱": "语义：冰箱是家用电器，不能自己移动或“停在楼下”，与句意不合。"}, "sentence_index": 6, "correct_answer": "自行车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请帮我给自行车充电。", "explanation": "这里应该用〈电动自行车〉。充电的是电动车；普通自行车靠人蹬，不需要充电。"}, {"text": "这辆自行车发动了，我们出发吧。", "explanation": "这里应该用〈骑〉。“发动”指启动发动机，自行车没有发动机，应说“骑上自行车”。"}, {"text": "妈妈把自行车哄睡了。", "explanation": "这里应该用〈停〉。“哄睡”用于需要安抚的人，自行车停放要用“停”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天修好了一个自行车。", "corrected_sentence": "我昨天修好了一辆自行车。", "error_description": "量词错误：“自行车”的量词应为“辆”，不能说“一个自行车”。应改为“修好了一辆自行车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我姐姐自行车。", "corrected_sentence": "这是我姐姐的自行车。", "error_description": "“的”漏用：表示领属关系的定语与中心语之间要加“的”，应说“姐姐的自行车”，不能说“姐姐自行车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a604ca5-856b-4e8b-ac01-e8eb9932bbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重", "is_correct": true, "explanation": "重：与“轻”相对，指程度深，与“这次的感冒很轻”形成反义。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“轻”没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮：形容光线，与“轻”没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "甜：形容味道，与“轻”没有反义关系。"}], "correct_answer": "重", "explanations": {"重": "重：与“轻”相对，指程度深，与“这次的感冒很轻”形成反义。", "快": "快：形容速度，与“轻”没有反义关系。", "亮": "亮：形容光线，与“轻”没有反义关系。", "甜": "甜：形容味道，与“轻”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指重量小，与‘重’相对；也指程度浅、数量少或不重要。", "primary_collocate": null, "pronunciation": "qīng", "ipa": "tɕʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "碳足迹小，地球的负担就轻。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他的伤很轻，不用住院。", "target_word": "轻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次犯的错不大，处罚也很轻。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的感冒很轻，吃点药就好了。", "target_word": "轻", "complexity_tier": "T3", "furigana": "zhè cì de gǎnmào hěn qīng, chī diǎn yào jiù hǎo le", "sentence_source": "generated"}, {"text": "这种药的副作用很轻，大部分人都能接受。", "target_word": "轻", "complexity_tier": "T3", "furigana": "zhè zhǒng yào de fùzuòyòng hěn qīng, dàbùfen rén dōu néng jiēshòu", "sentence_source": "generated"}, {"text": "这件衣服很轻，夏天穿正合适。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的书包太重了，应该换个轻的。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的病比上次轻，他很快就好了。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和经理比，他的责任轻多了。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很轻，湖面几乎没有波浪。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻轻", "label": "重叠"}, {"form": "輕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "重量小；程度浅、数量少、不重要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻（qīng）：重量小，与“重”相对；也指程度浅、数量少。"}, {"text": "请", "is_correct": false, "explanation": "qǐng（第三声）与 qīng（第一声）声调不同，意思是请求。"}, {"text": "庆", "is_correct": false, "explanation": "qìng（第四声）与 qīng（第一声）声调不同，意思是庆祝。"}, {"text": "亲", "is_correct": false, "explanation": "qīn 与 qīng 韵尾不同（-n 与 -ng），意思是亲人。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 qīng（第一声）声调不同，意思是感情。"}], "explanations": {"轻": "轻（qīng）：重量小，与“重”相对；也指程度浅、数量少。", "请": "qǐng（第三声）与 qīng（第一声）声调不同，意思是请求。", "庆": "qìng（第四声）与 qīng（第一声）声调不同，意思是庆祝。", "亲": "qīn 与 qīng 韵尾不同（-n 与 -ng），意思是亲人。", "情": "qíng（第二声）与 qīng（第一声）声调不同，意思是感情。"}, "sentence_index": null, "correct_answer": "轻"}, "level_3": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻：与“碳足迹小”呼应，表示地球的负担少。"}, {"text": "重", "is_correct": false, "explanation": "语义：与前一分句“碳足迹小”矛盾，负担应当是轻，不是重。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容负担。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地，不能用来形容负担。"}], "explanations": {"轻": "轻：与“碳足迹小”呼应，表示地球的负担少。", "重": "语义：与前一分句“碳足迹小”矛盾，负担应当是轻，不是重。", "快": "搭配：“快”说速度，不能用来形容负担。", "硬": "搭配：“硬”说质地，不能用来形容负担。"}, "sentence_index": 0, "correct_answer": "轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次聚会参加的人很轻，大家都很开心。", "explanation": "这里应该用〈少〉。轻表示数量少时，多用于负担、损失、处罚等，不用来形容人数。"}, {"text": "他对这件事的印象很轻，过了几天就忘了。", "explanation": "这里应该用〈浅〉。印象的深浅要用“浅”，“轻”不用来形容印象。"}, {"text": "这幅画的颜色很轻，看起来很舒服。", "explanation": "这里应该用〈淡〉。颜色的深浅要用“淡”，“轻”不用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻（qīng）：重量小，与“重”相对；也指程度浅、数量少。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 qīng（第一声）声调不同，意思是晴天。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 qīng 声母不同（x 与 q），意思是星星。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 qīng 声母不同（j 与 q），意思是经过。"}, {"text": "惊", "is_correct": false, "explanation": "jīng 与 qīng 声母不同（j 与 q），意思是惊讶。"}], "explanations": {"轻": "轻（qīng）：重量小，与“重”相对；也指程度浅、数量少。", "晴": "qíng（第二声）与 qīng（第一声）声调不同，意思是晴天。", "星": "xīng 与 qīng 声母不同（x 与 q），意思是星星。", "经": "jīng 与 qīng 声母不同（j 与 q），意思是经过。", "惊": "jīng 与 qīng 声母不同（j 与 q），意思是惊讶。"}, "sentence_index": null, "correct_answer": "轻"}, "level_3": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻：与“太重了”形成对比，书包应换成重量小的。"}, {"text": "沉", "is_correct": false, "explanation": "语义：“沉”说的也是重，与“太重了”之后要换轻的语境矛盾。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”说温度，不能用来形容书包的重量。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来形容书包。"}], "explanations": {"轻": "轻：与“太重了”形成对比，书包应换成重量小的。", "沉": "语义：“沉”说的也是重，与“太重了”之后要换轻的语境矛盾。", "热": "搭配：“热”说温度，不能用来形容书包的重量。", "甜": "搭配：“甜”说味道，不能用来形容书包。"}, "sentence_index": 6, "correct_answer": "轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很轻，一点小事就发火。", "explanation": "这里应该用〈大〉。脾气的程度要用“大”，“轻”不用来形容脾气。"}, {"text": "这台机器的速度很轻，比以前快多了。", "explanation": "这里应该用〈快〉。速度的快慢用“快”，“轻”不用来形容速度。"}, {"text": "这座山的高度很轻，爬起来一点都不累。", "explanation": "这里应该用〈低〉。高度用“高”或“低”，“轻”不用来形容高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点小病轻很，不用去医院。", "corrected_sentence": "这点小病很轻，不用去医院。", "error_description": "错误形式：“轻很”。正确形式：“很轻”。形容词“轻”作谓语时，程度副词“很”要放在它前面，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她拿着很轻袋子，慢慢走回家。", "corrected_sentence": "她拿着很轻的袋子，慢慢走回家。", "error_description": "错误形式：“很轻袋子”，缺少结构助词“的”。正确形式：“很轻的袋子”。“轻”修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
