INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "规划者指的是负责制定、设计或安排计划、方案、项目等的人或角色。", "primary_collocate": null, "pronunciation": "guī huà zhě", "ipa": "kuei˥ xua˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "城市规划者发现，有绿色植物的大楼更受人们欢迎。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "城市规划者希望修更多的地铁和车站。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这座新城的规划者是一位年轻的女建筑师。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规划者先去看了那片地，然后画了地图。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的规划者希望多种一些树。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的规划者会先听居民的意见。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个小区的规划者，对这里很熟。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规划者把新路线画在了地图上。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位规划者每天都在办公室里画图。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的规划者想在旁边修一个大操场。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "城市规划者", "label": "复合"}, {"form": "規劃者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "负责制定、设计或安排计划方案的人（城市、公园等项目的规划人员）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规划者", "is_correct": true, "explanation": "正确。「城市规划者」作主语，与「城市」搭配，句意通顺：城市规划者发现绿色大楼更受欢迎。"}, {"text": "牧民", "is_correct": false, "explanation": "语义：牧民从事放牧，与「城市」不相容，「城市牧民发现」句意矛盾。"}, {"text": "渔夫", "is_correct": false, "explanation": "语义：渔夫在水上劳动，与「城市」和「绿色植物的大楼」的语境不符。"}, {"text": "矿工", "is_correct": false, "explanation": "语义：「矿工」是采矿的人，「城市矿工」与「城市规划者发现大楼更受欢迎」的语境不符，句意不通。"}], "explanations": {"规划者": "正确。「城市规划者」作主语，与「城市」搭配，句意通顺：城市规划者发现绿色大楼更受欢迎。", "牧民": "语义：牧民从事放牧，与「城市」不相容，「城市牧民发现」句意矛盾。", "渔夫": "语义：渔夫在水上劳动，与「城市」和「绿色植物的大楼」的语境不符。", "矿工": "语义：「矿工」是采矿的人，「城市矿工」与「城市规划者发现大楼更受欢迎」的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "规划者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只规划者很有经验，大家都很信任他。", "explanation": "这里应该用〈位〉。「规划者」指人，量词「只」多用于动物或物件，指人应用「位」。"}, {"text": "那位规划者亲手盖了这座大楼。", "explanation": "这里应该用〈建筑工人〉。规划者只负责制定方案，不亲手施工，盖楼要说〈建筑工人〉。"}, {"text": "那位规划者每天都在厨房里做饭。", "explanation": "这里应该用〈厨师〉。规划者指制定计划的人，不指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规划者", "is_correct": true, "explanation": "正确。「规划者」与「小区」搭配，符合「对这里很熟」的语境。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外来参观的人，与「对这里很熟」矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不是小区的身份，「他是这个小区的病人」句意不通。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：「小区的乘客」搭配不当，乘客指乘坐交通工具的人。"}], "explanations": {"规划者": "正确。「规划者」与「小区」搭配，符合「对这里很熟」的语境。", "游客": "语义：游客是外来参观的人，与「对这里很熟」矛盾。", "病人": "语义：病人不是小区的身份，「他是这个小区的病人」句意不通。", "乘客": "搭配：「小区的乘客」搭配不当，乘客指乘坐交通工具的人。"}, "sentence_index": 6, "correct_answer": "规划者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服是那位规划者缝制的。", "explanation": "这里应该用〈裁缝〉。规划者只负责制定计划，缝制衣服是裁缝的工作。"}, {"text": "那位规划者每天给病人打针。", "explanation": "这里应该用〈医生〉。规划者负责制定计划，给病人打针是医生的工作。"}, {"text": "这位规划者在台上指挥乐队。", "explanation": "这里应该用〈指挥者〉。规划者指做计划的人，台上指挥乐队是指挥者的职责，应说〈指挥者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只城市规划者要考虑交通和绿地。", "corrected_sentence": "一位城市规划者要考虑交通和绿地。", "error_description": "量词错误：「规划者」指人，应用量词「位」，「只」用于动物或物件，不能用于人。正确说法是「一位城市规划者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很规划者，对这里非常熟。", "corrected_sentence": "他是这个小区的规划者，对这里非常熟。", "error_description": "词类错误：副词「很」不能直接修饰名词「规划者」，应说「他是这个小区的规划者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
