INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11656, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "乘坐地铁这种交通工具。", "primary_collocate": null, "pronunciation": "zuò dì tiě", "ipa": "tswo˥˩ ti˥˩ tʰjɛ˨˩˦", "syllable_count": 3, "sentences": [{"text": "如果更多人选择坐地铁或公交，路上的车就会减少，堵车情况也会变好。", "target_word": "坐地铁", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这样，人们更愿意坐地铁。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我每天早上坐地铁去上班。", "target_word": "坐地铁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐地铁比开车快，也不用找停车的地方。", "target_word": "坐地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，很多人选择坐地铁出门。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么去机场？我想坐地铁去。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我和朋友坐地铁去看电影。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家离地铁站很近，所以天天坐地铁。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一次坐地铁的时候，我找不到出口。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐地铁的时候，请给老人让座。", "target_word": "坐地铁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐了地铁", "label": "体标"}, {"form": "坐过地铁", "label": "体标"}], "register": "中性", "sense_fingerprint": "乘坐城市地下轨道交通出行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18eb6d63-0232-4cd9-8252-5118ed2ad4bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐地铁", "is_correct": true, "explanation": "正确。「坐地铁」指乘地铁出行，与后面的「公交」并列，构成出行方式的选择。"}, {"text": "买车", "is_correct": false, "explanation": "语义：买车会增加车辆，与后半句「路上的车就会减少」矛盾。"}, {"text": "闯红灯", "is_correct": false, "explanation": "搭配：「选择」后接出行方式，「闯红灯」不是出行方式，无法与「公交」并列。"}, {"text": "逃课", "is_correct": false, "explanation": "语义：逃课不是出行方式，与「公交」并列不通，也与「堵车情况也会变好」无关。"}], "explanations": {"坐地铁": "正确。「坐地铁」指乘地铁出行，与后面的「公交」并列，构成出行方式的选择。", "买车": "语义：买车会增加车辆，与后半句「路上的车就会减少」矛盾。", "闯红灯": "搭配：「选择」后接出行方式，「闯红灯」不是出行方式，无法与「公交」并列。", "逃课": "语义：逃课不是出行方式，与「公交」并列不通，也与「堵车情况也会变好」无关。"}, "sentence_index": 0, "correct_answer": "坐地铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机每天坐地铁把乘客送到终点。", "explanation": "这里应该用〈开〉。司机是驾驶地铁，应说「开地铁」；「坐地铁」指作为乘客乘坐，不能表示驾驶。"}, {"text": "这辆出租车每天坐地铁去机场。", "explanation": "这里的错误在主语：「坐地铁」的主语须是乘车的人，出租车是交通工具，不能坐地铁，改用「开」也不通；可改为「我每天坐地铁去机场」。"}, {"text": "他坐地铁走到了车站。", "explanation": "「坐地铁」只表示乘车，不能与表示步行的动作连用；这里的误用在于把乘车义用于步行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐地铁", "is_correct": true, "explanation": "正确。「坐地铁」与「去看电影」搭配，表示周末出行的方式。"}, {"text": "上课", "is_correct": false, "explanation": "语义：周末一般不上课，「上课去看电影」与周末的休闲安排矛盾。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是学习任务，「考试去看电影」与「和朋友」的休闲语境不符。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：「生病」不能带「去看电影」这样的目的动作，句子不通。"}], "explanations": {"坐地铁": "正确。「坐地铁」与「去看电影」搭配，表示周末出行的方式。", "上课": "语义：周末一般不上课，「上课去看电影」与周末的休闲安排矛盾。", "考试": "语义：考试是学习任务，「考试去看电影」与「和朋友」的休闲语境不符。", "生病": "搭配：「生病」不能带「去看电影」这样的目的动作，句子不通。"}, "sentence_index": 6, "correct_answer": "坐地铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在车站坐地铁买票，排了很长的队。", "explanation": "「坐地铁」只能指乘车，在站内买票、排队时还没有乘车，不能说「坐地铁」。"}, {"text": "我在站台坐地铁，等了十分钟。", "explanation": "这里应该用〈等车〉。等车时还没上车，「坐地铁」指已经乘车，不能用于站台上的等候。"}, {"text": "乘客要先坐地铁，再进站。", "explanation": "这里应该用〈检票〉。进站前要先检票，「坐地铁」指乘车，应在进站后，顺序不能颠倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天我坐地铁了去市中心。", "corrected_sentence": "昨天我坐地铁去市中心。", "error_description": "了的位置错误：「了」不能紧跟宾语「地铁」之后，「坐地铁了去」不通，应删去「了」，正确为「昨天我坐地铁去市中心」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我周末都坐地铁看朋友。", "corrected_sentence": "我周末都坐地铁去看朋友。", "error_description": "漏字错误：「坐地铁」后表示去往的动词「去」不能省略，「坐地铁看朋友」不通，应为「坐地铁去看朋友」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11657, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
