INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指没有遇到交通堵塞，车辆可以顺利行驶的状态。", "primary_collocate": null, "pronunciation": "bù dǔ chē", "ipa": "pu˥˩ tu˨˩˦ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "地铁很快，也不堵车。", "target_word": "不堵车", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "周日早上路上人少，开车去公园不堵车。", "target_word": "不堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢坐地铁，因为地铁不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在是半夜，路上不堵车，我们很快就到家了。", "target_word": "不堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天五点出门，所以上班路上总是不堵车。", "target_word": "不堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新路很宽，下雨天也不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天不堵车，我们半小时就能到机场。", "target_word": "不堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假的时候城里人少，开车真的不堵车。", "target_word": "不堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车可以走小路，所以不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城车很少，早上上班也不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "道路通畅、没有交通堵塞、车能顺利行驶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不堵车", "is_correct": true, "explanation": "不堵车：与“地铁很快”呼应，说明路况顺畅。"}, {"text": "很慢", "is_correct": false, "explanation": "语义：与前一分句“地铁很快”矛盾。"}, {"text": "很晚", "is_correct": false, "explanation": "搭配：“晚”说时间，不能用来形容地铁的运行状况。"}, {"text": "很堵", "is_correct": false, "explanation": "语义：与“地铁很快”矛盾，地铁运行顺畅，不能说很堵。"}], "explanations": {"不堵车": "不堵车：与“地铁很快”呼应，说明路况顺畅。", "很慢": "语义：与前一分句“地铁很快”矛盾。", "很晚": "搭配：“晚”说时间，不能用来形容地铁的运行状况。", "很堵": "语义：与“地铁很快”矛盾，地铁运行顺畅，不能说很堵。"}, "sentence_index": 0, "correct_answer": "不堵车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试做得很不堵车，我很满意。", "explanation": "这里应该用〈顺利〉。“不堵车”只说道路上车辆行驶顺畅，不能用来形容考试。"}, {"text": "这篇文章读起来很不堵车，很有节奏。", "explanation": "这里应该用〈流畅〉。“不堵车”只描述交通状况，不能用来形容文章。"}, {"text": "这段话很不堵车，我一看就懂了。", "explanation": "这里应该用〈通顺〉。“不堵车”只描述交通状况，不能用来形容话语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不堵车", "is_correct": true, "explanation": "不堵车：与“半小时就能到机场”呼应，说明路上车辆通行顺畅。"}, {"text": "很远", "is_correct": false, "explanation": "语义：“很远”说距离，与“半小时就能到”矛盾。"}, {"text": "很久", "is_correct": false, "explanation": "语义：“很久”说时间长，与“半小时就能到”矛盾。"}, {"text": "很冷", "is_correct": false, "explanation": "搭配：“冷”说天气，不能用来形容路况。"}], "explanations": {"不堵车": "不堵车：与“半小时就能到机场”呼应，说明路上车辆通行顺畅。", "很远": "语义：“很远”说距离，与“半小时就能到”矛盾。", "很久": "语义：“很久”说时间长，与“半小时就能到”矛盾。", "很冷": "搭配：“冷”说天气，不能用来形容路况。"}, "sentence_index": 6, "correct_answer": "不堵车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次出差的行程很不堵车，一切都很好。", "explanation": "这里应该用〈顺畅〉。“不堵车”只用于道路交通，行程的进行要说“顺畅”。"}, {"text": "这首歌唱起来很不堵车，大家都很喜欢。", "explanation": "这里应该用〈顺口〉。“不堵车”只用于车辆通行，不能用来形容歌曲。"}, {"text": "河道里的水很不堵车，流得很快。", "explanation": "这里应该用〈畅通〉。“不堵车”只用于交通，不能用来形容水流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末的路上不堵车过，我们很快就到了。", "corrected_sentence": "周末的路上不堵车，我们很快就到了。", "error_description": "错误形式：“不堵车过”。正确形式：“不堵车”。“过”是经历体标记，不能接在描述当下路况的“不堵车”后面，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天不堵车子，我们很快就能到。", "corrected_sentence": "今天不堵车，我们很快就能到。", "error_description": "错误形式：“不堵车子”。正确形式：“不堵车”。“堵车”是离合词，不能直接带“车子”作宾语，否定时直接说“不堵车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
