INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11659, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11659, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于运输人员或货物的各种工具，如汽车、火车、飞机、轮船等。", "primary_collocate": null, "pronunciation": "jiāo tōng gōng jù", "ipa": "tɕjɑʊ˥˥ tʰʊŋ˥˥ kʊŋ˥˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "很多人选择公共交通工具，比如公交车和地铁，这对环境有很多好处。", "target_word": "交通工具", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "乘坐公共交通工具时，每个人的碳足迹通常比开车小很多。", "target_word": "交通工具", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "飞机是最快的交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你上学用什么交通工具？", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北京，地铁是很方便的交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车是一种很环保的交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪时，很多交通工具都停了。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去海岛要换好几种交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的交通工具又多又方便。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在山里，没有交通工具，出门只能走路。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种交通工具", "label": "量词"}, {"form": "公共交通工具", "label": "复合"}], "register": "中性", "sense_fingerprint": "运输人员或货物的各种工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通工具", "is_correct": true, "explanation": "正确：“公共交通工具”指公交车、地铁等运送乘客的工具，与句中的例子相符。"}, {"text": "娱乐场所", "is_correct": false, "explanation": "语义：“娱乐场所”指游玩的地方，与“公交车和地铁”的例子不符，句子说不通。"}, {"text": "建筑材料", "is_correct": false, "explanation": "搭配：“公共”不能修饰“建筑材料”，且与公交车、地铁的例子不符。"}, {"text": "医疗设备", "is_correct": false, "explanation": "语义：“医疗设备”指用于治疗的器械，与“公交车和地铁”无关，句子说不通。"}], "explanations": {"交通工具": "正确：“公共交通工具”指公交车、地铁等运送乘客的工具，与句中的例子相符。", "娱乐场所": "语义：“娱乐场所”指游玩的地方，与“公交车和地铁”的例子不符，句子说不通。", "建筑材料": "搭配：“公共”不能修饰“建筑材料”，且与公交车、地铁的例子不符。", "医疗设备": "语义：“医疗设备”指用于治疗的器械，与“公交车和地铁”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "交通工具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天练习弹奏的交通工具是钢琴。", "explanation": "这里应该用〈乐器〉。交通工具指运送人或货物的车船，弹奏、练习的是乐器，钢琴属于乐器。"}, {"text": "妈妈在厨房里洗交通工具，洗得很干净。", "explanation": "这里应该用〈餐具〉。交通工具指运送人或货物的车船，厨房里洗的是餐具。"}, {"text": "球场上的运动员都穿着交通工具。", "explanation": "这里应该用〈衣服〉。交通工具指运送人或货物的车船，穿在身上的应是衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通工具", "is_correct": true, "explanation": "正确：下大雪时运输工具都停运，“都停了”与句意相合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”不会因下大雪而停止，与“都停了”的意思不合。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“停”不能用来说钢琴，“钢琴”与“都停了”搭配不当。"}, {"text": "演员", "is_correct": false, "explanation": "语义：“演员”是人，不会因下大雪“都停了”，句子说不通。"}], "explanations": {"交通工具": "正确：下大雪时运输工具都停运，“都停了”与句意相合。", "课本": "语义：“课本”不会因下大雪而停止，与“都停了”的意思不合。", "钢琴": "搭配：“停”不能用来说钢琴，“钢琴”与“都停了”搭配不当。", "演员": "语义：“演员”是人，不会因下大雪“都停了”，句子说不通。"}, "sentence_index": 6, "correct_answer": "交通工具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用交通工具切菜。", "explanation": "这里应该用〈工具〉。交通工具指运送人或货物的车船等，切菜用的是刀具之类的工具。"}, {"text": "书桌上摆着很多交通工具。", "explanation": "这里应该用〈文具〉。交通工具指运送人或货物的车船，书桌上摆的应是文具。"}, {"text": "农民用交通工具翻地。", "explanation": "这里应该用〈农具〉。交通工具是运输用的车船，翻地用的是农具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "骑自行车是我上班的一只交通工具。", "corrected_sentence": "骑自行车是我上班的一种交通工具。", "error_description": "量词错误：交通工具应用量词“种”。“只”用于动物或成对物品中的一个，应说“一种交通工具”，不能说“一只交通工具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴雨过后，很多交通工具们都停下来了。", "corrected_sentence": "暴雨过后，很多交通工具都停下来了。", "error_description": "词缀错误：“们”只用于指人，不能加在“交通工具”后面，且与“很多”重复。应说“很多交通工具都停下来了”，不能说“交通工具们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
