INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11665, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把物品或人从一个地方转移到另一个地方。", "primary_collocate": null, "pronunciation": "yùn sòng", "ipa": "yn˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "而公交车可以同时运送很多人，比每人都开车更环保。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这辆大卡车每天运送新鲜的水果。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用船把大米运送到海边的城市。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生开车把病人运送到医院。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车可以一次运送很多煤。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，车子不能把食物运送到山里。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机正在运送一批新书去北京。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门为超市运送牛奶。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，军人用直升机运送了很多水和药。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着小货车，运送桌子和椅子去学校。", "target_word": "运送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运送了", "label": "体标"}, {"form": "运送过", "label": "体标"}, {"form": "运送着", "label": "体标"}, {"form": "運送", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用交通工具把人或物转移到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运送", "is_correct": true, "explanation": "运送：用车辆等把人或物从一处送到另一处，此处指公交车同时载送很多乘客。"}, {"text": "乘坐", "is_correct": false, "explanation": "搭配：“乘坐”的宾语是交通工具，不能说乘坐很多人。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”多指人力搬动物件，“公交车同时搬运很多人”不成立。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，句中要表达的是把人运走，而不是驾驶人。"}], "explanations": {"运送": "运送：用车辆等把人或物从一处送到另一处，此处指公交车同时载送很多乘客。", "乘坐": "搭配：“乘坐”的宾语是交通工具，不能说乘坐很多人。", "搬运": "搭配：“搬运”多指人力搬动物件，“公交车同时搬运很多人”不成立。", "驾驶": "语义：“驾驶”指操纵车辆，句中要表达的是把人运走，而不是驾驶人。"}, "sentence_index": 0, "correct_answer": "运送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书运送到了桌子上，然后就去睡觉了。", "explanation": "这里应该用〈放〉。运送指用车船等在两地之间运输货物或人，把书从一处移到同屋的桌上应说〈放〉。"}, {"text": "他把这个好消息运送给了所有的朋友。", "explanation": "这里应该用〈传递〉。运送只用于实际的货物或人，消息应说〈传递〉。"}, {"text": "我每天运送自己到公司去上班。", "explanation": "这里应该用〈坐车〉。运送的对象是货物或他人，人自己去上班应说〈坐车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运送", "is_correct": true, "explanation": "运送：用交通工具把货物运到别处，此处指飞机把一批新书运往北京。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语须是交通工具，不能带“新书”作宾语。"}, {"text": "搭乘", "is_correct": false, "explanation": "配价：“搭乘”指人乘坐交通工具，不能带“新书”作宾语。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行书籍，飞机不能出版新书，句子说不通。"}], "explanations": {"运送": "运送：用交通工具把货物运到别处，此处指飞机把一批新书运往北京。", "驾驶": "配价：“驾驶”的宾语须是交通工具，不能带“新书”作宾语。", "搭乘": "配价：“搭乘”指人乘坐交通工具，不能带“新书”作宾语。", "出版": "语义：“出版”指印刷发行书籍，飞机不能出版新书，句子说不通。"}, "sentence_index": 6, "correct_answer": "运送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天运送了一个愉快的下午。", "explanation": "这里应该用〈度过〉。运送的对象是人或货物，时间不能被运送，应说〈度过〉。"}, {"text": "妈妈每天运送很多关心给孩子。", "explanation": "这里应该用〈表达〉。运送只用于实际的货物或人，关心应说〈表达〉。"}, {"text": "这把伞运送了我。", "explanation": "这里应该用〈遮〉（如“这把伞遮住了我”）。运送的主语须是能载人运物的车船等交通工具，雨伞不能运送人，应指伞为人遮雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂每天运送一批零件在车站。", "corrected_sentence": "这家工厂每天运送一批零件到车站。", "error_description": "“在”应改为“到”。运送的终点要用“到”引出，“在”只表示位置，不能用来表示运往的地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卡车每天运送过很多砖到工地。", "corrected_sentence": "卡车每天运送很多砖到工地。", "error_description": "“过”应删去。“每天”表示经常、反复发生的动作，不能和表示曾经经历的“过”一起用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
