INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指搭乘交通工具从一处到另一处。", "primary_collocate": null, "pronunciation": "chéng zuò", "ipa": "ʈʂʰɤŋ˧˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "乘坐公共交通工具时，每个人的碳足迹通常比开车小很多。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们明天乘坐火车去上海。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐飞机时，请关上手机。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天乘坐地铁去公司上班。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友乘坐游船，看到了很多鸟。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐出租车比乘坐公共汽车贵。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次乘坐飞机，心里有点紧张。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里，很多人每天乘坐公交车上下班。", "target_word": "乘坐", "complexity_tier": "T3", "furigana": "zhè ge chéng shì lǐ, hěn duō rén měi tiān chéng zuò gōng jiāo chē shàng xià bān.", "sentence_source": "generated"}, {"text": "游客们乘坐小船过河。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们乘坐的那辆公共汽车很挤。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乘坐了", "label": "体标"}, {"form": "乘坐过", "label": "体标"}, {"form": "乘坐着", "label": "体标"}], "register": "中性", "sense_fingerprint": "搭乘交通工具出行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘坐", "is_correct": true, "explanation": "乘坐：搭乘交通工具出行，此处指人搭乘公共交通工具。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复，与句中每个人的出行方式无关。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”带的是货物，不能用来指人搭乘交通工具。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”指查看核对，与句中的出行方式不相符。"}], "explanations": {"乘坐": "乘坐：搭乘交通工具出行，此处指人搭乘公共交通工具。", "修理": "语义：“修理”指修复，与句中每个人的出行方式无关。", "搬运": "搭配：“搬运”带的是货物，不能用来指人搭乘交通工具。", "检查": "语义：“检查”指查看核对，与句中的出行方式不相符。"}, "sentence_index": 0, "correct_answer": "乘坐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在家里乘坐沙发看书。", "explanation": "这里应该用〈坐〉。乘坐指搭乘交通工具，沙发不是交通工具，应说“坐在沙发上”。"}, {"text": "我每天乘坐自行车上班。", "explanation": "这里应该用〈骑〉。乘坐指坐在交通工具里，自行车要骑，应说〈骑〉。"}, {"text": "妈妈每天乘坐我去上学。", "explanation": "这里应该用〈接送〉。乘坐的宾语是交通工具，不能是人，接送孩子应说〈接送〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘坐", "is_correct": true, "explanation": "乘坐：坐飞机出行，此处指她第一次坐飞机。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”带的是货物，不能用来指搭乘飞机。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“取消”指撤销，句中说的是乘机，而不是撤销飞机。"}, {"text": "撞击", "is_correct": false, "explanation": "语义：“撞击”指猛烈碰撞，与句中“第一次坐飞机、心里紧张”的情境不符。"}], "explanations": {"乘坐": "乘坐：坐飞机出行，此处指她第一次坐飞机。", "搬运": "搭配：“搬运”带的是货物，不能用来指搭乘飞机。", "取消": "语义：“取消”指撤销，句中说的是乘机，而不是撤销飞机。", "撞击": "语义：“撞击”指猛烈碰撞，与句中“第一次坐飞机、心里紧张”的情境不符。"}, "sentence_index": 6, "correct_answer": "乘坐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我乘坐那辆公共汽车，自己亲手开着它去学校。", "explanation": "这里应该用〈驾驶〉。乘坐指作为乘客坐车，句中说自己亲手开车，是司机的行为，应说〈驾驶〉。"}, {"text": "我们乘坐步行去学校。", "explanation": "这里应该用〈走〉。乘坐要坐在交通工具里，步行不是乘坐，应说〈走〉。"}, {"text": "他乘坐了一个好消息回家。", "explanation": "这里应该用〈听到〉。乘坐的对象是交通工具，消息不能被乘坐，应说〈听到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午乘坐的飞机去北京。", "corrected_sentence": "我下午乘坐飞机去北京。", "error_description": "“乘坐”后面不能直接加“的”。“乘坐的飞机”只能作定语修饰名词，后面再接“去北京”就不成句，应去掉“的”，说“乘坐飞机去北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天乘坐了公交车上班。", "corrected_sentence": "他每天乘坐公交车上班。", "error_description": "“了”应删去。“每天”表示经常性的动作，不能和表示完成的“了”一起用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "宽敞", "is_correct": true, "explanation": "“宽敞”指空间大、不挤，与“拥挤”表示的人多、空间小正好相反。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指清晰、明白，与“拥挤”没有反义关系，只是同为形容词。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”指价格低，与“拥挤”的空间义无关，不构成反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力高，与“拥挤”没有反义关系。"}], "correct_answer": "宽敞", "explanations": {"宽敞": "“宽敞”指空间大、不挤，与“拥挤”表示的人多、空间小正好相反。", "清楚": "“清楚”指清晰、明白，与“拥挤”没有反义关系，只是同为形容词。", "便宜": "“便宜”指价格低，与“拥挤”的空间义无关，不构成反义词。", "聪明": "“聪明”形容智力高，与“拥挤”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "宽敞", "is_correct": true, "explanation": "“宽敞”指空间大、不挤，与“拥挤”表示的人多、空间小正好相反。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”指使用或行动不费力，与“拥挤”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“拥挤”的空间状态无关，不构成反义词。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有脏东西，与“拥挤”没有反义关系。"}], "correct_answer": "宽敞", "explanations": {"宽敞": "“宽敞”指空间大、不挤，与“拥挤”表示的人多、空间小正好相反。", "方便": "“方便”指使用或行动不费力，与“拥挤”没有反义关系。", "明亮": "“明亮”指光线充足，与“拥挤”的空间状态无关，不构成反义词。", "干净": "“干净”指没有脏东西，与“拥挤”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人或车辆等密集，空间小。", "primary_collocate": null, "pronunciation": "yōng jǐ", "ipa": "jʊŋ˥ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "在通勤时间，城市里的道路经常很拥挤。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "早上的地铁里非常拥挤。", "target_word": "拥挤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小商店太小，客人一多就很拥挤。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的街上很拥挤，我们慢慢走吧。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢去拥挤的地方。", "target_word": "拥挤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间很拥挤，放不下新桌子。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，公交车上特别拥挤。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的商场不太拥挤，我们去吧。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里太拥挤了，我们在外面等你。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前的火车站总是很拥挤。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥挤不堪", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容人多车多、空间小而显得很挤的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥挤", "is_correct": true, "explanation": "拥挤：形容道路上车多人多、空间小，与通勤高峰时段经常很挤的语境相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指人少、没有生气，与通勤时间道路很挤的情况相反。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”指地方大而没有人或东西，与通勤高峰时道路很挤的情况矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多形容声音或环境，不用来描写车多人挤的道路。"}], "explanations": {"拥挤": "拥挤：形容道路上车多人多、空间小，与通勤高峰时段经常很挤的语境相符。", "冷清": "语义：“冷清”指人少、没有生气，与通勤时间道路很挤的情况相反。", "空旷": "语义：“空旷”指地方大而没有人或东西，与通勤高峰时道路很挤的情况矛盾。", "安静": "搭配：“安静”多形容声音或环境，不用来描写车多人挤的道路。"}, "sentence_index": 0, "correct_answer": "拥挤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他性格很拥挤，从不计较小事。", "explanation": "这里应该用〈豁达〉。“拥挤”只形容人、车或空间的密集，不能用来形容性格。"}, {"text": "这首歌的节奏很拥挤，听起来很舒服。", "explanation": "这里应该用〈紧凑〉。“拥挤”只形容人、车或空间，不能用来形容节奏。"}, {"text": "这件事情很拥挤，我们需要再想想。", "explanation": "这里应该用〈复杂〉。“拥挤”说人多、空间小，不能用来形容事情的难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥挤", "is_correct": true, "explanation": "拥挤：形容车厢人多、空间小，与下班以后公交车上人很多的情况相符。"}, {"text": "空荡", "is_correct": false, "explanation": "语义：“空荡”指空间里没有人或东西，与下班高峰时车上特别挤的语境矛盾。"}, {"text": "稀疏", "is_correct": false, "explanation": "语义：“稀疏”指数量少、间隔大，与“特别”的程度和下班高峰的语境相反。"}, {"text": "颠簸", "is_correct": false, "explanation": "语义：“颠簸”指路面不平、车身晃动，与下班后车上人多、空间小的语境不符。"}], "explanations": {"拥挤": "拥挤：形容车厢人多、空间小，与下班以后公交车上人很多的情况相符。", "空荡": "语义：“空荡”指空间里没有人或东西，与下班高峰时车上特别挤的语境矛盾。", "稀疏": "语义：“稀疏”指数量少、间隔大，与“特别”的程度和下班高峰的语境相反。", "颠簸": "语义：“颠簸”指路面不平、车身晃动，与下班后车上人多、空间小的语境不符。"}, "sentence_index": 6, "correct_answer": "拥挤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份手续很拥挤，办起来很麻烦。", "explanation": "这里应该用〈繁琐〉。“拥挤”形容人或车多、空间小，不能用来形容手续。"}, {"text": "这个目标很拥挤，大家都知道要做什么。", "explanation": "这里应该用〈明确〉。“拥挤”只形容人、车或空间的密集，不能用来形容目标。"}, {"text": "这次会议的气氛很拥挤，大家都不太说话。", "explanation": "这里应该用〈沉闷〉。“拥挤”指人或空间的状态，不能用来形容会议的气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那间教室小，学生一多就很拥挤着。", "corrected_sentence": "那间教室小，学生一多就很拥挤。", "error_description": "错误：形容词“拥挤”作谓语时后面不能加“着”。正确说法是“很拥挤”，表示学生多时教室的状态，不加体标。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末的超市通道很拥挤地，我们等人少的时候再去吧。", "corrected_sentence": "周末的超市通道很拥挤，我们等人少的时候再去吧。", "error_description": "错误：形容词“拥挤”作谓语时后面不能加结构助词“地”。应说“很拥挤”，不说“很拥挤地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
