INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11673, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "车辆因道路拥挤而无法顺利行驶。", "primary_collocate": null, "pronunciation": "dǔ chē", "ipa": "tu˨˩˦ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "如果更多人选择坐地铁或公交，路上的车就会减少，堵车情况也会变好。", "target_word": "堵车", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "早上八点常常堵车，我只好坐地铁。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天路上容易堵车。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天为什么会堵车？", "target_word": "堵车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我怕堵车，所以六点就出门了。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末去公园的路总是堵车。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路一到下班时间就堵车。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为堵车，我今天迟到了。", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过节的时候，高速公路上最容易堵车。", "target_word": "堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们那儿上班时间堵车吗？", "target_word": "堵车", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "堵了车", "label": "体标"}, {"form": "堵过车", "label": "体标"}], "register": "口语", "sense_fingerprint": "道路上车辆太多，车流停滞或走得很慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堵车", "is_correct": true, "explanation": "堵车：车辆因路上车多而行驶不畅，与“路上的车减少、情况变好”的语境相符。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“加重”表示变得更严重，与后面“情况也会变好”的结果相矛盾。"}, {"text": "恶化", "is_correct": false, "explanation": "语义：“恶化”指情况变坏，与“路上的车就会减少”的前提及“变好”的结果相反。"}, {"text": "增多", "is_correct": false, "explanation": "搭配：“增多”说数量变多，不能直接修饰“情况”，且与“车会减少”的前文不协调。"}], "explanations": {"堵车": "堵车：车辆因路上车多而行驶不畅，与“路上的车减少、情况变好”的语境相符。", "加重": "语义：“加重”表示变得更严重，与后面“情况也会变好”的结果相矛盾。", "恶化": "语义：“恶化”指情况变坏，与“路上的车就会减少”的前提及“变好”的结果相反。", "增多": "搭配：“增多”说数量变多，不能直接修饰“情况”，且与“车会减少”的前文不协调。"}, "sentence_index": 0, "correct_answer": "堵车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下水道堵车了，水流不下去。", "explanation": "这里应该用〈堵塞〉。“堵车”只说车辆在路上行驶不畅，下水道被堵应说“堵塞”。"}, {"text": "人群堵车在入口，动不了。", "explanation": "这里应该用〈拥堵〉。“堵车”只用于车辆，人群聚集不畅应说“拥堵”。"}, {"text": "工作堵车了，进度很慢。", "explanation": "这里应该用〈停滞〉。“堵车”只指车辆在路上受阻，工作停顿应说“停滞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堵车", "is_correct": true, "explanation": "堵车：车辆在下班时间行驶不畅，与“一到下班时间就”的语境相符。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：“下雪”说的是天气，与“一到下班时间”的道路状况不符，句子意思不对。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”说的是天气，不能说明道路在下班时间的通行状况。"}, {"text": "放晴", "is_correct": false, "explanation": "搭配：“放晴”指天气转好，不用来描写道路在下班时间的状况。"}], "explanations": {"堵车": "堵车：车辆在下班时间行驶不畅，与“一到下班时间就”的语境相符。", "下雪": "语义：“下雪”说的是天气，与“一到下班时间”的道路状况不符，句子意思不对。", "下雨": "语义：“下雨”说的是天气，不能说明道路在下班时间的通行状况。", "放晴": "搭配：“放晴”指天气转好，不用来描写道路在下班时间的状况。"}, "sentence_index": 6, "correct_answer": "堵车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的演讲堵车了，停了很久。", "explanation": "这里应该用〈卡壳〉。“堵车”只指车辆在路上行驶不畅，说话受阻应说“卡壳”。"}, {"text": "这台机器堵车了，工人们只好等待。", "explanation": "这里应该用〈停摆〉。“堵车”只用于车辆在路上受阻，机器停转应说“停摆”。"}, {"text": "这批货物堵车在仓库里，卖不出去。", "explanation": "这里应该用〈积压〉。“堵车”只用于车辆，货物堆在仓库应说“积压”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天路上堵车很，我们迟到了。", "corrected_sentence": "今天路上堵车，我们迟到了。", "error_description": "错误：程度副词“很”被放在离合词“堵车”后面，句子不完整。“很”应修饰形容词或心理动词，不能附着在“堵车”之后。正确的说法是去掉“很”，直接说“今天路上堵车，我们迟到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们迟到了，因为路上堵车过。", "corrected_sentence": "我们迟到了，因为路上堵了车。", "error_description": "错误：离合词“堵车”的体标要插在中间，应说“堵了车”或“堵过车”，不能说“堵车过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
