INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指植物的繁殖器官，通常有花瓣、花蕊，颜色多样，可供观赏。", "primary_collocate": null, "pronunciation": "huā", "ipa": "xwa˥", "syllable_count": 1, "sentences": [{"text": "天气暖和了，公园里的花都开了。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，公园里开了很多花。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这朵花是红色的，很好看。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给妈妈买了一束花。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里的花颜色很多。", "target_word": "花", "complexity_tier": "T3", "furigana": "yuàn zi lǐ de huā yán sè hěn duō", "sentence_source": "generated"}, {"text": "那种花只在夏天开。", "target_word": "花", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把花放在桌子上了。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂在花上飞来飞去。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些花开得真漂亮。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢在院子里种花。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "花朵", "label": "复合"}, {"form": "鲜花", "label": "复合"}], "register": "中性", "sense_fingerprint": "植物开出的、颜色多样可供观赏的花朵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 蜜蜂 (Zipf 3.69), 飞来 (Zipf 3.47), 飞去 (Zipf 3.36)']::text[], '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花", "is_correct": true, "explanation": "花（huā）指植物开出的花朵，是本词的读音与词义。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huā（第一声）声调不同，意思是中华、华丽。"}, {"text": "画", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，意思是图画。"}, {"text": "瓜", "is_correct": false, "explanation": "guā 与 huā 只有声母不同（g 与 h），意思是瓜类。"}, {"text": "夸", "is_correct": false, "explanation": "kuā 与 huā 只有声母不同（k 与 h），意思是夸奖。"}], "explanations": {"花": "花（huā）指植物开出的花朵，是本词的读音与词义。", "华": "huá（第二声）与 huā（第一声）声调不同，意思是中华、华丽。", "画": "huà（第四声）与 huā（第一声）声调不同，意思是图画。", "瓜": "guā 与 huā 只有声母不同（g 与 h），意思是瓜类。", "夸": "kuā 与 huā 只有声母不同（k 与 h），意思是夸奖。"}, "sentence_index": null, "correct_answer": "花"}, "level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "花：指植物开出的花朵，与“都开了”搭配。"}, {"text": "叶子", "is_correct": false, "explanation": "搭配：叶子是植物的叶片，不会“开”，“叶子都开了”不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会开放，“都开了”只能用于植物的花。"}, {"text": "台阶", "is_correct": false, "explanation": "语义：台阶是建筑的构件，不会开放，与“都开了”不搭配。"}], "explanations": {"花": "花：指植物开出的花朵，与“都开了”搭配。", "叶子": "搭配：叶子是植物的叶片，不会“开”，“叶子都开了”不通。", "石头": "语义：石头不会开放，“都开了”只能用于植物的花。", "台阶": "语义：台阶是建筑的构件，不会开放，与“都开了”不搭配。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把这朵花切碎，放进汤里一起煮。", "explanation": "这里应该用〈蔬菜〉。切碎后放进汤里煮的应是蔬菜，花朵一般不作汤料，“花”在这里用错了对象。"}, {"text": "他的脸上长了很多花，看起来很难看。", "explanation": "这里应该用〈雀斑〉。描述脸上的小斑点要说“长雀斑”；“花”指植物的花朵，不能指皮肤上的斑点。"}, {"text": "这个玻璃杯上有很多花，洗也洗不干净。", "explanation": "这里应该用〈污渍〉。杯子上洗不掉的痕迹是污渍；“花”指植物的花朵，不能指器物上的脏痕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "花", "is_correct": true, "explanation": "花（huā）指植物开出的花朵，是本词的读音与词义。"}, {"text": "话", "is_correct": false, "explanation": "huà（第四声）与 huā 声调不同，意思是话语。"}, {"text": "化", "is_correct": false, "explanation": "huà（第四声）与 huā 声调不同，意思是变化。"}, {"text": "滑", "is_correct": false, "explanation": "huá（第二声）与 huā（第一声）声调不同，意思是光滑、滑动。"}, {"text": "挂", "is_correct": false, "explanation": "guà 与 huā 声母、声调都不同，意思是悬挂。"}], "explanations": {"花": "花（huā）指植物开出的花朵，是本词的读音与词义。", "话": "huà（第四声）与 huā 声调不同，意思是话语。", "化": "huà（第四声）与 huā 声调不同，意思是变化。", "滑": "huá（第二声）与 huā（第一声）声调不同，意思是光滑、滑动。", "挂": "guà 与 huā 声母、声调都不同，意思是悬挂。"}, "sentence_index": null, "correct_answer": "花"}, "level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "此处“花”是“把”字句的宾语，可以被放在桌子上。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能被拿起来放在桌子上，这样说不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“放”不与“大海”搭配，“把大海放在桌子上”不成立。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以搬动的物体，放在桌子上说不通。"}], "explanations": {"花": "此处“花”是“把”字句的宾语，可以被放在桌子上。", "太阳": "语义：太阳不能被拿起来放在桌子上，这样说不通。", "大海": "搭配：“放”不与“大海”搭配，“把大海放在桌子上”不成立。", "天空": "语义：天空不是可以搬动的物体，放在桌子上说不通。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋天到了，苹果树上结满了花。", "explanation": "这里应该用〈果子〉。“结”的对象是果实，花是开出来的，不能说“结花”。"}, {"text": "他在花店买了一只花。", "explanation": "量词错误：“只”多用于动物，花应用“朵”“束”“盆”等，不能说“一只花”。"}, {"text": "我家阳台上有一张花。", "explanation": "量词错误：“张”用于平面的东西，花应用“朵”“束”“盆”等，不能说“一张花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他送给我一个花。", "corrected_sentence": "他送给我一束花。", "error_description": "量词错误：“花”前应用“束”（一束花）或“朵”（一朵花），不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些花开地很好看。", "corrected_sentence": "这些花开得很好看。", "error_description": "补语错误：“开”后表示程度的补语要用“得”连接，不能用“地”（“地”用在动词前）。应说“开得很好看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
