INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人内心的情绪状态或感受。", "primary_collocate": null, "pronunciation": "xīn qíng", "ipa": "ɕin˥˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这样，大家花在路上的时间会更短，心情也会更好。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "今天天气很好，我的心情也很好。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，她的心情一下子变好了。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心情不好，晚饭吃得很少。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天心情怎么样？", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，我的心情总是有点儿难过。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的电话让我心情好多了。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐可以让人的心情放松下来。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以后，大家的心情都很轻松。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说，今天心情特别好。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好心情", "label": "复合"}, {"form": "坏心情", "label": "复合"}], "register": "中性", "sense_fingerprint": "心情：人内心的情绪状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心情", "is_correct": true, "explanation": "心情指人内心的情绪状态或感受，是本词的读音与词义。"}, {"text": "心形", "is_correct": false, "explanation": "xíng 与 qíng 只有声母不同（x 与 q），声调相同，意思是心的形状。"}, {"text": "心灵", "is_correct": false, "explanation": "líng 与 qíng 只有声母不同（l 与 q），声调相同，意思是心灵、精神。"}, {"text": "亲情", "is_correct": false, "explanation": "qīn 与 xīn 只有声母不同（q 与 x），意思是亲人之间的感情。"}], "explanations": {"心情": "心情指人内心的情绪状态或感受，是本词的读音与词义。", "心形": "xíng 与 qíng 只有声母不同（x 与 q），声调相同，意思是心的形状。", "心灵": "líng 与 qíng 只有声母不同（l 与 q），声调相同，意思是心灵、精神。", "亲情": "qīn 与 xīn 只有声母不同（q 与 x），意思是亲人之间的感情。"}, "sentence_index": null, "correct_answer": "心情"}, "level_3": {"options": [{"text": "心情", "is_correct": true, "explanation": "此处“心情”指心里的感受，“也会更好”与之搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能说“更好”，这里说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有心情可言，“也会更好”说不通。"}, {"text": "大山", "is_correct": false, "explanation": "搭配：“更好”不与“大山”搭配作主语，这样说不通。"}], "explanations": {"心情": "此处“心情”指心里的感受，“也会更好”与之搭配。", "月亮": "语义：“月亮”不能说“更好”，这里说不通。", "石头": "语义：石头没有心情可言，“也会更好”说不通。", "大山": "搭配：“更好”不与“大山”搭配作主语，这样说不通。"}, "sentence_index": 0, "correct_answer": "心情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很关心孩子的心情健康。", "explanation": "这里应该用〈心理〉。“心理健康”指心理状态良好；“心情”是暂时的情绪，不说“健康”。"}, {"text": "她对老朋友的心情很深。", "explanation": "这里应该用〈感情〉。“感情很深”指长期的情感；“心情”是暂时的情绪，不说“深”。"}, {"text": "他心里有一朵心情。", "explanation": "量词错误：“朵”用于花、云等，不能用于“心情”，应说“一种心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11678, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "心情", "is_correct": true, "explanation": "心情指人内心的情绪状态或感受，是本词的读音与词义。"}, {"text": "心惊", "is_correct": false, "explanation": "jīng 与 qíng 声母、声调都不同，意思是受惊、害怕。"}, {"text": "性情", "is_correct": false, "explanation": "xìngqíng 的首音节 xìng 与 xīn 韵母不同（ing 与 in），声调也不同，意思是性格、脾气。"}, {"text": "辛勤", "is_correct": false, "explanation": "qín 与 qíng 只差韵尾（n 与 ng），意思是勤劳。"}, {"text": "心性", "is_correct": false, "explanation": "xìng 与 qíng 声母不同（x 与 q），声调也不同，意思是心地、性情。"}], "explanations": {"心情": "心情指人内心的情绪状态或感受，是本词的读音与词义。", "心惊": "jīng 与 qíng 声母、声调都不同，意思是受惊、害怕。", "性情": "xìngqíng 的首音节 xìng 与 xīn 韵母不同（ing 与 in），声调也不同，意思是性格、脾气。", "辛勤": "qín 与 qíng 只差韵尾（n 与 ng），意思是勤劳。", "心性": "xìng 与 qíng 声母不同（x 与 q），声调也不同，意思是心地、性情。"}, "sentence_index": null, "correct_answer": "心情"}, "level_3": {"options": [{"text": "心情", "is_correct": true, "explanation": "此处“心情”是主语，指心里的感受，与“让我……好多了”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有心情，“让我桌子好多了”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能让人的状态“好多了”，语义不通。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“让我……好多了”的主语不能是“海洋”，搭配不当。"}], "explanations": {"心情": "此处“心情”是主语，指心里的感受，与“让我……好多了”搭配。", "桌子": "语义：桌子没有心情，“让我桌子好多了”说不通。", "课本": "语义：课本不能让人的状态“好多了”，语义不通。", "海洋": "搭配：“让我……好多了”的主语不能是“海洋”，搭配不当。"}, "sentence_index": 6, "correct_answer": "心情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对工作的心情很积极。", "explanation": "这里应该用〈心态〉。“积极”形容人的态度，“心情”指暂时的情绪，不能这样说。"}, {"text": "他的心情很外向。", "explanation": "这里应该用〈性格〉。“外向”描述人的性格，心情只是暂时的情绪，不能说“外向”。"}, {"text": "他有一张心情，很难说清。", "explanation": "量词错误：“张”用于平面的东西，不能用于“心情”，应说“一种心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这个消息，他的心情一下子好起去了。", "corrected_sentence": "听到这个消息，他的心情一下子好起来了。", "error_description": "补语错误：表示心情由差变好的趋向补语要用“起来”，“起去”不是合格搭配。应说“好起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一朵复杂的心情。", "corrected_sentence": "他有一种复杂的心情。", "error_description": "量词错误：“心情”前应用“种”（一种心情），“朵”用于花、云等，不能用于“心情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11679, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "反义：“恶劣”与“良好”意义相反，指品质很差、达不到标准，可用于“关系”。"}, {"text": "丰富", "is_correct": false, "explanation": "无关：“丰富”说内容或数量多，与“良好”的反义关系无关。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”说清楚、分明，与“良好”不是反义词。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”说构成繁多，与“良好”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "反义：“恶劣”与“良好”意义相反，指品质很差、达不到标准，可用于“关系”。", "丰富": "无关：“丰富”说内容或数量多，与“良好”的反义关系无关。", "清晰": "无关：“清晰”说清楚、分明，与“良好”不是反义词。", "复杂": "无关：“复杂”说构成繁多，与“良好”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
