INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11679, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物或行为的品质达到让人满意的标准。", "primary_collocate": null, "pronunciation": "liáng hǎo", "ipa": "liɑŋ˧˥ xɑʊ˧˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司的服务态度十分良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小养成了良好的习惯。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的睡眠对身体很重要。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国保持着良好的关系。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的卫生情况良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我这次的成绩良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人今天的状态良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的心态能帮你面对困难。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的空气质量一直很良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要给孩子一个良好的学习环境。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "良好：品质达到令人满意的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11679, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”形容服务态度达到令人满意的标准，与“十分”搭配自然。"}, {"text": "复杂", "is_correct": false, "explanation": "搭配：“复杂”说事情或问题的构成，不能用来形容服务态度。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“巨大”说规模或程度，服务态度不能用它来衡量。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”说负担或心情，不用来形容服务态度。"}], "explanations": {"良好": "正确：“良好”形容服务态度达到令人满意的标准，与“十分”搭配自然。", "复杂": "搭配：“复杂”说事情或问题的构成，不能用来形容服务态度。", "巨大": "语义：“巨大”说规模或程度，服务态度不能用它来衡量。", "沉重": "语义：“沉重”说负担或心情，不用来形容服务态度。"}, "sentence_index": 0, "correct_answer": "良好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是班里最良好的学生。", "explanation": "这里应该用〈优秀〉。良好说事物或状况达到标准，称赞人的出众要用优秀。"}, {"text": "这位老奶奶非常良好，经常帮助邻居。", "explanation": "这里应该用〈善良〉。良好说事物或状况达到标准，不用来形容人的品德。"}, {"text": "他长得很良好，走在街上很引人注目。", "explanation": "这里应该用〈英俊〉。良好不用来描述人的外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”说状态达到满意的标准，符合“病人今天的状态”。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”说速度，不能用来形容状态。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”说空间，不能用来描述病人的状态。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用于状态。"}], "explanations": {"良好": "正确：“良好”说状态达到满意的标准，符合“病人今天的状态”。", "迅速": "搭配：“迅速”说速度，不能用来形容状态。", "狭窄": "语义：“狭窄”说空间，不能用来描述病人的状态。", "清脆": "搭配：“清脆”形容声音，不能用于状态。"}, "sentence_index": 6, "correct_answer": "良好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们听到消息后都很良好。", "explanation": "这里应该用〈快乐〉。良好说事物或状况达到标准，不用来描述人的心情。"}, {"text": "他的论文水平良好，因此拿到了诺贝尔奖。", "explanation": "这里应该用〈卓越〉。良好只说达到标准，不足以形容诺贝尔奖级别的成就。"}, {"text": "那个夏天是我一生中最良好的回忆。", "explanation": "这里应该用〈美好〉。良好说状况或品质达到标准，回忆的感受要用美好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们良好的完成了这次任务。", "corrected_sentence": "他们良好地完成了这次任务。", "error_description": "结构错误：“良好”修饰动词“完成”要用“地”，应说“良好地完成”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的组织工作很良好地。", "corrected_sentence": "这次活动的组织工作很良好。", "error_description": "结构错误：“良好”作谓语形容词时后面不加“地”，“地”只用于修饰动词，应说“很良好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
