INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市里专门用来盖房子、让人居住的一片地方。", "primary_collocate": null, "pronunciation": "zhù zhái qū", "ipa": "tʂu˥˩ tʂaɪ˧˥ tɕʰy˥˥", "syllable_count": 3, "sentences": [{"text": "良好的城市规划会把住宅区、工作地点和车站设计得更近，让人们更容易使用公共交通。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我家住在一个安静的住宅区。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住宅区里有一个小公园。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区附近新开了一家超市。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区的路上车很少。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算在住宅区旁边建学校。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片住宅区住着很多老人。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上住宅区里没有什么声音。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从住宅区到地铁站要走十分钟。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的住宅区里有三十多栋楼。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "住宅區", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "住宅区：城市里专门用来居住的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住宅区", "is_correct": true, "explanation": "正确：“住宅区”是可以被规划布局的居住区域，与“工作地点和车站”并列，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然地理事物，不能被规划得更近。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“设计”的对象是空间或地点，不能说“设计情绪”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不能被设计得更近，与交通规划无关。"}], "explanations": {"住宅区": "正确：“住宅区”是可以被规划布局的居住区域，与“工作地点和车站”并列，符合句意。", "河流": "语义：“河流”是自然地理事物，不能被规划得更近。", "情绪": "搭配：“设计”的对象是空间或地点，不能说“设计情绪”。", "空气": "语义：“空气”不能被设计得更近，与交通规划无关。"}, "sentence_index": 0, "correct_answer": "住宅区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个住宅区有两间卧室和一个厨房。", "explanation": "这里应该用〈住宅〉。住宅区指成片的居住区，一套房子的卧室和厨房要说住宅。"}, {"text": "我的住宅区在六楼，阳台很大。", "explanation": "这里应该用〈公寓〉。住宅区指成片的居住区，一栋楼里的单套房子要说公寓。"}, {"text": "这个住宅区的客厅很大，阳光很好。", "explanation": "这里应该用〈房子〉。住宅区指成片的居住区，单套房子里的客厅不能说住宅区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住宅区", "is_correct": true, "explanation": "正确：“住宅区”是住着很多人的地方，与“住着很多老人”搭配。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不是供人居住的地方，不能与“住着很多老人”搭配。"}, {"text": "玻璃", "is_correct": false, "explanation": "配价：“住着”要求能住人的处所作主语，“玻璃”是材料，不能充当。"}, {"text": "车库", "is_correct": false, "explanation": "语义：“车库”是停车的地方，不适合住着很多老人。"}], "explanations": {"住宅区": "正确：“住宅区”是住着很多人的地方，与“住着很多老人”搭配。", "海洋": "语义：“海洋”不是供人居住的地方，不能与“住着很多老人”搭配。", "玻璃": "配价：“住着”要求能住人的处所作主语，“玻璃”是材料，不能充当。", "车库": "语义：“车库”是停车的地方，不适合住着很多老人。"}, "sentence_index": 6, "correct_answer": "住宅区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个住宅区住着八个人，每人一张上下铺。", "explanation": "这里应该用〈宿舍〉。住宅区指供人居住的成片区域，多人共住、摆着上下铺的地方要说宿舍。"}, {"text": "这个住宅区的病房里住满了病人，护士很忙。", "explanation": "这里应该用〈医院〉。住宅区是成片的居住区，有病房、护士忙碌的地方要说医院。"}, {"text": "这个住宅区的货物堆得很高，工人每天搬运。", "explanation": "这里应该用〈仓库〉。住宅区是供人居住的地方，堆放货物、搬运装卸的要说仓库。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近新建了一只大型住宅区。", "corrected_sentence": "我家附近新建了一个大型住宅区。", "error_description": "量词错误：“住宅区”应用“个”或“片”，“只”用于动物或成对的物品，应说“一个大型住宅区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带有一个很大住宅区。", "corrected_sentence": "这一带有一个很大的住宅区。", "error_description": "结构错误：“很大”修饰名词“住宅区”时要加“的”，应说“一个很大的住宅区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
