INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指具体的某个位置或场所。", "primary_collocate": null, "pronunciation": "dì diǎn", "ipa": "ti˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们明天开会的地点在二楼会议室。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把见面的时间和地点告诉我。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地点离地铁站很近，坐车很方便。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说考试的地点改到了三号教室。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们选了一个安静的地点拍照。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的时间和地点都已经定好了。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道婚礼的地点吗？", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他事情发生的地点。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的地点是学校门口的公园。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记不清我们第一次见面的地点了。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "活动地点", "label": "复合"}, {"form": "地點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "具体的位置或场所，常与时间并说，如开会、见面、比赛的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地点", "is_correct": true, "explanation": "正确。“地点”指开会发生的场所，与“在二楼会议室”相符。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻，不是场所，不能说“时间在二楼会议室”。"}, {"text": "内容", "is_correct": false, "explanation": "语义：“内容”指会议讨论的事项，不能指位置。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”说的是数量，不能说“人数在某个房间”。"}], "explanations": {"地点": "正确。“地点”指开会发生的场所，与“在二楼会议室”相符。", "时间": "语义：“时间”指时刻，不是场所，不能说“时间在二楼会议室”。", "内容": "语义：“内容”指会议讨论的事项，不能指位置。", "人数": "搭配：“人数”说的是数量，不能说“人数在某个房间”。"}, "sentence_index": 0, "correct_answer": "地点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病已经严重到这个地点了。", "explanation": "这里应该用〈地步〉。说病情严重到某种程度要用“地步”，“地点”指位置或场所，不表示程度。"}, {"text": "他的英语地点提高了很多。", "explanation": "这里应该用〈水平〉。能力、成绩的高低说“水平”，“提高”用于水平，“地点”不能用来说能力。"}, {"text": "这个地点的人口已经超过五百万。", "explanation": "这里应该用〈地区〉。说一片区域的人口要用“地区”，“地点”指具体的位置或场所，不能指大片区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地点", "is_correct": true, "explanation": "正确。“婚礼的地点”指婚礼举行的场所，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验，婚礼不是考试，不能问“婚礼的考试”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学生的功课，与婚礼无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人，不能用于婚礼。"}], "explanations": {"地点": "正确。“婚礼的地点”指婚礼举行的场所，符合句意。", "考试": "语义：“考试”是测验，婚礼不是考试，不能问“婚礼的考试”。", "作业": "语义：“作业”指学生的功课，与婚礼无关。", "身高": "体貌：“身高”只用于人，不能用于婚礼。"}, "sentence_index": 6, "correct_answer": "地点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把会议地点定在下午三点。", "explanation": "这里应该用〈时间〉。定下开会的时刻要说“时间”，“地点”指位置或场所，不指时刻。"}, {"text": "他的工资涨到了这个地点。", "explanation": "这里应该用〈数额〉。说工资涨到多少要用“数额”，“地点”指位置或场所，不指金额。"}, {"text": "他想了一个好地点来解决这个问题。", "explanation": "这里应该用〈办法〉。解决问题要说“想办法”，“地点”指位置或场所，不指解决问题的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去地点是一家书店。", "corrected_sentence": "我们明天去的地点是一家书店。", "error_description": "结构助词错误：“去”修饰“地点”时中间要加“的”，应说“去的地点”，不能说“去地点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没定好一条集合地点。", "corrected_sentence": "我还没定好一个集合地点。", "error_description": "量词错误：“地点”应搭配量词“个”，说“一个集合地点”；“条”用于线状事物，不能用于地点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
