INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专为自行车设置的行驶道路，通常与机动车道分离，保障骑行安全。", "primary_collocate": null, "pronunciation": "zì xíng chē dào", "ipa": "tsɨ˥˩ ɕiŋ˧˥ ʈʂʰɤ˥ tau˥˩", "syllable_count": 4, "sentences": [{"text": "一些城市还在建设自行车道，鼓励人们骑车去地铁站换乘。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路有一条很宽的自行车道。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在自行车道上停车。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新修的自行车道和马路分开了。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天沿着自行车道骑车上班。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的自行车道又平又安全。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车道上有很多人在骑车。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的自行车道越来越多。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车不能开进自行车道。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在自行车道旁边等爸爸。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "自行车道路", "label": "复合"}, {"form": "自行車道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与机动车道分开、专供自行车行驶的道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自行车道", "is_correct": true, "explanation": "正确。“建设自行车道”是常见搭配，符合“骑车去地铁站换乘”的语境。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：“建设”用于道路、设施，不能说“建设广告”。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是可以修建的设施。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，与修建无关。"}], "explanations": {"自行车道": "正确。“建设自行车道”是常见搭配，符合“骑车去地铁站换乘”的语境。", "广告": "搭配：“建设”用于道路、设施，不能说“建设广告”。", "语言": "语义：“语言”不是可以修建的设施。", "作业": "语义：“作业”是学习任务，与修建无关。"}, "sentence_index": 0, "correct_answer": "自行车道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车沿着这条自行车道开往北京。", "explanation": "这里应该用〈铁轨〉。火车行驶的是“铁轨”，自行车道是给自行车骑行的，火车不能沿着它开。"}, {"text": "那条自行车道是专给汽车走的。", "explanation": "这里应该用〈车道〉。自行车道供自行车行驶，汽车走的是车道，二者用途相反。"}, {"text": "我们在自行车道里停汽车。", "explanation": "这里应该用〈停车场〉。自行车道只供骑行，不能用来停汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自行车道", "is_correct": true, "explanation": "正确。“自行车道上有很多人在骑车”是合理的说法。"}, {"text": "天空", "is_correct": false, "explanation": "语义：人不能在天空上骑车，“天空”不是骑车的场所。"}, {"text": "文件", "is_correct": false, "explanation": "语义：“文件”是纸张或电子资料，不是骑车的地方。"}, {"text": "车牌", "is_correct": false, "explanation": "搭配：“车牌”是挂在车上的牌子，不是可以骑车的地方。"}], "explanations": {"自行车道": "正确。“自行车道上有很多人在骑车”是合理的说法。", "天空": "语义：人不能在天空上骑车，“天空”不是骑车的场所。", "文件": "语义：“文件”是纸张或电子资料，不是骑车的地方。", "车牌": "搭配：“车牌”是挂在车上的牌子，不是可以骑车的地方。"}, "sentence_index": 6, "correct_answer": "自行车道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条自行车道可以容纳五千人。", "explanation": "这里应该用〈体育馆〉。能容纳大量观众的场地叫“体育馆”，自行车道是给自行车骑行的，不能用来容纳人群。"}, {"text": "这条自行车道专门给行人走。", "explanation": "这里应该用〈人行道〉。自行车道供自行车行驶，行人走的是人行道。"}, {"text": "汽车可以在自行车道上快速开过。", "explanation": "这里应该用〈机动车道〉。自行车道与机动车道分开，汽车不能在自行车道上行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府把新的自行车道划马路边。", "corrected_sentence": "市政府把新的自行车道划在马路边。", "error_description": "语法错误：“划”带处所宾语时要说“划在”，即“把新的自行车道划在马路边”。漏掉“在”，说“划马路边”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市要修一个新的自行车道。", "corrected_sentence": "这座城市要修一条新的自行车道。", "error_description": "量词错误：“自行车道”是线状道路，应搭配量词“条”，说“一条新的自行车道”；“个”不能用于道路。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
