INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11687, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供乘客上下火车或地铁的站点。", "primary_collocate": null, "pronunciation": "dì tiě zhàn", "ipa": "ti˥˩ tʰjɛ˨˩˦ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "一些城市还在建设自行车道，鼓励人们骑车去地铁站换乘。", "target_word": "地铁站", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "我家附近有一个地铁站，走路五分钟就到。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，我在地铁站门口等朋友。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地铁站人很多，早上特别挤。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，最近的地铁站怎么走？", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地铁站买了一张地铁票。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，我跑到地铁站去躲雨。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站里有电梯，老人上下很方便。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从地铁站出来，往右走就是我们学校。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地铁站今天关门了，我们去下一站吧。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地铁站台", "label": "复合"}, {"form": "地鐵站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地铁线路上供乘客上下车的站点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁站", "is_correct": true, "explanation": "正确：指地铁的站点，骑车去这里乘坐地铁，符合句意。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂不是可以换乘交通的场所，与句意不符。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店不是换乘交通的场所，与“骑车去……换乘”的语境不符。"}, {"text": "人行道", "is_correct": false, "explanation": "语义：人行道供行人走路，与“骑车”的语境相矛盾。"}], "explanations": {"地铁站": "正确：指地铁的站点，骑车去这里乘坐地铁，符合句意。", "食堂": "语义：食堂不是可以换乘交通的场所，与句意不符。", "书店": "语义：书店不是换乘交通的场所，与“骑车去……换乘”的语境不符。", "人行道": "语义：人行道供行人走路，与“骑车”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "地铁站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐地铁站上班。", "explanation": "这里应该用〈地铁〉。“坐”的对象是地铁这种列车，地铁站是站点，不能坐。"}, {"text": "这个地铁站很长，经过了十几个站。", "explanation": "这里应该用〈地铁线〉。“很长”和“经过十几个站”说的是线路，地铁站只是一个停靠点，不能这样说。"}, {"text": "司机把地铁站开到了终点。", "explanation": "这里应该用〈列车〉。“开”的对象是车辆，地铁站是固定的站点，不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁站", "is_correct": true, "explanation": "正确：地铁站是可以跑进去躲雨的场所，与“跑到……去躲雨”的句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能让人跑进去躲雨，与句意相矛盾。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底无法很快跑到，也不能躲雨，与句意矛盾。"}, {"text": "朋友", "is_correct": false, "explanation": "配价：“跑到”要求处所作宾语，“朋友”是人，不能作为跑去的地点。"}], "explanations": {"地铁站": "正确：地铁站是可以跑进去躲雨的场所，与“跑到……去躲雨”的句意相符。", "冰箱": "语义：冰箱不能让人跑进去躲雨，与句意相矛盾。", "海底": "语义：海底无法很快跑到，也不能躲雨，与句意矛盾。", "朋友": "配价：“跑到”要求处所作宾语，“朋友”是人，不能作为跑去的地点。"}, "sentence_index": 6, "correct_answer": "地铁站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船靠了地铁站。", "explanation": "这里应该用〈码头〉。“靠”的是船，码头是船靠岸的地方；地铁站是列车停靠的站点，不能让船靠。"}, {"text": "地铁站进站了，大家赶紧上车。", "explanation": "这里应该用〈列车〉。“进站”的是列车，地铁站本身是站点，不会进站。"}, {"text": "我把地铁站停在了路边。", "explanation": "这里应该用〈车〉。“停”的对象是车辆，地铁站是站点，不能停在路边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校附近有一条地铁站。", "corrected_sentence": "我们学校附近有一个地铁站。", "error_description": "量词错误：“地铁站”应使用量词“个”，不能用“条”（“条”用于细长的事物，如路、河）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我地铁站买了一张票。", "corrected_sentence": "我在地铁站买了一张票。", "error_description": "介词遗漏：“地铁站”作地点时必须用“在”引出，应说“在地铁站买了一张票”，省略“在”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
