INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指乘客从一种交通工具转换到另一种交通工具，继续行程。", "primary_collocate": null, "pronunciation": "huàn chéng", "ipa": "xwan˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "虽然有时候坐公交需要换乘，可能没有开车方便，但从长远来看，这对城市的环境和居民的生活质量都有好处。", "target_word": "换乘", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "到了人民广场，请换乘二号线。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在前面那一站换乘公交车。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从机场到市中心要换乘一次。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天上班都要换乘两次地铁。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路线不用换乘，直接坐到公司。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次来这儿，我不知道在哪儿换乘。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换乘的时候，请注意脚下的台阶。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在北京站换乘了去上海的火车。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人行李多，换乘很不方便。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换乘了", "label": "体标"}, {"form": "换乘站", "label": "复合"}, {"form": "換乘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乘客中途改乘另一种交通工具或另一条线路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "换乘", "is_correct": true, "explanation": "“换乘”指中途从一种交通工具转到另一种，与“坐公交需要换乘”的语境相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，而“坐公交”的人是乘客，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏掉的东西，与“坐公交”无关，句子不通。"}, {"text": "停靠", "is_correct": false, "explanation": "配价：“停靠”的主语是车辆，不能说乘客需要停靠。"}], "explanations": {"换乘": "“换乘”指中途从一种交通工具转到另一种，与“坐公交需要换乘”的语境相符。", "驾驶": "语义：“驾驶”指操纵车辆，而“坐公交”的人是乘客，句意不通。", "修理": "语义：“修理”指修复坏掉的东西，与“坐公交”无关，句子不通。", "停靠": "配价：“停靠”的主语是车辆，不能说乘客需要停靠。"}, "sentence_index": 0, "correct_answer": "换乘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他临时换乘了主意。", "explanation": "这里应该用〈改变〉。“换乘”只用于乘客在交通工具之间转换，改变主意要用“改变”。"}, {"text": "他换乘了一份新工作。", "explanation": "此处指换工作，但“换乘”只用于交通工具之间的转换，不能用于工作。"}, {"text": "我在银行把美元换乘成人民币。", "explanation": "此处指兑换货币，但“换乘”只用于乘客在交通工具之间转换，不能用于货币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "换乘", "is_correct": true, "explanation": "“换乘”指中途换另一种交通工具，符合“不知道在哪儿换车”的语境。"}, {"text": "重复", "is_correct": false, "explanation": "语义：“重复”指再做一次，与“第一次来这儿”矛盾，句意不通。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指思念过去的人或事，与“第一次来这儿”不符，句意不通。"}, {"text": "失业", "is_correct": false, "explanation": "搭配：“失业”是不及物动词，不能与“在哪儿”搭配表示场所，句子不通。"}], "explanations": {"换乘": "“换乘”指中途换另一种交通工具，符合“不知道在哪儿换车”的语境。", "重复": "语义：“重复”指再做一次，与“第一次来这儿”矛盾，句意不通。", "怀念": "语义：“怀念”指思念过去的人或事，与“第一次来这儿”不符，句意不通。", "失业": "搭配：“失业”是不及物动词，不能与“在哪儿”搭配表示场所，句子不通。"}, "sentence_index": 6, "correct_answer": "换乘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服不合身，我去店里换乘了一件。", "explanation": "此处指更换衣物，但“换乘”只用于交通工具之间的转换，不能用于衣服。"}, {"text": "会议时间有变，我们把会议换乘到下周。", "explanation": "此处指调整时间，但“换乘”只用于乘客在交通工具之间转换，不能用于安排会议。"}, {"text": "我们要把数据从旧服务器换乘到新服务器。", "explanation": "这里应该用〈转移〉。“换乘”只用于乘客在交通工具之间转换，转移数据要用“转移”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在广州南站了换乘高铁去深圳。", "corrected_sentence": "我们在广州南站换乘高铁去深圳。", "error_description": "体标位置错误：“了”不能放在动词“换乘”之前，应说“在广州南站换乘高铁”，不能说“了换乘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在南京南站了换乘地铁回家。", "corrected_sentence": "我在南京南站换乘地铁回家。", "error_description": "体标位置错误：“了”不能放在动词“换乘”之前，应说“在南京南站换乘地铁回家”，不能说“了换乘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "眼前", "is_correct": true, "explanation": "反义：“眼前”指当前、目前，与“长远”着眼将来相对。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是具体家具，与“长远”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与“长远”的时间意义无关。"}, {"text": "友谊", "is_correct": false, "explanation": "无关：“友谊”指人与人之间的感情，与“长远”不构成反义。"}], "correct_answer": "眼前", "explanations": {"眼前": "反义：“眼前”指当前、目前，与“长远”着眼将来相对。", "桌子": "无关：“桌子”是具体家具，与“长远”没有反义关系。", "河流": "无关：“河流”是地理事物，与“长远”的时间意义无关。", "友谊": "无关：“友谊”指人与人之间的感情，与“长远”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "眼前", "is_correct": true, "explanation": "反义：“眼前”指当前、目前，与“长远”着眼将来相对。"}, {"text": "书包", "is_correct": false, "explanation": "无关：“书包”是装东西的用品，与“长远”没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：“海洋”是自然地理事物，与“长远”的时间意义无关。"}, {"text": "秋天", "is_correct": false, "explanation": "无关：“秋天”是季节，与“长远”不构成反义。"}], "correct_answer": "眼前", "explanations": {"眼前": "反义：“眼前”指当前、目前，与“长远”着眼将来相对。", "书包": "无关：“书包”是装东西的用品，与“长远”没有反义关系。", "海洋": "无关：“海洋”是自然地理事物，与“长远”的时间意义无关。", "秋天": "无关：“秋天”是季节，与“长远”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指时间跨度大，不是短时间能完成的。", "primary_collocate": null, "pronunciation": "cháng yuǎn", "ipa": "ʈʂʰɑŋ˧˥ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "虽然有时候坐公交需要换乘，可能没有开车方便，但从长远来看，这对城市的环境和居民的生活质量都有好处。", "target_word": "长远", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "做事要有长远的打算，不能只看眼前。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目光很长远，早就开始为将来存钱了。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个长远的计划需要大家一起努力。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从长远来看，多读书对你有好处。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只想眼前，也要想想长远的事。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做对公司的长远发展很重要。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境是一件长远的大事。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的长远目标是开一家自己的小店。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买便宜的东西可能省钱，但长远来看并不划算。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "長遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长远|形容词|时间跨度大，着眼将来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长远", "is_correct": true, "explanation": "正确：“长远”指时间跨度长，“从长远来看”表示着眼将来的角度。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”指便利，与前文“没有开车方便”自相矛盾，不能作为看问题的角度。"}, {"text": "高尚", "is_correct": false, "explanation": "搭配：“高尚”形容品德，不能用来说看问题的角度，“从高尚来看”不成立。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能用来表示看问题的角度，“从热闹来看”不成立。"}], "explanations": {"长远": "正确：“长远”指时间跨度长，“从长远来看”表示着眼将来的角度。", "方便": "语义：“方便”指便利，与前文“没有开车方便”自相矛盾，不能作为看问题的角度。", "高尚": "搭配：“高尚”形容品德，不能用来说看问题的角度，“从高尚来看”不成立。", "热闹": "搭配：“热闹”形容场面或气氛，不能用来表示看问题的角度，“从热闹来看”不成立。"}, "sentence_index": 0, "correct_answer": "长远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这座城市长远地工作了三年。", "explanation": "这里应该用〈长期〉。长远强调着眼将来的时间跨度，描述过去已经发生的一段时间要用〈长期〉。"}, {"text": "他长远地记着童年的那段时光。", "explanation": "这里应该用〈长久〉。“长久地记着”指记忆持续很久，长远用于将来的打算，不能用来描述过去的记忆。"}, {"text": "这种香水的味道很长远。", "explanation": "这里应该用〈持久〉。长远只用于时间跨度和将来的规划，香气、效果的持续要用〈持久〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长远", "is_correct": true, "explanation": "正确：“长远发展”指着眼将来的持续发展，符合句意。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能修饰“发展”。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容公司的发展。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”说场面或气氛，“热闹的发展”不符合搭配习惯。"}], "explanations": {"长远": "正确：“长远发展”指着眼将来的持续发展，符合句意。", "年轻": "搭配：“年轻”说人的年龄，不能修饰“发展”。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容公司的发展。", "热闹": "搭配：“热闹”说场面或气氛，“热闹的发展”不符合搭配习惯。"}, "sentence_index": 6, "correct_answer": "长远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他住在长远的山区。", "explanation": "这里应该用〈遥远〉。长远只说时间的跨度，不用于空间距离；说地方远要用〈遥远〉。"}, {"text": "这个长远的冬天很难熬。", "explanation": "这里应该用〈漫长〉。长远着眼将来，不用来形容令人觉得拖沓的时间，这里要用〈漫长〉。"}, {"text": "这座城市有长远的历史。", "explanation": "这里应该用〈悠久〉。长远指将来的时间跨度，不用来描述已经存在很久的历史，这里要用〈悠久〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她规划事业时想很长远。", "corrected_sentence": "她规划事业时想得很长远。", "error_description": "错误：“想很长远”；正确：“想得很长远”。动词与形容词之间作程度补语时要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长远的规划着自己的未来。", "corrected_sentence": "他长远地规划着自己的未来。", "error_description": "错误：“长远的规划着”；正确：“长远地规划着”。修饰动词要用“地”，“的”之后只能接名词，“长远的规划”是名词短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
