INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指让提供的服务变得更好，让用户更满意。", "primary_collocate": null, "pronunciation": "gǎi shàn fú wù", "ipa": "kai˨˩˦ ʂan˥˩ fu˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "政府也在努力改善服务，让班次更准时，车厢更干净。", "target_word": "改善服务", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家银行想改善服务，让客人少等一会儿。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店为了改善服务，请了更多的工作人员。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，我们要改善服务，客人才会再来。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院正在改善服务，现在可以在网上排队了。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店改善服务以后，住的客人多了很多。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想留住客人，饭馆必须改善服务。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理开会讨论怎么改善服务。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家快递公司改善服务后，送货快多了。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算改善服务，让老人办事更方便。", "target_word": "改善服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改善服務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "改善服务|动词短语|提升服务质量，让用户更满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改善服务", "is_correct": true, "explanation": "正确：“改善服务”指让服务变得更好，与“让班次更准时，车厢更干净”相符。"}, {"text": "取消服务", "is_correct": false, "explanation": "语义：“取消服务”与后文“让班次更准时，车厢更干净”的改进目标相矛盾。"}, {"text": "降低服务", "is_correct": false, "explanation": "语义：“降低服务”与后文“让班次更准时，车厢更干净”的改进目标相矛盾。"}, {"text": "发扬服务", "is_correct": false, "explanation": "搭配：“发扬”多用于精神、传统，不能用来搭配“服务”。"}], "explanations": {"改善服务": "正确：“改善服务”指让服务变得更好，与“让班次更准时，车厢更干净”相符。", "取消服务": "语义：“取消服务”与后文“让班次更准时，车厢更干净”的改进目标相矛盾。", "降低服务": "语义：“降低服务”与后文“让班次更准时，车厢更干净”的改进目标相矛盾。", "发扬服务": "搭配：“发扬”多用于精神、传统，不能用来搭配“服务”。"}, "sentence_index": 0, "correct_answer": "改善服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台旧洗衣机需要改善服务。", "explanation": "这里应该用〈修理〉。改善服务只能用于提供服务的人或机构，机器坏了要说〈修理〉。"}, {"text": "这家公司今年的利润改善服务了很多。", "explanation": "这里应该用〈提高〉。改善服务指让服务变好，利润这类数量要说〈提高〉。"}, {"text": "顾客们经常改善服务，让饭馆越来越好。", "explanation": "这里应该用〈提意见〉。改善服务的主体是提供服务的一方，顾客只能提意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改善服务", "is_correct": true, "explanation": "正确：“要想留住客人，饭馆必须改善服务”，与前文的留客目标相符。"}, {"text": "驱赶客人", "is_correct": false, "explanation": "语义：“驱赶客人”与前文“要想留住客人”的目标直接矛盾。"}, {"text": "拆除门面", "is_correct": false, "explanation": "语义：“拆除门面”会让客人无法进入，与“留住客人”的目标相矛盾。"}, {"text": "喂养宠物", "is_correct": false, "explanation": "配价：“喂养”的宾语应是动物，“饭馆必须喂养宠物”与句意无关。"}], "explanations": {"改善服务": "正确：“要想留住客人，饭馆必须改善服务”，与前文的留客目标相符。", "驱赶客人": "语义：“驱赶客人”与前文“要想留住客人”的目标直接矛盾。", "拆除门面": "语义：“拆除门面”会让客人无法进入，与“留住客人”的目标相矛盾。", "喂养宠物": "配价：“喂养”的宾语应是动物，“饭馆必须喂养宠物”与句意无关。"}, "sentence_index": 6, "correct_answer": "改善服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的纪律需要改善服务。", "explanation": "这里应该用〈整顿〉。改善服务只用于提供服务的行业，班级纪律要说〈整顿〉。"}, {"text": "他的感冒还没改善服务，要多休息。", "explanation": "这里应该用〈好转〉。改善服务是人为地让服务变好，病情自己变好要说〈好转〉。"}, {"text": "这块地的土质改善服务了很多。", "explanation": "这里应该用〈改良〉。改善服务只用于提供服务的行业，土地的质量要说〈改良〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅把改善服务了，希望多留住熟客。", "corrected_sentence": "这家餐厅改善服务了，希望多留住熟客。", "error_description": "错误：“把改善服务了”；正确：“改善服务了”。“把”后须接名词性宾语，“改善服务”是动宾短语，不能整体放在“把”后，应去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭馆改善服务过，客人越来越多。", "corrected_sentence": "饭馆改善服务了，客人越来越多。", "error_description": "错误：“改善服务过”；正确：“改善服务了”。“过”表示经历，不能放在宾语“服务”之后表示完成；这里表示完成应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
