INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "班次指定期运行的车、船、飞机等交通工具按时间排列的次序或次数。", "primary_collocate": null, "pronunciation": "bān cì", "ipa": "pan˥˥ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "政府也在努力改善服务，让班次更准时，车厢更干净。", "target_word": "班次", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这条线路的班次很多，等车不用太久。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的班次比平时少。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我查了一下火车班次，晚上还有一趟。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定增加早上的班次。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天，很多飞机班次都取消了。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的公交班次不多，最晚的一班九点开。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的班次写得很清楚，我们很快找到了回家的车。", "target_word": "班次", "complexity_tier": "T3", "furigana": "bān cì", "sentence_source": "generated"}, {"text": "船的班次太少，我们只好住一晚。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的班次从下个月开始，每十分钟一班。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "班次表", "label": "复合"}], "register": "中性", "sense_fingerprint": "班次|名词|交通工具定期运行的次序与次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "班次", "is_correct": true, "explanation": "正确。“让班次更准时”指车船按时运行，班次可以准时。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价说的是价钱，不能用“准时”来形容。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：“准时”不能修饰车票，车票本身不会准时。"}, {"text": "站台", "is_correct": false, "explanation": "语义：站台是候车的地方，不是运行安排，不能说“让站台更准时”。"}], "explanations": {"班次": "正确。“让班次更准时”指车船按时运行，班次可以准时。", "票价": "语义：票价说的是价钱，不能用“准时”来形容。", "车票": "搭配：“准时”不能修饰车票，车票本身不会准时。", "站台": "语义：站台是候车的地方，不是运行安排，不能说“让站台更准时”。"}, "sentence_index": 0, "correct_answer": "班次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐班次去上班，路上要一个小时。", "explanation": "这里应该用〈班车〉。班次是车辆运行的时间安排，不是车辆本身，不能说“坐班次”。"}, {"text": "我们在路口等了一辆班次。", "explanation": "这里应该用〈班〉。“辆”只用来数车辆本身，班次是运行安排，不能用“辆”来数。"}, {"text": "我把班次夹进了笔记本里。", "explanation": "这里应该用〈时刻表〉。班次本身不是纸张，能夹进笔记本的是写着班次的时刻表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "班次", "is_correct": true, "explanation": "正确。“公交班次不多”说的是班次数量少，符合句意。"}, {"text": "车速", "is_correct": false, "explanation": "语义：车速说的是快慢，不是数量，“车速不多”说不通。"}, {"text": "票务", "is_correct": false, "explanation": "搭配：票务不能用量词“一班”来数，也不会“九点开”。"}, {"text": "车况", "is_correct": false, "explanation": "语义：车况说的是车辆的状况好坏，不能说“不多”。"}], "explanations": {"班次": "正确。“公交班次不多”说的是班次数量少，符合句意。", "车速": "语义：车速说的是快慢，不是数量，“车速不多”说不通。", "票务": "搭配：票务不能用量词“一班”来数，也不会“九点开”。", "车况": "语义：车况说的是车辆的状况好坏，不能说“不多”。"}, "sentence_index": 6, "correct_answer": "班次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这趟车的班次只要两块钱。", "explanation": "这里应该用〈票价〉。班次是运行安排，不是价格，不能说“只要两块钱”。"}, {"text": "我们在等一只班次。", "explanation": "这里应该用〈班〉。“只”用于动物等，班次不能用“只”来数。"}, {"text": "我刷了一下班次，就进站了。", "explanation": "这里应该用〈公交卡〉。进站时刷的是公交卡，班次不能用来刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个站每天有很多辆班次去市中心。", "corrected_sentence": "这个站每天有很多班次去市中心。", "error_description": "“班次”前多加了量词“辆”。“辆”只用于车辆本身，班次是运行安排，不能用“辆”来数，应直接说“很多班次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司增加了两间班次。", "corrected_sentence": "我们公司增加了两个班次。", "error_description": "错误：量词“间”错用。“间”用于房屋等空间，班次不能用“间”来数，应说“两个班次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
