INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指火车、汽车等交通工具中用于容纳乘客或货物的空间单元。", "primary_collocate": null, "pronunciation": "chē xiāng", "ipa": "ʈʂʰɤ˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "政府也在努力改善服务，让班次更准时，车厢更干净。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这列火车一共有八节车厢。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货运列车的车厢里装满了煤。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到后面的车厢找座位。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李放在车厢的架子上。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上的地铁车厢里人很多。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第五节车厢里有一位老人在睡觉。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这节车厢是专门给带小孩的人坐的。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑进了车厢，大家都笑了。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在打扫车厢。", "target_word": "车厢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节", "label": "量词"}, {"form": "硬座车厢", "label": "复合"}, {"form": "卧铺车厢", "label": "复合"}, {"form": "車廂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "火车、地铁等交通工具上分隔出来的一节载客或载货的空间单元", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车厢", "is_correct": true, "explanation": "正确。“车厢更干净”说的是车里的空间干净，符合句意。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩说的是分数高低，不能说“更干净”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不能用“干净”来形容。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：“干净”不能修饰票价，票价不说干净不干净。"}], "explanations": {"车厢": "正确。“车厢更干净”说的是车里的空间干净，符合句意。", "成绩": "语义：成绩说的是分数高低，不能说“更干净”。", "脾气": "语义：脾气是性格特点，不能用“干净”来形容。", "票价": "搭配：“干净”不能修饰票价，票价不说干净不干净。"}, "sentence_index": 0, "correct_answer": "车厢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把车厢装进了书包里。", "explanation": "这里应该用〈铅笔盒〉。车厢是火车上载客的空间，不能装进书包，能装进书包的是小件物品。"}, {"text": "这张车厢里很挤。", "explanation": "这里应该用〈节〉。车厢按“节”计量，“张”用于平面的东西。"}, {"text": "我把车厢开走了。", "explanation": "这里应该用〈车〉。车厢是车的一部分，不能单独开走，开走的是车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车厢", "is_correct": true, "explanation": "正确。“第五节车厢里有一位老人”指火车的一节车厢，符合句意。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店不是火车的一节，“第五节书店”说不通。"}, {"text": "田地", "is_correct": false, "explanation": "搭配：“第五节”不用于计量田地，田地不能说“节”。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆不是按节划分的空间，句子无法成立。"}], "explanations": {"车厢": "正确。“第五节车厢里有一位老人”指火车的一节车厢，符合句意。", "书店": "语义：书店不是火车的一节，“第五节书店”说不通。", "田地": "搭配：“第五节”不用于计量田地，田地不能说“节”。", "饭馆": "语义：饭馆不是按节划分的空间，句子无法成立。"}, "sentence_index": 6, "correct_answer": "车厢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只车厢里坐满了人。", "explanation": "这里应该用〈节〉。“只”用于动物，车厢应该用“节”来数。"}, {"text": "这艘船的车厢里装满了货。", "explanation": "这里应该用〈船舱〉。船上的载货空间叫船舱，车厢只用于火车、汽车等。"}, {"text": "他把车厢挂在脖子上。", "explanation": "这里应该用〈项链〉。车厢是车的一部分，不能挂在脖子上，能挂的是项链。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这列火车有十个车厢。", "corrected_sentence": "这列火车有十节车厢。", "error_description": "车厢的量词错用了“个”。车厢按“节”计数，应说“十节车厢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张车厢是专门给老人坐的。", "corrected_sentence": "这节车厢是专门给老人坐的。", "error_description": "车厢的量词错用了“张”。车厢应该用“节”，“张”用于平面的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
