INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人口向城市地区集中，城市规模扩大，农村地区转变为城市地区的过程。", "primary_collocate": null, "pronunciation": "chéng shì huà", "ipa": "ʈʂʰɤŋ˧˥ ʂʐ̩˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "在当代城市化进程的纵深推进中，公共交通系统作为城市机能的动脉，其环境效益早已超越单纯的运输功能，演变为维系生态平衡与可持续发展的重要战略支点。", "target_word": "城市化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在城市化进程日益加速的今天，生活垃圾的处理已成为制约可持续发展的关键议题。", "target_word": "城市化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "城市化让更多农民搬进了城市。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的城市化速度很快。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化带来了交通和住房问题。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着城市化的发展，农村人口越来越少。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化提高了人们的生活水平。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的城市化已经完成。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家研究城市化对环境的影响。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化需要更多的学校和医院。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "城市化进程", "label": "复合"}, {"form": "逆城市化", "label": "复合"}], "register": "书面", "sense_fingerprint": "人口集中、农村变城市的社会发展过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市化", "is_correct": true, "explanation": "正确：「城市化进程」是固定搭配，指人口向城市集中、城市规模扩大的过程，与句中的城市机能和交通系统相合。"}, {"text": "沙漠化", "is_correct": false, "explanation": "语义：「沙漠化」指土地变成沙漠，与句中的城市机能、公共交通系统无关，不能填入。"}, {"text": "老龄化", "is_correct": false, "explanation": "语义：「老龄化」说人口年龄结构变老，句子讲的是城市交通与环境效益，此处不合。"}, {"text": "人民", "is_correct": false, "explanation": "搭配：「人民」是指人群的名词，不表示发展过程，不说「人民进程」。"}], "explanations": {"城市化": "正确：「城市化进程」是固定搭配，指人口向城市集中、城市规模扩大的过程，与句中的城市机能和交通系统相合。", "沙漠化": "语义：「沙漠化」指土地变成沙漠，与句中的城市机能、公共交通系统无关，不能填入。", "老龄化": "语义：「老龄化」说人口年龄结构变老，句子讲的是城市交通与环境效益，此处不合。", "人民": "搭配：「人民」是指人群的名词，不表示发展过程，不说「人民进程」。"}, "sentence_index": 0, "correct_answer": "城市化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的城市化设备很多，学生都很喜欢。", "explanation": "这里应该用〈现代化〉。城市化指人口和地区向城市集中，不修饰「设备」；「现代化设备」是固定搭配。"}, {"text": "这家工厂的城市化程度很高，产量也很大。", "explanation": "这里应该用〈工业化〉。工厂的生产方式转变称工业化；城市化指人口与地区向城市集中，不用于单个工厂。"}, {"text": "这个小区的设施城市化了，居民都很满意。", "explanation": "这里应该用〈升级〉。城市化指地区或人口的转变，不用于设施；设施变好应说「升级」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市化", "is_correct": true, "explanation": "正确：「城市化」指人口向城市集中、农村转为城市的过程，与句中「提高了人们的生活水平」相合。"}, {"text": "贫困化", "is_correct": false, "explanation": "语义：「贫困化」指变穷，与句中「提高了人们的生活水平」的结果相反。"}, {"text": "荒漠化", "is_correct": false, "explanation": "语义：「荒漠化」指土地变成荒漠，会降低人们的生活水平，与句义不合。"}, {"text": "污染", "is_correct": false, "explanation": "语义：「污染」使环境变差，会降低而非提高人们的生活水平，与句义不合。"}], "explanations": {"城市化": "正确：「城市化」指人口向城市集中、农村转为城市的过程，与句中「提高了人们的生活水平」相合。", "贫困化": "语义：「贫困化」指变穷，与句中「提高了人们的生活水平」的结果相反。", "荒漠化": "语义：「荒漠化」指土地变成荒漠，会降低人们的生活水平，与句义不合。", "污染": "语义：「污染」使环境变差，会降低而非提高人们的生活水平，与句义不合。"}, "sentence_index": 6, "correct_answer": "城市化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爷爷需要城市化，每天多走路。", "explanation": "这里应该用〈锻炼〉。城市化指人口与地区向城市集中，不用于人的身体活动。"}, {"text": "这块农田需要城市化，多浇些水。", "explanation": "这里应该用〈灌溉〉。城市化不用于农田浇水；给农田浇水应说「灌溉」。"}, {"text": "这位医生的城市化很高，非常有名。", "explanation": "这里应该用〈水平〉。城市化指地区与人口的转变，不用于形容人的能力高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县的城市化的让很多农民进了城。", "corrected_sentence": "这个县的城市化让很多农民进了城。", "error_description": "错误形式在「城市化」后多加了「的」。城市化作主语时其后不加「的」，正确形式为「这个县的城市化让……」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年城市化被很多村子变成了城区。", "corrected_sentence": "这几年城市化让很多村子变成了城区。", "error_description": "“被”与“让”混用：“城市化”是变化的过程，不能作“被”字句的受事，应用“让”引出使役，说“城市化让很多村子变成了城区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物从表面到底部或从前面到后面的距离很大。", "primary_collocate": null, "pronunciation": "zòng shēn", "ipa": "tsʊŋ˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "在当代城市化进程的纵深推进中，公共交通系统作为城市机能的动脉，其环境效益早已超越单纯的运输功能，演变为维系生态平衡与可持续发展的重要战略支点。", "target_word": "纵深", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从历史纵深来看，这一标志的演化轨迹恰与全球环保运动的阶段性跃迁相呼应。", "target_word": "纵深", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座礼堂的纵深很大，后排座位离讲台很远。", "target_word": "纵深", "complexity_tier": "T3", "furigana": "zòng shēn", "sentence_source": "generated"}, {"text": "军队向敌人的纵深前进。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子的纵深有五十米。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林的纵深处很安静。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库纵深很大，能放很多货。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防守的纵深越大，就越安全。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要看问题的纵深，不能只看表面。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究很有纵深，不只是表面的东西。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纵深处", "label": "复合"}, {"form": "縱深", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从表面到深处、从前到后的纵向深度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「纵深」zòng shēn，指从表面到底部或从前到后的距离很大。"}, {"text": "终身", "is_correct": false, "explanation": "zhōng（第一声）与 zòng（第四声）声母与声调都不同，「终身」意思是一辈子，与「纵深」不同。"}, {"text": "重申", "is_correct": false, "explanation": "chóng（第二声）与 zòng 的声母 ch 与 z 不同，「重申」意思是再次声明，与「纵深」不同。"}, {"text": "纵声", "is_correct": false, "explanation": "shēng 与 shēn 的韵母 eng 与 en 不同，「纵声」意思是放开嗓门，与「纵深」不同。"}], "explanations": {"纵深": "正确：「纵深」zòng shēn，指从表面到底部或从前到后的距离很大。", "终身": "zhōng（第一声）与 zòng（第四声）声母与声调都不同，「终身」意思是一辈子，与「纵深」不同。", "重申": "chóng（第二声）与 zòng 的声母 ch 与 z 不同，「重申」意思是再次声明，与「纵深」不同。", "纵声": "shēng 与 shēn 的韵母 eng 与 en 不同，「纵声」意思是放开嗓门，与「纵深」不同。"}, "sentence_index": null, "correct_answer": "纵深"}, "level_3": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「纵深推进」指向前、向深处推进，与句中城市化进程的语境相合。"}, {"text": "宽度", "is_correct": false, "explanation": "语义：「宽度」指左右之间的距离，与句中向纵深推进的意思不合。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：「色彩」不能用于「推进」，不说「色彩推进」。"}, {"text": "面积", "is_correct": false, "explanation": "语义：「面积」描述平面的大小，不能表示推进的深入程度。"}], "explanations": {"纵深": "正确：「纵深推进」指向前、向深处推进，与句中城市化进程的语境相合。", "宽度": "语义：「宽度」指左右之间的距离，与句中向纵深推进的意思不合。", "色彩": "搭配：「色彩」不能用于「推进」，不说「色彩推进」。", "面积": "语义：「面积」描述平面的大小，不能表示推进的深入程度。"}, "sentence_index": 0, "correct_answer": "纵深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条马路的纵深是绿色的。", "explanation": "这里应该用〈颜色〉。颜色指物体表面的色彩；纵深指从前到后的距离，不能说是什么颜色。"}, {"text": "这部电影的纵深有两个小时。", "explanation": "这里应该用〈时长〉。时长指时间的长短；纵深指空间中从前到后的距离，不用于计算时间。"}, {"text": "这个箱子的纵深要三百块钱。", "explanation": "这里应该用〈价格〉。价格指买卖的钱数；纵深是距离，不能用钱数来计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「这个仓库纵深很大」指仓库从前到后的距离很大，能放很多货，与句义相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」一般说「颜色很深」之类，不说仓库的「颜色很大」。"}, {"text": "音量", "is_correct": false, "explanation": "语义：「音量」指声音大小，与仓库的大小和容纳货物无关。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的情绪，与仓库能放很多货的语境不符。"}], "explanations": {"纵深": "正确：「这个仓库纵深很大」指仓库从前到后的距离很大，能放很多货，与句义相合。", "颜色": "搭配：「颜色」一般说「颜色很深」之类，不说仓库的「颜色很大」。", "音量": "语义：「音量」指声音大小，与仓库的大小和容纳货物无关。", "心情": "语义：「心情」是人的情绪，与仓库能放很多货的语境不符。"}, "sentence_index": 6, "correct_answer": "纵深"}, "level_6": {"correct_sentence_index": 2, "wrong_sentences": [{"text": "这根绳子的纵深有十米。", "explanation": "这里应该用〈长度〉。长度指一条线的长短；纵深指空间从前到后的深处，绳子不适用。"}, {"text": "这间屋子的纵深有十岁了。", "explanation": "这里应该用〈年龄〉。年龄指人或物存在的年数；纵深是空间中从前到后的距离，不能说「有十岁了」。"}, {"text": "这个箱子的纵深很重。", "explanation": "这里应该用〈重量〉。重量指轻重，纵深指距离，不能说「很重」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座墓穴的纵深大很，进去以后很难出来。", "corrected_sentence": "这座墓穴的纵深很大，进去以后很难出来。", "error_description": "错误形式把形容词谓语的「很」放在「大」之后。应说「纵深很大」，正确形式为「这座墓穴的纵深很大」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块田的一个纵深很大，能种很多庄稼。", "corrected_sentence": "这块田的纵深很大，能种很多庄稼。", "error_description": "错误形式用「一个」修饰「纵深」。「纵深」是抽象名词，不能用个体量词计数，正确形式为「这块田的纵深很大」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
