INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11702, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生物体器官或组织所具有的功能和作用。", "primary_collocate": null, "pronunciation": "jī néng", "ipa": "tɕi˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "长期高强度的精神压力会干扰内分泌系统的调节，使肝、肾等器官的机能在不知不觉中逐步衰退。", "target_word": "机能", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "运动可以提高心肺机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年的生理机能还在发育。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能改善肠胃机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不好会影响大脑的机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的肾脏机能正常。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，眼睛的机能也会变差。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后，他的身体机能慢慢恢复了。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽烟会损害肺的机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体的各种机能都需要休息。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "機能", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "生物体器官或组织所具有的功能和作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机能", "is_correct": true, "explanation": "正确。“肝、肾等器官的机能逐步衰退”指器官功能下降，与“干扰内分泌系统的调节”的因果语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是器官，“器官的食物逐步衰退”读不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是器官，“器官的乐器逐步衰退”读不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：器官没有性格，“器官的性格逐步衰退”读不通。"}], "explanations": {"机能": "正确。“肝、肾等器官的机能逐步衰退”指器官功能下降，与“干扰内分泌系统的调节”的因果语境相符。", "食物": "语义：食物不是器官，“器官的食物逐步衰退”读不通。", "乐器": "语义：乐器不是器官，“器官的乐器逐步衰退”读不通。", "性格": "语义：器官没有性格，“器官的性格逐步衰退”读不通。"}, "sentence_index": 0, "correct_answer": "机能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台手机的机能很多。", "explanation": "这里应该用〈功能〉。“机能”只用于生物体器官，手机的作用要说“功能”。"}, {"text": "医生检查了他的一台机能。", "explanation": "这里应该用〈种〉。“台”用于机器，机能是器官的作用，应说“一种机能”。"}, {"text": "这种药的机能很好。", "explanation": "这里应该用〈功效〉。“机能”指器官的作用，药物的效果要说“功效”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机能", "is_correct": true, "explanation": "正确。“眼睛的机能也会变差”指眼睛的功能下降，与“年纪大了”相符。"}, {"text": "性格", "is_correct": false, "explanation": "语义：眼睛没有性格，“眼睛的性格也会变差”读不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是数值，不能用“变差”来描述。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是数值，“眼睛的体重也会变差”不合理，且体重不用“变差”描述。"}], "explanations": {"机能": "正确。“眼睛的机能也会变差”指眼睛的功能下降，与“年纪大了”相符。", "性格": "语义：眼睛没有性格，“眼睛的性格也会变差”读不通。", "身高": "搭配：“身高”是数值，不能用“变差”来描述。", "体重": "搭配：“体重”是数值，“眼睛的体重也会变差”不合理，且体重不用“变差”描述。"}, "sentence_index": 6, "correct_answer": "机能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的机能很好。", "explanation": "这里应该用〈性能〉。“机能”用于生物体，电脑的效能要说“性能”。"}, {"text": "他身体里有一座机能。", "explanation": "这里应该用〈种〉。“座”用于大型建筑，机能应当用“种”。"}, {"text": "这项政策的机能很大。", "explanation": "这里应该用〈作用〉。“机能”指器官的功能，政策的影响要说“作用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "肝脏具有一台解毒的机能。", "corrected_sentence": "肝脏具有一种解毒的机能。", "error_description": "量词错误：“机能”前面的量词应为“种”，“台”用于机器，不能用于器官的作用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "锻炼能够增强心脏地机能。", "corrected_sentence": "锻炼能够增强心脏的机能。", "error_description": "结构助词错误：修饰名词“机能”应用“的”，写作“心脏的机能”；“地”多用于修饰动词、形容词，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动脉是将血液从心脏输送到身体各部位的血管，管壁较厚，弹性大。", "primary_collocate": null, "pronunciation": "dòng mài", "ipa": "tʊŋ˥˩ maɪ˥˩", "syllable_count": 2, "sentences": [{"text": "长期血压居高不下，会对血流通道造成持续压力，动脉的管壁逐渐增厚变硬，弹性随之下降，血液流经时的阻力明显增大。", "target_word": "动脉", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "动脉把血液从心脏送到全身。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生摸了摸他手腕上的动脉。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉的管壁比静脉厚，弹性也大。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏跳一下，血液就流进动脉。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的颈部动脉受了伤，流了很多血。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的动脉有点儿硬了，要少吃油。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉的血压比静脉的高得多。", "target_word": "动脉", "complexity_tier": "T3", "furigana": "dòng mài de xuè yā bǐ jìng mài de gāo de duō", "sentence_source": "generated"}, {"text": "医生把手放在动脉上，感觉到了脉搏。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉受伤时，血会流得很快。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "主动脉", "label": "复合"}, {"form": "动脉血", "label": "复合"}, {"form": "動脈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动脉：将血液从心脏输送到身体各部位的血管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气管", "is_correct": false, "explanation": "语义：气管是呼吸的通道，不是血液流经的管道，与“血流通道”“血液流经时的阻力”的语境不符。"}, {"text": "动脉", "is_correct": true, "explanation": "正确：动脉的管壁增厚变硬、弹性下降，与“血压居高不下”“血液流经时的阻力明显增大”的语境相符。"}, {"text": "神经", "is_correct": false, "explanation": "语义：神经负责传导信号，不是血液流经的管道，“管壁逐渐增厚变硬”的说法不适用。"}, {"text": "食管", "is_correct": false, "explanation": "语义：食管是消化道，与血压和血流阻力无关，放在此处不通。"}], "explanations": {"气管": "语义：气管是呼吸的通道，不是血液流经的管道，与“血流通道”“血液流经时的阻力”的语境不符。", "动脉": "正确：动脉的管壁增厚变硬、弹性下降，与“血压居高不下”“血液流经时的阻力明显增大”的语境相符。", "神经": "语义：神经负责传导信号，不是血液流经的管道，“管壁逐渐增厚变硬”的说法不适用。", "食管": "语义：食管是消化道，与血压和血流阻力无关，放在此处不通。"}, "sentence_index": 0, "correct_answer": "动脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动脉把血液从身体各处送回心脏。", "explanation": "这里应该用〈静脉〉。动脉把血液从心脏送往全身，把血液送回心脏的是静脉，方向正好相反。"}, {"text": "我在手腕上摸到了一只动脉。", "explanation": "这里应该用〈条〉。动脉是血管，量词用“条”；“只”多用于动物，不用于血管。"}, {"text": "医生给他抽了一管动脉去化验。", "explanation": "这里应该用〈血〉。动脉是输送血液的管道，被抽取的是血，应说“抽一管血”，不能说“抽一管动脉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指甲", "is_correct": false, "explanation": "语义：指甲是手指末端的角质层，与血管变硬、要少吃油的语境无关。"}, {"text": "动脉", "is_correct": true, "explanation": "正确：动脉可以变硬，医生提醒“要少吃油”，指的是血管的状况。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不会因为吃油而变硬，这里说的是血管病变。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“他的”后接身体部位，饼干不是人的器官，医生不会这样描述它的状况。"}], "explanations": {"指甲": "语义：指甲是手指末端的角质层，与血管变硬、要少吃油的语境无关。", "动脉": "正确：动脉可以变硬，医生提醒“要少吃油”，指的是血管的状况。", "耳朵": "语义：耳朵不会因为吃油而变硬，这里说的是血管病变。", "饼干": "搭配：“他的”后接身体部位，饼干不是人的器官，医生不会这样描述它的状况。"}, "sentence_index": 6, "correct_answer": "动脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "血液在动脉里交换氧气和二氧化碳。", "explanation": "这里应该用〈毛细血管〉。氧气和二氧化碳的交换发生在毛细血管里，动脉的作用是输送血液。"}, {"text": "动脉负责把疼痛的信号传给大脑。", "explanation": "这里应该用〈神经〉。传递疼痛信号的是神经，动脉的作用是输送血液。"}, {"text": "动脉负责过滤血液中的废物。", "explanation": "这里应该用〈肾脏〉。过滤血液、排出废物是肾脏的功能，动脉并不承担这项作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生的图上画着一只动脉。", "corrected_sentence": "医生的图上画着一条动脉。", "error_description": "量词错误：动脉是血管，应用量词“条”；“只”多用于动物，不能用于血管。正确的说法是“一条动脉”，错误的说法是“一只动脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的一张动脉被刀子割破了，血流得很快。", "corrected_sentence": "他的一条动脉被刀子割破了，血流得很快。", "error_description": "量词错误：“张”用于平面的东西，血管不能用“张”计量。正确的说法是“一条动脉”，错误的说法是“一张动脉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环境效益是指某项活动或政策对生态环境产生的正面影响和积极效果。", "primary_collocate": null, "pronunciation": "huán jìng xiào yì", "ipa": "xwan˧˥ tɕiŋ˥˩ ɕjaʊ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "在当代城市化进程的纵深推进中，公共交通系统作为城市机能的动脉，其环境效益早已超越单纯的运输功能，演变为维系生态平衡与可持续发展的重要战略支点。", "target_word": "环境效益", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "种树的环境效益很大，也能让空气变好。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂只看钱，不管环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的环境效益比它的门票收入更重要。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府想了解新公交的环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少开车能提高城市的环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策的环境效益，要过几年才看得出来。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能发电有很好的环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家算了一下回收塑料的环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不但要经济效益，也要考虑环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境效益", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某项活动或政策对生态环境的正面影响和积极效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境效益", "is_correct": true, "explanation": "正确：“超越单纯的运输功能”指积极的生态效果，与“维系生态平衡”相符。"}, {"text": "环境危害", "is_correct": false, "explanation": "语义：“危害”是负面影响，与“维系生态平衡”“战略支点”的正面语境矛盾。"}, {"text": "环境污染", "is_correct": false, "explanation": "语义：“污染”指对环境的破坏，与“可持续发展的战略支点”不符。"}, {"text": "交通拥堵", "is_correct": false, "explanation": "搭配：“超越运输功能，演变为战略支点”的主语应是积极效果，“拥堵”不能这样演变。"}], "explanations": {"环境效益": "正确：“超越单纯的运输功能”指积极的生态效果，与“维系生态平衡”相符。", "环境危害": "语义：“危害”是负面影响，与“维系生态平衡”“战略支点”的正面语境矛盾。", "环境污染": "语义：“污染”指对环境的破坏，与“可持续发展的战略支点”不符。", "交通拥堵": "搭配：“超越运输功能，演变为战略支点”的主语应是积极效果，“拥堵”不能这样演变。"}, "sentence_index": 0, "correct_answer": "环境效益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个人的环境效益很高，大家都很尊敬他。", "explanation": "这里应该用〈环保意识〉。环境效益指某项活动或政策对环境的好处，不能用来形容一个人；形容人应说“环保意识很强”。"}, {"text": "这家工厂投入很多钱，做了很多环境效益。", "explanation": "这里应该用〈环境保护〉。“效益”是结果，不能说“做环境效益”，应说“做环境保护”。"}, {"text": "这座城市的环境效益很严重。", "explanation": "这里应该用〈环境问题〉。环境效益是积极的好处，不能用“很严重”形容，严重的应是环境问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是政策的效果，与“这项政策的”搭配不通。"}, {"text": "环境效益", "is_correct": true, "explanation": "正确：政策的效果要过几年才能看出来，“环境效益”符合这个语境。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食与政策的成效无关，放在此处不通。"}, {"text": "外观", "is_correct": false, "explanation": "搭配：政策一般不说“外观”，“这项政策的外观”搭配不当。"}], "explanations": {"天气": "语义：天气不是政策的效果，与“这项政策的”搭配不通。", "环境效益": "正确：政策的效果要过几年才能看出来，“环境效益”符合这个语境。", "饮食": "语义：饮食与政策的成效无关，放在此处不通。", "外观": "搭配：政策一般不说“外观”，“这项政策的外观”搭配不当。"}, "sentence_index": 6, "correct_answer": "环境效益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个办法能节约环境效益。", "explanation": "这里应该用〈能源〉。“节约”的对象是能源等资源，效益不能被节约。"}, {"text": "这个工厂减排了很多环境效益。", "explanation": "这里应该用〈二氧化碳〉。“减排”的对象是排放物，效益不能被减排。"}, {"text": "工厂排出的环境效益要处理。", "explanation": "这里应该用〈污水〉。要处理的是污水等排放物，效益不能被排出或处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坐地铁能提高城市地环境效益。", "corrected_sentence": "坐地铁能提高城市的环境效益。", "error_description": "结构助词错误：修饰名词“环境效益”要用“的”，“地”只用于修饰动词、形容词。正确的说法是“城市的环境效益”，错误的说法是“城市地环境效益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新公园的环境效益们很高。", "corrected_sentence": "这个新公园的环境效益很高。", "error_description": "词形错误：“们”只用于指人或拟人化的名词，“环境效益”是抽象名词，不能加“们”。正确的说法是“环境效益很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
