INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11707, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生物群落与周围环境之间相互协调、相对稳定的状态。", "primary_collocate": null, "pronunciation": "shēng tài píng héng", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "在当代城市化进程的纵深推进中，公共交通系统作为城市机能的动脉，其环境效益早已超越单纯的运输功能，演变为维系生态平衡与可持续发展的重要战略支点。", "target_word": "生态平衡", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "乱捕鸟会破坏生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼少了，鹿变多，生态平衡出了问题。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护湿地，是为了保持生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湖的生态平衡已经恢复了。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家一直在研究海洋的生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外来的鱼会影响河里的生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态平衡对人类的生活很重要。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的动物太多，生态平衡就会改变。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把鱼放回河里，想让生态平衡好起来。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態平衡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生物群落与周围环境相互协调、相对稳定的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股票行情", "is_correct": false, "explanation": "语义：句子讲的是城市交通与环境效益，股票行情与之无关，不能与“可持续发展”并列。"}, {"text": "生态平衡", "is_correct": true, "explanation": "正确：句子说公共交通的环境效益在于维系生态平衡与可持续发展，“生态平衡”与“可持续发展”并列，合乎语境。"}, {"text": "流行歌曲", "is_correct": false, "explanation": "搭配：“维系”多接秩序、关系、平衡一类抽象对象，不说“维系歌曲”。"}, {"text": "个人隐私", "is_correct": false, "explanation": "语义：句中的主体是公共交通系统，个人隐私不能作为城市的战略支点。"}], "explanations": {"股票行情": "语义：句子讲的是城市交通与环境效益，股票行情与之无关，不能与“可持续发展”并列。", "生态平衡": "正确：句子说公共交通的环境效益在于维系生态平衡与可持续发展，“生态平衡”与“可持续发展”并列，合乎语境。", "流行歌曲": "搭配：“维系”多接秩序、关系、平衡一类抽象对象，不说“维系歌曲”。", "个人隐私": "语义：句中的主体是公共交通系统，个人隐私不能作为城市的战略支点。"}, "sentence_index": 0, "correct_answer": "生态平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈去超市买了生态平衡。", "explanation": "这个词不这么用：“买”要求的对象是商品，生态平衡是抽象的状态，不能买。"}, {"text": "他每天都在做生态平衡，很辛苦。", "explanation": "这个词不这么用：“做”后面接具体的事情，如“做饭”“做作业”；生态平衡是状态，应说“维护”或“保持”生态平衡。"}, {"text": "这位科学家擅长发明生态平衡。", "explanation": "这里应该用〈研究〉或〈发现〉。“发明”用于创造新的物品或方法，生态平衡是自然中形成的状态，不能被发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房价", "is_correct": false, "explanation": "语义：房价与河里的鱼无关，句子说的是生态问题，“影响河里的房价”不成立。"}, {"text": "生态平衡", "is_correct": true, "explanation": "正确：外来的鱼会打破河中的生态平衡，“影响河里的生态平衡”合乎语境。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费与河里的鱼和生态状况无关，句意中不存在能被影响的学费。"}, {"text": "铁路", "is_correct": false, "explanation": "搭配：“河里的”后接的应是河中的事物，铁路不能在河里，这样的搭配不成立。"}], "explanations": {"房价": "语义：房价与河里的鱼无关，句子说的是生态问题，“影响河里的房价”不成立。", "生态平衡": "正确：外来的鱼会打破河中的生态平衡，“影响河里的生态平衡”合乎语境。", "学费": "语义：学费与河里的鱼和生态状况无关，句意中不存在能被影响的学费。", "铁路": "搭配：“河里的”后接的应是河中的事物，铁路不能在河里，这样的搭配不成立。"}, "sentence_index": 6, "correct_answer": "生态平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里有一只生态平衡，真美。", "explanation": "量词：〈只〉用于动物等个体，“生态平衡”是抽象名词，不能用“只”计量。"}, {"text": "这家公司去年终于实现了生态平衡。", "explanation": "这里应该用〈收支平衡〉。“生态平衡”指生物与环境相互协调的状态，公司收入与支出相抵要说〈收支平衡〉。"}, {"text": "他的生态平衡跑得很快。", "explanation": "搭配：“跑”的主语应是人或车辆，“生态平衡”是状态，不会跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乱捕乱杀让这片湖的生态平衡破坏了。", "corrected_sentence": "乱捕乱杀让这片湖的生态平衡被破坏了。", "error_description": "“生态平衡”是被破坏的对象，应用被动句，说“生态平衡被破坏了”。只说“生态平衡破坏了”缺少“被”，意思像是平衡自己失去了，不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖里的生态平衡们一直保持着。", "corrected_sentence": "湖里的生态平衡一直保持着。", "error_description": "词形错误：“们”只用于指人或拟人化的名词，“生态平衡”是抽象名词，不能加“们”。正确的说法是“生态平衡一直保持着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
