INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "支点是指杠杆上起支撑作用并让杠杆能绕其转动的固定点，也可以比喻为事情发展的关键或基础。", "primary_collocate": null, "pronunciation": "zhī diǎn", "ipa": "ʈʂʅ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "在当代城市化进程的纵深推进中，公共交通系统作为城市机能的动脉，其环境效益早已超越单纯的运输功能，演变为维系生态平衡与可持续发展的重要战略支点。", "target_word": "支点", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此时，半导体物理学的成熟为能源转型提供了关键支点。", "target_word": "支点", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个小镇把旅游当作发展的支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到合适的支点，小公司也能撬动大市场。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育是社会进步的重要支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这份工作看作人生的新支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的政策能成为经济增长的支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稳定的家庭是孩子成长的支点。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司以科技创新为发展的支点。", "target_word": "支点", "complexity_tier": "T3", "furigana": "zhè jiā gōngsī yǐ kējì chuàngxīn wéi fāzhǎn de zhīdiǎn。", "sentence_source": "generated"}, {"text": "阿基米德说：给我一个支点，我就能撬起地球。", "target_word": "支点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支點", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "杠杆的固定点；比喻事情发展的关键或基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指点", "is_correct": false, "explanation": "指点（zhǐ 第三声）与支点（zhī 第一声）声调不同，意思是指教、点拨。"}, {"text": "支点", "is_correct": true, "explanation": "支点：杠杆上起支撑、让杠杆能转动的固定点，也比喻事情发展的关键或基础。"}, {"text": "吃点", "is_correct": false, "explanation": "吃点（chī）与支点（zhī）声母不同（ch 与 zh），意思是吃一些东西。"}, {"text": "质点", "is_correct": false, "explanation": "质点（zhì 第四声）与支点（zhī 第一声）声调不同，是物理学中忽略大小的理想化物体。"}, {"text": "支店", "is_correct": false, "explanation": "支店（diàn 第四声）与支点（diǎn 第三声）声调不同，意思是分店。"}], "explanations": {"指点": "指点（zhǐ 第三声）与支点（zhī 第一声）声调不同，意思是指教、点拨。", "支点": "支点：杠杆上起支撑、让杠杆能转动的固定点，也比喻事情发展的关键或基础。", "吃点": "吃点（chī）与支点（zhī）声母不同（ch 与 zh），意思是吃一些东西。", "质点": "质点（zhì 第四声）与支点（zhī 第一声）声调不同，是物理学中忽略大小的理想化物体。", "支店": "支店（diàn 第四声）与支点（diǎn 第三声）声调不同，意思是分店。"}, "sentence_index": null, "correct_answer": "支点"}, "level_3": {"options": [{"text": "粉尘", "is_correct": false, "explanation": "语义：粉尘是污染物，与句中“环境效益”“生态平衡”的正面语境相悖。"}, {"text": "支点", "is_correct": true, "explanation": "支点：比喻事物发展的关键或基础，与“重要战略”搭配，符合句意。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“战略”修饰规划、目标或地位，不说“战略账单”。"}, {"text": "段子", "is_correct": false, "explanation": "语域：段子是口语化的笑话，与这句书面论述的语域不符，“战略段子”也不成词。"}], "explanations": {"粉尘": "语义：粉尘是污染物，与句中“环境效益”“生态平衡”的正面语境相悖。", "支点": "支点：比喻事物发展的关键或基础，与“重要战略”搭配，符合句意。", "账单": "搭配：“战略”修饰规划、目标或地位，不说“战略账单”。", "段子": "语域：段子是口语化的笑话，与这句书面论述的语域不符，“战略段子”也不成词。"}, "sentence_index": 0, "correct_answer": "支点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的支点在上游。", "explanation": "这里应该用〈源头〉。支点指杠杆上的固定点或关键基础；河流的起始处应说源头。"}, {"text": "这个三角形的支点在顶角。", "explanation": "这里应该用〈顶点〉。支点指杠杆上的固定点或关键基础；三角形的角应说顶点。"}, {"text": "这个圆的支点恰好在正中央。", "explanation": "这里应该用〈圆心〉。支点指杠杆上的固定点；圆的中心应说圆心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试点", "is_correct": false, "explanation": "试点（shì 第四声）与支点（zhī）声母不同（sh 与 zh），声调也不同，意思是先行试验的地方。"}, {"text": "支点", "is_correct": true, "explanation": "支点：杠杆上起支撑、让杠杆能转动的固定点，也比喻事情发展的关键或基础。"}, {"text": "字典", "is_correct": false, "explanation": "字典（zì 第四声）与支点（zhī）声母不同（z 与 zh），声调也不同，意思是字典。"}, {"text": "疵点", "is_correct": false, "explanation": "疵点（cī 第一声）与支点（zhī 第一声）声母不同（c 与 zh），意思是产品或作品的缺点。"}, {"text": "质点", "is_correct": false, "explanation": "质点（zhì 第四声）与支点（zhī 第一声）声调不同，是物理学中忽略大小的理想化物体。"}], "explanations": {"试点": "试点（shì 第四声）与支点（zhī）声母不同（sh 与 zh），声调也不同，意思是先行试验的地方。", "支点": "支点：杠杆上起支撑、让杠杆能转动的固定点，也比喻事情发展的关键或基础。", "字典": "字典（zì 第四声）与支点（zhī）声母不同（z 与 zh），声调也不同，意思是字典。", "疵点": "疵点（cī 第一声）与支点（zhī 第一声）声母不同（c 与 zh），意思是产品或作品的缺点。", "质点": "质点（zhì 第四声）与支点（zhī 第一声）声调不同，是物理学中忽略大小的理想化物体。"}, "sentence_index": null, "correct_answer": "支点"}, "level_3": {"options": [{"text": "病毒", "is_correct": false, "explanation": "语义：病毒含负面义，与“好的政策”的正面语境冲突，不能说“经济增长的病毒”。"}, {"text": "支点", "is_correct": true, "explanation": "支点：比喻推动发展的关键，与“好的政策能成为”相合，符合句意。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“增长”后不接“驾照”这类证件名词。"}, {"text": "罐头", "is_correct": false, "explanation": "语义：罐头是食品，与“经济增长”这一抽象过程毫不相干。"}], "explanations": {"病毒": "语义：病毒含负面义，与“好的政策”的正面语境冲突，不能说“经济增长的病毒”。", "支点": "支点：比喻推动发展的关键，与“好的政策能成为”相合，符合句意。", "驾照": "搭配：“增长”后不接“驾照”这类证件名词。", "罐头": "语义：罐头是食品，与“经济增长”这一抽象过程毫不相干。"}, "sentence_index": 6, "correct_answer": "支点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子的支点在刻度零点。", "explanation": "这里应该用〈零点〉。支点指杠杆上的固定点或关键基础；尺子的起算点应说零点。"}, {"text": "这次比赛的支点就设在跑道起点。", "explanation": "这里应该用〈起点〉。支点指杠杆的固定支撑点或关键基础；跑道的出发位置应说起点。"}, {"text": "这台相机的支点对准了远处的山。", "explanation": "这里应该用〈焦点〉。支点指杠杆的固定支撑点；镜头的聚焦位置应说焦点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司找到了一把重要的支点。", "corrected_sentence": "公司找到了一个重要的支点。", "error_description": "量词错误：“支点”应搭配“个”，说“一个重要的支点”；“把”多用于有柄的器具，不用于“支点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革为城市发展提供了一条重要支点。", "corrected_sentence": "这次改革为城市发展提供了一个重要支点。", "error_description": "量词错误：“支点”应搭配“个”，说“一个重要支点”；“支点”不搭配“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在城市中运行的铁路运输系统，包括地铁、轻轨等，用于快速运送乘客。", "primary_collocate": null, "pronunciation": "guǐ dào jiāo tōng", "ipa": "kweɪ̯˨˩˦ tɑʊ̯˥˩ tɕjɑʊ̯˥ tʰʊŋ˥", "syllable_count": 4, "sentences": [{"text": "当个体选择地铁、公交或共享轨道交通作为日常通勤的主要载体，其行为本质上构成对私人机动化出行模式的系统性替代，由此引发的连锁效应深刻重塑了城市的污染谱系。", "target_word": "轨道交通", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "该模式通过将高容量轨道交通站点与混合功能用地布局进行耦合设计，使居住、就业、商业与公共服务在步行可达范围内高度集聚，从而在空间结构层面抑制了长距离通勤的刚性需求。", "target_word": "轨道交通", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市正在建设新的轨道交通。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轨道交通包括地铁和轻轨。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轨道交通的优点是速度快、准点。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民可以乘坐轨道交通去上班。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的轨道交通线路明年开通。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发展轨道交通能减少道路拥堵。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轨道交通沿线的房价普遍较高。", "target_word": "轨道交通", "complexity_tier": "T3", "furigana": "guǐ dào jiāo tōng", "sentence_source": "generated"}, {"text": "政府投入大量资金修建轨道交通。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "城市轨道交通", "label": "复合"}, {"form": "軌道交通", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "城市中以地铁、轻轨等为主的铁路客运系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共享信息", "is_correct": false, "explanation": "语义：通勤的主要载体是交通方式，信息不能充当通勤载体。"}, {"text": "轨道交通", "is_correct": true, "explanation": "正确：“共享轨道交通”指与地铁、公交并列的共享交通方式，与“作为通勤载体”相符。"}, {"text": "共享知识", "is_correct": false, "explanation": "语义：知识不是可以承担通勤功能的载体，与句意不符。"}, {"text": "共享睡眠", "is_correct": false, "explanation": "搭配：“共享”搭配的是可以分享的设施或资源，睡眠不能被共享。"}], "explanations": {"共享信息": "语义：通勤的主要载体是交通方式，信息不能充当通勤载体。", "轨道交通": "正确：“共享轨道交通”指与地铁、公交并列的共享交通方式，与“作为通勤载体”相符。", "共享知识": "语义：知识不是可以承担通勤功能的载体，与句意不符。", "共享睡眠": "搭配：“共享”搭配的是可以分享的设施或资源，睡眠不能被共享。"}, "sentence_index": 0, "correct_answer": "轨道交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "轨道交通包括地铁和公交车。", "explanation": "这里应该用〈公共交通〉。轨道交通指地铁、轻轨等在轨道上运行的系统，公交车不属于轨道交通。"}, {"text": "他每天骑着轨道交通去上班。", "explanation": "搭配：〈骑〉用于自行车、马等，轨道交通是运输系统，要说“乘坐”轨道交通。"}, {"text": "妈妈在超市买了两份轨道交通。", "explanation": "这个词不这么用：“买”的对象应是商品，轨道交通是城市运输系统，不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语文", "is_correct": false, "explanation": "语义：语文不是交通线路，句子讲的是新线路明年开通，“新的语文线路”不成立。"}, {"text": "轨道交通", "is_correct": true, "explanation": "正确：“新的轨道交通线路”是常见说法，与“明年开通”相符。"}, {"text": "海鲜", "is_correct": false, "explanation": "语义：海鲜不能作为线路开通，与句意不符。"}, {"text": "流行歌曲", "is_correct": false, "explanation": "搭配：“线路”指交通或通信的路径，不能说“流行歌曲线路”。"}], "explanations": {"语文": "语义：语文不是交通线路，句子讲的是新线路明年开通，“新的语文线路”不成立。", "轨道交通": "正确：“新的轨道交通线路”是常见说法，与“明年开通”相符。", "海鲜": "语义：海鲜不能作为线路开通，与句意不符。", "流行歌曲": "搭配：“线路”指交通或通信的路径，不能说“流行歌曲线路”。"}, "sentence_index": 6, "correct_answer": "轨道交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这趟轨道交通在大海上航行。", "explanation": "这里应该用〈轮船〉。轨道交通只在轨道上运行，不能在大海上航行；在海上航行的应说〈轮船〉。"}, {"text": "我家门口有一棵轨道交通。", "explanation": "量词：〈棵〉用于树木等植物，轨道交通是城市运输系统，不能用“棵”计量。"}, {"text": "这列轨道交通很会唱歌。", "explanation": "搭配：“唱歌”的主语应是能唱的人，轨道交通是运输系统，不会唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我坐过一只轨道交通。", "corrected_sentence": "我坐过轨道交通。", "error_description": "量词错误：“只”用于动物，不能用来计量轨道交通这类运输系统。去掉“一只”，直接说“我坐过轨道交通”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市的轨道交通们很完善。", "corrected_sentence": "这座城市的轨道交通很完善。", "error_description": "词形错误：“们”只用于指人或拟人化的名词，“轨道交通”是事物，不能加“们”。正确的说法是“轨道交通很完善”，错误的说法是“轨道交通们很完善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11711, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
