INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "计划、安排中留出的、可灵活调整的余地。", "primary_collocate": null, "pronunciation": "jī dòng", "ipa": "tɕi˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出差行程里要留一些机动，以应对突发情况。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计划里要留一点机动。", "target_word": "机动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "预算中应保留一定的机动。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方案缺少机动，很难调整。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "给团队多一些机动，工作会更顺利。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安排日程时，我们要留有机动。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的计划很死板，没有一点机动。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理给了我们很大的机动。", "target_word": "机动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经费有机动，就不怕临时变化。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间表上有机动，改起来很方便。", "target_word": "机动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "机动性", "label": "复合"}, {"form": "機動", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "计划、安排中可灵活调整的余地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机动", "is_correct": true, "explanation": "正确：“留一些……以应对突发情况”指行程中留出可调整的余地，“机动”符合语境。"}, {"text": "集体", "is_correct": false, "explanation": "语义：“留一些集体”不通，集体指一群人，不能被留出。"}, {"text": "公共", "is_correct": false, "explanation": "语义：“公共”形容事物归大家所有，不能被留出，句意不通。"}, {"text": "社会", "is_correct": false, "explanation": "搭配：“社会”不能作“留”的对象，“留一些社会”不成立。"}], "explanations": {"机动": "正确：“留一些……以应对突发情况”指行程中留出可调整的余地，“机动”符合语境。", "集体": "语义：“留一些集体”不通，集体指一群人，不能被留出。", "公共": "语义：“公共”形容事物归大家所有，不能被留出，句意不通。", "社会": "搭配：“社会”不能作“留”的对象，“留一些社会”不成立。"}, "sentence_index": 0, "correct_answer": "机动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事没有商量的机动。", "explanation": "这里应该用〈余地〉。“没有……的余地”是固定说法，“机动”指计划、安排中可调整的部分，不能用于商量。"}, {"text": "这份合同的条款很有机动。", "explanation": "这里应该用〈弹性〉。合同、条款等制度的伸缩余地说“有弹性”，“机动”多指计划、安排中可随时调整的部分。"}, {"text": "这个方案缺少一辆机动，很难调整。", "explanation": "量词错误：“机动”是抽象名词，不能用〈辆〉（车辆的量词）计量，应说〈一点机动〉或〈一些机动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机动", "is_correct": true, "explanation": "正确：“没有一点机动”指计划中一点可调整的余地都没有，与“很死板”相呼应。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：计划不能说“没有噪音”，“噪音”与计划的死板程度无关，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：计划不具有年龄，“没有一点年龄”与前句“很死板”无法衔接。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能用来形容计划，“计划没有体重”不成立。"}], "explanations": {"机动": "正确：“没有一点机动”指计划中一点可调整的余地都没有，与“很死板”相呼应。", "噪音": "语义：计划不能说“没有噪音”，“噪音”与计划的死板程度无关，句意不通。", "年龄": "语义：计划不具有年龄，“没有一点年龄”与前句“很死板”无法衔接。", "体重": "搭配：“体重”不能用来形容计划，“计划没有体重”不成立。"}, "sentence_index": 6, "correct_answer": "机动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目还有很大的发展机动。", "explanation": "这里应该用〈空间〉。“发展空间”指可以发展的余地，“机动”指计划、安排中可调整的部分，不说“发展机动”。"}, {"text": "这套流程的机动请了三天假。", "explanation": "搭配：“请假”的主语应是人，“机动”指计划、安排中可调整的余地，不能请假。"}, {"text": "路上的机动比自行车多。", "explanation": "这里的“机动”指以发动机为动力的车辆（即机动车），但不能单独作名词指车辆，与句中计划安排的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们给计划留一块机动。", "corrected_sentence": "我们给计划留一些机动。", "error_description": "错误：“机动”是抽象名词，不能用“块”计量；应说“一些机动”或“一点机动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份计划是一些机动。", "corrected_sentence": "这份计划有一些机动。", "error_description": "错误：“机动”作名词表示可调整的余地，应与动词“有”搭配，不能用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11712, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
