INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们为了通勤等目的使用交通工具移动的行为", "primary_collocate": null, "pronunciation": "chū xíng", "ipa": "ʈʂʰu˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "如果越来越多的人选择地铁和公交上班，私人机动化出行模式就会减少，城市的污染也会随之减轻。", "target_word": "出行", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "研究发现，公共交通便利社区的居民，日均机动车出行次数比传统社区少四成，骑车和步行等绿色出行的比例则明显上升。", "target_word": "出行", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "现在很多城市的出行方式越来越多样。", "target_word": "出行", "complexity_tier": "T3", "furigana": "xiàn zài hěn duō chéng shì de chū xíng fāng shì yuè lái yuè duō yàng", "sentence_source": "generated"}, {"text": "地铁让上班族的出行更方便。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿色出行对环境有好处。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天的出行时间要一个小时。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早高峰的出行人数特别多。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司鼓励大家低碳出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的日常出行主要靠公交。", "target_word": "出行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车是很好的短途出行方式。", "target_word": "出行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出行方式", "label": "复合"}, {"form": "绿色出行", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：人们为通勤等目的使用交通工具移动的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出行", "is_correct": true, "explanation": "正确答案：“机动化出行模式”指人们以机动方式出门移动的模式，与通勤主题相合。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“私人机动化饮食模式”语义不通，饮食与交通方式无关。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“机动化”不能修饰语言，语义不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“机动化玩意儿模式”不成义，“玩意儿”不能修饰“模式”，且偏口语。"}], "explanations": {"出行": "正确答案：“机动化出行模式”指人们以机动方式出门移动的模式，与通勤主题相合。", "饮食": "语义：“私人机动化饮食模式”语义不通，饮食与交通方式无关。", "语言": "语义：“机动化”不能修饰语言，语义不通。", "玩意儿": "语义：“机动化玩意儿模式”不成义，“玩意儿”不能修饰“模式”，且偏口语。"}, "sentence_index": 0, "correct_answer": "出行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地铁是一种很好的出行。", "explanation": "这里应该用〈交通工具〉。出行指人的移动行为，不能指可以乘坐的工具。"}, {"text": "地铁让上班族的一只出行更方便。", "explanation": "这里是量词错误：出行的量词应用“次”，“只”用于动物或成对的东西。"}, {"text": "早高峰时，地铁站里的出行很大。", "explanation": "这里应该用〈人流〉。出行是个人的移动行为，不能用来形容地铁站里人多的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出行", "is_correct": true, "explanation": "正确答案：“早高峰的出行人数”指早高峰时出门移动的人数，语义通顺。"}, {"text": "饮水", "is_correct": false, "explanation": "语义：“饮水”指喝水，不能用来计算早高峰的人数。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：“草坪”不是人群，不能说“草坪人数”。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“人数”不与“花园”这类场所名词搭配。"}], "explanations": {"出行": "正确答案：“早高峰的出行人数”指早高峰时出门移动的人数，语义通顺。", "饮水": "语义：“饮水”指喝水，不能用来计算早高峰的人数。", "草坪": "语义：“草坪”不是人群，不能说“草坪人数”。", "花园": "搭配：“人数”不与“花园”这类场所名词搭配。"}, "sentence_index": 6, "correct_answer": "出行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们买了两张出行。", "explanation": "这里应该用〈车票〉。出行是移动的行为，不能用量词“张”来计量或购买。"}, {"text": "骑自行车是一台很好的短途出行。", "explanation": "这里是量词错误：“台”用于机器，出行的量词应用“次”。"}, {"text": "这条路的出行很平。", "explanation": "这里应该用〈路面〉。路面指道路的表面，出行指人的移动行为，不能用来形容路面平不平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天上班都要一只长距离出行。", "corrected_sentence": "他每天上班都要一次长距离出行。", "error_description": "错误形式：“一只长距离出行”；正确形式：“一次长距离出行”。出行的量词应为“次”，“只”用于动物或成对的东西，不能用来计量出行。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一块低碳出行让城市的空气更干净。", "corrected_sentence": "一次低碳出行让城市的空气更干净。", "error_description": "错误形式：“一块低碳出行”；正确形式：“一次低碳出行”。出行的量词应为“次”，“块”不用于出行。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
