INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11715, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11715, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像锁链一样一环扣一环、相互关联的；也指同一品牌统一经营的多家店铺。", "primary_collocate": null, "pronunciation": "lián suǒ", "ipa": "ljɛn˧˥ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "当个体选择地铁、公交或共享轨道交通作为日常通勤的主要载体，其行为本质上构成对私人机动化出行模式的系统性替代，由此引发的连锁效应深刻重塑了城市的污染谱系。", "target_word": "连锁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "连锁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一场大雨引起了连锁反应。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家附近新开了一家连锁超市。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小错误可能引起连锁反应。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家连锁餐厅在全国有两百家店。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油价上涨产生了连锁效应。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一家连锁酒店当经理。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌的连锁店遍布全国。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多米诺骨牌一倒，就会产生连锁反应。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連鎖", "label": "繁体"}, {"form": "连锁店", "label": "复合"}, {"form": "连锁反应", "label": "复合"}], "register": "中性", "sense_fingerprint": "一环扣一环地相互关联的；同一品牌统一经营的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静止", "is_correct": false, "explanation": "语义：“静止”指不动，与“由此引发”的一连串效应相悖。"}, {"text": "连锁", "is_correct": true, "explanation": "连锁：环环相扣的，修饰“效应”，与“由此引发”的句意相合。"}, {"text": "孤立", "is_correct": false, "explanation": "语义：“孤立”指彼此不相关联，与“由此引发”的因果关系相悖。"}, {"text": "紧急", "is_correct": false, "explanation": "搭配：“紧急”多修饰事件、措施，不说“紧急效应”。"}], "explanations": {"静止": "语义：“静止”指不动，与“由此引发”的一连串效应相悖。", "连锁": "连锁：环环相扣的，修饰“效应”，与“由此引发”的句意相合。", "孤立": "语义：“孤立”指彼此不相关联，与“由此引发”的因果关系相悖。", "紧急": "搭配：“紧急”多修饰事件、措施，不说“紧急效应”。"}, "sentence_index": 0, "correct_answer": "连锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条连锁很结实，拉不断。", "explanation": "这里应该用〈锁链〉。连锁作形容词，指环环相扣或多店统一经营，不指具体的链条，应说锁链。"}, {"text": "他买了一本连锁画，讲的是三国故事。", "explanation": "这里应该用〈连环画〉。连锁指环环相扣或多店统一经营，成套的图画书应说连环画。"}, {"text": "他用连锁把门锁着。", "explanation": "这里应该用〈锁链〉。连锁指环环相扣或多店统一经营，用来锁门的链条应说锁链。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静止", "is_correct": false, "explanation": "语义：“静止”与“油价上涨”所引发的动态影响相悖。"}, {"text": "连锁", "is_correct": true, "explanation": "连锁：环环相扣的，修饰“效应”，与“油价上涨产生”的句意相合。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”修饰地域、空间，不修饰“效应”。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”修饰颜色或外观，不修饰“效应”。"}], "explanations": {"静止": "语义：“静止”与“油价上涨”所引发的动态影响相悖。", "连锁": "连锁：环环相扣的，修饰“效应”，与“油价上涨产生”的句意相合。", "辽阔": "搭配：“辽阔”修饰地域、空间，不修饰“效应”。", "雪白": "搭配：“雪白”修饰颜色或外观，不修饰“效应”。"}, "sentence_index": 6, "correct_answer": "连锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一条连锁，挂在脖子上。", "explanation": "这里应该用〈链子〉。连锁指环环相扣或多店统一经营，首饰上的细链应说链子。"}, {"text": "这条管道的连锁很牢固，不会漏水。", "explanation": "这里应该用〈接口〉。连锁指环环相扣或多店统一经营，管道的连接处应说接口。"}, {"text": "他们俩的连锁很深厚。", "explanation": "这里应该用〈交情〉。连锁指环环相扣或多店统一经营，人与人之间深厚的感情应说交情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一次停电引起了连锁反映。", "corrected_sentence": "一次停电引起了连锁反应。", "error_description": "用字错误：应说“连锁反应”，不说“连锁反映”；“反映”指把情况或意见告知他人，与指一环接一环的“反应”不同。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴雨过后，交通瘫痪引起了连锁了效应。", "corrected_sentence": "暴雨过后，交通瘫痪引起了连锁效应。", "error_description": "体标误用：“了”不能插在修饰语“连锁”与中心语“效应”之间；去掉“了”即为正确句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
