INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某种现象中不同类型或程度的分布情况", "primary_collocate": null, "pronunciation": "pǔ xì", "ipa": "pʰu²¹⁴ ɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "当个体选择地铁、公交或共享轨道交通作为日常通勤的主要载体，其行为本质上构成对私人机动化出行模式的系统性替代，由此引发的连锁效应深刻重塑了城市的污染谱系。", "target_word": "谱系", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市的污染谱系正在变化。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告分析了河水里污染的谱系。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的菜品口味谱系很宽，从清淡到麻辣都有。", "target_word": "谱系", "complexity_tier": "T3", "furigana": "zhè jiā cān tīng de cài pǐn kǒu wèi pǔ xì hěn kuān, cóng qīng dàn dào má là dōu yǒu。", "sentence_source": "generated"}, {"text": "这个楼盘的户型谱系很宽，从一居到五居都有。", "target_word": "谱系", "complexity_tier": "T3", "furigana": "zhè ge lóu pán de hù xíng pǔ xì hěn kuān, cóng yī jū dào wǔ jū dōu yǒu。", "sentence_source": "generated"}, {"text": "地铁多了以后，污染谱系有了变化。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的房价谱系很宽，从郊区到市中心都有。", "target_word": "谱系", "complexity_tier": "T3", "furigana": "zhè ge chéng shì de fáng jià pǔ xì hěn kuān, cóng jiāo qū dào shì zhōng xīn dōu yǒu。", "sentence_source": "generated"}, {"text": "城市的气味谱系，从花香到汽油味都有。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家茶庄的产品从绿茶到红茶，形成了完整的谱系。", "target_word": "谱系", "complexity_tier": "T3", "furigana": "zhè jiā chá zhuāng de chǎn pǐn cóng lǜ chá dào hóng chá, xíng chéng le wán zhěng de pǔ xì。", "sentence_source": "generated"}, {"text": "这家公司的产品价格谱系很宽。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "譜系", "label": "繁体"}, {"form": "谱系图", "label": "复合"}], "register": "书面", "sense_fingerprint": "谱系：某种现象中不同类型或程度的分布情况（如污染谱系）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11717, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谱系", "is_correct": true, "explanation": "谱系：某种现象中不同类型或程度的分布情况，如污染谱系。"}, {"text": "辅系", "is_correct": false, "explanation": "fǔ xì：声母 f 与 p 不同，声调相同，意为大学里的辅修专业。"}, {"text": "普世", "is_correct": false, "explanation": "pǔ shì：声母 sh 与 x 不同，声调相同，意为普遍适用于所有人。"}, {"text": "补习", "is_correct": false, "explanation": "bǔ 与 pǔ 声母不同，xí（第二声）与 xì（第四声）声调不同，意思是为补充功课而学习。"}], "explanations": {"谱系": "谱系：某种现象中不同类型或程度的分布情况，如污染谱系。", "辅系": "fǔ xì：声母 f 与 p 不同，声调相同，意为大学里的辅修专业。", "普世": "pǔ shì：声母 sh 与 x 不同，声调相同，意为普遍适用于所有人。", "补习": "bǔ 与 pǔ 声母不同，xí（第二声）与 xì（第四声）声调不同，意思是为补充功课而学习。"}, "sentence_index": null, "correct_answer": "谱系"}, "level_3": {"options": [{"text": "谱系", "is_correct": true, "explanation": "正确：“污染谱系”指城市污染在各类型、程度上的分布，与“污染”搭配。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：“乐曲”是音乐作品，城市的污染不是乐曲，句子意思不通。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”指文字的书写形式，与污染无关，放入句中不通。"}, {"text": "作风", "is_correct": false, "explanation": "搭配：“作风”指人的行为习惯，不能与“污染”组合。"}], "explanations": {"谱系": "正确：“污染谱系”指城市污染在各类型、程度上的分布，与“污染”搭配。", "乐曲": "语义：“乐曲”是音乐作品，城市的污染不是乐曲，句子意思不通。", "字体": "语义：“字体”指文字的书写形式，与污染无关，放入句中不通。", "作风": "搭配：“作风”指人的行为习惯，不能与“污染”组合。"}, "sentence_index": 0, "correct_answer": "谱系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班上的谱系贴在墙上。", "explanation": "这里应该用〈名单〉。谱系指某种现象中不同类型或程度的分布，不指班级人员的名单；贴在墙上的人员列表要用“名单”。"}, {"text": "信封上写着收件人的谱系。", "explanation": "这里应该用〈地址〉。谱系指某种现象中不同类型或程度的分布，不指收件地点；信封上写的收件地点要用“地址”。"}, {"text": "院子里有一个大谱系。", "explanation": "这里应该用〈大树〉。谱系是抽象的分布情况，不是可以放在院子里的植物；“院子里有一棵大树”要用“大树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谱系", "is_correct": true, "explanation": "正确：“房价谱系”指房价在各档次上的分布，与“很宽”“从郊区到市中心”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物身体的温度，与房价无关，句子意思不通。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”是地方性的语言变体，房价不是方言，搭配不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这种书面描述的语体不合。"}], "explanations": {"谱系": "正确：“房价谱系”指房价在各档次上的分布，与“很宽”“从郊区到市中心”相符。", "体温": "语义：“体温”指人或动物身体的温度，与房价无关，句子意思不通。", "方言": "语义：“方言”是地方性的语言变体，房价不是方言，搭配不通。", "玩意儿": "语域：“玩意儿”是口语说法，与这种书面描述的语体不合。"}, "sentence_index": 6, "correct_answer": "谱系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的谱系很宽，从开幕到闭幕都有。", "explanation": "这里应该用〈议程〉。谱系指某种现象中不同类型或程度的分布，不指会议的安排；会议的安排要用“议程”。"}, {"text": "老师在谱系里批改了作业。", "explanation": "这里应该用〈本子〉。谱系指某种现象中不同类型或程度的分布，不是可以批改作业的地方；批改作业要在“本子”上进行。"}, {"text": "这个谱系很陡，上坡时很费力。", "explanation": "这里应该用〈坡〉。谱系指某种现象中不同类型或程度的分布，不是地形；“陡”和“上坡”说的是坡，要用“坡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者把城市的污染看成一位谱系。", "corrected_sentence": "研究者把城市的污染看成一个谱系。", "error_description": "量词用错：「位」用于人，不用于抽象的谱系；「谱系」指分布情况，应用「个」，应改为「一个谱系」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告按时间整理了这座城市地污染谱系。", "corrected_sentence": "这份报告按时间整理了这座城市的污染谱系。", "error_description": "修饰名词要用「的」，不能用「地」。「地」用于修饰动词、形容词，这里修饰名词「污染谱系」，应写成「城市的污染谱系」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
