INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "燃油是用于发动机或加热设备的液体燃料，如汽油、柴油等。", "primary_collocate": null, "pronunciation": "rán yóu", "ipa": "ɻan˧˥ joʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "汽车需要燃油才能行驶。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "最近燃油价格又上涨了。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车每百公里用八升燃油。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加油站出售不同种类的燃油。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "燃油是发动机的能量来源。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船上的燃油快用完了。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞前要加满燃油。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "燃油燃烧时会产生废气。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机想办法节省燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台锅炉使用的燃油是柴油。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃油车", "label": "复合"}, {"form": "燃油费", "label": "复合"}], "register": "中性", "sense_fingerprint": "发动机、加热设备所用的汽油、柴油等液体燃料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃油", "is_correct": true, "explanation": "正确：汽车靠燃油燃烧产生动力，“需要燃油才能行驶”符合常识。"}, {"text": "食物", "is_correct": false, "explanation": "语义：汽车不靠食物提供动力，“需要食物才能行驶”不成立。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料用于涂色，与汽车行驶无关，句意不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“行驶”需要的是能量，不能说需要钢铁才能行驶；钢铁用于制造汽车。"}], "explanations": {"燃油": "正确：汽车靠燃油燃烧产生动力，“需要燃油才能行驶”符合常识。", "食物": "语义：汽车不靠食物提供动力，“需要食物才能行驶”不成立。", "颜料": "语义：颜料用于涂色，与汽车行驶无关，句意不通。", "钢铁": "搭配：“行驶”需要的是能量，不能说需要钢铁才能行驶；钢铁用于制造汽车。"}, "sentence_index": 0, "correct_answer": "燃油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "煤是常用的燃油。", "explanation": "这里应该用〈燃料〉。煤是固体，“燃油”指汽油、柴油等液体燃料，不能说“煤是燃油”。"}, {"text": "妈妈用燃油炒菜。", "explanation": "这里应该用〈食用油〉。“燃油”是发动机、加热设备用的燃料，不用于烹饪，炒菜应说“食用油”。"}, {"text": "这辆车加了一块燃油。", "explanation": "量词错误：燃油是液体，应用〈升〉〈桶〉等计量，不能用〈块〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃油", "is_correct": true, "explanation": "正确：“加满燃油”指给飞机油箱加满燃料，符合起飞前的常识。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不能被“加满”，“加满”只用于油、水等液体或气体。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“加满”搭配液体或气体，不说“加满行李”，行李应说“装满”或“装好”。"}, {"text": "货物", "is_correct": false, "explanation": "搭配：“加满”不用于货物，货物应说“装满”或“装载”。"}], "explanations": {"燃油": "正确：“加满燃油”指给飞机油箱加满燃料，符合起飞前的常识。", "乘客": "语义：乘客不能被“加满”，“加满”只用于油、水等液体或气体。", "行李": "搭配：“加满”搭配液体或气体，不说“加满行李”，行李应说“装满”或“装好”。", "货物": "搭配：“加满”不用于货物，货物应说“装满”或“装载”。"}, "sentence_index": 6, "correct_answer": "燃油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的轴承需要加燃油。", "explanation": "这里应该用〈润滑油〉。轴承需要润滑，燃油只为发动机、加热设备提供燃烧能量，不用于润滑。"}, {"text": "工人在墙上刷了燃油。", "explanation": "这里应该用〈油漆〉。墙面用油漆涂刷，燃油是燃烧用的液体燃料，不能用于涂刷。"}, {"text": "医院用燃油给手术器械消毒。", "explanation": "这里应该用〈酒精〉。器械消毒要用“酒精”等消毒剂，“燃油”是发动机、加热设备用的液体燃料，不能用于消毒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一个燃油。", "corrected_sentence": "他买了一桶燃油。", "error_description": "错误：燃油是液体，量词应用“桶”“升”等，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机把燃油满加了。", "corrected_sentence": "司机把燃油加满了。", "error_description": "错误：结果补语“满”应紧跟动词，应说“加满”，不能说“满加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
