INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指机器或设备开始工作和停止工作的操作。", "primary_collocate": null, "pronunciation": "qǐ tíng", "ipa": "tɕʰi˨˩˦ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "启停", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这辆车的启停很灵敏，红灯时会自动熄火。", "target_word": "启停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "频繁启停会让电机很快变热。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器启停时，电流会突然变大。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红灯时，发动机的启停全由电脑控制。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风扇的启停要靠这个开关来控制。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水泵的启停要由专人负责。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的启停太频繁了，容易坏。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调启停时声音很小，晚上听不到。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯的启停不平稳，乘客会不舒服。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "启停系统", "label": "复合"}, {"form": "啟停", "label": "繁体"}], "register": "科技", "sense_fingerprint": "机器设备开始和停止工作的操作（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启停", "is_correct": true, "explanation": "正确。“频繁启停”指机器反复启动和停止，与“怠速运行”一起构成排放来源。"}, {"text": "充电", "is_correct": false, "explanation": "语义：充电不产生尾气，与前文“氮氧化物、颗粒物”的排放语境不符。"}, {"text": "修车", "is_correct": false, "explanation": "语义：修车不是汽车运行的状态，无法与“怠速运行”并列描述排放。"}, {"text": "洗车", "is_correct": false, "explanation": "搭配：“频繁洗车”不能与“怠速运行”并列，作为排放来源说不通。"}], "explanations": {"启停": "正确。“频繁启停”指机器反复启动和停止，与“怠速运行”一起构成排放来源。", "充电": "语义：充电不产生尾气，与前文“氮氧化物、颗粒物”的排放语境不符。", "修车": "语义：修车不是汽车运行的状态，无法与“怠速运行”并列描述排放。", "洗车": "搭配：“频繁洗车”不能与“怠速运行”并列，作为排放来源说不通。"}, "sentence_index": 0, "correct_answer": "启停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的启停是220伏。", "explanation": "这里应该用〈电压〉。启停指机器开始和停止工作的操作，不表示电压的高低。"}, {"text": "这台电机的启停很甜，孩子们都爱吃。", "explanation": "这里应该用〈糖果〉。启停指机器开始和停止工作的操作，不能吃，也没有甜味。"}, {"text": "这台机器的启停很有礼貌，见人就点头。", "explanation": "这里应该用〈服务员〉。启停指机器开始和停止工作的操作，不会有礼貌，也不会点头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启停", "is_correct": true, "explanation": "正确。“启停要由专人负责”指水泵的开关操作需要有人管理。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是需要人负责的操作，与水泵的启停无关。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“负责”一般搭配工作、事务，“重量”不能由人负责。"}, {"text": "味道", "is_correct": false, "explanation": "语义：水泵没有需要专人负责的味道，句意不通。"}], "explanations": {"启停": "正确。“启停要由专人负责”指水泵的开关操作需要有人管理。", "颜色": "语义：“颜色”不是需要人负责的操作，与水泵的启停无关。", "重量": "搭配：“负责”一般搭配工作、事务，“重量”不能由人负责。", "味道": "语义：水泵没有需要专人负责的味道，句意不通。"}, "sentence_index": 6, "correct_answer": "启停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电梯的启停有三层楼那么高。", "explanation": "这里应该用〈行程〉。启停指开始和停止工作的操作，不表示电梯上下的距离。"}, {"text": "电梯的启停每分钟上升三层。", "explanation": "这里应该用〈速度〉。启停指开始和停止工作的操作，不表示电梯运行的速度。"}, {"text": "这个启停很爱笑，每天都请客人喝茶。", "explanation": "这里应该用〈老板〉。启停指机器开始和停止工作的操作，不会笑，也不会请客人喝茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电机得启停很安静。", "corrected_sentence": "这台电机的启停很安静。", "error_description": "“得”误用：“电机”与“启停”之间应用结构助词“的”，应说“这台电机的启停很安静”，不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电梯今天启停着三次。", "corrected_sentence": "电梯今天启停了三次。", "error_description": "体标错误：“启停”指已经发生的几次动作，应用“了”，不能用“着”，应说“启停了三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
