INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11720, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指发动机在空转状态下不加油门时的最低稳定转速。", "primary_collocate": null, "pronunciation": "dài sù", "ipa": "taɪ̯˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "怠速", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "发动机不踩油门时的转速叫怠速。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车的怠速有点高，停着也很响。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷车时，发动机的怠速会比平时高一些。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅说，怠速不稳是火花塞的问题。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台发动机不踩油门时，怠速是八百转。", "target_word": "怠速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车一直抖，我觉得是怠速太低了。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修车师傅把怠速调高了一点。", "target_word": "怠速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开空调以后，怠速会自动升高。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车的怠速很平稳，几乎没有声音。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怠速运转", "label": "复合"}], "register": "科技", "sense_fingerprint": "发动机不踩油门时的最低稳定转速（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怠速", "is_correct": true, "explanation": "正确答案，指发动机不踩油门时的最低稳定转速。"}, {"text": "代数", "is_correct": false, "explanation": "shù（第四声）与 sù（第四声）声母不同：sh 与 s，意思是代数。"}, {"text": "待续", "is_correct": false, "explanation": "xù（第四声）与 sù（第四声）声母不同：x 与 s，意思是待续。"}, {"text": "代付", "is_correct": false, "explanation": "fù（第四声）与 sù（第四声）声母不同：f 与 s，意思是代为付款。"}, {"text": "带路", "is_correct": false, "explanation": "lù（第四声）与 sù（第四声）声母不同：l 与 s，意思是带领道路。"}], "explanations": {"怠速": "正确答案，指发动机不踩油门时的最低稳定转速。", "代数": "shù（第四声）与 sù（第四声）声母不同：sh 与 s，意思是代数。", "待续": "xù（第四声）与 sù（第四声）声母不同：x 与 s，意思是待续。", "代付": "fù（第四声）与 sù（第四声）声母不同：f 与 s，意思是代为付款。", "带路": "lù（第四声）与 sù（第四声）声母不同：l 与 s，意思是带领道路。"}, "sentence_index": null, "correct_answer": "怠速"}, "level_3": {"options": [{"text": "怠速", "is_correct": true, "explanation": "正确。“怠速运行”指发动机不踩油门时的空转，与“频繁启停”一起说明车辆停车时的排放来源。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”是买东西的行为，不是汽车的运行状态，与排放来源无关。"}, {"text": "打气", "is_correct": false, "explanation": "语义：“打气”是给轮胎充气，不产生尾气，与“怠速运行”的排放语境无关。"}, {"text": "校对", "is_correct": false, "explanation": "语义：“校对”是核对文字的工作，与汽车排放无关，句子不通。"}], "explanations": {"怠速": "正确。“怠速运行”指发动机不踩油门时的空转，与“频繁启停”一起说明车辆停车时的排放来源。", "购买": "语义：“购买”是买东西的行为，不是汽车的运行状态，与排放来源无关。", "打气": "语义：“打气”是给轮胎充气，不产生尾气，与“怠速运行”的排放语境无关。", "校对": "语义：“校对”是核对文字的工作，与汽车排放无关，句子不通。"}, "sentence_index": 0, "correct_answer": "怠速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的怠速达到了每分钟六千转。", "explanation": "这里应该用〈转速〉。怠速指不踩油门时的最低稳定转速，不能用来形容高转速。"}, {"text": "车轮在泥里怠速，怎么也出不去。", "explanation": "这里应该用〈空转〉。怠速只指发动机的运转状态，车轮空转要说“空转”。"}, {"text": "这辆车的怠速最高能到每小时两百公里。", "explanation": "这里应该用〈极速〉。怠速指空转时的最低稳定转速，不指车子能达到的最高速度，应说“极速”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怠速", "is_correct": true, "explanation": "正确。“怠速太低”指空转转速过低，容易让发动机抖动。"}, {"text": "火花塞", "is_correct": false, "explanation": "搭配：“太低了”只说转速、温度等数值，不能说零件的高低。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离与车子抖动的原因无关，且“距离太低”不成立。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：要说“空调温度太低”，不能直接说“空调太低”。"}], "explanations": {"怠速": "正确。“怠速太低”指空转转速过低，容易让发动机抖动。", "火花塞": "搭配：“太低了”只说转速、温度等数值，不能说零件的高低。", "距离": "语义：距离与车子抖动的原因无关，且“距离太低”不成立。", "空调": "搭配：要说“空调温度太低”，不能直接说“空调太低”。"}, "sentence_index": 6, "correct_answer": "怠速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台发动机的怠速是三升，马力很强。", "explanation": "这里应该用〈排量〉。怠速指空转时的最低稳定转速，不表示发动机的容积，应说“排量”。"}, {"text": "这辆车的怠速很大，能装下五个人。", "explanation": "这里应该用〈空间〉。怠速指空转时的最低稳定转速，不表示车内的容量，应说“空间”。"}, {"text": "熄火以后，车子还在怠速。", "explanation": "这里应该用〈滑行〉。熄火后发动机已停止工作，不能再说“怠速”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修车师傅把怠速调了低一点。", "corrected_sentence": "修车师傅把怠速调低了一点。", "error_description": "补语位置错误：“把”字句中补语应紧跟动词，应说“调低了一点”，不能说“调了低一点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卡车地怠速很高，邻居都嫌吵。", "corrected_sentence": "卡车的怠速很高，邻居都嫌吵。", "error_description": "“的”误用为“地”：“怠速”是名词，前面的定语应用“的”，不能用“地”，应说“卡车的怠速很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
