INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11721, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氮氧化物是氮和氧组成的化合物，常见于汽车尾气和工业废气，会污染空气并形成酸雨。", "primary_collocate": null, "pronunciation": "dàn yǎng huà wù", "ipa": "tan˥˩ jaŋ˨˩˦ xua˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "氮氧化物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "汽车尾气里有氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮氧化物会污染空气。", "target_word": "氮氧化物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂排出的氮氧化物，会形成酸雨。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市空气里的氮氧化物越来越少。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车安装了装置，能减少氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮氧化物是一种有害的气体。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家正在检测河边空气中的氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气中的氮氧化物太多，容易形成雾霾。", "target_word": "氮氧化物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车不排放氮氧化物，更干净。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种氮氧化物", "label": "量词"}], "register": "科技", "sense_fingerprint": "氮和氧组成的化合物，来自尾气和废气，污染空气、形成酸雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11721, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "氮氧化物", "is_correct": true, "explanation": "正确：氮氧化物是尾气中排出的有害化合物，可以被“释放”，与句中的颗粒物、挥发性有机化合物并列。"}, {"text": "电动车", "is_correct": false, "explanation": "语义：电动车是交通工具，不是被释放的排放物，“释放的……”后接的应当是物质。"}, {"text": "空气质量", "is_correct": false, "explanation": "搭配：“释放”后接的是污染物质，不能接“空气质量”这种状态，句子不通。"}, {"text": "公共交通", "is_correct": false, "explanation": "语义：公共交通是一种服务网络，不是可以被释放的物质，与句中“稀释排放”的语境不符。"}], "explanations": {"氮氧化物": "正确：氮氧化物是尾气中排出的有害化合物，可以被“释放”，与句中的颗粒物、挥发性有机化合物并列。", "电动车": "语义：电动车是交通工具，不是被释放的排放物，“释放的……”后接的应当是物质。", "空气质量": "搭配：“释放”后接的是污染物质，不能接“空气质量”这种状态，句子不通。", "公共交通": "语义：公共交通是一种服务网络，不是可以被释放的物质，与句中“稀释排放”的语境不符。"}, "sentence_index": 0, "correct_answer": "氮氧化物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在田里撒了很多氮氧化物，庄稼就长得更好。", "explanation": "这里应该用〈化肥〉。撒到田里能让庄稼长得好的是化肥；氮氧化物是有害的污染物，不能用来施肥。"}, {"text": "每天早上，我都深深地呼吸氮氧化物。", "explanation": "这里应该用〈氧气〉。“呼吸”的对象是氧气或空气，氮氧化物是有害的污染物，人不能这样呼吸它。"}, {"text": "这种氮氧化物很甜，孩子都爱吃。", "explanation": "这里应该用〈糖〉。糖才会很甜、适合给孩子吃；氮氧化物是有害气体，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "氮氧化物", "is_correct": true, "explanation": "正确：氮氧化物是一种有害的气体，与“有害”“气体”都相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不是有害气体，与“有害”的描述相矛盾。"}, {"text": "颗粒物", "is_correct": false, "explanation": "搭配：“一种……的气体”不能修饰颗粒物，颗粒物是固体或液体微粒。"}, {"text": "酸雨", "is_correct": false, "explanation": "语义：酸雨是降落到地面的液态降水，不是气体，句中“气体”的说法不成立。"}], "explanations": {"氮氧化物": "正确：氮氧化物是一种有害的气体，与“有害”“气体”都相符。", "蔬菜": "语义：蔬菜是食物，不是有害气体，与“有害”的描述相矛盾。", "颗粒物": "搭配：“一种……的气体”不能修饰颗粒物，颗粒物是固体或液体微粒。", "酸雨": "语义：酸雨是降落到地面的液态降水，不是气体，句中“气体”的说法不成立。"}, "sentence_index": 6, "correct_answer": "氮氧化物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里用氮氧化物做饭。", "explanation": "这里应该用〈天然气〉。做饭要用可燃的天然气；氮氧化物是有害的污染物，不能用来燃烧做饭。"}, {"text": "冬天家里用氮氧化物取暖。", "explanation": "这里应该用〈煤〉。冬天取暖烧的是煤等燃料；氮氧化物是污染物，不能用来取暖。"}, {"text": "腌制食品时用了氮氧化物保鲜。", "explanation": "这里应该用〈亚硝酸盐〉。腌制食品时用的是亚硝酸盐这类添加剂；氮氧化物不能用来保鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车的尾气里含有一只氮氧化物。", "corrected_sentence": "这辆车的尾气里含有一种氮氧化物。", "error_description": "量词错误：氮氧化物是气体，应该用“种”计量，“只”用于动物等个体，不能修饰它。正确说法是“一种氮氧化物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂明年排放了大量氮氧化物。", "corrected_sentence": "工厂明年排放大量氮氧化物。", "error_description": "体标错误：“明年”指将来，“了”表示动作已完成，不能与将来时间搭配。应去掉“了”，说“明年排放大量氮氧化物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11722, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
