INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "颗粒物是指空气中非常细小的固体或液体微粒，比如灰尘、烟尘等。", "primary_collocate": null, "pronunciation": "kē lì wù", "ipa": "kʰɤ˥ li˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "颗粒物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天空气里的颗粒物很多，出门要戴口罩。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的颗粒物会让空气变脏。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颗粒物太小，我们用眼睛看不见。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，空气中的颗粒物少了很多。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，颗粒物进入肺里对身体不好。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以把空气里的颗粒物过滤掉。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天烧煤会产生很多颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里每天都要测量颗粒物的浓度。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车尾气里也有颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "细颗粒物", "label": "复合"}, {"form": "可吸入颗粒物", "label": "复合"}, {"form": "顆粒物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气中细小的固体或液体微粒，如灰尘、烟尘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颗粒物", "is_correct": true, "explanation": "正确：颗粒物是汽车排放的细小微粒，与句中的氮氧化物、有机化合物并列。"}, {"text": "电动车", "is_correct": false, "explanation": "语义：电动车是交通工具，不是被释放的排放物，与“释放的……”的搭配不符。"}, {"text": "空气质量", "is_correct": false, "explanation": "搭配：“释放”后接的是污染物质，不能接“空气质量”这种状态，句子不通。"}, {"text": "公共交通", "is_correct": false, "explanation": "语义：公共交通是服务网络，不是可以释放的物质，与句义冲突。"}], "explanations": {"颗粒物": "正确：颗粒物是汽车排放的细小微粒，与句中的氮氧化物、有机化合物并列。", "电动车": "语义：电动车是交通工具，不是被释放的排放物，与“释放的……”的搭配不符。", "空气质量": "搭配：“释放”后接的是污染物质，不能接“空气质量”这种状态，句子不通。", "公共交通": "语义：公共交通是服务网络，不是可以释放的物质，与句义冲突。"}, "sentence_index": 0, "correct_answer": "颗粒物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都用颗粒物刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙要用牙膏；颗粒物是空气中的微粒，不能用来刷牙。"}, {"text": "屋子里的颗粒物太厚，我一眼就能看见。", "explanation": "这里应该用〈灰尘〉。颗粒物细小、肉眼看不见，不能说“太厚，一眼就能看见”；灰尘才可以。"}, {"text": "草叶上结满了颗粒物。", "explanation": "这里应该用〈露水〉。“结”用于露、霜等，颗粒物是微粒，不会结成露水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颗粒物", "is_correct": true, "explanation": "正确：空气净化器可以过滤掉空气里的颗粒物，句义通顺。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是人需要的气体，机器不会把它从空气里过滤掉，句义不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不在空气里，“过滤掉蔬菜”与句中的语境不符。"}, {"text": "绿植", "is_correct": false, "explanation": "语义：绿植是植物，不会悬浮在空气里被过滤，句子不成立。"}], "explanations": {"颗粒物": "正确：空气净化器可以过滤掉空气里的颗粒物，句义通顺。", "氧气": "语义：氧气是人需要的气体，机器不会把它从空气里过滤掉，句义不通。", "蔬菜": "语义：蔬菜不在空气里，“过滤掉蔬菜”与句中的语境不符。", "绿植": "语义：绿植是植物，不会悬浮在空气里被过滤，句子不成立。"}, "sentence_index": 6, "correct_answer": "颗粒物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都喝一杯颗粒物。", "explanation": "这里应该用〈牛奶〉。颗粒物是空气中的微粒，不能喝。"}, {"text": "妈妈用颗粒物做了一碗面条。", "explanation": "这里应该用〈面粉〉。做面条要用面粉，颗粒物不是食材。"}, {"text": "这杯咖啡里加了两勺颗粒物。", "explanation": "这里应该用〈糖〉。咖啡里加的是糖或奶，颗粒物不能加入饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大风过后，街上的一只颗粒物飘走了。", "corrected_sentence": "大风过后，街上的一些颗粒物飘走了。", "error_description": "量词错误：颗粒物是许多细小微粒，应该用“些”，“只”用于动物等个体，不能修饰颗粒物。正确说法是“一些颗粒物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器昨天过滤掉着很多颗粒物。", "corrected_sentence": "这台机器昨天过滤掉了很多颗粒物。", "error_description": "体标错误：“昨天”发生的已完成动作要用“了”，“着”表示动作持续，不能用在这里。正确说法是“过滤掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
