INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11723, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物质在常温下能变成气态并扩散到空气中的性质。", "primary_collocate": null, "pronunciation": "huī fā xìng", "ipa": "xweɪ̯˥ fa˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "挥发性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "酒精的挥发性很强。", "target_word": "挥发性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汽油的挥发性比水大得多。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种油漆的挥发性很高，要开窗通风。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为挥发性强，香水要盖紧瓶盖。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的这瓶药水挥发性很强，要放在冷处。", "target_word": "挥发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的挥发性不强，所以杯里的水几天才会变少。", "target_word": "挥发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们比较几种液体的挥发性。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指甲油味道很重，是因为它的挥发性强。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度越高，物质的挥发性就越强。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挥发性有机物", "label": "复合"}, {"form": "揮發性", "label": "繁体"}], "register": "科技", "sense_fingerprint": "物质常温下变成气态扩散到空气中的性质（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挥发性", "is_correct": true, "explanation": "正确。“挥发性有机化合物”是固定说法，指容易挥发到空气中的有机物，与前文的污染物语境一致。"}, {"text": "导电性", "is_correct": false, "explanation": "语义：“导电性”说的是能否导电，与释放到空气中的污染物无关，句子意思不通。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”描述物体的外形，不是物质的化学性质，不能用来修饰“有机化合物”。"}, {"text": "延展性", "is_correct": false, "explanation": "搭配：“延展性”多用于金属等材料，不能用来修饰“有机化合物”。"}], "explanations": {"挥发性": "正确。“挥发性有机化合物”是固定说法，指容易挥发到空气中的有机物，与前文的污染物语境一致。", "导电性": "语义：“导电性”说的是能否导电，与释放到空气中的污染物无关，句子意思不通。", "形状": "语义：“形状”描述物体的外形，不是物质的化学性质，不能用来修饰“有机化合物”。", "延展性": "搭配：“延展性”多用于金属等材料，不能用来修饰“有机化合物”。"}, "sentence_index": 0, "correct_answer": "挥发性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种矿石的挥发性很高，不容易切割。", "explanation": "这里应该用〈硬度〉。切割难易取决于硬度，挥发性指变成气体的性质，与能否切割无关。"}, {"text": "这种锅的挥发性很好，煮饭很快。", "explanation": "这里应该用〈导热性〉。煮饭快是因为锅导热好，挥发性指变成气体的性质，与导热无关。"}, {"text": "他的挥发性很强，一生气就大声叫。", "explanation": "挥发性只用于物质，指常温下变成气体的性质，不能用来形容人的脾气，形容人应说〈脾气〉或〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挥发性", "is_correct": true, "explanation": "正确。“水的挥发性不强”说明水不易变成气体，与“杯里的水几天才会变少”的意思一致。"}, {"text": "弹性", "is_correct": false, "explanation": "语义：“弹性”描述物体受力后恢复原状的能力，水没有这种性质，句子不通。"}, {"text": "韧性", "is_correct": false, "explanation": "搭配：“韧性”用来形容材料不易折断，不能用来描述水的强弱。"}, {"text": "脆性", "is_correct": false, "explanation": "语义：“脆性”指物体易碎的性质，与水会慢慢变少的情况无关。"}], "explanations": {"挥发性": "正确。“水的挥发性不强”说明水不易变成气体，与“杯里的水几天才会变少”的意思一致。", "弹性": "语义：“弹性”描述物体受力后恢复原状的能力，水没有这种性质，句子不通。", "韧性": "搭配：“韧性”用来形容材料不易折断，不能用来描述水的强弱。", "脆性": "语义：“脆性”指物体易碎的性质，与水会慢慢变少的情况无关。"}, "sentence_index": 6, "correct_answer": "挥发性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种杀虫剂的挥发性很大，喝一口就会中毒。", "explanation": "这里应该用〈毒性〉。喝一口就中毒说明的是毒性，挥发性只指变成气体的性质。"}, {"text": "水的挥发性是一百摄氏度，烧开后要关火。", "explanation": "这里应该用〈沸点〉。一百摄氏度是水开始沸腾的温度，挥发性是性质，不能用温度数字来表示。"}, {"text": "这座山的挥发性很高，爬起来很累。", "explanation": "这里应该用〈坡度〉。挥发性指物质变成气体的性质，不能用来形容山的陡峭，应说“坡度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种溶剂地挥发性很强，要远离明火。", "corrected_sentence": "这种溶剂的挥发性很强，要远离明火。", "error_description": "错误形式：“溶剂地挥发性”，“地”用于修饰动词，修饰名词“挥发性”前应用“的”。正确形式：“溶剂的挥发性很强”，“的”连接名词与其修饰语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种香料油是挥发性，用完要盖紧。", "corrected_sentence": "这种香料油有挥发性，用完要盖紧。", "error_description": "错误形式：“是挥发性”，“是”用于判断，不能直接接表示性质的名词；表示物质具有某种性质应用“有”。正确形式：“有挥发性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
