INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由两种或两种以上不同元素组成的物质。", "primary_collocate": null, "pronunciation": "huà hé wù", "ipa": "xu̯a˥˩ xɤ˧˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "水是一种化合物。", "target_word": "化合物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "盐是由钠和氯组成的化合物。", "target_word": "化合物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种化合物很容易溶于水。", "target_word": "化合物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "二氧化碳是碳和氧组成的化合物。", "target_word": "化合物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，化合物由不同元素组成。", "target_word": "化合物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个瓶子里装着一种白色的化合物。", "target_word": "化合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们做实验，想知道这种化合物有没有毒。", "target_word": "化合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书上看过一种新的化合物。", "target_word": "化合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化合物和混合物不同，里面的元素很难分开。", "target_word": "化合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氧化镁是镁和氧燃烧后生成的化合物。", "target_word": "化合物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种化合物", "label": "量词"}, {"form": "有机化合物", "label": "复合"}, {"form": "无机化合物", "label": "复合"}], "register": "书面", "sense_fingerprint": "化学中由两种或以上元素组成的纯净物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化合物", "is_correct": true, "explanation": "正确。水是由氢和氧结合成的化合物，所以“水是一种化合物”成立。"}, {"text": "动物", "is_correct": false, "explanation": "语义：水不是动物，“水是一种动物”与事实不符，句子不通。"}, {"text": "金属", "is_correct": false, "explanation": "语义：水不是金属，“水是一种金属”与事实不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：水不是植物，“水是一种植物”与事实不符。"}], "explanations": {"化合物": "正确。水是由氢和氧结合成的化合物，所以“水是一种化合物”成立。", "动物": "语义：水不是动物，“水是一种动物”与事实不符，句子不通。", "金属": "语义：水不是金属，“水是一种金属”与事实不符。", "植物": "语义：水不是植物，“水是一种植物”与事实不符。"}, "sentence_index": 0, "correct_answer": "化合物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空气是由氮、氧等组成的化合物。", "explanation": "这里应该用〈混合物〉。空气中的各种气体只是混在一起，没有化学结合，不属于化合物。"}, {"text": "氧是一种化合物，在元素周期表中有编号。", "explanation": "这里应该用〈单质〉。氧只由一种元素组成，属于单质；化合物要由两种或两种以上不同元素组成。"}, {"text": "老师从柜子里拿出一种化合物，它会跑来跑去。", "explanation": "这里应该用〈动物〉。化合物是物质，不会跑来跑去，应说“动物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化合物", "is_correct": true, "explanation": "正确。做实验要检测的是化学物质有没有毒，化合物符合语境。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日不是可以做实验检测毒性的物质，“这种节日有没有毒”不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是物质，不能做实验检测有没有毒，句子不通。"}, {"text": "星座", "is_correct": false, "explanation": "语义：星座不是物质，不能通过实验检测有没有毒。"}], "explanations": {"化合物": "正确。做实验要检测的是化学物质有没有毒，化合物符合语境。", "节日": "语义：节日不是可以做实验检测毒性的物质，“这种节日有没有毒”不通。", "天气": "语义：天气不是物质，不能做实验检测有没有毒，句子不通。", "星座": "语义：星座不是物质，不能通过实验检测有没有毒。"}, "sentence_index": 6, "correct_answer": "化合物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "氧气是一种化合物，只由氧元素组成。", "explanation": "这里应该用〈单质〉。只由一种元素组成的物质叫单质，化合物要由两种或两种以上元素组成。"}, {"text": "糖水是糖溶解在水里形成的化合物。", "explanation": "这里应该用〈溶液〉。糖溶在水里只是混合在一起，没有化学结合，应说溶液。"}, {"text": "钢是铁和碳熔合成的化合物，比铁硬。", "explanation": "这里应该用〈合金〉。钢是金属与其他元素熔合成的合金，不是由化学结合形成的化合物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里有三只化合物。", "corrected_sentence": "实验室里有三种化合物。", "error_description": "错误形式：“化合物”是物质，量词应用“种”，不能用“只”。正确形式：“三种化合物”，“种”是表示物质种类的通用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家发现了一种新地化合物，很有用。", "corrected_sentence": "科学家发现了一种新的化合物，很有用。", "error_description": "错误形式：“新地化合物”，“地”用于修饰动词，修饰名词应用“的”。正确形式：“一种新的化合物”，“的”连接形容词与其所修饰的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
