INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雾霾是雾和霾的混合物，常见于城市，是一种空气污染现象，会降低能见度并危害健康。", "primary_collocate": null, "pronunciation": "wù mái", "ipa": "u˥˩ mai̯˧˥", "syllable_count": 2, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "雾霾", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天的雾霾很重。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京冬天常常有雾霾。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雾霾太大，天空灰蒙蒙的。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "因为雾霾，我们没去爬山。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，雾霾对身体不好。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出门的时候，请戴上口罩，因为外面有雾霾。", "target_word": "雾霾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂太多的城市，冬天常常有很重的雾霾。", "target_word": "雾霾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，雾霾就慢慢散了。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的雾霾让飞机晚点了。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场雾霾", "label": "量词"}, {"form": "雾霾天", "label": "复合"}], "register": "中性", "sense_fingerprint": "城市常见的由雾和霾混合形成的空气污染现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雾霾", "is_correct": true, "explanation": "正确：“城市雾霾”指空气污染现象，与“光化学烟雾”同属大气污染，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不是大气污染物或前体物，与“光化学烟雾”的形成无关，句意不通。"}, {"text": "雾气", "is_correct": false, "explanation": "语义：雾气是水汽凝结而成，不会参与光化学反应形成烟雾的前体过程。"}, {"text": "废水", "is_correct": false, "explanation": "搭配：“前体物”指参与大气反应的气态或颗粒态物质，“废水”是液态，不能构成前体关系。"}], "explanations": {"雾霾": "正确：“城市雾霾”指空气污染现象，与“光化学烟雾”同属大气污染，符合句意。", "课本": "语义：课本是书籍，不是大气污染物或前体物，与“光化学烟雾”的形成无关，句意不通。", "雾气": "语义：雾气是水汽凝结而成，不会参与光化学反应形成烟雾的前体过程。", "废水": "搭配：“前体物”指参与大气反应的气态或颗粒态物质，“废水”是液态，不能构成前体关系。"}, "sentence_index": 0, "correct_answer": "雾霾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们爬山时，在半路上遇到了一颗雾霾。", "explanation": "这里应该用〈场〉。〈颗〉用于颗粒状或圆形的小物体，雾霾是弥漫在大范围空气中的现象，应说“一场雾霾”。"}, {"text": "洗完澡，浴室里全是雾霾，什么也看不清。", "explanation": "这里应该用〈雾气〉。雾气是水汽遇冷凝成的小水滴，浴室里白茫茫的一片是雾气；雾霾是空气中的污染颗粒，不能用来指浴室里的水汽。"}, {"text": "路上扬起了很多雾霾，车都看不清了。", "explanation": "这里应该用〈尘土〉。尘土是被车或风扬起的土粒，雾霾是悬浮在空气中的污染，不能说“扬起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雾霾", "is_correct": true, "explanation": "正确：外面空气有污染，所以要戴口罩，“雾霾”符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会危害呼吸，不能作为戴口罩的理由。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与空气防护无关，不能说明戴口罩的原因。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“因为外面有……，请戴口罩”要求是危害呼吸的东西，“玩具”不能搭配这一句型。"}], "explanations": {"雾霾": "正确：外面空气有污染，所以要戴口罩，“雾霾”符合句意。", "蛋糕": "语义：蛋糕不会危害呼吸，不能作为戴口罩的理由。", "钢琴": "语义：钢琴与空气防护无关，不能说明戴口罩的原因。", "玩具": "搭配：“因为外面有……，请戴口罩”要求是危害呼吸的东西，“玩具”不能搭配这一句型。"}, "sentence_index": 6, "correct_answer": "雾霾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "远处的山上有一座雾霾，什么都看不见。", "explanation": "这里应该用〈场〉。〈座〉用于山、楼房等大型固定的物体，雾霾是弥漫的空气现象，应说“一场雾霾”。"}, {"text": "他在屋里抽烟，满屋子都是雾霾。", "explanation": "这里应该用〈烟〉。〈烟〉是香烟燃烧产生的烟雾，屋里抽烟后的烟气是烟，雾霾是大范围的空气污染，不能这样用。"}, {"text": "他用布把桌子上的雾霾擦掉了。", "explanation": "这里应该用〈灰尘〉。灰尘是落在物体表面的细小颗粒，可以用布擦掉；雾霾是悬浮在空气中的污染，不能这样擦掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条雾霾让我们很难受。", "corrected_sentence": "这场雾霾让我们很难受。", "error_description": "错误：“这条雾霾”，“条”用于细长的物体，雾霾应使用量词“场”。正确为“这场雾霾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天的一条雾霾让飞机晚点了。", "corrected_sentence": "昨天的一场雾霾让飞机晚点了。", "error_description": "错误：“一条雾霾”，“条”用于细长的物体，雾霾应使用量词“场”。正确为“一场雾霾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
