INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11727, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "光化学是化学的一个分支，研究物质在光照射下发生的化学反应。", "primary_collocate": null, "pronunciation": "guāng huà xué", "ipa": "kuaŋ˥ xu̯a˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "他大学毕业后专门研究光化学，每天在实验室里用紫外灯照射溶液。", "target_word": "光化学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光化学是化学的一部分。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥在大学学光化学。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光化学研究光和物质的变化。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是讲光化学的。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光化学需要用特别的灯做实验。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对光化学很感兴趣，周末常和同学讨论光照下的化学反应。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，光化学能解释植物为什么要晒太阳。", "target_word": "光化学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学过光化学的人都知道，光可以让化学反应开始。", "target_word": "光化学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光化学是化学的一个重要分支，很多人还不太了解。", "target_word": "光化学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光化学反应", "label": "复合"}, {"form": "光化学烟雾", "label": "复合"}], "register": "书面", "sense_fingerprint": "研究物质在光照下发生化学反应的化学分支", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光化学", "is_correct": true, "explanation": "正确：“专门研究光化学”，光化学研究光照下的化学反应，与“用紫外灯照射溶液”的实验相符。"}, {"text": "舞蹈", "is_correct": false, "explanation": "语义：舞蹈是艺术活动，与“每天在实验室里用紫外灯照射溶液”的研究对象不符，句意不通。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育是运动健身，不是研究溶液化学反应的学科，与实验室语境不符。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是艺术形式，不是研究紫外线照射下化学变化的学科，句意不通。"}], "explanations": {"光化学": "正确：“专门研究光化学”，光化学研究光照下的化学反应，与“用紫外灯照射溶液”的实验相符。", "舞蹈": "语义：舞蹈是艺术活动，与“每天在实验室里用紫外灯照射溶液”的研究对象不符，句意不通。", "体育": "语义：体育是运动健身，不是研究溶液化学反应的学科，与实验室语境不符。", "音乐": "语义：音乐是艺术形式，不是研究紫外线照射下化学变化的学科，句意不通。"}, "sentence_index": 0, "correct_answer": "光化学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科学家用光化学研究光的传播。", "explanation": "这里应该用〈光学〉。光学研究光的传播与性质，光化学研究光引起的化学反应，二者不能互换。"}, {"text": "我们学校新开了一只光化学课。", "explanation": "这里应该用〈门〉。〈只〉用于动物或成对物件中的一个，学科和课程应用〈门〉，应说“一门光化学课”。"}, {"text": "这种技术的原理属于光化学，它的主要作用是测量房间的温度。", "explanation": "这里应该用〈热学〉。测量温度依靠热量与物体状态的关系，属于热学；光化学研究光引起的化学变化，与温度测量无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光化学", "is_correct": true, "explanation": "正确：“对光化学很感兴趣”，光化学是化学的分支，与“讨论光照下的化学反应”相符，句意通顺。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“讨论光照下的化学反应”与蛋糕无关，句意不通。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：袜子与“讨论光照下的化学反应”不搭配，句意不通。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“对……很感兴趣”一般搭配学科、爱好，“厕所”不能与这一结构搭配。"}], "explanations": {"光化学": "正确：“对光化学很感兴趣”，光化学是化学的分支，与“讨论光照下的化学反应”相符，句意通顺。", "蛋糕": "语义：“讨论光照下的化学反应”与蛋糕无关，句意不通。", "袜子": "语义：袜子与“讨论光照下的化学反应”不搭配，句意不通。", "厕所": "搭配：“对……很感兴趣”一般搭配学科、爱好，“厕所”不能与这一结构搭配。"}, "sentence_index": 6, "correct_answer": "光化学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "光化学老师用杠杆讲解力的原理，同学们都听懂了。", "explanation": "这里应该用〈物理〉。杠杆和力的原理属于物理学，光化学只研究光引起的化学变化，不能讲解力学。"}, {"text": "窗外有一座光化学，挡住了视线。", "explanation": "这里应该用〈门〉。〈座〉用于山、楼房等大型固定物，光化学是学科，应说“一门光化学”。"}, {"text": "光化学课上老师讲解了一首古诗。", "explanation": "这里应该用〈文学〉。讲解古诗属于文学，光化学研究光引起的化学变化，不研究诗歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业以后研究一只光化学。", "corrected_sentence": "他毕业以后研究一门光化学。", "error_description": "错误：“一只光化学”，“只”用于动物或成对物件中的一个，学科应用“门”。正确为“一门光化学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他过学光化学。", "corrected_sentence": "他学过光化学。", "error_description": "语序错误：经历体“过”应紧跟动词之后，应说“学过光化学”，不能说“过学光化学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
