INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指燃烧或化学反应产生的悬浮在空气中的细小颗粒，使空气变得浑浊、不透明。", "primary_collocate": null, "pronunciation": "yān wù", "ipa": "jɛn˥ wu˥˩", "syllable_count": 2, "sentences": [{"text": "房间里充满了烟雾，什么也看不清。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排出的烟雾污染了空气。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灾现场冒出了大量烟雾。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员冲进烟雾里救人。", "target_word": "烟雾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汽车尾气和烟雾让城市的天空发灰。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户没关，烟雾飘进了屋子。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟雾散去以后，我们才看见山。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用湿毛巾捂住口鼻，躲开烟雾。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验时产生的烟雾有毒，要开窗。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟雾越来越浓，我们只好离开。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "团", "label": "量词"}, {"form": "股", "label": "量词"}, {"form": "烟雾弹", "label": "复合"}, {"form": "煙霧", "label": "繁体"}], "register": "通用", "sense_fingerprint": "燃烧或反应产生、悬浮空气中使空气浑浊的细小颗粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烟雾", "is_correct": true, "explanation": "正确：烟雾是悬浮在房间里的细小颗粒，充满房间后就让人看不清。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是透明的，充满房间不会让人看不清，与句意矛盾。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不会遮挡视线，与“什么也看不清”矛盾。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“充满”不能接“尺寸”这样的度量，应说“大小”。"}], "explanations": {"烟雾": "正确：烟雾是悬浮在房间里的细小颗粒，充满房间后就让人看不清。", "空气": "语义：空气是透明的，充满房间不会让人看不清，与句意矛盾。", "音乐": "语义：音乐不会遮挡视线，与“什么也看不清”矛盾。", "尺寸": "搭配：“充满”不能接“尺寸”这样的度量，应说“大小”。"}, "sentence_index": 0, "correct_answer": "烟雾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋子里飘出了一只烟雾。", "explanation": "这里量词应用〈股〉或〈团〉，不用“只”。“只”用于动物或成对东西中的一个，烟雾不属于这类。"}, {"text": "早晨的烟雾很清新，让人心情愉快。", "explanation": "这里应该用〈雾〉。晨雾清新；烟雾含有燃烧产生的颗粒，不能用来形容清新的早晨。"}, {"text": "他用烟雾擦干净了玻璃。", "explanation": "这里应该用〈抹布〉。烟雾飘在空中，不能用来擦东西；擦玻璃要用抹布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烟雾", "is_correct": true, "explanation": "正确：烟雾散去后，视线才能看到山，句意成立。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不会遮挡视线，“散去”后才看见山说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道散去与看见山没有关系，句子不通。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光不会挡住视线，“散去”后才看见山说不通。"}], "explanations": {"烟雾": "正确：烟雾散去后，视线才能看到山，句意成立。", "声音": "语义：声音不会遮挡视线，“散去”后才看见山说不通。", "味道": "语义：味道散去与看见山没有关系，句子不通。", "灯光": "语义：灯光不会挡住视线，“散去”后才看见山说不通。"}, "sentence_index": 6, "correct_answer": "烟雾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个烟雾，很温柔。", "explanation": "这里应该用〈人〉或〈朋友〉之类的词。烟雾指空中的细小颗粒，不能用来指人。"}, {"text": "他的心情像烟雾一样清澈。", "explanation": "这里应该用〈浑浊〉。烟雾本身浑浊、不透明，不能用来比喻清澈的心情。"}, {"text": "他把烟雾装进箱子里，拿去卖了。", "explanation": "这里把烟雾当成了可以装箱出售的〈货物〉；烟雾是飘在空气里的颗粒，不能装箱出卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋子里冒出了一个烟雾。", "corrected_sentence": "屋子里冒出了一股烟雾。", "error_description": "量词错误：烟雾用“股”或“团”计量，“个”不适合。正确：一股烟雾；错误：一个烟雾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "烟雾开散了，我们终于看见了山。", "corrected_sentence": "烟雾散开了，我们终于看见了山。", "error_description": "补语顺序错误：“散开”是动补结构，补语“开”应紧跟动词，不能说“开散”。正确：散开了；错误：开散了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
