INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11729, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "作为后续发展或生成过程之前已存在或需先具备的事物或阶段。", "primary_collocate": null, "pronunciation": "qián tǐ", "ipa": "tɕʰjɛn˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种药的前体是一种常见的化学物质。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家找到了这种蛋白质的前体。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前体经过几步反应，才变成最后的产品。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂用前体来做塑料。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把前体放进了反应罐里。", "target_word": "前体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种激素的前体在肝脏里生成。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验前，老师先检查了前体的纯度。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前体不够纯，产品的质量就不好。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在研究新药的前体。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮肤里有一种物质，是维生素的前体。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "前体物", "label": "复合"}, {"form": "前體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生成过程之前需先具备的事物或阶段，如化学中的前体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前体", "is_correct": true, "explanation": "正确：前体是生成药物或其他产物之前的原料，句中“是一种常见的化学物质”的描述成立。"}, {"text": "配方", "is_correct": false, "explanation": "语义：配方是药物的配比方子，不是一种化学物质，与“是一种常见的化学物质”矛盾。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：说明书是印刷的说明文字，不是化学物质。"}, {"text": "疗效", "is_correct": false, "explanation": "搭配：“是一种常见的化学物质”只能用于物质，“疗效”指药物的效果，不能这样描述。"}], "explanations": {"前体": "正确：前体是生成药物或其他产物之前的原料，句中“是一种常见的化学物质”的描述成立。", "配方": "语义：配方是药物的配比方子，不是一种化学物质，与“是一种常见的化学物质”矛盾。", "说明书": "语义：说明书是印刷的说明文字，不是化学物质。", "疗效": "搭配：“是一种常见的化学物质”只能用于物质，“疗效”指药物的效果，不能这样描述。"}, "sentence_index": 0, "correct_answer": "前体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器已经组装好了，是可以用的前体。", "explanation": "这里应该用〈成品〉。前体指制成产品之前的原料或阶段；已经组装好、可以直接使用的机器要说成品。"}, {"text": "这家工厂买了三只前体。", "explanation": "这里量词应用〈种〉或〈批〉，不用“只”。前体是物质，“只”用于动物或成对的东西。"}, {"text": "他是我们公司的前体。", "explanation": "这里应该用〈前任〉。前体指事物或阶段，不指人；指某人在职位上的前任要用前任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前体", "is_correct": true, "explanation": "正确：句中检查的是某种前体的纯度，“前体”指生成产物之前的原料，句意成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以检查纯度的东西，与“纯度”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是化学原料，谈不上“纯度”。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“纯度”只能用于物质，“亮度”不能与之搭配。"}], "explanations": {"前体": "正确：句中检查的是某种前体的纯度，“前体”指生成产物之前的原料，句意成立。", "天气": "语义：天气不是可以检查纯度的东西，与“纯度”矛盾。", "手机": "语义：手机不是化学原料，谈不上“纯度”。", "亮度": "搭配：“纯度”只能用于物质，“亮度”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "前体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这一领域的前体，很多人都向他学习。", "explanation": "这里应该用〈先驱〉。前体指事物或阶段，不指人；率先开拓一个领域的人要用先驱。"}, {"text": "我的前体比我大十岁，是我的老师。", "explanation": "这里应该用〈前辈〉。前体不指人；年长资深、值得学习的人要用前辈。"}, {"text": "这个活动的前体是我们班长。", "explanation": "这里应该用〈发起人〉。前体指事物，不指人；说某件事的发起人是某人要用发起人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司买了一个前体。", "corrected_sentence": "这家公司买了一批前体。", "error_description": "量词错误：“前体”是物质，应用“批”或“种”计量，不能用“个”。正确：一批前体；错误：一个前体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把前体出倒来了。", "corrected_sentence": "我们把前体倒出来了。", "error_description": "补语顺序错误：“倒出来”中，“出”紧跟动词，“来”在最后；“出倒来”顺序颠倒。正确：倒出来；错误：出倒来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将分散的要素集中起来，形成规模更大的生产方式或组织形式。", "primary_collocate": null, "pronunciation": "jí yuē huà", "ipa": "tɕi˧˥ yœ˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "集约化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代农业体系高度依赖单一作物的大规模种植，这种集约化农业模式虽然提升了短期产出效率，却对生物多样性的维持构成了严峻挑战。", "target_word": "集约化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代农业越来越走向集约化。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集约化生产能节省不少土地。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子正在推进土地集约化。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集约化养殖提高了产量。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业通过集约化降低了成本。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市发展需要土地集约化利用。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集约化经营让小农场联合起来。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们担心集约化会伤害环境。", "target_word": "集约化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集約化", "label": "繁体"}, {"form": "集约", "label": "复合"}, {"form": "集约化经营", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把分散的要素集中起来，形成更大规模的生产或组织方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集约化", "is_correct": true, "explanation": "正确：“集约化”指把分散要素集中起来的生产方式，可作“通过……载客”的方式，与“稀释人均排放”相合。"}, {"text": "个体化", "is_correct": false, "explanation": "语义：“个体化”与前文“规模化公共交通网络”相反，不能用来稀释排放。"}, {"text": "碎片化", "is_correct": false, "explanation": "语义：“碎片化”指分散零乱，与“规模化”冲突，不能说通过它稀释排放。"}, {"text": "私有化", "is_correct": false, "explanation": "搭配：“私有化”指产权归属的变化，不能作为载客的方式，搭配不当。"}], "explanations": {"集约化": "正确：“集约化”指把分散要素集中起来的生产方式，可作“通过……载客”的方式，与“稀释人均排放”相合。", "个体化": "语义：“个体化”与前文“规模化公共交通网络”相反，不能用来稀释排放。", "碎片化": "语义：“碎片化”指分散零乱，与“规模化”冲突，不能说通过它稀释排放。", "私有化": "搭配：“私有化”指产权归属的变化，不能作为载客的方式，搭配不当。"}, "sentence_index": 0, "correct_answer": "集约化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上课时注意力很集约化。", "explanation": "这里应该用〈集中〉。“集约化”指生产或组织方式的集中，不能用来描述注意力，注意力应说集中。"}, {"text": "这台机器的功率很集约化。", "explanation": "这里应该用〈大〉。“集约化”指生产或组织方式，不描述功率的大小，功率大应说大。"}, {"text": "他的歌声很集约化。", "explanation": "这里应该用〈动听〉。“集约化”指生产或组织方式，不能用来形容声音，形容歌声好听应说动听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集约化", "is_correct": true, "explanation": "正确：“集约化”是通过集中生产降低成本的方式，与“降低了成本”前后一致。"}, {"text": "繁琐化", "is_correct": false, "explanation": "语义：繁琐化会增加环节和成本，与“降低了成本”相矛盾。"}, {"text": "奢侈化", "is_correct": false, "explanation": "语义：“奢侈化”指花费增多、追求享受，与“降低了成本”正相反，不能作为降低成本的手段。"}, {"text": "随意化", "is_correct": false, "explanation": "语义：“随意化”指不加规划、随便行事，无法起到降低成本的作用，与“降低了成本”相矛盾。"}], "explanations": {"集约化": "正确：“集约化”是通过集中生产降低成本的方式，与“降低了成本”前后一致。", "繁琐化": "语义：繁琐化会增加环节和成本，与“降低了成本”相矛盾。", "奢侈化": "语义：“奢侈化”指花费增多、追求享受，与“降低了成本”正相反，不能作为降低成本的手段。", "随意化": "语义：“随意化”指不加规划、随便行事，无法起到降低成本的作用，与“降低了成本”相矛盾。"}, "sentence_index": 6, "correct_answer": "集约化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的集约化很鲜美。", "explanation": "这里应该用〈味道〉。“集约化”指生产或组织方式，不描述食物的口感，味道鲜美应说味道。"}, {"text": "他的性格很集约化，做事从不拖拉。", "explanation": "这里应该用〈干练〉。“集约化”指生产或组织方式，不用来描写人的性格，形容做事利落应说干练。"}, {"text": "这场比赛的集约化很精彩。", "explanation": "这里应该用〈水平〉。“集约化”指生产或组织方式，评价比赛的质量要说水平，不能用集约化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个农场的集约化很高。", "corrected_sentence": "这个农场的集约化程度很高。", "error_description": "“集约化”是抽象名词，表示高低要说“集约化程度”，直接说“集约化很高”搭配不当，应补上“程度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂正在推行一本集约化生产方式。", "corrected_sentence": "这家工厂正在推行一种集约化生产方式。", "error_description": "量词误用：“集约化生产方式”不能用书册量词“本”；应改为通用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11733, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
