INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11733, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在液体中加溶剂，使溶液的浓度降低。", "primary_collocate": null, "pronunciation": "xī shì", "ipa": "ɕi˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "工人先用清水稀释这桶原液，再装进瓶子里。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说要用清水稀释这瓶药液。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把浓盐水稀释成百分之一的溶液。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验前，老师先稀释了这瓶浓硫酸。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种消毒液必须加水稀释后才能使用。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓度太高的溶液，可以加水稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把原液和水按一比十稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "溶液稀释以后，颜色变浅了。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，我们学习怎样稀释溶液。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农药太浓会伤害植物，使用前要稀释。", "target_word": "稀释", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稀释了", "label": "体标"}, {"form": "稀释过", "label": "体标"}, {"form": "稀释液", "label": "复合"}, {"form": "稀释剂", "label": "复合"}], "register": "中性", "sense_fingerprint": "化学、医药中，加溶剂使溶液浓度降低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11733, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稀释", "is_correct": true, "explanation": "稀释指加入溶剂使溶液浓度降低，是本词的读音与意思。"}, {"text": "喜事", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，喜事意思是高兴的事。"}, {"text": "失事", "is_correct": false, "explanation": "shī 与 xī 声母不同（sh 与 x），失事意思是发生事故。"}, {"text": "西施", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，西施是古代美女的名字。"}], "explanations": {"稀释": "稀释指加入溶剂使溶液浓度降低，是本词的读音与意思。", "喜事": "xǐ（第三声）与 xī（第一声）声调不同，喜事意思是高兴的事。", "失事": "shī 与 xī 声母不同（sh 与 x），失事意思是发生事故。", "西施": "shī（第一声）与 shì（第四声）声调不同，西施是古代美女的名字。"}, "sentence_index": null, "correct_answer": "稀释"}, "level_3": {"options": [{"text": "稀释", "is_correct": true, "explanation": "正确：加清水使原液浓度降低，与“用清水”的语境相符。"}, {"text": "浓缩", "is_correct": false, "explanation": "语义：浓缩是使浓度升高，与加清水的作用相反。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是去掉水分，与用清水处理的语境矛盾。"}, {"text": "加强", "is_correct": false, "explanation": "搭配：“用清水加强原液”说不通，加强不能表示改变浓度。"}], "explanations": {"稀释": "正确：加清水使原液浓度降低，与“用清水”的语境相符。", "浓缩": "语义：浓缩是使浓度升高，与加清水的作用相反。", "烘干": "语义：烘干是去掉水分，与用清水处理的语境矛盾。", "加强": "搭配：“用清水加强原液”说不通，加强不能表示改变浓度。"}, "sentence_index": 0, "correct_answer": "稀释"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖在热水里很快稀释了。", "explanation": "这里应该用〈溶解〉。稀释是加入溶剂使溶液浓度降低，糖在水中溶解不是稀释。"}, {"text": "工人在车间里稀释了这块铁板。", "explanation": "这里应该用〈锻造〉。稀释指在液体中加溶剂降低浓度，不指对金属进行锻打加工。"}, {"text": "他用开水稀释茶叶。", "explanation": "这里应该用〈冲泡〉。稀释的对象是溶液，要降低浓度，不能用于茶叶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀释", "is_correct": true, "explanation": "“按一比十稀释”指按比例加水降低浓度，符合把字句的语境。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却是降温，与按比例混合降低浓度无关。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是去掉水分，与句中加水降低浓度的意思相反。"}, {"text": "结晶", "is_correct": false, "explanation": "配价：“结晶”是不及物动词，不能用“把”字句带宾语“原液和水”。"}], "explanations": {"稀释": "“按一比十稀释”指按比例加水降低浓度，符合把字句的语境。", "冷却": "语义：冷却是降温，与按比例混合降低浓度无关。", "烘干": "语义：烘干是去掉水分，与句中加水降低浓度的意思相反。", "结晶": "配价：“结晶”是不及物动词，不能用“把”字句带宾语“原液和水”。"}, "sentence_index": 6, "correct_answer": "稀释"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面包要稀释二十分钟。", "explanation": "这里应该用〈烘焙〉。稀释是加溶剂降低浓度，不用于面包的加热制作。"}, {"text": "鸡蛋要稀释十分钟。", "explanation": "这里应该用〈煮〉。稀释只能使溶液变淡，不能用于煮鸡蛋。"}, {"text": "黄瓜要稀释一晚。", "explanation": "这里应该用〈腌制〉。稀释用于降低溶液浓度，不用于腌渍蔬菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她加了很多水，把果汁稀释很淡。", "corrected_sentence": "她加了很多水，把果汁稀释得很淡。", "error_description": "应为“稀释得很淡”。表示程度的补语前要用“得”，漏掉“得”，“稀释很淡”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这罐原液太浓，工人加了水把它稀释。", "corrected_sentence": "这罐原液太浓，工人加了水把它稀释了。", "error_description": "应为“把它稀释了”。“把”字句的谓语后要有“了”或补语等成分，漏掉“了”，句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
