INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物体抵抗外力破坏的能力，或力量、程度的大小。", "primary_collocate": null, "pronunciation": "qiáng dù", "ipa": "tɕʰjɑŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这种钢的强度很高。", "target_word": "强度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做桥的材料，强度一定要够。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子的强度不够，会断的。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师先测试了木板的强度。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铝的强度比铁低，但是更轻。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃杯的强度不高，一摔就碎。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料加了纤维以后，强度提高了。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的墙要有足够的强度。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种新材料的强度是普通钢的两倍。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全帽的强度必须符合标准。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "強度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "材料或物体抵抗外力、不易损坏的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11734, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确答案：强度，qiáng dù，指物体抵抗外力破坏的能力。"}, {"text": "强大", "is_correct": false, "explanation": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。"}, {"text": "强盗", "is_correct": false, "explanation": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。"}, {"text": "抢渡", "is_correct": false, "explanation": "qiǎng dù（第三声）与 qiáng dù 声调不同，意思是抢先渡河。"}], "explanations": {"强度": "正确答案：强度，qiáng dù，指物体抵抗外力破坏的能力。", "强大": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。", "强盗": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。", "抢渡": "qiǎng dù（第三声）与 qiáng dù 声调不同，意思是抢先渡河。"}, "sentence_index": null, "correct_answer": "强度"}, "level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「很高」修饰物体的结实程度，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很高”不能修饰“颜色”，颜色只说深浅。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“很高”不说寿命，寿命要说“很长”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：钢是物体，没有性格，句子说不通。"}], "explanations": {"强度": "正确：「很高」修饰物体的结实程度，符合句意。", "颜色": "搭配：“很高”不能修饰“颜色”，颜色只说深浅。", "寿命": "搭配：“很高”不说寿命，寿命要说“很长”。", "性格": "语义：钢是物体，没有性格，句子说不通。"}, "sentence_index": 0, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块陶瓷的强度很高，能轻易划伤玻璃。", "explanation": "这里应该用〈硬度〉。强度指抵抗外力破坏的能力，能否划伤别的材料要用硬度。"}, {"text": "这台机器的强度很高，零件误差不到0.01毫米。", "explanation": "这里应该用〈精度〉。强度指抵抗外力破坏的能力，零件加工的准确程度要用精度。"}, {"text": "这块钢的强度很大，所以特别重。", "explanation": "这里应该用〈密度〉。强度指抵抗外力破坏的能力，单位体积的重量要用密度，不能用来说明东西重不重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「提高」说的是强度这类程度，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，年龄只说增长。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，体重要说增加或增长。"}, {"text": "身高", "is_correct": false, "explanation": "语义：塑料不会长高，身高只能说增长，句子说不通。"}], "explanations": {"强度": "正确：「提高」说的是强度这类程度，符合句意。", "年龄": "搭配：“提高”用于水平、质量，年龄只说增长。", "体重": "搭配：“提高”用于水平、质量，体重要说增加或增长。", "身高": "语义：塑料不会长高，身高只能说增长，句子说不通。"}, "sentence_index": 6, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块钢板的强度是五毫米。", "explanation": "这里应该用〈厚度〉。强度是抵抗外力的能力，不能用毫米计量。"}, {"text": "这个箱子的强度很大，放不进车里。", "explanation": "这里应该用〈体积〉。强度指抵抗外力破坏的能力，物体占的空间大小要用体积。"}, {"text": "他的强度很大，一拳就打碎了木板。", "explanation": "这里应该用〈力气〉。强度说的是物体的结实程度，人的力量要说力气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根绳子的强度够足，可以吊起一袋米。", "corrected_sentence": "这根绳子的强度足够，可以吊起一袋米。", "error_description": "语序错误：“够足”应为“足够”。说强度达到所需的程度时，要说“强度足够”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥的强度提了高了，可以承受更重的车。", "corrected_sentence": "这座桥的强度提高了，可以承受更重的车。", "error_description": "拆分错误：“提高”是不能拆开的词，“了”不能插在中间。应说“强度提高了”，不能说“强度提了高了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一定时期内运输旅客的数量。", "primary_collocate": null, "pronunciation": "kè yùn liàng", "ipa": "kʰɤ˥˩ yn˥˩ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "传统燃油汽车在频繁启停与怠速运行中释放的氮氧化物、颗粒物及挥发性有机化合物，是城市雾霾与光化学烟雾形成的关键前体物；而规模化公共交通网络通过集约化载客显著稀释了人均排放强度，使得单位客运量所产生的环境污染降至个体交通的零头。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "春运期间，火车客运量明显增加。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这座机场的客运量超过了两千万。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假到了，铁路客运量一天比一天多。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受天气影响，今天航班的客运量下降了。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线路的客运量是全市最高的。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的公交客运量每年都在变化。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新高铁开通后，这个车站的客运量翻了一倍。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告显示，全国水路客运量比去年少了。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，长途汽车的客运量特别大。", "target_word": "客运量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "交通统计中，一定时期内运送旅客的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客运量", "is_correct": true, "explanation": "正确：“单位客运量”指每运送一定数量的旅客，与前文“集约化载客”照应，搭配自然。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价是金额，不会产生环境污染，句意说不通。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入是钱数，与“排放”和“污染”无关，句子语义不通。"}, {"text": "运费", "is_correct": false, "explanation": "搭配：“单位运费”不能与“所产生的环境污染”搭配，运费本身是金额，也不会产生污染。"}], "explanations": {"客运量": "正确：“单位客运量”指每运送一定数量的旅客，与前文“集约化载客”照应，搭配自然。", "票价": "语义：票价是金额，不会产生环境污染，句意说不通。", "收入": "语义：收入是钱数，与“排放”和“污染”无关，句子语义不通。", "运费": "搭配：“单位运费”不能与“所产生的环境污染”搭配，运费本身是金额，也不会产生污染。"}, "sentence_index": 0, "correct_answer": "客运量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个港口去年的客运量超过了一千万吨，主要是集装箱。", "explanation": "这里应该用〈货运量〉。客运量指运送旅客的数量，集装箱和货物的吨数要用货运量。"}, {"text": "这家商场周末的客运量特别大，很多人来购物。", "explanation": "这里应该用〈客流量〉。客运量是交通部门统计运送旅客数量的指标，商场里的人流要用客流量。"}, {"text": "节假日期间，这个公园门口的客运量增加了很多。", "explanation": "这里应该用〈人流量〉。客运量指运送旅客的数量，公园门口进出的人群要用人流量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客运量", "is_correct": true, "explanation": "正确：客运量指运送旅客的数量，会随年份变化，与“公交”搭配自然。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高度，公交车没有身高，句子说不通。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”指语言的组织规则，公交车没有语法，句意不合。"}, {"text": "发音", "is_correct": false, "explanation": "语义：“发音”指说话的声音，公交不会发音，句意不合。"}], "explanations": {"客运量": "正确：客运量指运送旅客的数量，会随年份变化，与“公交”搭配自然。", "身高": "体貌：“身高”指人的身体高度，公交车没有身高，句子说不通。", "语法": "语义：“语法”指语言的组织规则，公交车没有语法，句意不合。", "发音": "语义：“发音”指说话的声音，公交不会发音，句意不合。"}, "sentence_index": 6, "correct_answer": "客运量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆大巴的客运量最多能容纳四十五人。", "explanation": "这里应该用〈载客量〉。客运量指一定时期内运送旅客的总数，一辆车最多能坐多少人要用载客量。"}, {"text": "这趟航班的客运量达到了百分之九十。", "explanation": "这里应该用〈上座率〉。上座率是座位被占用的比例，用百分数表示；客运量计算的是人数，不能用百分比。"}, {"text": "早高峰时，这条高速路的客运量达到了每小时三千辆。", "explanation": "这里应该用〈车流量〉。客运量指运送旅客的人数，单位时间内经过道路的车辆数要用车流量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年一季度，全市地铁的客运量达到了两亿个。", "corrected_sentence": "今年一季度，全市地铁的客运量达到了两亿人次。", "error_description": "“客运量”的计量单位应为“人次”，不能用“个”。“客运量”计算的是运送旅客的人次，所以应说“两亿人次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月全市公交客运量了三千万人次。", "corrected_sentence": "上个月全市公交客运了三千万人次。", "error_description": "“客运量”是名词，不能直接作动词；表示“运送旅客”的动词是“客运”，应说“客运了三千万人次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
