INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人类活动或自然因素导致环境（如空气、水、土壤）中有害物质增加，破坏生态平衡的现象。", "primary_collocate": null, "pronunciation": "huán jìng wū rǎn", "ipa": "xwan˧˥ tɕiŋ˥˩ u˥ ɻan˨˩˦", "syllable_count": 4, "sentences": [{"text": "汽车尾气排放得越来越多，城市的环境污染也越来越重。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境污染让城市的空气变差了。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排放废水，造成了环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该一起减少环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变黑是环境污染的结果。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境污染对孩子的健康影响很大。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在努力解决环境污染问题。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料垃圾也会带来环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的环境污染比以前轻多了。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的环境污染很严重，鱼越来越少。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境污染", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有害物质进入空气、水、土壤，破坏生态的现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境污染", "is_correct": true, "explanation": "正确：「越来越重」描述的是环境污染的程度，与前文汽车尾气排放增多的语境相符。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：「越来越重」的主语应是污染、排放一类的结果，「乘客」是人，不能说「越来越重」。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是车辆的设施，不会因排放增多而「越来越重」，与语境不符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是驾驶车辆的人，不能「越来越重」，与尾气排放的语境无关。"}], "explanations": {"环境污染": "正确：「越来越重」描述的是环境污染的程度，与前文汽车尾气排放增多的语境相符。", "乘客": "搭配：「越来越重」的主语应是污染、排放一类的结果，「乘客」是人，不能说「越来越重」。", "座位": "语义：座位是车辆的设施，不会因排放增多而「越来越重」，与语境不符。", "司机": "语义：司机是驾驶车辆的人，不能「越来越重」，与尾气排放的语境无关。"}, "sentence_index": 0, "correct_answer": "环境污染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府正在推进环境污染。", "explanation": "这里应该用〈环境治理〉。「推进」用于要促成的工作和计划，污染是要消除的现象，不能被推进。"}, {"text": "这家公司的核心任务是环境污染。", "explanation": "这里应该用〈环境保护〉。「核心任务」指要去做的工作，环境污染是一种现象，不能作为任务。"}, {"text": "我在报告中写到一只环境污染。", "explanation": "这里应该用〈种〉。「只」多用于动物和单件物品，环境污染是抽象现象，量词应用「种」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境污染", "is_correct": true, "explanation": "正确：「解决……问题」的宾语是环境污染这类社会问题，与「努力」「政府」的语境相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是需要解决的问题，「解决月亮问题」不成立。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是可以被解决的问题，与前文语境不符。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：「解决」的宾语应是问题、矛盾或困难，「饺子」是食物，不能与「解决」搭配。"}], "explanations": {"环境污染": "正确：「解决……问题」的宾语是环境污染这类社会问题，与「努力」「政府」的语境相符。", "月亮": "语义：月亮不是需要解决的问题，「解决月亮问题」不成立。", "春天": "语义：春天是季节，不是可以被解决的问题，与前文语境不符。", "饺子": "搭配：「解决」的宾语应是问题、矛盾或困难，「饺子」是食物，不能与「解决」搭配。"}, "sentence_index": 6, "correct_answer": "环境污染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周都进行环境污染。", "explanation": "这里应该用〈环境监测〉。「进行」后接检测、活动等工作，环境污染是需要消除的现象，不能被进行。"}, {"text": "社区组织了环境污染。", "explanation": "这里应该用〈环境整治〉。「组织」的对象是行动、活动，环境污染本身不是可以组织的行动。"}, {"text": "我们在会上讨论了一条环境污染。", "explanation": "这里应该用〈种〉。「条」多用于河流、消息、道路等，环境污染是抽象现象，量词应用「种」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期乱倒垃圾会造成严重地环境污染。", "corrected_sentence": "长期乱倒垃圾会造成严重的环境污染。", "error_description": "定语标记错误：修饰名词「环境污染」的形容词定语后应用「的」，不能用「地」（「地」用于修饰动词的状语）。正确形式是「严重的环境污染」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市存在一块严重的环境污染。", "corrected_sentence": "这座城市存在一种严重的环境污染。", "error_description": "量词错误：「块」用于有块状形状的具体物体或地块，环境污染是抽象现象，应用「种」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11738, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "反义：「升」指数量或温度变高，与表示变低的「降」相对。"}, {"text": "唱", "is_correct": false, "explanation": "与「降」在任何义项上都不构成反义，只是同为动词。"}, {"text": "写", "is_correct": false, "explanation": "与「降」在任何义项上都不构成反义，只是同为动词。"}, {"text": "吃", "is_correct": false, "explanation": "与「降」在任何义项上都不构成反义，只是同为动词。"}], "correct_answer": "升", "explanations": {"升": "反义：「升」指数量或温度变高，与表示变低的「降」相对。", "唱": "与「降」在任何义项上都不构成反义，只是同为动词。", "写": "与「降」在任何义项上都不构成反义，只是同为动词。", "吃": "与「降」在任何义项上都不构成反义，只是同为动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
