INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使数量或程度变低", "primary_collocate": null, "pronunciation": "jiàng", "ipa": "tɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "昨天下了雨，今天气温降了十度。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机太贵，商店说下个月会降到两千。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近没好好学习，考试成绩降了很多。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了药以后，他的体温慢慢降下来了。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海鲜太多卖不完，老板把价格降了一半。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有雪，山上的温度会降到零下五度。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了半年药，他的血压终于降下来了。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂用了新机器，生产的成本降了不少。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为大家都不买，房子的价格一直在降。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我这半年坚持运动，血糖降到了正常水平。", "target_word": "降", "complexity_tier": "T3", "furigana": "jiàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "降了", "label": "体标（了）"}, {"form": "降过", "label": "体标（过）"}, {"form": "降低", "label": "复合词"}, {"form": "降价", "label": "复合词"}, {"form": "下降", "label": "复合词"}], "register": "中性", "sense_fingerprint": "价格、温度、成绩等数量或程度变低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：听到的 jiàng（第四声）即「降」，意思是使数量或程度变低。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲话。"}, {"text": "将", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是将要、将来。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是看见。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。"}], "explanations": {"降": "正确：听到的 jiàng（第四声）即「降」，意思是使数量或程度变低。", "讲": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲话。", "将": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是将要、将来。", "见": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是看见。", "江": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：「气温……降了十度」表示气温变低，与前文「下了雨」的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：气温不能被「吃」，「气温吃了十度」与语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：气温不能被「唱」，与数量变化的语境无关。"}, {"text": "买", "is_correct": false, "explanation": "搭配：「买」用于商品，不能说「气温买了」，与数量变化的搭配不符。"}], "explanations": {"降": "正确：「气温……降了十度」表示气温变低，与前文「下了雨」的语境相符。", "吃": "语义：气温不能被「吃」，「气温吃了十度」与语境不符。", "唱": "语义：气温不能被「唱」，与数量变化的语境无关。", "买": "搭配：「买」用于商品，不能说「气温买了」，与数量变化的搭配不符。"}, "sentence_index": 0, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把杯子降在了桌上。", "explanation": "这里应该用〈放〉。「降」表示数量或程度变低，把杯子放在桌上要用「放」。"}, {"text": "幸福降临到了他的家里。", "explanation": "这里的「降」读 jiàng，意思是来到、落到某人身上，不是「数量或程度变低」的意思。"}, {"text": "皇帝降旨免除了这一年的赋税。", "explanation": "这里的「降」读 jiàng，意思是下达（命令），不是「数量或程度变低」的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11738, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：听到的 jiàng（第四声）即「降」，意思是使数量或程度变低。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。"}, {"text": "剑", "is_correct": false, "explanation": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是剑。"}, {"text": "姜", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。"}, {"text": "健", "is_correct": false, "explanation": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是健康。"}], "explanations": {"降": "正确：听到的 jiàng（第四声）即「降」，意思是使数量或程度变低。", "奖": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。", "剑": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是剑。", "姜": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。", "健": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是健康。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：「血压终于降下来了」表示血压下降，与「吃了半年药」的因果语境相符。"}, {"text": "升", "is_correct": false, "explanation": "搭配：「升下来」不是常见搭配，「升」表示向上，与血压下降的语境相反。"}, {"text": "写", "is_correct": false, "explanation": "语义：血压不能被「写」下来，与语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：血压不能被「唱」下来，与语境不符。"}], "explanations": {"降": "正确：「血压终于降下来了」表示血压下降，与「吃了半年药」的因果语境相符。", "升": "搭配：「升下来」不是常见搭配，「升」表示向上，与血压下降的语境相反。", "写": "语义：血压不能被「写」下来，与语境不符。", "唱": "语义：血压不能被「唱」下来，与语境不符。"}, "sentence_index": 6, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把画降在了墙上。", "explanation": "这里应该用〈挂〉。「降」表示数量或程度变低，把画固定在墙上要用「挂」。"}, {"text": "小宝宝降生在一个冬天的早晨。", "explanation": "这里的「降」指出生，是另一种用法，不是「数量或程度变低」的意思。"}, {"text": "他终于降服了那匹烈马。", "explanation": "这里的「降」读 xiáng，意思是使……服从，不是「数量或程度变低」的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚气温会降在零度。", "corrected_sentence": "今晚气温会降到零度。", "error_description": "补语错误：表示数值降到某个点，应说「降到」，「降在」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把价格降下来了了。", "corrected_sentence": "老板把价格降下来了。", "error_description": "「了」的重复：「降下来了」中的「了」已表示完成，句末不能再加一个「了」，正确形式是「降下来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
