INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11739, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指整数后不足整单位的部分，或总数中除去整数后剩余的小数目。", "primary_collocate": null, "pronunciation": "líng tou", "ipa": "liŋ˧˥ tʰou", "syllable_count": 2, "sentences": [{"text": "坐地铁上班，废气排放能降至开车的零头。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服九十九块八，我不要零头。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一共一百零三块，老板把零头去掉了。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的年薪是五十万零八千，别人只说五十万，不说零头。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货一共一百二十五件，零头是二十五件。", "target_word": "零头", "complexity_tier": "T3", "furigana": "zhè pī huò yí gòng yì bǎi èr shí wǔ jiàn, líng tou shì èr shí wǔ jiàn.", "sentence_source": "generated"}, {"text": "三十五块的零头是五块，你不用给了。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数字太乱，我们只算整数，不算零头。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一年挣一百万，我才挣他的零头。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跟他们比，我们的工资只是个零头。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些苹果一共十斤二两，二两是零头。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "零頭", "label": "繁体"}], "register": "口语", "sense_fingerprint": "整数之外多出来的小数目，或只占总数一小部分的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "零头", "is_correct": true, "explanation": "零头：整数之外不足整单位的小部分，符合“降至……的零头”的语境。"}, {"text": "小数", "is_correct": false, "explanation": "语义：小数是数字的一种书写形式，不能指排放量降到的小部分。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“降至”后接数量或水平，不接“时间”。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体占据的空间大小，不用来说废气排放的多少。"}], "explanations": {"零头": "零头：整数之外不足整单位的小部分，符合“降至……的零头”的语境。", "小数": "语义：小数是数字的一种书写形式，不能指排放量降到的小部分。", "时间": "搭配：“降至”后接数量或水平，不接“时间”。", "体积": "语义：体积指物体占据的空间大小，不用来说废气排放的多少。"}, "sentence_index": 0, "correct_answer": "零头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "买完东西，老板找了我三块零头。", "explanation": "这里应该用〈零钱〉。零头指不足整数的剩余部分，找给顾客的钱要说零钱。"}, {"text": "他的年薪是五十万，全是零头。", "explanation": "这里把整个总额说成零头，与“整数之外不足整单位的部分”义相反，本题不符。"}, {"text": "这个电话号码的零头是七。", "explanation": "这里应该用〈尾数〉。尾数指一个数末位的数字；电话号码不分整数与零头，末位数字要说尾数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "零头", "is_correct": true, "explanation": "零头：不够整数的小数目，正好与“只算整数”形成对比。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与数目无关，“不算颜色”说不通。"}, {"text": "高度", "is_correct": false, "explanation": "语义：高度是测量的尺度，不是需要计算取舍的数目，与“只算整数”的语境矛盾。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“算”接数量或钱款，不说“算方向”。"}], "explanations": {"零头": "零头：不够整数的小数目，正好与“只算整数”形成对比。", "颜色": "语义：颜色与数目无关，“不算颜色”说不通。", "高度": "语义：高度是测量的尺度，不是需要计算取舍的数目，与“只算整数”的语境矛盾。", "方向": "搭配：“算”接数量或钱款，不说“算方向”。"}, "sentence_index": 6, "correct_answer": "零头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次结账，他把整数凑成了零头。", "explanation": "这里应该说“把零头凑成整数”。凑整是把零头补足为整数，方向不能颠倒。"}, {"text": "这笔账算完，零头刚好是整数，没有剩余。", "explanation": "这里应该说〈没有零头〉。零头指不足整数的部分，不能是整数，说零头是整数自相矛盾。"}, {"text": "这次结账，老板把我的零头当成了工钱。", "explanation": "这里应该用〈工钱〉。工钱是劳动报酬，零头是不足整数的剩余钱，不能当作工钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "收银员抹掉了零头们。", "corrected_sentence": "收银员抹掉了零头。", "error_description": "“们”只用于指人或有生命的名词，“零头”是抽象的数量，不能加“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔账算下来还剩一只零头。", "corrected_sentence": "这笔账算下来还剩一点零头。", "error_description": "“零头”前应用量词“点”（或“些”）；“只”用于动物或单个的物件，不能修饰“零头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查并计算数字或账目，看看对不对。", "primary_collocate": null, "pronunciation": "hé suàn", "ipa": "xɤ˧˥ suan˥˩", "syllable_count": 2, "sentences": [{"text": "在比较两种出行方式时，研究者必须把车辆制造和能源生产各环节的排放逐项核算清楚，才能得出可靠的结论。", "target_word": "核算", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "会计正在核算这个月的账目。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财务部每年年底都要核算一次账目。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把发票和账本一起核算了一遍。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再核算一下这笔账，数字好像不对。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王核算了三次，结果还是不一样。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让会计核算公司今年的收入。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核算完账目以后，他发现少了一千元。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔费用已经核算过了，没有错误。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先核算数字，再交给经理。", "target_word": "核算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核算了", "label": "体标"}, {"form": "核算过", "label": "体标"}, {"form": "成本核算", "label": "复合"}, {"form": "核算员", "label": "复合"}], "register": "中性", "sense_fingerprint": "检查并计算账目、数字是否正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68b16bd-3f13-4d32-96ca-e7b7d329e4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核算", "is_correct": true, "explanation": "核算（hé suàn）：检查并计算账目或数字是否正确。"}, {"text": "核酸", "is_correct": false, "explanation": "suān（第一声）与 suàn（第四声）声调不同，意思是核酸，指一类生物大分子。"}, {"text": "还算", "is_correct": false, "explanation": "hái 与 hé 韵母不同（ai 与 e），意思是还算、勉强过得去。"}, {"text": "盘算", "is_correct": false, "explanation": "pán 与 hé 声母不同（p 与 h），意思是心里打算、谋划。"}], "explanations": {"核算": "核算（hé suàn）：检查并计算账目或数字是否正确。", "核酸": "suān（第一声）与 suàn（第四声）声调不同，意思是核酸，指一类生物大分子。", "还算": "hái 与 hé 韵母不同（ai 与 e），意思是还算、勉强过得去。", "盘算": "pán 与 hé 声母不同（p 与 h），意思是心里打算、谋划。"}, "sentence_index": null, "correct_answer": "核算"}, "level_3": {"options": [{"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶指操纵车辆，与核对排放数字无关，“逐项驾驶清楚”说不通。"}, {"text": "核算", "is_correct": true, "explanation": "正确：“逐项核算清楚”指一项项计算、核对，与句意相符。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点，不能与“排放”搭配。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”需要接受者和所赠之物，“排放”不能被赠送，句意不通。"}], "explanations": {"驾驶": "语义：驾驶指操纵车辆，与核对排放数字无关，“逐项驾驶清楚”说不通。", "核算": "正确：“逐项核算清楚”指一项项计算、核对，与句意相符。", "游览": "搭配：“游览”的对象是景点，不能与“排放”搭配。", "赠送": "配价：“赠送”需要接受者和所赠之物，“排放”不能被赠送，句意不通。"}, "sentence_index": 0, "correct_answer": "核算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察正在核算他的身份。", "explanation": "这里应该用〈核实〉。核算指计算、核对账目或数字，核实身份要用“核实”，“核算身份”说不通。"}, {"text": "医生核算了病人的体温。", "explanation": "这里应该用〈测量〉。核算用于账目和数字的计算核对，体温是量出来的，不用“核算”。"}, {"text": "他又去核算了一遍门有没有锁好。", "explanation": "这里应该用〈检查〉。门锁不是账目或数字，检查门锁要用“检查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核算", "is_correct": true, "explanation": "正确：“核算收入”指计算、核对收入的数字。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与计算收入无关。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能与“收入”搭配。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”接的是事项或意见，不能直接带“收入”这类数量宾语。"}], "explanations": {"核算": "正确：“核算收入”指计算、核对收入的数字。", "烹饪": "语义：烹饪指做饭，与计算收入无关。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能与“收入”搭配。", "同意": "配价：“同意”接的是事项或意见，不能直接带“收入”这类数量宾语。"}, "sentence_index": 6, "correct_answer": "核算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在会议上核算了这个问题。", "explanation": "这里应该用〈讨论〉。核算指计算、核对账目或数字，讨论问题要用“讨论”。"}, {"text": "他在表格上核算了自己的名字。", "explanation": "这里应该用〈登记〉。核算针对数字和账目，把名字写进表格要用“登记”。"}, {"text": "专家正在核算这幅画的真假。", "explanation": "这里应该用〈鉴定〉。核算是对数字、账目的计算核对，判断真假要用“鉴定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "麻烦你帮我核算一下了这个月的开支。", "corrected_sentence": "麻烦你帮我核算一下这个月的开支。", "error_description": "错误形式：“核算一下了”；正确形式：“核算一下”。“一下”是动量补语，表示动作的次数或时间，后面不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔账我已经核算完着。", "corrected_sentence": "这笔账我已经核算完了。", "error_description": "错误形式：“核算完着”；正确形式：“核算完了”。“完”作结果补语表示动作结束，动作已完成要用“了”，“着”表示持续的状态，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
