INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将某个项目、数字或事项记录在总账或统计之中。", "primary_collocate": null, "pronunciation": "jì rù", "ipa": "tɕi˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "更为关键的是，在全生命周期碳核算框架下，公共交通即使计入车辆制造、能源生产与基础设施维护的隐含碳排放，其人均碳足迹仍较私家车通勤低达60%以上——这一数据在高密度城市语境中甚至可攀升至75%，凸显其在减缓全球气候变暖进程中的不可替代性。", "target_word": "计入", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这笔钱要计入今年的总收入。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加班费也应该计入工资。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩没有计入总分。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计把这笔费用计入了成本。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩的票不用计入总人数。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的比赛成绩要计入班级总分。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把快递费计入总价里。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的利润已经计入账本了。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税费没有计入商品价格。", "target_word": "计入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "计入了", "label": "体标"}, {"form": "计入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把项目或数字记录进总账或统计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68b16bd-3f13-4d32-96ca-e7b7d329e4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11744, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "计入", "is_correct": true, "explanation": "计入（jì rù）：把项目或数字记录进总账或统计之中。"}, {"text": "挤入", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是挤进去。"}, {"text": "进入", "is_correct": false, "explanation": "jìn 比 jì 多一个韵尾 n，意思是走进某个地方。"}, {"text": "置入", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），意思是放置进去。"}], "explanations": {"计入": "计入（jì rù）：把项目或数字记录进总账或统计之中。", "挤入": "jǐ（第三声）与 jì（第四声）声调不同，意思是挤进去。", "进入": "jìn 比 jì 多一个韵尾 n，意思是走进某个地方。", "置入": "zhì 与 jì 声母不同（zh 与 j），意思是放置进去。"}, "sentence_index": null, "correct_answer": "计入"}, "level_3": {"options": [{"text": "计入", "is_correct": true, "explanation": "正确：“计入”指把隐含碳排放记进碳足迹的统计之中，与句意相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶指操纵车辆，与把排放记入统计的意思无关。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点，不能与“隐含碳排放”搭配。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”接的是意见或事项，不能直接带“隐含碳排放”这样的宾语。"}], "explanations": {"计入": "正确：“计入”指把隐含碳排放记进碳足迹的统计之中，与句意相符。", "驾驶": "语义：驾驶指操纵车辆，与把排放记入统计的意思无关。", "游览": "搭配：“游览”的对象是景点，不能与“隐含碳排放”搭配。", "同意": "配价：“同意”接的是意见或事项，不能直接带“隐含碳排放”这样的宾语。"}, "sentence_index": 0, "correct_answer": "计入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他计入了我们的团队。", "explanation": "这里应该用〈加入〉。计入指把项目或数字记进总数，成为团队成员要用“加入”。"}, {"text": "他计入了决赛。", "explanation": "这里应该用〈进入〉。计入只用于把数目或项目记进总数，进入决赛要用“进入”。"}, {"text": "飞机计入了机场。", "explanation": "这里应该用〈抵达〉。计入不表示到达，飞机到达机场要用“抵达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "计入", "is_correct": true, "explanation": "正确：“计入班级总分”指把比赛成绩记进总分之中。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与比赛成绩的统计无关。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”需要接受者和所赠之物，句中“班级总分”不能充当所赠之物。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能与“班级总分”搭配。"}], "explanations": {"计入": "正确：“计入班级总分”指把比赛成绩记进总分之中。", "烹饪": "语义：烹饪指做饭，与比赛成绩的统计无关。", "赠送": "配价：“赠送”需要接受者和所赠之物，句中“班级总分”不能充当所赠之物。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能与“班级总分”搭配。"}, "sentence_index": 6, "correct_answer": "计入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我计入了那部电影。", "explanation": "这里应该用〈喜欢〉。计入指把数目记进总数，表达对电影的喜爱要用“喜欢”。"}, {"text": "大家计入了这个问题。", "explanation": "这里应该用〈讨论〉。计入不表示讨论，讨论问题要用“讨论”。"}, {"text": "她计入了新裙子。", "explanation": "这里应该用〈穿〉。计入指把数字记进总数，穿衣服要用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔钱已经计入着今年的收入。", "corrected_sentence": "这笔钱已经计入了今年的收入。", "error_description": "错误形式：“计入着”；正确形式：“计入了”。“计入”表示动作已经完成，要用“了”，“着”表示持续状态，与“计入”不搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔补贴没有计入了今年的工资。", "corrected_sentence": "这笔补贴没有计入今年的工资。", "error_description": "错误形式：“没有计入了”；正确形式：“没有计入”。否定“没有”表示未发生，与表示完成的“了”不能同时用在同一动作上，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
