INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11745, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指各种陆地上使用的交通工具，如汽车、火车、自行车等。", "primary_collocate": null, "pronunciation": "chē liàng", "ipa": "ʈʂʰɤ˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这条路上的车辆很多。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把车辆停在白线里面。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨以后，车辆都开得很慢。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车、火车和自行车都是车辆。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥不让大型车辆通过。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在检查过路的车辆。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上的车辆多了，空气变差了。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场里停着很多车辆。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口禁止车辆进入。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年城市里的车辆都在增加。", "target_word": "车辆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批车辆", "label": "量词"}, {"form": "机动车辆", "label": "复合"}, {"form": "非机动车辆", "label": "复合"}], "register": "中性", "sense_fingerprint": "陆地交通工具的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68b16bd-3f13-4d32-96ca-e7b7d329e4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车厢", "is_correct": false, "explanation": "语义：车厢是列车的一部分，路上不会有很多车厢，与“这条路上的……很多”不符。"}, {"text": "车辆", "is_correct": true, "explanation": "正确：车辆泛指路上跑的各种车，可以与“这条路上的……很多”搭配。"}, {"text": "车驾", "is_correct": false, "explanation": "语域：“车驾”是书面敬称，专指帝王或贵人的车，不能用于一般车辆。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是乘车凭证，不是路上跑的车，句中说的是“很多”，不能指车票。"}], "explanations": {"车厢": "语义：车厢是列车的一部分，路上不会有很多车厢，与“这条路上的……很多”不符。", "车辆": "正确：车辆泛指路上跑的各种车，可以与“这条路上的……很多”搭配。", "车驾": "语域：“车驾”是书面敬称，专指帝王或贵人的车，不能用于一般车辆。", "车票": "语义：车票是乘车凭证，不是路上跑的车，句中说的是“很多”，不能指车票。"}, "sentence_index": 0, "correct_answer": "车辆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司新买了一只车辆。", "explanation": "这里应该用〈批〉。车辆是集合名词，计量用“一批”；“只”用于动物等，不能计量车辆。"}, {"text": "我每天骑车辆上学。", "explanation": "这里应该用〈自行车〉。车辆是统称，“骑”要搭配自行车、摩托车这类具体的车，不能说“骑车辆”。"}, {"text": "车辆里停着很多汽车。", "explanation": "这里应该用〈停车场〉。车辆是车的统称，不能当作停放汽车的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树木", "is_correct": false, "explanation": "语义：树木多了本应让空气变好，与“空气变差了”矛盾。"}, {"text": "车辆", "is_correct": true, "explanation": "正确：车辆多了会排放废气，使空气变差，与后半句的因果相符。"}, {"text": "车床", "is_correct": false, "explanation": "语义：车床是加工金属的机器，不会在马路上大量出现。"}, {"text": "车舆", "is_correct": false, "explanation": "语域：“车舆”是书面语，指古代的车，口语里不用于描述马路上的车。"}], "explanations": {"树木": "语义：树木多了本应让空气变好，与“空气变差了”矛盾。", "车辆": "正确：车辆多了会排放废气，使空气变差，与后半句的因果相符。", "车床": "语义：车床是加工金属的机器，不会在马路上大量出现。", "车舆": "语域：“车舆”是书面语，指古代的车，口语里不用于描述马路上的车。"}, "sentence_index": 6, "correct_answer": "车辆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在车辆上跳绳。", "explanation": "这里应该用〈操场〉。车辆是交通工具，不能当作跳绳的场地。"}, {"text": "他每天给车辆让座。", "explanation": "这里应该用〈老人〉。让座的对象必须是人，车辆不能接受让座。"}, {"text": "这座城市新增了一个车辆。", "explanation": "这里应该用〈批〉。“个”不用于车辆，集合计量用“一批”；“一辆车辆”重复，不能用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们看到一个车辆排队过桥。", "corrected_sentence": "我们看到一批车辆排队过桥。", "error_description": "错误：“一个车辆”，应为“一批车辆”。车辆是集合名词，计量用“批”，“个”不能用于车辆；“一辆车辆”同样重复，不能用“辆”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年路上的车辆多过不少。", "corrected_sentence": "这几年路上的车辆多了不少。", "error_description": "错误：“多过不少”，应为“多了不少”。“多过”是比较句用法，需要比较对象；这句说的是数量已经增加，要用“了”表示变化。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明示", "is_correct": true, "explanation": "反义：明示指明白地直接说出来，与“隐含”（藏在话语背后、没有直说）相对。"}, {"text": "制造", "is_correct": false, "explanation": "无关：制造指做出物品，与“隐含”的意思不构成反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "无关：保存指留存、不让损坏，与“隐含”表示意思藏在言语中没有关系。"}, {"text": "遵守", "is_correct": false, "explanation": "无关：遵守指依照规定去做，与“隐含”不构成反义关系。"}], "correct_answer": "明示", "explanations": {"明示": "反义：明示指明白地直接说出来，与“隐含”（藏在话语背后、没有直说）相对。", "制造": "无关：制造指做出物品，与“隐含”的意思不构成反义关系。", "保存": "无关：保存指留存、不让损坏，与“隐含”表示意思藏在言语中没有关系。", "遵守": "无关：遵守指依照规定去做，与“隐含”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明示", "is_correct": true, "explanation": "反义：明示指明白地说出来，与“隐含”（意思藏在背后）相对。"}, {"text": "吸收", "is_correct": false, "explanation": "无关：吸收指把外界的东西纳入自身，与“隐含”不构成反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：搬运指把物体从一处移到另一处，与“隐含”不构成反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：修理指把损坏的东西修好，与“隐含”不构成反义关系。"}], "correct_answer": "明示", "explanations": {"明示": "反义：明示指明白地说出来，与“隐含”（意思藏在背后）相对。", "吸收": "无关：吸收指把外界的东西纳入自身，与“隐含”不构成反义关系。", "搬运": "无关：搬运指把物体从一处移到另一处，与“隐含”不构成反义关系。", "修理": "无关：修理指把损坏的东西修好，与“隐含”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指某种意思或情感没有直接说出来，而是藏在话语或文字背后。", "primary_collocate": null, "pronunciation": "yǐn hán", "ipa": "in˨˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "他没有直接说出口，但这句话的语气里隐含着明显的不满。", "target_word": "隐含", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这句话里隐含着一个意思，他不想去。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话隐含着对我们的不满。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗隐含着作者对家乡的想念。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有直说，但话里隐含着批评。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容里隐含着一种说不出的难过。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题隐含了很多没有说出口的意思。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你仔细想想，他的话隐含什么意思？", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的字里行间隐含着深深的感情。", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告里隐含的意思，你听出来了吗？", "target_word": "隐含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐含着", "label": "体标（着）"}, {"form": "隐含了", "label": "体标（了）"}], "register": "书面", "sense_fingerprint": "意思或情感不直接说出，藏在话语文字背后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68b16bd-3f13-4d32-96ca-e7b7d329e4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬运", "is_correct": false, "explanation": "语义：搬运指把东西从一处移到另一处，不能用来形容语气。"}, {"text": "隐含", "is_correct": true, "explanation": "正确：“隐含着明显的不满”指不满藏在语气里，没有直接说出，与句意相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指把坏了的东西修好，与“语气里……着明显的不满”无关。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：吸收指把外界的东西纳入自身，与“语气里……着明显的不满”无关。"}], "explanations": {"搬运": "语义：搬运指把东西从一处移到另一处，不能用来形容语气。", "隐含": "正确：“隐含着明显的不满”指不满藏在语气里，没有直接说出，与句意相符。", "修理": "语义：修理指把坏了的东西修好，与“语气里……着明显的不满”无关。", "吸收": "语义：吸收指把外界的东西纳入自身，与“语气里……着明显的不满”无关。"}, "sentence_index": 0, "correct_answer": "隐含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他隐含了自己的想法。", "explanation": "这里应该用〈隐瞒〉。隐含指意思藏在话里，不是人主动去藏，不能说“隐含了自己的想法”。"}, {"text": "这套食谱隐含了五道素菜。", "explanation": "这里应该用〈包括〉。隐含只用于意思、情感，不能用来列举食谱里包括的内容。"}, {"text": "这个箱子隐含了三个苹果。", "explanation": "这里应该用〈包含〉。隐含只用于意思、情感，不能说东西或数量被“隐含”在容器里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明说", "is_correct": false, "explanation": "语义：“明说”指直接说出来，与“没有说出口”直接矛盾。"}, {"text": "隐含", "is_correct": true, "explanation": "正确：隐含了，表示意思藏在问题里，没有直接说出，与“没有说出口的意思”相合。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”后接决定、消息，不接“意思”，说“宣布很多意思”不通。"}, {"text": "说出", "is_correct": false, "explanation": "语义：“说出”与“没有说出口”直接矛盾。"}], "explanations": {"明说": "语义：“明说”指直接说出来，与“没有说出口”直接矛盾。", "隐含": "正确：隐含了，表示意思藏在问题里，没有直接说出，与“没有说出口的意思”相合。", "宣布": "搭配：“宣布”后接决定、消息，不接“意思”，说“宣布很多意思”不通。", "说出": "语义：“说出”与“没有说出口”直接矛盾。"}, "sentence_index": 6, "correct_answer": "隐含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱隐含在床下。", "explanation": "这里应该用〈隐藏〉。隐含只指意思或情感藏在话里，不能用于把东西藏在某处。"}, {"text": "那棵树后面隐含着一个小洞。", "explanation": "这里应该用〈隐蔽〉。隐含不能用来描述地点或物体的遮蔽状态。"}, {"text": "他悄悄隐含在人群中。", "explanation": "这里应该用〈隐身〉。隐含不能用于人主动躲进人群的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的回答里很隐含着很多不满。", "corrected_sentence": "他的回答里隐含着很多不满。", "error_description": "错误：“很隐含着”，应删去“很”。隐含是动词，不能受程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数字隐含了着一个重要的问题。", "corrected_sentence": "这个数字隐含着一个重要的问题。", "error_description": "错误：“隐含了着”，应为“隐含着”。表示持续存在要用“着”，“了”与“着”不能同时用在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
