INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指个人或家庭私有，主要用于非营业性出行的汽车。", "primary_collocate": null, "pronunciation": "sī jiā chē", "ipa": "sɨ˥ tɕja˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "更为关键的是，在全生命周期碳核算框架下，公共交通即使计入车辆制造、能源生产与基础设施维护的隐含碳排放，其人均碳足迹仍较私家车通勤低达60%以上——这一数据在高密度城市语境中甚至可攀升至75%，凸显其在减缓全球气候变暖进程中的不可替代性。", "target_word": "私家车", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我爸爸买了一辆新的私家车。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多家庭都有私家车。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们开私家车去郊外玩。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的私家车越来越多。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天开私家车去公司上班。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的私家车是白色的。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了私家车，出门方便多了。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "私家车太多，路上常常堵车。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不开私家车，坐地铁上班。", "target_word": "私家车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "私家车主", "label": "复合"}, {"form": "私家車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人或家庭私有、非营业用的汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68b16bd-3f13-4d32-96ca-e7b7d329e4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自行车", "is_correct": false, "explanation": "语义：自行车通勤几乎没有碳排放，公共交通不可能比它低60%以上。"}, {"text": "私家车", "is_correct": true, "explanation": "正确：句中拿公共交通与个人或家庭日常驾驶的汽车通勤作比较。"}, {"text": "货车", "is_correct": false, "explanation": "语义：货车用于运输货物，不是个人日常上下班的出行方式。"}, {"text": "游艇", "is_correct": false, "explanation": "语义：游艇属休闲水上用品，不能作为日常通勤的交通工具。"}], "explanations": {"自行车": "语义：自行车通勤几乎没有碳排放，公共交通不可能比它低60%以上。", "私家车": "正确：句中拿公共交通与个人或家庭日常驾驶的汽车通勤作比较。", "货车": "语义：货车用于运输货物，不是个人日常上下班的出行方式。", "游艇": "语义：游艇属休闲水上用品，不能作为日常通勤的交通工具。"}, "sentence_index": 0, "correct_answer": "私家车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们单位的私家车每天接送领导。", "explanation": "这里应该用〈公车〉。私家车指个人或家庭自用的车，单位公用的车要说公车。"}, {"text": "私家车在路口巡逻。", "explanation": "这里应该用〈警车〉。私家车是个人或家庭自用的车，不用于巡逻执法；执法巡逻的车要说警车。"}, {"text": "这辆私家车每天往返运送钢材。", "explanation": "这里应该用〈货车〉。私家车主要用于非营业性出行，不用来营运或运送货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公交车", "is_correct": false, "explanation": "语义：公交车属公共运营，不归家庭所有，与句首“我家的”相矛盾。"}, {"text": "私家车", "is_correct": true, "explanation": "正确：“我家的”后接家庭自有的车，与“是白色的”搭配，句意通顺。"}, {"text": "警车", "is_correct": false, "explanation": "搭配：“警车”属公安部门用车，不能说“我家的警车”。"}, {"text": "救护车", "is_correct": false, "explanation": "语义：救护车是医疗急救用车，不是家庭私有的车，与“我家的”不符。"}], "explanations": {"公交车": "语义：公交车属公共运营，不归家庭所有，与句首“我家的”相矛盾。", "私家车": "正确：“我家的”后接家庭自有的车，与“是白色的”搭配，句意通顺。", "警车": "搭配：“警车”属公安部门用车，不能说“我家的警车”。", "救护车": "语义：救护车是医疗急救用车，不是家庭私有的车，与“我家的”不符。"}, "sentence_index": 6, "correct_answer": "私家车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私家车在火灾现场灭火。", "explanation": "这里应该用〈消防车〉。私家车是个人自用的车，不用于灭火救援；灭火的专用车要说消防车。"}, {"text": "私家车在固定线路上每天运营。", "explanation": "这里应该用〈公交车〉。私家车不营业，不能按固定线路运营；定线运营的车要说公交车。"}, {"text": "私家车在马路上洒水降尘。", "explanation": "这里应该用〈洒水车〉。私家车只供个人或家庭自用，不用于洒水降尘；这类公用车辆要说洒水车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家新买了一条私家车。", "corrected_sentence": "我们家新买了一辆私家车。", "error_description": "量词错误：“私家车”是车辆，应用量词“辆”；“条”用于细长的东西，不能说“一条私家车”。正确说法是“一辆私家车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天吃私家车上班。", "corrected_sentence": "他每天坐私家车上班。", "error_description": "搭配错误：“吃”不能与交通工具搭配；“私家车”应与“坐”或“开”搭配，说“坐私家车上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1a61c3f-b874-4b6d-829e-6909ff95581d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低密度", "is_correct": true, "explanation": "反义：“高密度”指单位体积内物质多，“低密度”指物质少，二者构成反义。"}, {"text": "美丽", "is_correct": false, "explanation": "与“高密度”无反义关系，“美丽”形容外貌或景色的好看。"}, {"text": "清楚", "is_correct": false, "explanation": "与“高密度”无反义关系，“清楚”形容明白、不模糊。"}, {"text": "安静", "is_correct": false, "explanation": "与“高密度”无反义关系，“安静”形容声音或环境平和。"}], "correct_answer": "低密度", "explanations": {"低密度": "反义：“高密度”指单位体积内物质多，“低密度”指物质少，二者构成反义。", "美丽": "与“高密度”无反义关系，“美丽”形容外貌或景色的好看。", "清楚": "与“高密度”无反义关系，“清楚”形容明白、不模糊。", "安静": "与“高密度”无反义关系，“安静”形容声音或环境平和。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低密度", "is_correct": true, "explanation": "反义：“高密度”指单位体积内物质多，“低密度”指物质少，二者构成反义。"}, {"text": "缓慢", "is_correct": false, "explanation": "与“高密度”无反义关系，“缓慢”形容速度慢。"}, {"text": "柔软", "is_correct": false, "explanation": "与“高密度”无反义关系，“柔软”形容质地或触感。"}, {"text": "复杂", "is_correct": false, "explanation": "与“高密度”无反义关系，“复杂”形容事物头绪多、不简单。"}], "correct_answer": "低密度", "explanations": {"低密度": "反义：“高密度”指单位体积内物质多，“低密度”指物质少，二者构成反义。", "缓慢": "与“高密度”无反义关系，“缓慢”形容速度慢。", "柔软": "与“高密度”无反义关系，“柔软”形容质地或触感。", "复杂": "与“高密度”无反义关系，“复杂”形容事物头绪多、不简单。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指单位体积内包含的物质数量很大，或者事物分布很集中。", "primary_collocate": null, "pronunciation": "gāo mì dù", "ipa": "kau˥ mi˥˩ tu˥˩", "syllable_count": 3, "sentences": [{"text": "更为关键的是，在全生命周期碳核算框架下，公共交通即使计入车辆制造、能源生产与基础设施维护的隐含碳排放，其人均碳足迹仍较私家车通勤低达60%以上——这一数据在高密度城市语境中甚至可攀升至75%，凸显其在减缓全球气候变暖进程中的不可替代性。", "target_word": "高密度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种高密度材料比普通木头重得多。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铅是一种高密度的金属，拿起来很沉。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究高密度的固态电池。", "target_word": "高密度", "complexity_tier": "T3", "furigana": "kē xué jiā zhèng zài yán jiū gāo mì dù de gù tài diàn chí", "sentence_source": "generated"}, {"text": "高密度的星体会产生很强的引力。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块高密度板材很适合做家具。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种高密度泡沫比普通泡沫更结实。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高密度的金属放进水里会马上沉下去。", "target_word": "高密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用高密度聚乙烯制造水管。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高密度养殖区需要定期检查水质。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高密度聚乙烯", "label": "复合词"}], "register": "书面", "sense_fingerprint": "高密度：单位体积内物质多或分布集中，多作定语，书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高密度", "is_correct": true, "explanation": "正确：“高密度”修饰“城市语境”，指城市人口和建筑集中，与前文讨论的交通碳排放相合，句意通顺。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“速度”说的是运动或变化的快慢，不能用来修饰“城市语境”，句子说不通。"}, {"text": "高频", "is_correct": false, "explanation": "搭配：“频”指次数，不能修饰“城市语境”，此处说不通。"}, {"text": "高温", "is_correct": false, "explanation": "语义：“高温”指气温高，与句中讨论的人均碳足迹和公共交通无关，句子的逻辑被破坏。"}], "explanations": {"高密度": "正确：“高密度”修饰“城市语境”，指城市人口和建筑集中，与前文讨论的交通碳排放相合，句意通顺。", "高速": "搭配：“速度”说的是运动或变化的快慢，不能用来修饰“城市语境”，句子说不通。", "高频": "搭配：“频”指次数，不能修饰“城市语境”，此处说不通。", "高温": "语义：“高温”指气温高，与句中讨论的人均碳足迹和公共交通无关，句子的逻辑被破坏。"}, "sentence_index": 0, "correct_answer": "高密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡里的高密度咖啡因让人睡不着。", "explanation": "这里应该用〈高浓度〉。密度指单位体积内物质的质量，溶液或饮品中某种成分的多少要用浓度。"}, {"text": "这块金属的高密度让它在高温下不易变形。", "explanation": "这里应该用〈耐热〉。密度指单位体积内物质的多少，金属在高温下不变形要用耐热，二者不能互换。"}, {"text": "这种钢材的高密度让它能承受很大压力。", "explanation": "这里应该用〈高强度〉。强度指材料抵抗外力的能力，密度指单位体积的质量，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高密度", "is_correct": true, "explanation": "正确：“高密度泡沫”指单位体积内物质多的泡沫，这样的泡沫才能比普通泡沫更结实，句意通顺。"}, {"text": "低密度", "is_correct": false, "explanation": "语义：“低密度”指单位体积内物质少，与“更结实”的意思相矛盾。"}, {"text": "高效", "is_correct": false, "explanation": "搭配：“效率”说的是做事的成效，不能用来修饰泡沫的材质。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“速度”不用来描述材料的性质，此处说不通。"}], "explanations": {"高密度": "正确：“高密度泡沫”指单位体积内物质多的泡沫，这样的泡沫才能比普通泡沫更结实，句意通顺。", "低密度": "语义：“低密度”指单位体积内物质少，与“更结实”的意思相矛盾。", "高效": "搭配：“效率”说的是做事的成效，不能用来修饰泡沫的材质。", "高速": "搭配：“速度”不用来描述材料的性质，此处说不通。"}, "sentence_index": 6, "correct_answer": "高密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台仪器的高密度让测量结果更可靠。", "explanation": "这里应该用〈高精度〉。精度指测量的准确程度，密度指单位体积的质量，不能用来说测量结果可不可靠。"}, {"text": "这块石头的高密度让它很难被划伤。", "explanation": "这里应该用〈硬度〉。硬度指物体抵抗划伤和压入的能力，密度指单位体积内物质的多少，不能用来说石头是否难被划伤。"}, {"text": "这座塔的高密度让人惊叹。", "explanation": "这里应该用〈高度〉。高度指从底部到顶端的距离，密度指单位体积的质量，不能用来说塔有多高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块很高密度的合金非常结实。", "corrected_sentence": "这块高密度的合金非常结实。", "error_description": "错误形式“很高密度”：“高密度”本身已表示“单位体积内物质多”，是固定的形容词，不能再被“很”修饰。正确形式为“高密度的合金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块合金被高密度了，所以很耐磨。", "corrected_sentence": "这块合金变得高密度了，所以很耐磨。", "error_description": "错误形式“被高密度”：“被”字句要求动词，“高密度”是形容词，不能用于被动，应说“变得高密度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "反义：“攀升”指数值或温度不断升高，“下降”指向下减少，二者构成反义。"}, {"text": "停留", "is_correct": false, "explanation": "与“攀升”无反义关系，“停留”指暂时不动或留在某处。"}, {"text": "展开", "is_correct": false, "explanation": "与“攀升”无反义关系，“展开”指铺开或摊开。"}, {"text": "搬运", "is_correct": false, "explanation": "与“攀升”无反义关系，“搬运”指把东西从一处移到另一处。"}], "correct_answer": "下降", "explanations": {"下降": "反义：“攀升”指数值或温度不断升高，“下降”指向下减少，二者构成反义。", "停留": "与“攀升”无反义关系，“停留”指暂时不动或留在某处。", "展开": "与“攀升”无反义关系，“展开”指铺开或摊开。", "搬运": "与“攀升”无反义关系，“搬运”指把东西从一处移到另一处。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减少", "is_correct": true, "explanation": "反义：“攀升”指数量不断增长，“减少”指数量变少，二者构成反义。"}, {"text": "包含", "is_correct": false, "explanation": "与“攀升”无反义关系，“包含”指内部含有某些东西。"}, {"text": "漂浮", "is_correct": false, "explanation": "与“攀升”无反义关系，“漂浮”指浮在液体或空气中。"}, {"text": "装饰", "is_correct": false, "explanation": "与“攀升”无反义关系，“装饰”指把东西打扮得更好看。"}], "correct_answer": "减少", "explanations": {"减少": "反义：“攀升”指数量不断增长，“减少”指数量变少，二者构成反义。", "包含": "与“攀升”无反义关系，“包含”指内部含有某些东西。", "漂浮": "与“攀升”无反义关系，“漂浮”指浮在液体或空气中。", "装饰": "与“攀升”无反义关系，“装饰”指把东西打扮得更好看。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指向高处移动或增长，常用于描述价格、温度或数量的增加。", "primary_collocate": null, "pronunciation": "pān shēng", "ipa": "pʰan˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "今年夏天的气温不断攀升。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价在几年内一直攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月的苹果价格攀升了不少。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失业率连续三个月攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "随着天气变热，用电量快速攀升。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的销售额今年攀升到一百万。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油价攀升让很多司机很担心。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的考试成绩一路攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "气温攀升到了三十八度。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生人数逐年攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "攀升了", "label": "体标（了）"}, {"form": "攀升着", "label": "体标（着）"}, {"form": "攀升过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "攀升：价格、气温、数量等不断升高增长，多用于新闻书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攀升", "is_correct": true, "explanation": "正确：“攀升”指温度或数值不断升高，与“不断”搭配，符合句意。"}, {"text": "攀登", "is_correct": false, "explanation": "搭配：“攀登”指人或动物向高处爬，不能用来说气温的变化。"}, {"text": "奔跑", "is_correct": false, "explanation": "语义：“奔跑”指快速跑动，不能用来形容气温的变化，句子说不通。"}, {"text": "游荡", "is_correct": false, "explanation": "语义：“游荡”指漫无目的地走动，与气温持续上升的意思不符。"}], "explanations": {"攀升": "正确：“攀升”指温度或数值不断升高，与“不断”搭配，符合句意。", "攀登": "搭配：“攀登”指人或动物向高处爬，不能用来说气温的变化。", "奔跑": "语义：“奔跑”指快速跑动，不能用来形容气温的变化，句子说不通。", "游荡": "语义：“游荡”指漫无目的地走动，与气温持续上升的意思不符。"}, "sentence_index": 0, "correct_answer": "攀升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里的气温攀升，天气变得更冷了。", "explanation": "这里应该用〈下降〉。攀升指温度上升，天气变冷、温度降低要用下降，本句前后矛盾。"}, {"text": "他的口音一直攀升，听起来越来越重。", "explanation": "这里应该用〈加重〉。攀升用于价格、气温、数量等可量化的指标，口音的轻重要说加重。"}, {"text": "他的脚步逐渐攀升，跑步也越来越快。", "explanation": "这里应该用〈加快〉。攀升用于价格、气温、数量等可量化的指标，脚步的快慢要说加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攀升", "is_correct": true, "explanation": "正确：“油价攀升”指油价不断上涨，让司机担心，句意通顺。"}, {"text": "攀谈", "is_correct": false, "explanation": "搭配：“攀谈”指人与人交谈，不能用来说油价。"}, {"text": "飘扬", "is_correct": false, "explanation": "搭配：“飘扬”指旗帜等在空中摆动，不能用来描述油价。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，不能用来形容油价，句子说不通。"}], "explanations": {"攀升": "正确：“油价攀升”指油价不断上涨，让司机担心，句意通顺。", "攀谈": "搭配：“攀谈”指人与人交谈，不能用来说油价。", "飘扬": "搭配：“飘扬”指旗帜等在空中摆动，不能用来描述油价。", "干燥": "语义：“干燥”指缺少水分，不能用来形容油价，句子说不通。"}, "sentence_index": 6, "correct_answer": "攀升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汗水一天天攀升。", "explanation": "这里应该用〈增多〉。攀升用于价格、气温、数量等可量化的指标，汗水变多要说增多。"}, {"text": "这个小区的脏乱一天天攀升。", "explanation": "这里应该用〈加剧〉。攀升用于可量化的指标，脏乱程度加重要说加剧。"}, {"text": "他的工作节奏攀升了。", "explanation": "这里应该用〈加快〉。攀升用于数量或价格，节奏的变化要说加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的电费被攀升了。", "corrected_sentence": "夏天的电费攀升了。", "error_description": "错误形式“被攀升”：“攀升”是不及物动词，没有被动用法，前面不能加“被”。正确形式为“电费攀升了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司把成本攀升到了一百万。", "corrected_sentence": "这家公司的成本攀升到了一百万。", "error_description": "错误形式“把成本攀升”：“攀升”是不及物动词，不能用于“把”字句，应说“成本攀升到了一百万”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
