INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "清楚地显示出来，让人容易注意到。", "primary_collocate": null, "pronunciation": "tū xiǎn", "ipa": "tʰu˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种从自然智慧中汲取灵感的跨学科探索，进一步凸显了保护昆虫多样性的深远意义。", "target_word": "凸显", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件事凸显了他的责任心。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，他的速度优势凸显出来。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试凸显了他的学习短板。", "target_word": "凸显", "complexity_tier": "T3", "furigana": "zhè cì kǎo shì tū xiǎn le tā de xué xí duǎn bǎn.", "sentence_source": "generated"}, {"text": "数据凸显了问题的严重性。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难面前，普通人的勇气更加凸显。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事凸显了家人之间的爱。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策凸显出政府对教育的重视。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的优点在困难中凸显出来了。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图表生动地凸显了两国的差距。", "target_word": "凸显", "complexity_tier": "T3", "furigana": "zhè xiē tú biǎo shēng dòng de tū xiǎn le liǎng guó de chā jù.", "sentence_source": "generated"}], "morphological_forms": [{"form": "凸顯", "label": "繁体"}, {"form": "凸显了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "凸显|把某种特点或意义清楚地显示出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凸显", "is_correct": true, "explanation": "正确：“凸显”表示清楚地显示出来，与“深远意义”的语境相合。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“凸显”的显示义相反，与“进一步”的强调语气矛盾。"}, {"text": "削弱", "is_correct": false, "explanation": "语义：“削弱”意义与“深远意义”冲突，前后语义不一致。"}, {"text": "凸起", "is_correct": false, "explanation": "搭配：“凸起”指物体表面鼓起，不用于抽象的意义，搭配不当。"}], "explanations": {"凸显": "正确：“凸显”表示清楚地显示出来，与“深远意义”的语境相合。", "隐藏": "语义：“隐藏”与“凸显”的显示义相反，与“进一步”的强调语气矛盾。", "削弱": "语义：“削弱”意义与“深远意义”冲突，前后语义不一致。", "凸起": "搭配：“凸起”指物体表面鼓起，不用于抽象的意义，搭配不当。"}, "sentence_index": 0, "correct_answer": "凸显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他凸显了一场考试。", "explanation": "这里应该用〈举行〉。“凸显”指清楚地显示出来，不能表示组织考试，组织考试应说举行。"}, {"text": "他凸显了一顿晚饭。", "explanation": "这里应该用〈吃〉。“凸显”指清楚地显示出来，不能表示吃饭，吃晚饭应说吃。"}, {"text": "妈妈凸显了一件毛衣。", "explanation": "这里应该用〈织〉。“凸显”指清楚地显示出来，不能表示编织，织一件毛衣应说织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凸显", "is_correct": true, "explanation": "正确：“凸显”表示清楚地显示出来，与“家人之间的爱”的语境相合。"}, {"text": "掩饰", "is_correct": false, "explanation": "语义：“掩饰”是遮盖真实情感，与“故事”要表现的爱相矛盾。"}, {"text": "点缀", "is_correct": false, "explanation": "搭配：“点缀”多用于景物，不接抽象的“爱”作宾语，搭配不当。"}, {"text": "分隔", "is_correct": false, "explanation": "语义：“分隔”使东西分开，与“家人之间的爱”所表达的联结相反。"}], "explanations": {"凸显": "正确：“凸显”表示清楚地显示出来，与“家人之间的爱”的语境相合。", "掩饰": "语义：“掩饰”是遮盖真实情感，与“故事”要表现的爱相矛盾。", "点缀": "搭配：“点缀”多用于景物，不接抽象的“爱”作宾语，搭配不当。", "分隔": "语义：“分隔”使东西分开，与“家人之间的爱”所表达的联结相反。"}, "sentence_index": 6, "correct_answer": "凸显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块田的庄稼被大雨凸显了。", "explanation": "这里应该用〈冲走〉。“凸显”指清楚地显示出来，庄稼被雨水带走要说冲走，不能说凸显。"}, {"text": "司机凸显了一杯咖啡。", "explanation": "这里应该用〈喝〉。“凸显”指清楚地显示出来，不能表示饮用，喝咖啡应说喝。"}, {"text": "他凸显了一块饼干。", "explanation": "这里应该用〈吃〉。“凸显”指清楚地显示出来，不能表示吃东西，吃饼干应说吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛凸显去他的速度优势。", "corrected_sentence": "这次比赛凸显出他的速度优势。", "error_description": "趋向补语错误：应说“凸显出”，不能说“凸显去”。“出”表示显露出来，“去”表示向离开的方向，与“凸显”的意思不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张地图清楚的凸显了山脉的走向。", "corrected_sentence": "这张地图清楚地凸显了山脉的走向。", "error_description": "“清楚”修饰动词“凸显”，作状语要用“地”，不能用“的”，应改为“清楚地凸显”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变冷", "is_correct": true, "explanation": "「变冷」指温度下降，与「变暖」构成反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "「保护」与「变暖」既不反义也不近义，不是答案。"}, {"text": "扩大", "is_correct": false, "explanation": "「扩大」与「变暖」没有反义关系，不是答案。"}, {"text": "出现", "is_correct": false, "explanation": "「出现」与「变暖」没有反义关系，不是答案。"}], "correct_answer": "变冷", "explanations": {"变冷": "「变冷」指温度下降，与「变暖」构成反义关系。", "保护": "「保护」与「变暖」既不反义也不近义，不是答案。", "扩大": "「扩大」与「变暖」没有反义关系，不是答案。", "出现": "「出现」与「变暖」没有反义关系，不是答案。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变冷", "is_correct": true, "explanation": "「变冷」指温度下降，与「变暖」构成反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "「收拾」与「变暖」没有反义关系，不是答案。"}, {"text": "复习", "is_correct": false, "explanation": "「复习」与「变暖」没有反义关系，不是答案。"}, {"text": "散步", "is_correct": false, "explanation": "「散步」与「变暖」没有反义关系，不是答案。"}], "correct_answer": "变冷", "explanations": {"变冷": "「变冷」指温度下降，与「变暖」构成反义关系。", "收拾": "「收拾」与「变暖」没有反义关系，不是答案。", "复习": "「复习」与「变暖」没有反义关系，不是答案。", "散步": "「散步」与「变暖」没有反义关系，不是答案。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "温度升高，通常指气候或环境温度上升。", "primary_collocate": null, "pronunciation": "biàn nuǎn", "ipa": "pjɛn˥˩ nwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "更为关键的是，在全生命周期碳核算框架下，公共交通即使计入车辆制造、能源生产与基础设施维护的隐含碳排放，其人均碳足迹仍较私家车通勤低达60%以上——这一数据在高密度城市语境中甚至可攀升至75%，凸显其在减缓全球气候变暖进程中的不可替代性。", "target_word": "变暖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "面对全球变暖加剧、降水模式日益不稳定的现实，现代水资源管理正面临前所未有的挑战。", "target_word": "变暖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "全球变暖让冰川越来越少。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家担心地球会继续变暖。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气候变暖，海平面升高了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近几十年，北极变暖的速度很快。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球变暖对农业有很大影响。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水变暖以后，鱼的数量少了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水变暖会让台风变得更强。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，今年的气候明显变暖了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變暖", "label": "繁体"}, {"form": "变暖了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "变暖|气候或环境的温度逐渐上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变暖", "is_correct": true, "explanation": "「变暖」指温度上升，与「减缓全球气候……进程」及「全球气候」的语境相符。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：「冷却」指温度下降，与「减缓……进程」的目标正相反，句意不通。"}, {"text": "保护", "is_correct": false, "explanation": "语义：「保护」是对具体对象的护理，不能用来修饰「进程」，与「减缓……进程」句意不合。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：「隔离」指使分开，「减缓全球气候隔离进程」的句意不合。"}], "explanations": {"变暖": "「变暖」指温度上升，与「减缓全球气候……进程」及「全球气候」的语境相符。", "冷却": "语义：「冷却」指温度下降，与「减缓……进程」的目标正相反，句意不通。", "保护": "语义：「保护」是对具体对象的护理，不能用来修饰「进程」，与「减缓……进程」句意不合。", "隔离": "语义：「隔离」指使分开，「减缓全球气候隔离进程」的句意不合。"}, "sentence_index": 0, "correct_answer": "变暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海平面变暖了。", "explanation": "这里应该用〈升高〉。「变暖」指温度上升，说海平面的高低要用〈升高〉。"}, {"text": "冰川的面积变暖了。", "explanation": "这里应该用〈减少〉。「变暖」只描述温度变化，说冰川的面积变化要用〈减少〉。"}, {"text": "这个班的人数变暖了。", "explanation": "这里应该用〈增加〉。「变暖」只说温度上升，人数的变化要用〈增加〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐烂", "is_correct": false, "explanation": "搭配：「腐烂」用于食物、有机物，不说地球腐烂。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：「咳嗽」是人或动物的生理动作，地球不会咳嗽。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：「失眠」指人睡不着，用在「地球」身上句意不通。"}, {"text": "变暖", "is_correct": true, "explanation": "「变暖」指地球温度升高、影响农业，符合语境。"}], "explanations": {"腐烂": "搭配：「腐烂」用于食物、有机物，不说地球腐烂。", "咳嗽": "语义：「咳嗽」是人或动物的生理动作，地球不会咳嗽。", "失眠": "语义：「失眠」指人睡不着，用在「地球」身上句意不通。", "变暖": "「变暖」指地球温度升高、影响农业，符合语境。"}, "sentence_index": 6, "correct_answer": "变暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的失业率变暖了。", "explanation": "这里应该用〈下降〉。「变暖」只说温度上升，失业率的变化要用〈下降〉。"}, {"text": "这片森林的面积变暖了。", "explanation": "这里应该用〈扩大〉。「变暖」只用于温度，说森林面积的变化要用〈扩大〉。"}, {"text": "这个城市的人口变暖得很快。", "explanation": "这里应该用〈增长〉。「变暖」只说温度上升，人口的变化要用〈增长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近几年，北极的气候变暖了很快。", "corrected_sentence": "近几年，北极的气候变暖得很快。", "error_description": "补语错误：程度补语要用“得”连接，应说“变暖得很快”，不能说“变暖了很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，地球变暖的很厉害，冰川也在减少。", "corrected_sentence": "这几年，地球变暖得很厉害，冰川也在减少。", "error_description": "补语错误：程度补语前要用“得”，不能用“的”，应说“变暖得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
