INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某事物可以代替另一事物使用的特性。", "primary_collocate": null, "pronunciation": "tì dài xìng", "ipa": "tʰi˥˩ taɪ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "更为关键的是，在全生命周期碳核算框架下，公共交通即使计入车辆制造、能源生产与基础设施维护的隐含碳排放，其人均碳足迹仍较私家车通勤低达60%以上——这一数据在高密度城市语境中甚至可攀升至75%，凸显其在减缓全球气候变暖进程中的不可替代性。", "target_word": "替代性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种塑料的替代性很强，可以用在很多地方。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机对电脑有一定的替代性。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石油的替代性很弱，各国都很重视它。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种药的替代性很高，医生可以任选一种。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子书对纸质书的替代性越来越强。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种零件的替代性很差，坏了只能买原来的。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同类产品的替代性高，价格竞争很激烈。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能对煤炭的替代性正在提高。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司选材料时会先考虑替代性。", "target_word": "替代性", "complexity_tier": "T3", "furigana": "gōng sī xuǎn cái liào shí huì xiān kǎo lǜ tì dài xìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可替代性", "label": "复合词"}], "register": "书面", "sense_fingerprint": "替代性：一事物能代替另一事物使用的特性，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替代性", "is_correct": true, "explanation": "替代性：可以代替另一事物使用的特性。此处为“不可替代性”的组成部分，指无法被取代。"}, {"text": "必要性", "is_correct": false, "explanation": "搭配：“不可必要性”不成词，且句意说的是能否代替，而非是否需要。"}, {"text": "紧迫性", "is_correct": false, "explanation": "搭配：“不可紧迫性”不成词，句意与紧迫无关。"}, {"text": "稳定性", "is_correct": false, "explanation": "语义：“稳定性”指不易变化，句意说的是一事物能否代替另一事物，两者不符。"}], "explanations": {"替代性": "替代性：可以代替另一事物使用的特性。此处为“不可替代性”的组成部分，指无法被取代。", "必要性": "搭配：“不可必要性”不成词，且句意说的是能否代替，而非是否需要。", "紧迫性": "搭配：“不可紧迫性”不成词，句意与紧迫无关。", "稳定性": "语义：“稳定性”指不易变化，句意说的是一事物能否代替另一事物，两者不符。"}, "sentence_index": 0, "correct_answer": "替代性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块屏幕的替代性很暗，夜里看不清字。", "explanation": "这里应该用〈亮度〉。亮度指发光的明暗程度，替代性指能否代替，不能用“暗”来形容。"}, {"text": "这种电池的替代性很长，用得很久。", "explanation": "这里应该用〈寿命〉。寿命指使用的期限，替代性是能否代替的特性，不能说“长”。"}, {"text": "这种药的替代性很便宜，穷人也买得起。", "explanation": "这里应该用〈价格〉。价格指价钱的高低，替代性不能用“便宜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替代性", "is_correct": true, "explanation": "替代性：可以代替另一事物使用的特性。此处指零件能否被其他零件代替。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物或气体的滋味，零件不能说有味道的好坏，句子不通。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“差”用于说质量或性能，不说“数量很差”。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语，指窍门或内情，与书面的专业描述语体不协调，且不能说零件的门道差。"}], "explanations": {"替代性": "替代性：可以代替另一事物使用的特性。此处指零件能否被其他零件代替。", "味道": "语义：“味道”指食物或气体的滋味，零件不能说有味道的好坏，句子不通。", "数量": "搭配：“差”用于说质量或性能，不说“数量很差”。", "门道": "语域：“门道”是口语，指窍门或内情，与书面的专业描述语体不协调，且不能说零件的门道差。"}, "sentence_index": 6, "correct_answer": "替代性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的替代性很鲜艳，适合夏天穿。", "explanation": "这里应该用〈颜色〉。颜色指物体的色彩，替代性指能否代替，不能用“鲜艳”来形容。"}, {"text": "这道菜的替代性很咸，我吃了一碗饭。", "explanation": "这里应该用〈味道〉。味道指食物入口后的滋味，替代性不能用“咸”来形容。"}, {"text": "这位歌手的替代性很清脆，听了很舒服。", "explanation": "这里应该用〈音色〉。音色指声音的质地，替代性不能用“清脆”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种材料的替代性强很，换成别的也能用。", "corrected_sentence": "这种材料的替代性很强，换成别的也能用。", "error_description": "错误形式“强很”：“很”是程度副词，应放在形容词“强”之前，应说“很强”，不能说“强很”。", "correct_sentence_indices": [1, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师在设计时会重点考虑替代性很。", "corrected_sentence": "工程师在设计时会重点考虑替代性。", "error_description": "错误形式“替代性很”：“很”是程度副词，不能直接放在名词“替代性”后面作谓语，句子说不完整，应删去“很”，说“考虑替代性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
