INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指观察或认识问题时所涉及的范围或角度。", "primary_collocate": null, "pronunciation": "shì yù", "ipa": "ʂɻ̩˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "从城市规划的宏观视阈审视，公共交通导向型开发（TOD）模式已从理论构想升华为全球大都市空间重构的核心范式。", "target_word": "视阈", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从历史的视阈来看，这个问题并不新鲜。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书可以拓宽我们的视阈。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从经济视阈分析，这项政策对小企业有利。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换一个视阈，你会发现不同的答案。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望我们打开视阈，不要只看分数。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化视阈不同，人们对礼貌的理解也不同。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳出个人的视阈，才能看到整个社会的变化。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者把研究视阈扩大到了海洋领域。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书给读者带来了全新的视阈。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "視閾", "label": "繁体"}], "register": "书面", "sense_fingerprint": "视阈：观察问题的范围或角度（抽象的视野）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11757, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视阈", "is_correct": true, "explanation": "视阈：shì yù，指观察问题的范围或角度。"}, {"text": "食欲", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是食欲，胃口。"}, {"text": "事务", "is_correct": false, "explanation": "yù（ü）与 wù（u）韵母不同，意思是事务。"}, {"text": "事宜", "is_correct": false, "explanation": "yù 与 yí 韵母不同，意思是事宜，指各种具体安排。"}], "explanations": {"视阈": "视阈：shì yù，指观察问题的范围或角度。", "食欲": "shí（第二声）与 shì（第四声）声调不同，意思是食欲，胃口。", "事务": "yù（ü）与 wù（u）韵母不同，意思是事务。", "事宜": "yù 与 yí 韵母不同，意思是事宜，指各种具体安排。"}, "sentence_index": null, "correct_answer": "视阈"}, "level_3": {"options": [{"text": "视阈", "is_correct": true, "explanation": "视阈：观察问题的范围或角度。与“宏观”搭配，表示审视问题的视角范围。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“宏观”修饰视野、尺度等抽象对象，不说“宏观味道”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是可见的色彩属性，不能作为审视的角度，句子不通。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语，指窍门，与书面的“宏观……审视”语体不协调。"}], "explanations": {"视阈": "视阈：观察问题的范围或角度。与“宏观”搭配，表示审视问题的视角范围。", "味道": "搭配：“宏观”修饰视野、尺度等抽象对象，不说“宏观味道”。", "颜色": "语义：“颜色”是可见的色彩属性，不能作为审视的角度，句子不通。", "门道": "语域：“门道”是口语，指窍门，与书面的“宏观……审视”语体不协调。"}, "sentence_index": 0, "correct_answer": "视阈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶的视阈很烫，喝的时候要小心。", "explanation": "这里应该用〈温度〉。温度指冷热的程度，视阈指观察的范围或角度，不能用“烫”来形容。"}, {"text": "这幅画的视阈很鲜艳，挂在客厅很好看。", "explanation": "这里应该用〈颜色〉。颜色指物体的色彩，视阈指观察的范围或角度，不能用“鲜艳”来形容。"}, {"text": "这块石头的视阈很轻，一只手就能拿起来。", "explanation": "这里应该用〈重量〉。重量指物体的轻重，视阈指观察的范围或角度，不能用“轻”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视阈", "is_correct": true, "explanation": "视阈：观察问题的范围或角度。此处指不同文化各自的看问题的角度。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高度，不能用来说明文化之间的差别。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”一般说物体的轻重，不与“文化”搭配。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”指绘画用的色料，与文化的差异无关，句子不通。"}], "explanations": {"视阈": "视阈：观察问题的范围或角度。此处指不同文化各自的看问题的角度。", "身高": "语义：“身高”指人的高度，不能用来说明文化之间的差别。", "重量": "搭配：“重量”一般说物体的轻重，不与“文化”搭配。", "颜料": "语义：“颜料”指绘画用的色料，与文化的差异无关，句子不通。"}, "sentence_index": 6, "correct_answer": "视阈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的视阈很咸，我喝了一半。", "explanation": "这里应该用〈味道〉。味道指食物入口后的滋味，视阈指观察的范围或角度，不能用“咸”来形容。"}, {"text": "这瓶香水的视阈很浓，喷多了很刺鼻。", "explanation": "这里应该用〈气味〉。气味指物体散发的味道，视阈指观察的范围或角度，不能用“浓”来形容。"}, {"text": "这块布的视阈很粗，摸起来扎手。", "explanation": "这里应该用〈质地〉。质地指材料本身的结构或手感，视阈指观察的范围或角度，不能用“粗”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该视阈拓宽，多了解不同的领域。", "corrected_sentence": "我们应该把视阈拓宽，多了解不同的领域。", "error_description": "“把”字句中，“把”应放在处置对象“视阈”之前，应说“把视阈拓宽”。缺少“把”，直接说“视阈拓宽”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行让他的视阈拓宽很大。", "corrected_sentence": "这次旅行让他的视阈拓宽得很大。", "error_description": "补语要用“得”引出，应说“拓宽得很大”。省去“得”，“拓宽很大”不成立，补语前必须有“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
