INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11759, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从无到有地创造出新事物，或者把隐藏的东西呈现出来，比如造房子、做软件。", "primary_collocate": null, "pronunciation": "kāi fā", "ipa": "kʰai˥ fa˥", "syllable_count": 2, "sentences": [{"text": "他们公司正在开发一个新的手机软件。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想开发一款适合孩子的学习游戏。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每个人都有需要开发的潜力。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组用了三个月开发这套系统。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想开发一个帮助老人买菜的小程序。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师们已经开发出了第一版软件。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把开发新系统的任务交给了小王。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习编程以后，我也想自己开发游戏。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算开发一个新的小区。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的软件需要工程师认真开发和测试。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开发了", "label": "体标"}, {"form": "开发过", "label": "体标"}, {"form": "开发着", "label": "体标"}, {"form": "开发者", "label": "复合"}, {"form": "開發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开发：从无到有创造（软件、楼盘），或挖掘出潜力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11759, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确答案：开发（kāi fā），指从无到有地创造新事物。"}, {"text": "开放", "is_correct": false, "explanation": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。"}, {"text": "开方", "is_correct": false, "explanation": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学中的开平方、开立方）。"}, {"text": "开花", "is_correct": false, "explanation": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。"}, {"text": "开伐", "is_correct": false, "explanation": "fá（第二声）与 fā（第一声）声调不同，意思是砍伐树木。"}], "explanations": {"开发": "正确答案：开发（kāi fā），指从无到有地创造新事物。", "开放": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。", "开方": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学中的开平方、开立方）。", "开花": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。", "开伐": "fá（第二声）与 fā（第一声）声调不同，意思是砍伐树木。"}, "sentence_index": null, "correct_answer": "开发"}, "level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发”指从无到有地研制软件，与“手机软件”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”只能指进食，软件不能被吃。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”用于植物或种子，不能说种软件。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体受热变成液体，不能用来指研制软件。"}], "explanations": {"开发": "正确：“开发”指从无到有地研制软件，与“手机软件”搭配，符合句意。", "吃": "语义：“吃”只能指进食，软件不能被吃。", "种": "搭配：“种”用于植物或种子，不能说种软件。", "融化": "语义：“融化”指固体受热变成液体，不能用来指研制软件。"}, "sentence_index": 0, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们用了三个月开发这座大桥。", "explanation": "这里应该用〈建造〉。开发多指研制软件、产品或开拓楼盘、资源，修建桥梁要用建造。"}, {"text": "这家工厂一年开发了十万辆汽车。", "explanation": "这里应该用〈制造〉。开发指研制新产品，不指大批量生产，批量造汽车要用制造。"}, {"text": "作家用了三年开发这部小说。", "explanation": "这里应该用〈写〉。开发用于研制、开拓，不用于创作文学作品，写小说要用写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发新系统”指研制新系统，与“新系统”搭配，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指加热或焚烧，不能说烧新系统的任务。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“新系统”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语多是衣物、身体等，不能说洗新系统。"}], "explanations": {"开发": "正确：“开发新系统”指研制新系统，与“新系统”搭配，符合句意。", "烧": "语义：“烧”指加热或焚烧，不能说烧新系统的任务。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“新系统”作宾语。", "洗": "搭配：“洗”的宾语多是衣物、身体等，不能说洗新系统。"}, "sentence_index": 6, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片山林被人乱开发，动物越来越少。", "explanation": "这句话用的是“过度、盲目利用自然资源”的意思，与本词“从无到有地研制新事物”的意思不同。"}, {"text": "这座山已经被开发得只剩下石头了。", "explanation": "这句话用的是“开采矿产等资源”的意思，与本词“研制、创造新事物”的意思不同。"}, {"text": "这片湿地被人开发以后，鸟都飞走了。", "explanation": "这句话用的是“开垦、占用土地”的意思，与本词“研制、创造新事物”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们正在开发了一个新的学习软件。", "corrected_sentence": "他们正在开发一个新的学习软件。", "error_description": "错误：“正在”表示动作进行中，与表示完成的“了”不能同用。应删去“开发”后的“了”，说“他们正在开发一个新的学习软件。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们还没开发了这个新软件。", "corrected_sentence": "我们还没开发这个新软件。", "error_description": "错误：否定句中“没”与“了”不能同用，“没开发了”应改为“没开发”。应说“我们还没开发这个新软件。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11760, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
