INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某事物的初步设想或构思。", "primary_collocate": null, "pronunciation": "gòu xiǎng", "ipa": "kou̯˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "设计师正在构想一座新的图书馆。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写小说以前，他先构想了故事的结局。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起构想一下未来的校园生活吧。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她早就构想好了这次旅行的路线。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师构想过一种不用电的灯。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们构想自己十年后的样子。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画图，慢慢构想新家的样子。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把这个项目构想出一个大概的轮廓。", "target_word": "构想", "complexity_tier": "T3", "furigana": "wǒ men xiān bǎ zhè ge xiàng mù gòu xiǎng chū yí ge dà gài de lún kuò", "sentence_source": "generated"}, {"text": "导演构想了很久，才决定拍这个故事。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在构想怎样建一座沙堡。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "构想了", "label": "体标"}, {"form": "构想过", "label": "体标"}, {"form": "構想", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：对尚未做的事物进行初步设想、构思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "构想", "is_correct": true, "explanation": "正确：“构想”指对尚未建成的事物进行初步设想，与设计师的工作相符。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象多为污渍或物件，一座新的图书馆不能被“清洗”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉已有的建筑，与“新的图书馆”和设计工作相矛盾。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：“梦见”指睡梦中出现的景象，不是设计师正在做的工作。"}], "explanations": {"构想": "正确：“构想”指对尚未建成的事物进行初步设想，与设计师的工作相符。", "清洗": "搭配：“清洗”的对象多为污渍或物件，一座新的图书馆不能被“清洗”。", "拆除": "语义：“拆除”指拆掉已有的建筑，与“新的图书馆”和设计工作相矛盾。", "梦见": "语义：“梦见”指睡梦中出现的景象，不是设计师正在做的工作。"}, "sentence_index": 0, "correct_answer": "构想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正在构想这个方案的可行性。", "explanation": "这里应该用〈考虑〉。构想是对尚未做的事物进行初步设想，衡量方案是否可行应用〈考虑〉。"}, {"text": "学生们正在构想课文，一会儿就要考试了。", "explanation": "这里应该用〈背诵〉。构想针对尚未做的事情，不用于记忆已有的课文；背课文应用〈背诵〉。"}, {"text": "他仔细构想了昨天晚饭的菜色。", "explanation": "这里应该用〈回忆〉。构想是对尚未做的事物进行设想，回想已经发生的事应用〈回忆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构想", "is_correct": true, "explanation": "正确：“构想”指在纸上画图前先在头脑中设想新家的样子，与语境相符。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”是用相机记录影像，与“在纸上画图”的手绘方式相冲突。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”针对可以量化的尺寸，不能用于“样子”这类外观。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”的对象是文件或内容，不能用于“新家的样子”。"}], "explanations": {"构想": "正确：“构想”指在纸上画图前先在头脑中设想新家的样子，与语境相符。", "拍摄": "语义：“拍摄”是用相机记录影像，与“在纸上画图”的手绘方式相冲突。", "测量": "搭配：“测量”针对可以量化的尺寸，不能用于“样子”这类外观。", "删除": "搭配：“删除”的对象是文件或内容，不能用于“新家的样子”。"}, "sentence_index": 6, "correct_answer": "构想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仔细构想蚂蚁的路线。", "explanation": "这里应该用〈观察〉。构想是对尚未做的事物进行设想，观察的是已经存在的蚂蚁，应用〈观察〉。"}, {"text": "医生在构想病人的心脏。", "explanation": "这里应该用〈检查〉。构想不用于已经存在的身体器官，给病人心脏做诊断应用〈检查〉。"}, {"text": "妈妈在构想厨房里的碗筷。", "explanation": "这里应该用〈清洗〉。构想是对尚未做的事物进行设想，洗碗筷这类已存在的事情应用〈清洗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先构想了出这个游戏的规则。", "corrected_sentence": "他先构想出了这个游戏的规则。", "error_description": "错误：结果补语“出”放错了位置，“构想了出”语序不对。正确：“构想出了”。结果补语必须紧跟动词，之后再接“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们构想了过一个新的游戏方案。", "corrected_sentence": "我们构想过一个新的游戏方案。", "error_description": "错误：“构想”后同时用了“了”和“过”。正确：“构想过”。“过”表示曾经有过的经历，不与表示完成的“了”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
