INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11761, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指规模很大、人口众多、经济和文化都很发达的城市。", "primary_collocate": null, "pronunciation": "dà dū shì", "ipa": "ta˥˩ tu˥ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "从城市规划的宏观视阈审视，公共交通导向型开发（TOD）模式已从理论构想升华为全球大都市空间重构的核心范式。", "target_word": "大都市", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在当代大都市的发展图景中，城市绿地与垂直农场已超越其单纯的生态功能，演变为重塑经济地理格局的战略性要素。", "target_word": "大都市", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "上海是中国人口最多的大都市之一。", "target_word": "大都市", "complexity_tier": "T3", "furigana": "shàng hǎi shì zhōng guó rén kǒu zuì duō de dà dū shì zhī yī", "sentence_source": "generated"}, {"text": "这座大都市的交通很方便，地铁到处都是。", "target_word": "大都市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人毕业后想去大都市工作。", "target_word": "大都市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大都市里的房价比小城市高得多。", "target_word": "大都市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东京是世界有名的大都市，人口超过一千万。", "target_word": "大都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小住在小镇，第一次来到大都市，觉得什么都新鲜。", "target_word": "大都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大都市的夜晚灯光明亮，街上还有很多人。", "target_word": "大都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大都市每天有几百万人坐地铁上班。", "target_word": "大都市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "规模大、人口多、经济文化发达的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bf87788-5a50-449d-91ed-9ab27df85da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小城镇", "is_correct": false, "explanation": "语义：小城镇规模小，与“全球”的范围以及“核心范式”的地位相冲突。"}, {"text": "农村", "is_correct": false, "explanation": "语义：农村不是城市，与前文的“城市规划”和“公共交通导向型开发”不相符。"}, {"text": "乡下", "is_correct": false, "explanation": "语域：“乡下”是口语说法，与这段书面论述的正式语体不协调；它指乡村，也与“全球……空间重构”的城市语境相冲突。"}, {"text": "大都市", "is_correct": true, "explanation": "大都市指规模很大、人口众多、经济和文化都很发达的城市，与全球空间重构的语境相符。"}], "explanations": {"小城镇": "语义：小城镇规模小，与“全球”的范围以及“核心范式”的地位相冲突。", "农村": "语义：农村不是城市，与前文的“城市规划”和“公共交通导向型开发”不相符。", "乡下": "语域：“乡下”是口语说法，与这段书面论述的正式语体不协调；它指乡村，也与“全球……空间重构”的城市语境相冲突。", "大都市": "大都市指规模很大、人口众多、经济和文化都很发达的城市，与全球空间重构的语境相符。"}, "sentence_index": 0, "correct_answer": "大都市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只大都市的交通很方便，地铁到处都是。", "explanation": "这里应该用〈座〉。〈只〉多用于动物，大都市是城市，要用〈座〉或〈个〉来计量。"}, {"text": "这本大都市的交通很方便，地铁到处都是。", "explanation": "这里应该用〈座〉。〈本〉用于书籍、册子，不能用来数城市。"}, {"text": "这条大都市的交通很方便，地铁到处都是。", "explanation": "这里应该用〈座〉。〈条〉多用于长条形的东西，如河流、道路，大都市不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小镇", "is_correct": false, "explanation": "语义：小镇规模小、人口少，与“人口超过一千万”的说法矛盾。"}, {"text": "村庄", "is_correct": false, "explanation": "语义：村庄的人口和规模都与“世界有名”及“人口超过一千万”不相符。"}, {"text": "小地方", "is_correct": false, "explanation": "语域：“小地方”偏口语，且表示规模小，与“人口超过一千万”的客观陈述不协调。"}, {"text": "大都市", "is_correct": true, "explanation": "大都市指规模很大、人口众多的城市，与东京的情况相符。"}], "explanations": {"小镇": "语义：小镇规模小、人口少，与“人口超过一千万”的说法矛盾。", "村庄": "语义：村庄的人口和规模都与“世界有名”及“人口超过一千万”不相符。", "小地方": "语域：“小地方”偏口语，且表示规模小，与“人口超过一千万”的客观陈述不协调。", "大都市": "大都市指规模很大、人口众多的城市，与东京的情况相符。"}, "sentence_index": 6, "correct_answer": "大都市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座小大都市每天只有几十个人坐地铁上班。", "explanation": "这里应该用〈小城市〉。〈大都市〉指规模很大、人口众多的城市，不能用来指小城市，“小大都市”自相矛盾。"}, {"text": "很小的大都市每天只有几十个人坐地铁上班。", "explanation": "这里应该用〈小城镇〉。〈大都市〉指规模很大的城市，不能用来形容小城镇。"}, {"text": "这座不大的大都市每天只有几十个人坐地铁上班。", "explanation": "这里应该用〈中小城市〉。〈大都市〉规模很大，不能用“不大”来形容它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下个月要搬到一只大都市工作。", "corrected_sentence": "我下个月要搬到一座大都市工作。", "error_description": "量词错误：大都市是城市，应用量词“座”。“只”多用于动物，不能用来数城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他毕业后一直住大都市里。", "corrected_sentence": "他毕业后一直住在大都市里。", "error_description": "介词缺失：表示居住的地点要说“住在……里”，“住大都市里”少了“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
