INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11762, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指可以容纳很大体积或很多数量的物体。", "primary_collocate": null, "pronunciation": "gāo róng liàng", "ipa": "kɑu̯˥ ɻʊŋ˧˥ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这座高容量站点每天能运送大量乘客。", "target_word": "高容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了扩大存储能力，公司购入了一批高容量硬盘。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "wèi le kuò dà cún chǔ néng lì, gōng sī gòu rù le yì pī gāo róng liàng yìng pán", "sentence_source": "generated"}, {"text": "这台高容量服务器一次可以处理大量数据。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè tái gāo róng liàng fú wù qì yí cì kě yǐ chǔ lǐ dà liàng shù jù", "sentence_source": "generated"}, {"text": "这座高容量仓库可以放上万箱货物。", "target_word": "高容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的地铁线路采用了高容量列车。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "xīn jiàn de dì tiě xiàn lù cǎi yòng le gāo róng liàng liè chē", "sentence_source": "generated"}, {"text": "这套储能系统采用了高容量电池。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè tào chǔ néng xì tǒng cǎi yòng le gāo róng liàng diàn chí", "sentence_source": "generated"}, {"text": "码头需要高容量的运输船来运货。", "target_word": "高容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种高容量水箱够全家用一个星期。", "target_word": "高容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府打算多买些高容量公交车。", "target_word": "高容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高容量冷藏车能把大量水果运到外地。", "target_word": "高容量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "定语：运输、仓储等设施或工具能容纳大体积或大数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高容量", "is_correct": true, "explanation": "正确：“高容量”指能容纳大量乘客，与“运送大量乘客”的语境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外观，与站点能容纳多少人无关。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：“清洁”描述卫生状况，与站点能否运送大量乘客无关。"}, {"text": "高温", "is_correct": false, "explanation": "语义：“高温”描述温度，不能说明站点的容量。"}], "explanations": {"高容量": "正确：“高容量”指能容纳大量乘客，与“运送大量乘客”的语境相符。", "漂亮": "体貌：“漂亮”形容外观，与站点能容纳多少人无关。", "清洁": "语义：“清洁”描述卫生状况，与站点能否运送大量乘客无关。", "高温": "语义：“高温”描述温度，不能说明站点的容量。"}, "sentence_index": 0, "correct_answer": "高容量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个高容量的班长很受同学欢迎。", "explanation": "这里把“高容量”当成了〈能力强、心胸宽〉的意思。“高容量”只指设施或工具能容纳多少，不能用来形容人。"}, {"text": "他心里装着一份高容量的烦恼。", "explanation": "这里把“高容量”当成了〈大量〉的意思。“高容量”只指设施或工具能容纳多少，不能修饰“烦恼”这类抽象的感受。"}, {"text": "这座仓库存放了高容量的货物。", "explanation": "这里把“高容量”当成了〈大批〉的意思，说的是货物数量多。“高容量”只修饰能装东西的设施或容器，不能修饰被装的货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高容量", "is_correct": true, "explanation": "正确：“高容量”说明运输船能装载大量货物，与“码头需要……来运货”的语境相符。"}, {"text": "豪华", "is_correct": false, "explanation": "语义：“豪华”强调奢侈的装饰，与运货的需求无关。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰运输船。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”指人的年龄，不能用来形容船。"}], "explanations": {"高容量": "正确：“高容量”说明运输船能装载大量货物，与“码头需要……来运货”的语境相符。", "豪华": "语义：“豪华”强调奢侈的装饰，与运货的需求无关。", "清脆": "搭配：“清脆”形容声音，不能修饰运输船。", "年轻": "语义：“年轻”指人的年龄，不能用来形容船。"}, "sentence_index": 6, "correct_answer": "高容量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆高容量冷藏车跑得很快，一个小时就到了。", "explanation": "这里应该用〈高速〉。“高容量”说明能装多少，不能描述车跑得快不快；“跑得很快”应当用〈高速〉。"}, {"text": "这辆冷藏车的高容量是红色的。", "explanation": "这里把“高容量”当成了〈颜色〉的意思。“高容量”只说明能装多少，不能指车身的颜色。"}, {"text": "这辆冷藏车高容量地开过了大桥。", "explanation": "这里把“高容量”当成了〈快〉的意思。“高容量”只说能装多少，不能修饰“开”这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座很高容量的水库能蓄很多水。", "corrected_sentence": "这座高容量的水库能蓄很多水。", "error_description": "错误：程度副词“很”不能修饰“高容量”。“高容量”是定语性的词，应直接放在名词前，说“这座高容量的水库”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆高容量地冷藏车能运很多水果。", "corrected_sentence": "这辆高容量的冷藏车能运很多水果。", "error_description": "错误：修饰名词“冷藏车”时用了状语助词“地”。正确：“高容量的冷藏车”。“地”用于修饰动词，名词前的定语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
