INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11763, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11763, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公共交通车辆停靠和乘客上下车的地方。", "primary_collocate": null, "pronunciation": "zhàn diǎn", "ipa": "ʈʂan˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "该模式通过将高容量轨道交通站点与混合功能用地布局进行耦合设计，使居住、就业、商业与公共服务在步行可达范围内高度集聚，从而在空间结构层面抑制了长距离通勤的刚性需求。", "target_word": "站点", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条公交线一共有十八个站点。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁新增了三个站点。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近的公交站点又多了两个。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个站点离我家只有五分钟。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站点的名字会在车里报出来。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府决定调整几个站点的位置。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看看路线图上有哪些站点。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个站点都有电子屏幕显示到站时间。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线路取消了两个人少的站点。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个站点", "label": "量词"}, {"form": "站點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：公交、地铁等线路上车辆停靠、乘客上下车的点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11763, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站点", "is_correct": true, "explanation": "“站点”指公交车、地铁等车辆停靠、乘客上下车的地方，与“高容量轨道交通”搭配，符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指人，不是可以与用地布局进行空间耦合设计的场所，句子意思不通。"}, {"text": "票价", "is_correct": false, "explanation": "语义：“票价”是金额，不能在空间层面与用地布局耦合设计。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”指车内供乘客就座的位置，不是可以与用地布局进行空间耦合设计的场所。"}], "explanations": {"站点": "“站点”指公交车、地铁等车辆停靠、乘客上下车的地方，与“高容量轨道交通”搭配，符合句意。", "乘客": "语义：“乘客”指人，不是可以与用地布局进行空间耦合设计的场所，句子意思不通。", "票价": "语义：“票价”是金额，不能在空间层面与用地布局耦合设计。", "座位": "语义：“座位”指车内供乘客就座的位置，不是可以与用地布局进行空间耦合设计的场所。"}, "sentence_index": 0, "correct_answer": "站点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座站点有四层楼，里面有候车室和商店。", "explanation": "这里应该用〈车站〉。站点是车辆停靠、乘客上下车的位置，没有楼层和候车室，有这类建筑的设施应说车站。"}, {"text": "站点很长，要坐一个小时才到终点。", "explanation": "这里应该用〈线路〉。站点是车辆停靠、乘客上下车的地方，没有长短；说路程远近要用线路。"}, {"text": "这条线路新增了一条站点。", "explanation": "这里应该用〈个〉。站点按“个”计量，“条”用于线路、河流等，不能用来数站点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站点", "is_correct": true, "explanation": "“站点”是需要调整位置的停靠点，与“几个”“调整……的位置”搭配，符合句意。"}, {"text": "班次", "is_correct": false, "explanation": "语义：“班次”指发车的时间安排，没有可以调整的空间位置。"}, {"text": "车费", "is_correct": false, "explanation": "搭配：“位置”不能用于车费，车费可以调整，但不说“车费的位置”。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”没有可以调整的空间位置，不能说“时间的位置”。"}], "explanations": {"站点": "“站点”是需要调整位置的停靠点，与“几个”“调整……的位置”搭配，符合句意。", "班次": "语义：“班次”指发车的时间安排，没有可以调整的空间位置。", "车费": "搭配：“位置”不能用于车费，车费可以调整，但不说“车费的位置”。", "时间": "搭配：“时间”没有可以调整的空间位置，不能说“时间的位置”。"}, "sentence_index": 6, "correct_answer": "站点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "站点开得很快，一眨眼就到了。", "explanation": "这里应该用〈公交车〉。站点是乘客上下车的地方，不能作“开”的主体；开得快的应是公交车。"}, {"text": "司机启动了站点，车子慢慢开走了。", "explanation": "这里应该用〈汽车〉。站点是乘客上下车的地方，不能被启动；启动的应是汽车。"}, {"text": "这条线路上有一把站点。", "explanation": "这里应该用〈个〉。“把”用于有柄的物品，站点要用“个”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条地铁线一共有二十条站点。", "corrected_sentence": "这条地铁线一共有二十个站点。", "error_description": "量词错误：“站点”应用量词“个”，不用“条”（“条”用于线路、河流等狭长事物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条线路新增个站点。", "corrected_sentence": "这条线路新增一个站点。", "error_description": "数量结构错误：量词“个”前面要有数词，“新增个站点”少了“一”，应说“新增一个站点”或“新增几个站点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
