INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11765, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指用于特定用途的土地，如工业、农业或居住等。", "primary_collocate": null, "pronunciation": "yòng dì", "ipa": "jʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "该模式通过将高容量轨道交通站点与混合功能用地布局进行耦合设计，使居住、就业、商业与公共服务在步行可达范围内高度集聚，从而在空间结构层面抑制了长距离通勤的刚性需求。", "target_word": "用地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "市政府决定把这块用地划给新学校。", "target_word": "用地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的用地不够，工厂只好搬走。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市规划把东边的用地留给公园。", "target_word": "用地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块用地原来是农田，现在要建医院。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校申请了一块新用地。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里的住房用地越来越少。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司买下了工厂旁边的用地。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片用地只能种粮食，不能盖房子。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府对工业用地的管理很严。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块用地", "label": "量词"}, {"form": "建设用地", "label": "复合"}, {"form": "工业用地", "label": "复合"}, {"form": "居住用地", "label": "复合"}], "register": "书面", "sense_fingerprint": "规划上指定特定用途的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用地", "is_correct": true, "explanation": "“用地”指规划为特定用途的土地，此处修饰“布局”，与“混合功能”搭配，是正确答案。"}, {"text": "车辆", "is_correct": false, "explanation": "语义：“车辆”不是土地，不能讨论“混合功能”的空间布局。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指人，不是功能用地的布局对象，句子意思不通。"}, {"text": "票价", "is_correct": false, "explanation": "语义：“票价”是金额，不是土地，不能与“混合功能”进行布局设计。"}], "explanations": {"用地": "“用地”指规划为特定用途的土地，此处修饰“布局”，与“混合功能”搭配，是正确答案。", "车辆": "语义：“车辆”不是土地，不能讨论“混合功能”的空间布局。", "乘客": "语义：“乘客”指人，不是功能用地的布局对象，句子意思不通。", "票价": "语义：“票价”是金额，不是土地，不能与“混合功能”进行布局设计。"}, "sentence_index": 0, "correct_answer": "用地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块用地的墙上挂着很多画，每周都有展览。", "explanation": "这里应该用〈美术馆〉。“用地”是规划用途的土地，没有墙面可以挂画办展；办展览、挂画要用“美术馆”。"}, {"text": "这块用地的书很多，学生们常来借阅。", "explanation": "这里应该用〈图书馆〉。“用地”是规划用途的土地，不是藏书的场所；借书、看书要用“图书馆”。"}, {"text": "政府批准了一只用地。", "explanation": "这里应该用〈块〉。“只”用于动物等，用地要用“块”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用地", "is_correct": true, "explanation": "“用地”指规划用途的土地，与“住房”组成“住房用地”，是正确答案。"}, {"text": "学位", "is_correct": false, "explanation": "搭配：“住房”后面不能接“学位”，二者没有搭配关系。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是交给学校的钱，与住房无关，句子意思不通。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“车票”是乘车凭证，不是土地，“住房车票”说不通。"}], "explanations": {"用地": "“用地”指规划用途的土地，与“住房”组成“住房用地”，是正确答案。", "学位": "搭配：“住房”后面不能接“学位”，二者没有搭配关系。", "学费": "语义：“学费”是交给学校的钱，与住房无关，句子意思不通。", "车票": "语义：“车票”是乘车凭证，不是土地，“住房车票”说不通。"}, "sentence_index": 6, "correct_answer": "用地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块用地开在街角，生意一直很好。", "explanation": "这里应该用〈商店〉。“用地”是规划用途的土地，不能开门营业、做生意；开在街角、做生意的应说商店。"}, {"text": "这家工厂买下了一把用地，准备盖厂房。", "explanation": "这里应该用〈块〉。“把”用于有柄的物品，用地要用“块”计量。"}, {"text": "这块用地的水很清，夏天总是挤满了人。", "explanation": "这里应该用〈游泳池〉。“用地”指规划用途的土地，不是供人游泳的水池；说泳池的水质和人流要用“游泳池”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市里划出了一只用地，准备建新医院。", "corrected_sentence": "市里划出了一块用地，准备建新医院。", "error_description": "量词错误：“用地”应用量词“块”，不用“只”（“只”用于动物等，不用于土地）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校旁边有一块的用地，准备盖一栋宿舍楼。", "corrected_sentence": "学校旁边有一块用地，准备盖一栋宿舍楼。", "error_description": "语法错误：数量短语“一块”后不能加“的”来修饰“用地”，应说“一块用地”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
