INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对事物的整体结构、格局或安排进行规划和设计。", "primary_collocate": null, "pronunciation": "bù jú", "ipa": "pu˥˩ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "新区的整体布局由专家共同设计。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的产业布局很合理。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司在海外的布局正在扩大。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的布局要方便病人就医。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家认为公园的布局需要调整。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市规划先看整体布局，再看细节。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小区的绿地布局很科学。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府重新设计了学校的布局。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的布局能让交通更方便。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "企业要先做好长远的战略布局。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整体布局", "label": "复合"}, {"form": "空间布局", "label": "复合"}, {"form": "产业布局", "label": "复合"}, {"form": "战略布局", "label": "复合"}], "register": "书面", "sense_fingerprint": "对整体结构、格局的规划与设计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局（bù jú）：指整体结构的规划与设计，是本句所用的意思。"}, {"text": "入局", "is_correct": false, "explanation": "rù 与 bù 只有声母不同，意思是进入某种局面或竞争。"}, {"text": "路局", "is_correct": false, "explanation": "lù 与 bù 只有声母不同，意思是铁路局（铁路管理机构）。"}, {"text": "不拘", "is_correct": false, "explanation": "jū（第一声）与 jú（第二声）声调不同，意思是不受限制、不拘泥。"}, {"text": "不及", "is_correct": false, "explanation": "jí 与 jú 韵母不同，意思是来不及、赶不上。"}], "explanations": {"布局": "布局（bù jú）：指整体结构的规划与设计，是本句所用的意思。", "入局": "rù 与 bù 只有声母不同，意思是进入某种局面或竞争。", "路局": "lù 与 bù 只有声母不同，意思是铁路局（铁路管理机构）。", "不拘": "jū（第一声）与 jú（第二声）声调不同，意思是不受限制、不拘泥。", "不及": "jí 与 jú 韵母不同，意思是来不及、赶不上。"}, "sentence_index": null, "correct_answer": "布局"}, "level_3": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局：指整体结构和安排，与「由专家共同设计」相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来说新区的整体情况。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「设计」不搭配「价格」，价格不是由设计产生的。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指人的数量，不是可以设计的对象，句子无法成立。"}], "explanations": {"布局": "布局：指整体结构和安排，与「由专家共同设计」相符。", "身材": "体貌：身材指人的体形，不能用来说新区的整体情况。", "价格": "搭配：「设计」不搭配「价格」，价格不是由设计产生的。", "人数": "语义：人数指人的数量，不是可以设计的对象，句子无法成立。"}, "sentence_index": 0, "correct_answer": "布局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼的布局很坚固，地震时不容易倒。", "explanation": "这里应该用〈结构〉。布局指整体安排，说建筑坚固、不易倒塌要用结构。"}, {"text": "这张沙发的布局很鲜艳，放在客厅里特别显眼。", "explanation": "这里应该用〈颜色〉。布局指整体安排，不能用来形容颜色鲜艳，应说沙发的颜色很鲜艳。"}, {"text": "这套房子的布局很贵，超出了我的预算。", "explanation": "这里应该用〈价格〉。布局指整体安排，不能用来说价钱高低，应说房子的价格很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11766, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局（bù jú）：指整体结构的规划与设计，是本句所用的意思。"}, {"text": "不惧", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）只有声调不同，意思是不害怕、不畏惧。"}, {"text": "不挤", "is_correct": false, "explanation": "jǐ（第三声）与 jú（第二声）只有声调不同，意思是不拥挤。"}, {"text": "不吉", "is_correct": false, "explanation": "jí 与 jú 韵母不同，意思是不吉利。"}], "explanations": {"布局": "布局（bù jú）：指整体结构的规划与设计，是本句所用的意思。", "不惧": "jù（第四声）与 jú（第二声）只有声调不同，意思是不害怕、不畏惧。", "不挤": "jǐ（第三声）与 jú（第二声）只有声调不同，意思是不拥挤。", "不吉": "jí 与 jú 韵母不同，意思是不吉利。"}, "sentence_index": null, "correct_answer": "布局"}, "level_3": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局：指绿地的安排与格局，与「很科学」相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「科学」不修饰颜色，句子说的是绿地的安排是否合理。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指人的性情，不能用来形容绿地。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指存在的时间长短，「很科学」无法修饰绿地的年龄。"}], "explanations": {"布局": "布局：指绿地的安排与格局，与「很科学」相符。", "颜色": "搭配：「科学」不修饰颜色，句子说的是绿地的安排是否合理。", "脾气": "语义：脾气指人的性情，不能用来形容绿地。", "年龄": "语义：年龄指存在的时间长短，「很科学」无法修饰绿地的年龄。"}, "sentence_index": 6, "correct_answer": "布局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的布局很高，身材也很健壮。", "explanation": "这里应该用〈个子〉。布局指事物的整体安排，不能形容人的身高，说人的高矮要用个子。"}, {"text": "这家工厂的布局很大，工人也很多。", "explanation": "这里应该用〈规模〉。布局指安排格局，说企业的大小要用规模。"}, {"text": "这辆新车的布局很快，一小时能跑两百公里。", "explanation": "这里应该用〈速度〉。布局指安排格局，不用来说快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个园区有一只新的布局。", "corrected_sentence": "这个园区有一种新的布局。", "error_description": "“布局”的量词用错：“只”多用于动物或成对的东西，布局应该用“种”，正确说法是「一种新的布局」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个园区的的布局很合理。", "corrected_sentence": "这个园区的布局很合理。", "error_description": "“的”重复：“园区的布局”中只用一个“的”，多加一个“的”是错误，应说「这个园区的布局很合理」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
