INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长期或固定地住在某个地方。", "primary_collocate": null, "pronunciation": "jū zhù", "ipa": "tɕy˥˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "我们一家人在北京居住了十年。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢在安静的小城居住。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长期居住在国外，很少回家。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区居住着很多老人。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小居住在海边的村子里。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在居住在哪个城市？", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼里居住的大多是年轻人。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们曾经在上海居住过两年。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区居住的人家不多，路也不好走。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在离公司近的地方居住。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "居住了", "label": "体标"}, {"form": "居住着", "label": "体标"}, {"form": "居住过", "label": "体标"}], "register": "书面", "sense_fingerprint": "长期固定地住在某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "正确：「在北京居住了十年」表示长期固定地住在某地，与句意一致。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是一次性事件，不能持续十年，「在北京出生了十年」说不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：「打碎」是瞬时动作，不能与「在北京……了十年」这类时段搭配。"}, {"text": "叫", "is_correct": false, "explanation": "配价：「叫」需要带称呼作宾语，「在北京叫了十年」缺少所需成分，句子不成立。"}], "explanations": {"居住": "正确：「在北京居住了十年」表示长期固定地住在某地，与句意一致。", "出生": "语义：出生是一次性事件，不能持续十年，「在北京出生了十年」说不通。", "打碎": "搭配：「打碎」是瞬时动作，不能与「在北京……了十年」这类时段搭配。", "叫": "配价：「叫」需要带称呼作宾语，「在北京叫了十年」缺少所需成分，句子不成立。"}, "sentence_index": 0, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这家旅馆居住了五分钟就走了。", "explanation": "这里应该用〈停留〉。居住强调长期固定，只待五分钟应说〈停留〉。"}, {"text": "这把椅子居住在客厅里。", "explanation": "居住的主语须是人或动物，椅子不能居住，这里应说〈放〉。"}, {"text": "我去北京居住朋友。", "explanation": "这里应该用〈访问〉。居住不能带人作宾语，拜访朋友要说〈访问〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "正确：「这座楼里居住的大多是年轻人」，「居住」修饰前面的处所，指住在楼里的人。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售的对象是商品，「这座楼里出售的大多是年轻人」毫无意义。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：「举办」要求活动作宾语，不能说「举办的大多是年轻人」。"}, {"text": "建造", "is_correct": false, "explanation": "配价：「建造」的受事是建筑物，人不能被建造，句子的搭配不成立。"}], "explanations": {"居住": "正确：「这座楼里居住的大多是年轻人」，「居住」修饰前面的处所，指住在楼里的人。", "出售": "语义：出售的对象是商品，「这座楼里出售的大多是年轻人」毫无意义。", "举办": "搭配：「举办」要求活动作宾语，不能说「举办的大多是年轻人」。", "建造": "配价：「建造」的受事是建筑物，人不能被建造，句子的搭配不成立。"}, "sentence_index": 6, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在酒店居住了一下午就离开了。", "explanation": "这里应该用〈待〉。居住强调长期固定，只待一下午应说〈待〉。"}, {"text": "我们居住了长城，每天都去看。", "explanation": "这里应该用〈参观〉。居住不能以景点作宾语，去长城看景要说〈参观〉。"}, {"text": "这盏灯居住在书房里。", "explanation": "这里应该用〈安装〉。居住的主语须是人或动物，灯不能居住，应说〈安装〉在书房里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社区居住了着不少老人。", "corrected_sentence": "这个社区居住着不少老人。", "error_description": "体标错误：「了」与「着」不能同时加在动词「居住」上，多出的「了」应删去，正确说法是「这个社区居住着不少老人。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我父母曾经在广州居住了过一段时间。", "corrected_sentence": "我父母曾经在广州居住过一段时间。", "error_description": "体标错误：「了」与「过」不能同时加在动词「居住」上，多出的「了」应删去，正确说法是「居住过一段时间」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失业", "is_correct": true, "explanation": "反义：就业指找到工作，失业指失去工作，两者意义相反。"}, {"text": "休息", "is_correct": false, "explanation": "无关：休息指停下来放松，与就业没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：旅行指外出游览，与就业没有反义关系。"}, {"text": "结婚", "is_correct": false, "explanation": "无关：结婚指组成家庭，与就业没有反义关系。"}], "correct_answer": "失业", "explanations": {"失业": "反义：就业指找到工作，失业指失去工作，两者意义相反。", "休息": "无关：休息指停下来放松，与就业没有反义关系。", "旅行": "无关：旅行指外出游览，与就业没有反义关系。", "结婚": "无关：结婚指组成家庭，与就业没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失业", "is_correct": true, "explanation": "反义：就业指找到工作，失业指失去工作，两者意义相反。"}, {"text": "出发", "is_correct": false, "explanation": "无关：出发指动身离开，与就业没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：游泳指在水中运动，与就业没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌指用声音表演，与就业没有反义关系。"}], "correct_answer": "失业", "explanations": {"失业": "反义：就业指找到工作，失业指失去工作，两者意义相反。", "出发": "无关：出发指动身离开，与就业没有反义关系。", "游泳": "无关：游泳指在水中运动，与就业没有反义关系。", "唱歌": "无关：唱歌指用声音表演，与就业没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指得到一份职业，开始工作。", "primary_collocate": null, "pronunciation": "jiù yè", "ipa": "tɕjoʊ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他大学毕业后在上海就业。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年毕业生就业不太容易。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学护理，毕业后不愁就业。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人毕业后选择回家乡就业。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司帮助残疾人就业。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥去年毕业，很快就业了。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐刚毕业，正在找工作，还没就业。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学一门技术，就业会更容易。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，先就业再考虑换工作。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小城就业，每月收入不高。", "target_word": "就业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "就业了", "label": "体标"}, {"form": "就业过", "label": "体标"}], "register": "中性", "sense_fingerprint": "得到职业并开始工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就业", "is_correct": true, "explanation": "就业：指找到工作、开始工作，与“大学毕业后在上海”的语境相符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休指年老后停止工作，刚大学毕业的人不可能退休。"}, {"text": "出版", "is_correct": false, "explanation": "语义：出版指编印发行书刊，“他在上海出版”读不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指来到世界，与“大学毕业后”的时间顺序矛盾。"}], "explanations": {"就业": "就业：指找到工作、开始工作，与“大学毕业后在上海”的语境相符。", "退休": "语义：退休指年老后停止工作，刚大学毕业的人不可能退休。", "出版": "语义：出版指编印发行书刊，“他在上海出版”读不通。", "出生": "语义：出生指来到世界，与“大学毕业后”的时间顺序矛盾。"}, "sentence_index": 0, "correct_answer": "就业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被学校任命为副校长，下个月就业。", "explanation": "这里应该用〈就职〉。就职指正式就任职务，多用于官职或领导职位；就业指找到工作、开始工作，不用于就任职务。"}, {"text": "他感冒后去医院就业。", "explanation": "这里应该用〈就医〉。就医指去医院看病；就业指找工作，不能用来指看病。"}, {"text": "他在公司工作了五年，因为身体不好，上个月就业了。", "explanation": "这里应该用〈辞职〉。他原本已有工作，离开工作要说辞职；就业指找到工作、开始工作，与“工作了五年”的情况矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就业", "is_correct": true, "explanation": "就业：指找到工作、开始工作，与“刚毕业、正在找工作”的语境一致。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：辞职指离开现有工作，姐姐正在找工作，还没有工作可辞。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶指操纵车辆等，与“找工作”无关，“还没驾驶”句意不通。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：与“刚毕业”冲突，同一句中不能说“刚毕业，还没毕业”。"}], "explanations": {"就业": "就业：指找到工作、开始工作，与“刚毕业、正在找工作”的语境一致。", "辞职": "语义：辞职指离开现有工作，姐姐正在找工作，还没有工作可辞。", "驾驶": "语义：驾驶指操纵车辆等，与“找工作”无关，“还没驾驶”句意不通。", "毕业": "语义：与“刚毕业”冲突，同一句中不能说“刚毕业，还没毕业”。"}, "sentence_index": 6, "correct_answer": "就业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被派到外地担任镇长，下周就业。", "explanation": "这里应该用〈上任〉。上任指正式就任官职或领导职务；就业指找到工作，不用于就任职务。"}, {"text": "他高中毕业后决定就业入伍。", "explanation": "这里应该用〈参军〉。就业指找到工作、开始工作；加入部队服役要说参军。"}, {"text": "疫情结束后，那家工厂就业了。", "explanation": "这里应该用〈复工〉。复工指停工后重新开工，多用于工厂、公司；就业只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业后深圳就业了。", "corrected_sentence": "他毕业后在深圳就业了。", "error_description": "介词遗漏：表示就业地点的「深圳」前要用介词「在」，应说「在深圳就业」，不能省略「在」。正确句为「他毕业后在深圳就业了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经在深圳就业着了。", "corrected_sentence": "他已经在深圳就业了。", "error_description": "错误在于多加了“着”。“着”表示持续状态，与“就业”这种一次完成的动作不兼容，表示完成时只用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指政府或公共机构为满足公众需求而提供的服务，如教育、医疗、交通。", "primary_collocate": null, "pronunciation": "gōng gòng fú wù", "ipa": "kʊŋ˥ kʊŋ˥˩ fu˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "该模式通过将高容量轨道交通站点与混合功能用地布局进行耦合设计，使居住、就业、商业与公共服务在步行可达范围内高度集聚，从而在空间结构层面抑制了长距离通勤的刚性需求。", "target_word": "公共服务", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府要为市民提供更好的公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的公共服务很方便，医院和学校都在附近。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育、医疗和交通都是重要的公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的公共服务比城市少，政府正在改善。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共服务做得好，市民的生活就会更方便。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新区增加了公园和图书馆等公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年都花很多钱发展公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人最需要医疗和养老这样的公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府想让所有人都能用上公共服务。", "target_word": "公共服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共服務", "label": "繁体"}, {"form": "项", "label": "量词"}], "register": "书面语", "sense_fingerprint": "政府或公共机构为公众提供的教育、医疗、交通等服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共服务", "is_correct": true, "explanation": "公共服务：指政府或公共机构提供的教育、医疗、交通等服务，与居住、就业、商业并列。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“高度集聚”用于人口、设施、产业等，不能说空气在步行范围内集聚。"}, {"text": "矿产", "is_correct": false, "explanation": "语义：矿产多分布在矿区，不会与居住、商业一起在步行可达范围内集聚，句意不通。"}, {"text": "农业", "is_correct": false, "explanation": "语义：农业用地不会与居住、商业一起在步行可达范围内高度集聚，句意不通。"}], "explanations": {"公共服务": "公共服务：指政府或公共机构提供的教育、医疗、交通等服务，与居住、就业、商业并列。", "空气": "搭配：“高度集聚”用于人口、设施、产业等，不能说空气在步行范围内集聚。", "矿产": "语义：矿产多分布在矿区，不会与居住、商业一起在步行可达范围内集聚，句意不通。", "农业": "语义：农业用地不会与居住、商业一起在步行可达范围内高度集聚，句意不通。"}, "sentence_index": 0, "correct_answer": "公共服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这个城市的公共服务，每天都很忙。", "explanation": "这里应该用〈公务员〉。公共服务指服务内容，不指人；指人应说〈公务员〉。"}, {"text": "这座城市新建了一座公共服务，方便了市民。", "explanation": "这里应该用〈项〉。公共服务是服务事项，应用量词“项”；“座”多用于大型建筑。"}, {"text": "这个城市的公共服务很发达，有很多餐馆和商店。", "explanation": "这里应该用〈服务业〉。餐馆、商店属于服务业；公共服务指政府或公共机构提供的服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共服务", "is_correct": true, "explanation": "公共服务：指政府或公共机构提供的服务，与“新增了公园和图书馆等”并列，语境相符。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药是化学品，不能与公园、图书馆并列作为“新增”的对象。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不能与公园、图书馆并列作为公共建设的新增内容，句意不通。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“增加”可以带“收入”，但与“公园和图书馆等”并列时只能指设施或服务。"}], "explanations": {"公共服务": "公共服务：指政府或公共机构提供的服务，与“新增了公园和图书馆等”并列，语境相符。", "农药": "语义：农药是化学品，不能与公园、图书馆并列作为“新增”的对象。", "宠物": "语义：宠物不能与公园、图书馆并列作为公共建设的新增内容，句意不通。", "收入": "搭配：“增加”可以带“收入”，但与“公园和图书馆等”并列时只能指设施或服务。"}, "sentence_index": 6, "correct_answer": "公共服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司给员工的公共服务很多，包括年终奖和补贴。", "explanation": "这里应该用〈福利〉。年终奖和补贴是公司给员工的福利，不是政府或公共机构提供的公共服务。"}, {"text": "这家超市的公共服务很好，店员很热情。", "explanation": "这里应该用〈商业服务〉。超市是私人经营，店员的待客服务属于商业服务，不是政府或公共机构提供的公共服务。"}, {"text": "这家工厂生产的公共服务很受欢迎。", "explanation": "这里应该用〈产品〉。工厂生产的是产品，公共服务不是工厂生产的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府新增了一座公共服务，方便市民。", "corrected_sentence": "政府新增了一项公共服务，方便市民。", "error_description": "量词错误：“公共服务”应使用量词“项”，不能用“座”，因为“座”多用于大型建筑或山等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府所有居民提供了公共服务。", "corrected_sentence": "市政府为所有居民提供了公共服务。", "error_description": "介词遗漏：「提供」的受益对象「所有居民」前要用介词「为」，应说「为所有居民提供了公共服务」，不能省略「为」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "一种移动方式，指两脚交替向前迈动，使身体向前移动。", "primary_collocate": null, "pronunciation": "bù xíng", "ipa": "pu˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们小区附近有地铁站，超市和医院都在步行可达范围内。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天上班都骑车或步行，既省钱又锻炼身体。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步行是最环保的出行方式。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校很近，步行只要十分钟。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车和步行都比开车更环保。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步行对身体好，也不花钱。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街只能步行，不能开车。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步行和骑车是城市里常见的出行方式。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天步行半小时，对健康很有好处。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步行比坐公交慢，但是更自由。", "target_word": "步行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作为出行方式的步行，与骑行、开车等相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "步行", "is_correct": true, "explanation": "正确答案。步行（bù xíng）指不乘车、用脚走路的出行方式。"}, {"text": "不幸", "is_correct": false, "explanation": "不幸（bù xìng）与步行的第二音节声调不同：行读xíng（第二声），幸读xìng（第四声），意思是运气不好。"}, {"text": "不信", "is_correct": false, "explanation": "不信（bù xìn）与步行的第二音节不同：xíng与xìn的韵尾不同（ng与n），意思是不相信。"}, {"text": "不兴", "is_correct": false, "explanation": "不兴（bù xīng）与步行的第二音节声调不同：行读xíng（第二声），兴读xīng（第一声），意思是不流行。"}], "explanations": {"步行": "正确答案。步行（bù xíng）指不乘车、用脚走路的出行方式。", "不幸": "不幸（bù xìng）与步行的第二音节声调不同：行读xíng（第二声），幸读xìng（第四声），意思是运气不好。", "不信": "不信（bù xìn）与步行的第二音节不同：xíng与xìn的韵尾不同（ng与n），意思是不相信。", "不兴": "不兴（bù xīng）与步行的第二音节声调不同：行读xíng（第二声），兴读xīng（第一声），意思是不流行。"}, "sentence_index": null, "correct_answer": "步行"}, "level_3": {"options": [{"text": "步行", "is_correct": true, "explanation": "正确。“步行可达范围”指步行能到达的范围，与“在……范围内”的用法相符。"}, {"text": "步调", "is_correct": false, "explanation": "语义：“步调”指行走或工作的节奏，不表示移动方式，不能说“在步调可达范围内”。"}, {"text": "行程", "is_correct": false, "explanation": "搭配：“可达范围”前面要说到达的方式，“行程”指旅程的安排，不能作为到达方式。"}, {"text": "步履", "is_correct": false, "explanation": "语域：“步履”是文学语体，专指走路的姿态，与这段专业论述的语体不合，且不能指移动方式。"}], "explanations": {"步行": "正确。“步行可达范围”指步行能到达的范围，与“在……范围内”的用法相符。", "步调": "语义：“步调”指行走或工作的节奏，不表示移动方式，不能说“在步调可达范围内”。", "行程": "搭配：“可达范围”前面要说到达的方式，“行程”指旅程的安排，不能作为到达方式。", "步履": "语域：“步履”是文学语体，专指走路的姿态，与这段专业论述的语体不合，且不能指移动方式。"}, "sentence_index": 0, "correct_answer": "步行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他步行冲过了终点线。", "explanation": "这里应该用〈跑步〉。“步行”指慢慢地走路、不用车，冲过终点线的快速动作要说“跑步”。"}, {"text": "实验要按照步行进行。", "explanation": "这里应该用〈步骤〉。“按照”后面接的是步骤、程序，“步行”是走路的动作，不能用来指操作的顺序。"}, {"text": "他迈着坚定的步行走进了会场。", "explanation": "这里应该用〈步伐〉。“迈”的对象是步伐，“步行”是走路这一动作，不能作为迈出的步子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步行", "is_correct": true, "explanation": "正确。“这条街只能步行”指只允许用脚走路，“不能开车”与之对应。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：街道上不能游泳，“只能游泳，不能开车”读不通。"}, {"text": "飞行", "is_correct": false, "explanation": "语义：街道上不能飞行，与“只能……不能开车”的语境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：街道只能用来睡觉，于理不合，句子读不通。"}], "explanations": {"步行": "正确。“这条街只能步行”指只允许用脚走路，“不能开车”与之对应。", "游泳": "语义：街道上不能游泳，“只能游泳，不能开车”读不通。", "飞行": "语义：街道上不能飞行，与“只能……不能开车”的语境不合。", "睡觉": "语义：街道只能用来睡觉，于理不合，句子读不通。"}, "sentence_index": 6, "correct_answer": "步行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家步行一致地前进。", "explanation": "这里应该用〈步调〉。“步调一致”指行动的节奏相同，“步行”是走路这一动作，不能与“一致”搭配。"}, {"text": "这台电脑步行得很快。", "explanation": "这里应该用〈运行〉。“步行”指用脚走路，形容电脑的工作速度要说“运行”。"}, {"text": "这项计划步行得很顺利。", "explanation": "这里应该用〈进行〉。“步行”指用脚走路，说计划的进展要用“进行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这次出行选择了一辆步行。", "corrected_sentence": "我们这次出行选择了一次步行。", "error_description": "量词错误：把“步行”错用了“辆”。“辆”用于车辆，步行是一种移动方式，应当用“次”，正确说法是“一次步行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去学校不远，一辆步行只要十分钟。", "corrected_sentence": "去学校不远，步行只要十分钟。", "error_description": "量词错误：“步行”是动作，不能用“辆”计量，“辆”用于车辆。正确说法是直接说“步行只要十分钟”，去掉“一辆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11774, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与「集聚」相反，指使分开、散开。"}, {"text": "研究", "is_correct": false, "explanation": "研究：指深入探讨问题，与人或事物的聚合、分开都无关。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指使损坏的东西恢复正常，与「集聚」的意思无关。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃：指不再坚持，与「集聚」的意思无关。"}], "correct_answer": "分散", "explanations": {"分散": "分散：与「集聚」相反，指使分开、散开。", "研究": "研究：指深入探讨问题，与人或事物的聚合、分开都无关。", "修理": "修理：指使损坏的东西恢复正常，与「集聚」的意思无关。", "放弃": "放弃：指不再坚持，与「集聚」的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
